/******************************************************************************
    Procedure:  formatted_locn_code

    Purpose:    Format a numeric location code

******************************************************************************/
  FUNCTION formatted_locn_code
  (p_client_locn_code     IN NUMBER)
  RETURN VARCHAR2
  IS
  BEGIN

    RETURN TO_CHAR(p_client_locn_code,'FM00');

  END formatted_locn_code;

/******************************************************************************
    Procedure:  get_previous

    Purpose:    Get current client location info if not already retrieved

******************************************************************************/
  PROCEDURE get_previous
  IS
  BEGIN
    IF r_previous.client_number IS NULL THEN
      SELECT *
        INTO r_previous
        FROM client_location
       WHERE client_number = g_client_number
         AND client_locn_code = g_client_locn_code;
    END IF;
  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      NULL;
  END get_previous;


/******************************************************************************
    Procedure:  get

    Purpose:    SELECT one row from CLIENT_LOCATION

******************************************************************************/
  PROCEDURE get
  IS
  BEGIN
    SELECT
           client_number
         , client_locn_code
         , client_locn_name
         , hdbs_company_code
         , address_1
         , address_2
         , address_3
         , city
         , province
         , postal_code
         , country
         , business_phone
         , home_phone
         , cell_phone
         , fax_number
         , email_address
         , locn_expired_ind
         , returned_mail_date
         , trust_location_ind
         , cli_locn_comment
         , update_timestamp
         , update_userid
         , update_org_unit
         , add_timestamp
         , add_userid
         , add_org_unit
         , revision_count
      INTO
           g_client_number
         , g_client_locn_code
         , g_client_locn_name
         , g_hdbs_company_code
         , g_address_1
         , g_address_2
         , g_address_3
         , g_city
         , g_province
         , g_postal_code
         , g_country
         , g_business_phone
         , g_home_phone
         , g_cell_phone
         , g_fax_number
         , g_email_address
         , g_locn_expired_ind
         , g_returned_mail_date
         , g_trust_location_ind
         , g_cli_locn_comment
         , g_update_timestamp
         , g_update_userid
         , g_update_org_unit
         , g_add_timestamp
         , g_add_userid
         , g_add_org_unit
         , g_revision_count
      FROM client_location
     WHERE client_number = g_client_number
       AND client_locn_code = g_client_locn_code;

    EXCEPTION
      WHEN NO_DATA_FOUND THEN
        NULL;

  END get;

