CREATE OR REPLACE EDITIONABLE PACKAGE BODY "THE"."FTA_ILRR_ACQUIRER_PLUGIN_PKG" 
AS
/******************************************************************************
Purpose:   Message_to_queue
Notes:     Populates the Queue

REVISIONS:
Ver        Date        Author           Description
---------  ----------  ---------------  ------------------------------------
01_00_05   03/28/2006  A. Stephenson    Amended Existing
           03/29/2012  Forte Consulting Amended to include Geometry only events
******************************************************************************/
  PROCEDURE message_to_queue(
    p_action                         IN       VARCHAR2
  , p_op_type                        IN       VARCHAR2
  , p_fia_skey                       IN       VARCHAR2
  , p_map_feature_id                 IN       VARCHAR2)
  IS
    v_enqueue_options                    DBMS_AQ.enqueue_options_t;
    v_message_properties                 DBMS_AQ.message_properties_t;
    v_recipients                         DBMS_AQ.aq$_recipient_list_t;
    v_message_handle                     RAW(16);
    v_message                            fta_ilrr_event_typ;
  BEGIN

    if p_op_type = 'Geometry' then
       --Geometry changes use MAP_FEATURE_ID as ILRR_AQ.ILRR_ACQUIRER_FTA_EVENTS.AGENCY_SYSTEM_ID
       v_message := fta_ilrr_event_typ(p_action, p_op_type, p_map_feature_id, p_fia_skey);
    else
       v_message := fta_ilrr_event_typ(p_action, p_op_type, p_fia_skey, p_map_feature_id);
    end if;
    DBMS_AQ.enqueue(queue_name => 'MOF_QUEUES.FTA_ILRR_EVENT_Q'
                  , enqueue_options => v_enqueue_options
                  , message_properties => v_message_properties
                  , payload => v_message
                  , msgid => v_message_handle);
  END;

/******************************************************************************
Purpose:   GET SKEYS
Notes:     gets the necessary business keys from the related tables

REVISIONS:
Ver        Date        Author           Description
---------  ----------  ---------------  ------------------------------------
01_00_05   03/09/2006  A. Stephenson    Amended Existing
           03/29/2012  Forte Consulting Amended to remove Cut Block processing and include Geometry only events
******************************************************************************/
  PROCEDURE get_skeys(
    p_forest_file_id                 IN       VARCHAR2
  , p_hva_skey                       IN       NUMBER
  , p_ret_forest_file_id             OUT      VARCHAR2
  , p_ret_hva_skey                   OUT      NUMBER
  , p_amend_type                     IN       VARCHAR2
  , p_amend_skey                     IN OUT   VARCHAR2
  , p_ret_map_feature_id             IN OUT   NUMBER)
  IS

    l_amendment_id             fsr_gravel_pit.amendment_id%TYPE;
    l_gp_number                fsr_gravel_pit.gp_number%TYPE;
    l_map_block_id             managed_licence.map_block_id%TYPE;
    l_ml_type_code             managed_licence.ml_type_code%TYPE;

  BEGIN
    IF p_amend_type = 'COMM' THEN
       --Communication Site changes
       BEGIN
          SELECT map_feature_id
            INTO p_ret_map_feature_id
            FROM communication_site_geom
           WHERE forest_file_id = p_forest_file_id
             AND amendment_id = p_amend_skey;
       EXCEPTION WHEN NO_DATA_FOUND THEN
          p_ret_map_feature_id := null;
       END;
    END IF;

    IF p_amend_type = 'FRGP' THEN
       --determine key attributes from trigger concatenated p_amend_skey
       l_amendment_id := substr(p_amend_skey,1,instr(p_amend_skey,'|')-1);
       l_gp_number := substr(p_amend_skey,instr(p_amend_skey,'|')+1);

       --FSR Gravel Pit changes
       BEGIN
          SELECT map_feature_id
            INTO p_ret_map_feature_id
            FROM fsr_gravel_pit_geom
           WHERE forest_file_id = p_forest_file_id
             AND amendment_id = l_amendment_id
             AND gp_number = l_gp_number;
       EXCEPTION WHEN NO_DATA_FOUND THEN
          p_ret_map_feature_id := null;
       END;
    END IF;

    IF p_amend_type = 'FUPR' THEN
       --Free Use Permit changes
       BEGIN
          SELECT map_feature_id
            INTO p_ret_map_feature_id
            FROM free_use_permit_geom
           WHERE forest_file_id = p_forest_file_id
             AND amendment_id = p_amend_skey;
       EXCEPTION WHEN NO_DATA_FOUND THEN
          p_ret_map_feature_id := null;
       END;
    END IF;

    IF p_amend_type = 'HVA' THEN
      -- join for the harvesting authority amend geom table
      SELECT forest_file_id
        INTO p_ret_forest_file_id
        FROM harvesting_authority hva
       WHERE hva.hva_skey = p_hva_skey;
    END IF;

    IF p_amend_type = 'MNLC' THEN
       --determine key attributes from trigger concatenated p_amend_skey
       l_amendment_id := substr(p_amend_skey, 1, instr(p_amend_skey,'|')-1);
       l_map_block_id := substr(p_amend_skey, instr(p_amend_skey,'|')+1, (instr(p_amend_skey,'|',1,2)-(instr(p_amend_skey,'|')+1)));
       l_ml_type_code := substr(p_amend_skey, instr(p_amend_skey,'|',1,2)+1);

       --Managed Licence changes
       BEGIN
          SELECT map_feature_id
            INTO p_ret_map_feature_id
            FROM managed_licence_geom
           WHERE forest_file_id = p_forest_file_id
             AND amendment_id = l_amendment_id
             AND map_block_id = l_map_block_id
             AND ml_type_code = l_ml_type_code;
       EXCEPTION WHEN NO_DATA_FOUND THEN
          p_ret_map_feature_id := null;
       END;
    END IF;

    IF p_amend_type = 'RMAP' THEN
       --Recreation Map Feature changes
       BEGIN
          SELECT map_feature_id
            INTO p_ret_map_feature_id
            FROM recreation_map_feature_geom
           WHERE rmf_skey = p_amend_skey;
       EXCEPTION WHEN NO_DATA_FOUND THEN
          p_ret_map_feature_id := null;
       END;
    END IF;

    IF p_amend_type = 'RMF' THEN
      -- join for rec map feature
      SELECT rmf.forest_file_id
        INTO p_ret_forest_file_id
        FROM recreation_map_feature rmf
       WHERE rmf.rmf_skey = p_amend_skey;
    END IF;

    IF p_amend_type = 'RSA' THEN
      SELECT rpa.forest_file_id
        INTO p_ret_forest_file_id
        FROM road_prmt_amend rpa
       WHERE rpa.road_prmt_amend_skey = p_amend_skey;
    END IF;

    if p_ret_forest_file_id is null then
        p_ret_forest_file_id := p_forest_file_id;
    end if;
    if p_ret_hva_skey is null then
        p_ret_hva_skey := p_hva_skey;
    end if;

  END get_skeys;

/******************************************************************************
Purpose:   ADD
Notes:

REVISIONS:
Ver        Date        Author           Description
---------  ----------  ---------------  ------------------------------------
01_00_05   03/09/2006  A. Stephenson    Amended Existing
           03/29/2012  Forte Consulting Amended to remove Cut Block processing
******************************************************************************/
  PROCEDURE add_rec(
    p_forest_file_id                 IN       VARCHAR2
  , p_hva_skey                       IN       NUMBER
  , p_ret_forest_file_id             IN OUT   VARCHAR2
  , p_ret_hva_skey                   IN OUT   NUMBER
  , p_op_scope                       IN       VARCHAR2
  , p_amend_type                     IN       VARCHAR2
  , p_amend_skey                     IN OUT   VARCHAR2)
  IS
    p_fia_skey                         fta_ilrr_attributes.fia_skey%TYPE;
    p_rec_exists                       VARCHAR2(2);
    i                                  NUMBER := 0;

    v_ret_map_feature_id       NUMBER(10);

    CURSOR c_pfu_fia_recs
    IS
      SELECT fia_skey
        FROM fta_ilrr_attributes
       WHERE forest_file_id = p_ret_forest_file_id
         AND hva_skey IS NULL
         AND cb_skey IS NULL;

    CURSOR c_hva_fia_recs
    IS
      SELECT fia_skey
        FROM fta_ilrr_attributes
       WHERE hva_skey = p_ret_hva_skey
         AND cb_skey IS NULL;

  BEGIN
    p_rec_exists := 'Y';

    IF p_amend_type IN('HVA', 'RMF', 'RSA') THEN
      get_skeys(p_forest_file_id, p_hva_skey, p_ret_forest_file_id, p_ret_hva_skey, p_amend_type, p_amend_skey, v_ret_map_feature_id);
    ELSE
    -- these get set in get skeys - if get skeys isn't accessed they need to be set here
    -- option to overloading the mailine with in out variables which won't work with triggers
        p_ret_forest_file_id := p_forest_file_id;
        p_ret_hva_skey := p_hva_skey;
    END IF;

    -- get the fia_skey for the queue
    if p_hva_skey is not null then
           OPEN c_hva_fia_recs;

                LOOP
                  FETCH  c_hva_fia_recs
                    INTO p_fia_skey;

                  i := i + 1;
                  EXIT WHEN i = 1;
                END LOOP;

                IF c_hva_fia_recs%NOTFOUND THEN
                  p_rec_exists := 'N';
                END IF;

                CLOSE c_hva_fia_recs;

     end if;

    if p_ret_forest_file_id is not null
       and p_ret_hva_skey is null then

       OPEN c_pfu_fia_recs;

            LOOP
              FETCH  c_pfu_fia_recs
                INTO p_fia_skey;

              i := i + 1;
              EXIT WHEN i = 1;
            END LOOP;

            IF c_pfu_fia_recs%NOTFOUND THEN
              p_rec_exists := 'N';
            END IF;

            CLOSE c_pfu_fia_recs;
      end if;


    IF p_rec_exists = 'N' THEN
      SELECT fta_ilrr_attributes_seq.NEXTVAL
        INTO p_fia_skey
        FROM DUAL;
      INSERT INTO fta_ilrr_attributes
             (fia_skey
            , forest_file_id
            , hva_skey
            , operation_scope
            , entry_timestamp)
      VALUES (p_fia_skey
            , p_ret_forest_file_id
            , p_ret_hva_skey
            , p_op_scope
            , SYSDATE);
    END IF;

    --call to queue
    message_to_queue('Insert', p_op_scope, p_fia_skey, null);
  END add_rec;

/******************************************************************************
Purpose:   DELETE
Notes:

REVISIONS:
Ver        Date        Author           Description
---------  ----------  ---------------  ------------------------------------
01_00_05   03/09/2006  A. Stephenson    Amended Existing
           03/29/2012  Forte Consulting Amended to remove Cut Block processing
******************************************************************************/
  PROCEDURE delete_rec(
    p_forest_file_id                 IN       VARCHAR2
  , p_hva_skey                       IN       NUMBER
  , p_ret_forest_file_id             IN OUT   VARCHAR2
  , p_ret_hva_skey                   IN OUT   NUMBER
  , p_op_scope                       IN       VARCHAR2
  , p_amend_type                     IN       VARCHAR2
  , p_amend_skey                     IN OUT   VARCHAR2)
  IS
    p_fia_skey                         fta_ilrr_attributes.fia_skey%TYPE;
    p_rec_exists                       VARCHAR2(2);
    i                                  NUMBER := 0;

    v_ret_map_feature_id       NUMBER(10);

    CURSOR c_pfu_fia_recs
    IS
      SELECT fia_skey
        FROM fta_ilrr_attributes
       WHERE forest_file_id = p_ret_forest_file_id
         AND hva_skey IS NULL
         AND cb_skey IS NULL;

    CURSOR c_hva_fia_recs
    IS
      SELECT fia_skey
        FROM fta_ilrr_attributes
       WHERE hva_skey = p_ret_hva_skey
         AND cb_skey IS NULL;

  BEGIN
    p_rec_exists := 'Y';

    IF p_amend_type IN('HVA', 'RMF', 'RSA') THEN
      get_skeys(p_forest_file_id, p_hva_skey, p_ret_forest_file_id, p_ret_hva_skey, p_amend_type, p_amend_skey, v_ret_map_feature_id);
    ELSE
    -- these get set in get skeys - if get skeys isn't accessed they need to be set here
    -- option to overloading the mailine with in out variables which won't work with triggers
        p_ret_forest_file_id := p_forest_file_id;
        p_ret_hva_skey := p_hva_skey;
    END IF;
    -- get the fia_skey for the queue
      if p_hva_skey is not null then

            OPEN c_hva_fia_recs;

            LOOP
              FETCH  c_hva_fia_recs
                INTO p_fia_skey;

              i := i + 1;
              EXIT WHEN i = 1;
            END LOOP;

            IF c_hva_fia_recs%NOTFOUND THEN
              p_rec_exists := 'N';
            END IF;

            CLOSE c_hva_fia_recs;
      end if;

    if p_ret_forest_file_id is not null
        and P_ret_hva_skey is null then
       OPEN c_pfu_fia_recs;

            LOOP
              FETCH  c_pfu_fia_recs
                INTO p_fia_skey;

              i := i + 1;
              EXIT WHEN i = 1;
            END LOOP;

            IF c_pfu_fia_recs%NOTFOUND THEN
              p_rec_exists := 'N';
            END IF;

            CLOSE c_pfu_fia_recs;
      end if;


    IF p_rec_exists = 'Y' THEN
      DELETE FROM fta_ilrr_attributes
       WHERE fia_skey = p_fia_skey;

      --call to queue
      message_to_queue('Delete', p_op_scope, p_fia_skey, null);
    END IF;
  END delete_rec;

/******************************************************************************
Purpose:   UPDATE
Notes:

REVISIONS:
Ver        Date        Author           Description
---------  ----------  ---------------  ------------------------------------
01_00_05   03/09/2006  A. Stephenson    Amended Existing
           03/29/2012  Forte Consulting Amended to remove Cut Block processing
******************************************************************************/
  PROCEDURE update_rec(
    p_forest_file_id                 IN       VARCHAR2
  , p_hva_skey                       IN       NUMBER
  , p_ret_forest_file_id             IN OUT   VARCHAR2
  , p_ret_hva_skey                   IN OUT   NUMBER
  , p_op_scope                       IN       VARCHAR2
  , p_amend_type                     IN       VARCHAR2
  , p_amend_skey                     IN OUT   VARCHAR2)
  IS
    p_fia_skey                         fta_ilrr_attributes.fia_skey%TYPE;
    p_rec_exists                       VARCHAR2(2);
    i                                  NUMBER := 0;

    v_ret_map_feature_id       NUMBER(10);

    CURSOR c_pfu_fia_recs
    IS
      SELECT fia_skey
        FROM fta_ilrr_attributes
       WHERE forest_file_id = p_ret_forest_file_id
         AND hva_skey IS NULL
         AND cb_skey IS NULL;

    CURSOR c_hva_fia_recs
    IS
      SELECT fia_skey
        FROM fta_ilrr_attributes
       WHERE hva_skey = p_ret_hva_skey
         AND cb_skey IS NULL;

  BEGIN
    p_rec_exists := 'Y';

    IF p_amend_type IN('HVA', 'RMF', 'RSA') THEN
      get_skeys(p_forest_file_id, p_hva_skey, p_ret_forest_file_id, p_ret_hva_skey, p_amend_type, p_amend_skey, v_ret_map_feature_id);
    ELSE
    -- these get set in get skeys - if get skeys isn't accessed they need to be set here
    -- option to overloading the mailine with in out variables which won't work with triggers
        p_ret_forest_file_id := p_forest_file_id;
        p_ret_hva_skey := p_hva_skey;
    END IF;
    -- get the fia_skey for the queue
    if p_hva_skey is not null then
        OPEN c_hva_fia_recs;

        LOOP
          FETCH  c_hva_fia_recs
            INTO p_fia_skey;

          i := i + 1;
          EXIT WHEN i = 1;
        END LOOP;

        IF c_hva_fia_recs%NOTFOUND THEN
          p_rec_exists := 'N';
          add_rec(p_forest_file_id,
                  p_hva_skey,
                  p_ret_forest_file_id,
                  p_ret_hva_skey,
                  p_op_scope,
                  p_amend_type,
                  p_amend_skey);
        END IF;

        CLOSE c_hva_fia_recs;
    end if;

    if p_ret_forest_file_id is not null
        and P_ret_hva_skey is null then -- forest_file

         OPEN c_pfu_fia_recs;

            LOOP
              FETCH  c_pfu_fia_recs
                INTO p_fia_skey;

              i := i + 1;
              EXIT WHEN i = 1;
            END LOOP;

            IF c_pfu_fia_recs%NOTFOUND THEN
              p_rec_exists := 'N';
              add_rec(p_forest_file_id,
                      p_hva_skey,
                      p_ret_forest_file_id,
                      p_ret_hva_skey,
                      p_op_scope,
                      p_amend_type,
                      p_amend_skey);
            END IF;

            CLOSE c_pfu_fia_recs;
      end if;


--call to queue
    IF p_rec_exists = 'Y' THEN

      message_to_queue('Update', p_op_scope, p_fia_skey, null);
    END IF;
  END update_rec;

/******************************************************************************
Purpose:   ADD GEOMETRY
Notes:

REVISIONS:
Ver        Date        Author           Description
---------  ----------  ---------------  ------------------------------------
           03/29/2012  Forte Consulting Created to process Geometry only events
******************************************************************************/
  PROCEDURE add_geom_rec(
    p_forest_file_id                 IN       VARCHAR2
  , p_hva_skey                       IN       NUMBER
  , p_ret_forest_file_id             IN OUT   VARCHAR2
  , p_ret_hva_skey                   IN OUT   NUMBER
  , p_op_scope                       IN       VARCHAR2
  , p_amend_type                     IN       VARCHAR2
  , p_amend_skey                     IN OUT   VARCHAR2
  , p_map_feature_id                 IN       NUMBER)
  IS
    TYPE loc_id_list IS TABLE OF VARCHAR2(25)
      INDEX BY BINARY_INTEGER;
    map_feature_id_lst         loc_id_list;
    p_fia_skey                 fta_ilrr_attributes.fia_skey%TYPE;
    i                          NUMBER := 0;

    v_ret_map_feature_id       NUMBER(10);

    CURSOR c_pfu_fia_recs
    IS
      SELECT fia_skey
        FROM fta_ilrr_attributes
       WHERE forest_file_id = p_ret_forest_file_id
         AND hva_skey IS NULL
         AND cb_skey IS NULL;

    CURSOR c_hva_fia_recs
    IS
      SELECT fia_skey
        FROM fta_ilrr_attributes
       WHERE hva_skey = p_ret_hva_skey
         AND cb_skey IS NULL;

  BEGIN

    --determine the Geometry unique identifier (ILRR Location IDs - ISSUING_AGENCY_LOCATION_ID)
    IF p_amend_type IN ('TAAP') THEN
       --Tenure Application changes
       SELECT map_feature_id
         BULK COLLECT INTO map_feature_id_lst
         FROM tenure_application_map_feature
        WHERE tenure_app_id = p_amend_skey
          AND forest_file_id = p_forest_file_id
          AND cut_block_id IS NULL;

       p_ret_forest_file_id := p_forest_file_id;
       p_ret_hva_skey := p_hva_skey;

    ELSIF p_amend_type IN ('TAIN') THEN
       --Tenure Application changes
       SELECT to_char(map_feature_id) || ' - Pending'
         BULK COLLECT INTO map_feature_id_lst
         FROM tenure_application_map_feature
        WHERE tenure_app_id = p_amend_skey
          AND forest_file_id = p_forest_file_id
          AND cut_block_id IS NULL;

       p_ret_forest_file_id := p_forest_file_id;
       p_ret_hva_skey := p_hva_skey;

    ELSIF p_amend_type in ('HVA','RMF','RSA') THEN
       --join for rec map feature
       get_skeys(p_forest_file_id, p_hva_skey, p_ret_forest_file_id, p_ret_hva_skey, p_amend_type, p_amend_skey, v_ret_map_feature_id);

       --need to determine whether Tenure Application State is APP or INB to include - Pending
       SELECT decode(ta.tenure_application_state_code
                       ,'INB',mf.map_feature_id || ' - Pending'
                       ,'APP',mf.map_feature_id
                             , null)
         BULK COLLECT INTO map_feature_id_lst
         FROM tenure_application_map_feature mf
              JOIN tenure_application ta ON mf.tenure_app_id = ta.tenure_app_id
        WHERE mf.map_feature_id = p_map_feature_id;

    ELSE
       --need to determine whether Tenure Application State is APP or INB to include - Pending
       SELECT decode(ta.tenure_application_state_code
                       ,'INB',mf.map_feature_id || ' - Pending'
                       ,'APP',mf.map_feature_id
                             , null)
         BULK COLLECT INTO map_feature_id_lst
         FROM tenure_application_map_feature mf
              JOIN tenure_application ta ON mf.tenure_app_id = ta.tenure_app_id
        WHERE mf.map_feature_id = p_map_feature_id;

       p_ret_forest_file_id := p_forest_file_id;
       p_ret_hva_skey := p_hva_skey;
    END IF;

    -- get the fia_skey for the queue
    if p_hva_skey is not null then
           OPEN c_hva_fia_recs;

                LOOP
                  FETCH  c_hva_fia_recs
                    INTO p_fia_skey;

                  i := i + 1;
                  EXIT WHEN i = 1;
                END LOOP;

                CLOSE c_hva_fia_recs;

    end if;

    if p_ret_forest_file_id is not null
       and p_ret_hva_skey is null then

       OPEN c_pfu_fia_recs;

            LOOP
              FETCH  c_pfu_fia_recs
                INTO p_fia_skey;

              i := i + 1;
              EXIT WHEN i = 1;
            END LOOP;

            CLOSE c_pfu_fia_recs;
    end if;

    FOR j in 1..map_feature_id_lst.count LOOP
       --only create Geometry event when MAP_FEATURE_ID exists
       if map_feature_id_lst(j) is not null and p_fia_skey is not null then
          --call to queue
          message_to_queue('Insert', p_op_scope, p_fia_skey, map_feature_id_lst(j));
       end if;
    END LOOP;
  END add_geom_rec;

/******************************************************************************
Purpose:   DELETE GEOMETRY
Notes:

REVISIONS:
Ver        Date        Author           Description
---------  ----------  ---------------  ------------------------------------
           03/29/2012  Forte Consulting Created to process Geometry only events
******************************************************************************/
  PROCEDURE delete_geom_rec(
    p_forest_file_id                 IN       VARCHAR2
  , p_hva_skey                       IN       NUMBER
  , p_ret_forest_file_id             IN OUT   VARCHAR2
  , p_ret_hva_skey                   IN OUT   NUMBER
  , p_op_scope                       IN       VARCHAR2
  , p_amend_type                     IN       VARCHAR2
  , p_amend_skey                     IN OUT   VARCHAR2
  , p_map_feature_id                 IN       NUMBER)
  IS
    TYPE loc_id_list IS TABLE OF VARCHAR2(25)
      INDEX BY BINARY_INTEGER;
    map_feature_id_lst         loc_id_list;
    p_fia_skey                 fta_ilrr_attributes.fia_skey%TYPE;
    i                          NUMBER := 0;

    v_ret_map_feature_id       NUMBER(10) := null;

    CURSOR c_pfu_fia_recs
    IS
      SELECT fia_skey
        FROM fta_ilrr_attributes
       WHERE forest_file_id = p_ret_forest_file_id
         AND hva_skey IS NULL
         AND cb_skey IS NULL;

    CURSOR c_hva_fia_recs
    IS
      SELECT fia_skey
        FROM fta_ilrr_attributes
       WHERE hva_skey = p_ret_hva_skey
         AND cb_skey IS NULL;

  BEGIN

    --determine the Geometry unique identifier (ILRR Location IDs - ISSUING_AGENCY_LOCATION_ID)
    IF p_amend_type IN ('TAIN') THEN
       --Tenure Application changes
       SELECT to_char(map_feature_id) || ' - Pending'
         BULK COLLECT INTO map_feature_id_lst
         FROM tenure_application_map_feature
        WHERE tenure_app_id = p_amend_skey
          AND forest_file_id = p_forest_file_id
          AND cut_block_id IS NULL;

       p_ret_forest_file_id := p_forest_file_id;
       p_ret_hva_skey := p_hva_skey;

    ELSIF p_amend_type in ('COMM','FRGP','FUPR','HVA','MNLC','RMAP','RMF','RSA') THEN
       --join for rec map feature
      get_skeys(p_forest_file_id, p_hva_skey, p_ret_forest_file_id, p_ret_hva_skey, p_amend_type, p_amend_skey, v_ret_map_feature_id);

       --the p_amend_type in ('HVA','RMF','RSA') already know the MAP_FEATURE_ID
       if v_ret_map_feature_id is null then
          v_ret_map_feature_id := p_map_feature_id;
       end if;

       --need to determine whether Tenure Application State is APP or INB to include - Pending
       SELECT decode(ta.tenure_application_state_code
                       ,'INB',mf.map_feature_id || ' - Pending'
                       ,'APP',mf.map_feature_id
                             , null)
         BULK COLLECT INTO map_feature_id_lst
         FROM tenure_application_map_feature mf
              JOIN tenure_application ta ON mf.tenure_app_id = ta.tenure_app_id
        WHERE mf.map_feature_id = v_ret_map_feature_id;

    ELSIF p_amend_type = 'RSCT' THEN
       --Road Section changes
       SELECT decode(ta.tenure_application_state_code
                                  ,'INB',mf.map_feature_id || ' - Pending'
                                  ,'APP',mf.map_feature_id
                                        , null)
         BULK COLLECT INTO map_feature_id_lst
         FROM
              (SELECT geo.map_feature_id
                 FROM road_section_geom geo
                WHERE geo.forest_file_id = p_forest_file_id and road_section_id = p_amend_skey
              UNION
               SELECT rsa.map_feature_id
                 FROM road_prmt_amend prm
                      JOIN road_section_amend_geom rsa ON prm.road_prmt_amend_skey = rsa.road_prmt_amend_skey
                WHERE prm.forest_file_id = p_forest_file_id and prm.road_section_id = p_amend_skey
                  AND prm.amend_status_st = 'PND') mf
              JOIN tenure_application_map_feature tmf ON mf.map_feature_id = tmf.map_feature_id
              JOIN tenure_application ta ON tmf.tenure_app_id = ta.tenure_app_id;

       p_ret_forest_file_id := p_forest_file_id;
       p_ret_hva_skey := p_hva_skey;

    ELSIF p_amend_type = 'HARV' THEN
       --Harvesting Authority changes with no Cutting Permit ID
       SELECT decode(ta.tenure_application_state_code
                                  ,'INB',mf.map_feature_id || ' - Pending'
                                  ,'APP',mf.map_feature_id
                                        , null)
         BULK COLLECT INTO map_feature_id_lst
         FROM
              (SELECT geo.map_feature_id
                 FROM harvest_authority_geom geo
                WHERE geo.hva_skey = p_hva_skey
              UNION
               SELECT hvaa.map_feature_id
                 FROM harvest_authority_amend_geom hvaa
                WHERE hvaa.hva_skey = p_hva_skey) mf
              JOIN tenure_application_map_feature tmf ON mf.map_feature_id = tmf.map_feature_id
              JOIN tenure_application ta ON tmf.tenure_app_id = ta.tenure_app_id;

       p_ret_forest_file_id := p_forest_file_id;
       --reset p_ret_hva_skey as not required for HARVESTING_AUTHORITY records with no CUTTING_PERMIT_ID
       p_ret_hva_skey := null;

    ELSE
       --need to determine whether Tenure Application State is APP or INB to include - Pending
       SELECT decode(ta.tenure_application_state_code
                       ,'INB',mf.map_feature_id || ' - Pending'
                       ,'APP',mf.map_feature_id
                             , null)
         BULK COLLECT INTO map_feature_id_lst
         FROM tenure_application_map_feature mf
              JOIN tenure_application ta ON mf.tenure_app_id = ta.tenure_app_id
        WHERE mf.map_feature_id = p_map_feature_id;

       p_ret_forest_file_id := p_forest_file_id;
       p_ret_hva_skey := p_hva_skey;
    END IF;

    -- get the fia_skey for the queue
    if p_ret_hva_skey is not null then

            OPEN c_hva_fia_recs;

            i := 0;

            LOOP
              FETCH  c_hva_fia_recs
                INTO p_fia_skey;

              i := i + 1;
              EXIT WHEN i = 1;
            END LOOP;

            CLOSE c_hva_fia_recs;
    end if;

    if (p_ret_forest_file_id is not null and p_ret_hva_skey is null) or
       (p_ret_forest_file_id is not null and p_ret_hva_skey is not null and p_fia_skey is null)
       then

       OPEN c_pfu_fia_recs;

         i := 0;

            LOOP
              FETCH  c_pfu_fia_recs
                INTO p_fia_skey;

              i := i + 1;
              EXIT WHEN i = 1;
            END LOOP;

            CLOSE c_pfu_fia_recs;
    end if;

    FOR j in 1..map_feature_id_lst.count LOOP
       --only create Geometry event when MAP_FEATURE_ID exists
       if map_feature_id_lst(j) is not null and p_fia_skey is not null then
          --call to queue
          message_to_queue('Delete', p_op_scope, p_fia_skey, map_feature_id_lst(j));
       end if;
    END LOOP;
  END delete_geom_rec;

/******************************************************************************
Purpose:   UPDATE GEOMETRY
Notes:

REVISIONS:
Ver        Date        Author           Description
---------  ----------  ---------------  ------------------------------------
           03/29/2012  Forte Consulting Created to process Geometry only events
******************************************************************************/
  PROCEDURE update_geom_rec(
    p_forest_file_id                 IN       VARCHAR2
  , p_hva_skey                       IN       NUMBER
  , p_ret_forest_file_id             IN OUT   VARCHAR2
  , p_ret_hva_skey                   IN OUT   NUMBER
  , p_op_scope                       IN       VARCHAR2
  , p_amend_type                     IN       VARCHAR2
  , p_amend_skey                     IN OUT   VARCHAR2
  , p_map_feature_id                 IN       NUMBER)
  IS
    TYPE loc_id_list IS TABLE OF VARCHAR2(25)
      INDEX BY BINARY_INTEGER;
    map_feature_id_lst         loc_id_list;
    p_fia_skey                 fta_ilrr_attributes.fia_skey%TYPE;
    i                          NUMBER := 0;

    v_ret_map_feature_id       NUMBER(10);


    CURSOR c_pfu_fia_recs
    IS
      SELECT fia_skey
        FROM fta_ilrr_attributes
       WHERE forest_file_id = p_ret_forest_file_id
         AND hva_skey IS NULL
         AND cb_skey IS NULL;

    CURSOR c_hva_fia_recs
    IS
      SELECT fia_skey
        FROM fta_ilrr_attributes
       WHERE hva_skey = p_ret_hva_skey
         AND cb_skey IS NULL;

  BEGIN

    --determine the Geometry unique identifier (ILRR Location IDs - ISSUING_AGENCY_LOCATION_ID)
    IF p_amend_type in ('HVA','RMF','RSA') THEN
       --join for rec map feature
      get_skeys(p_forest_file_id, p_hva_skey, p_ret_forest_file_id, p_ret_hva_skey, p_amend_type, p_amend_skey, v_ret_map_feature_id);

       --need to determine whether Tenure Application State is APP or INB to include - Pending
       SELECT decode(ta.tenure_application_state_code
                       ,'INB',mf.map_feature_id || ' - Pending'
                       ,'APP',mf.map_feature_id
                             , null)
         BULK COLLECT INTO map_feature_id_lst
         FROM tenure_application_map_feature mf
              JOIN tenure_application ta ON mf.tenure_app_id = ta.tenure_app_id
        WHERE mf.map_feature_id = p_map_feature_id;

    ELSIF p_amend_type = 'RSCT' THEN
       --Road Section changes
       SELECT decode(ta.tenure_application_state_code
                                  ,'INB',mf.map_feature_id || ' - Pending'
                                  ,'APP',mf.map_feature_id
                                        , null)
         BULK COLLECT INTO map_feature_id_lst
         FROM
              (SELECT geo.map_feature_id
                 FROM road_section_geom geo
                WHERE geo.forest_file_id = p_forest_file_id and road_section_id = p_amend_skey
              UNION
               SELECT rsa.map_feature_id
                 FROM road_prmt_amend prm
                      JOIN road_section_amend_geom rsa ON prm.road_prmt_amend_skey = rsa.road_prmt_amend_skey
                WHERE prm.forest_file_id = p_forest_file_id and prm.road_section_id = p_amend_skey
                  AND prm.amend_status_st = 'PND') mf
              JOIN tenure_application_map_feature tmf ON mf.map_feature_id = tmf.map_feature_id
              JOIN tenure_application ta ON tmf.tenure_app_id = ta.tenure_app_id;

       p_ret_forest_file_id := p_forest_file_id;
       p_ret_hva_skey := p_hva_skey;

    ELSE
       --need to determine whether Tenure Application State is APP or INB to include - Pending
       SELECT decode(ta.tenure_application_state_code
                       ,'INB',mf.map_feature_id || ' - Pending'
                       ,'APP',mf.map_feature_id
                             , null)
         BULK COLLECT INTO map_feature_id_lst
         FROM tenure_application_map_feature mf
              JOIN tenure_application ta ON mf.tenure_app_id = ta.tenure_app_id
        WHERE mf.map_feature_id = p_map_feature_id;

       p_ret_forest_file_id := p_forest_file_id;
       p_ret_hva_skey := p_hva_skey;
    END IF;

    -- get the fia_skey for the queue
    if p_hva_skey is not null then
        OPEN c_hva_fia_recs;

        i := 0;

        LOOP
          FETCH  c_hva_fia_recs
            INTO p_fia_skey;

          i := i + 1;
          EXIT WHEN i = 1;
        END LOOP;

        CLOSE c_hva_fia_recs;
    end if;

    if (p_ret_forest_file_id is not null and p_ret_hva_skey is null) or
       (p_ret_forest_file_id is not null and p_ret_hva_skey is not null and p_fia_skey is null)
       then

         OPEN c_pfu_fia_recs;

           i := 0;

            LOOP
              FETCH  c_pfu_fia_recs
                INTO p_fia_skey;

              i := i + 1;
              EXIT WHEN i = 1;
            END LOOP;

            CLOSE c_pfu_fia_recs;
    end if;

    FOR j in 1..map_feature_id_lst.count LOOP
       --only create Geometry event when MAP_FEATURE_ID exists
       if map_feature_id_lst(j) is not null and p_fia_skey is not null then
          --call to queue
          message_to_queue('Update', p_op_scope, p_fia_skey, map_feature_id_lst(j));
       end if;
    END LOOP;
  END update_geom_rec;

/******************************************************************************
Purpose:   Mainline
Notes:     Interface for the package.

REVISIONS:
Ver        Date        Author           Description
---------  ----------  ---------------  ------------------------------------
01_00_05   03/09/2006  A. Stephenson    Amended Existing
           03/29/2012  Forte Consulting Amended to remove Cut Block processing and include Geometry only events
******************************************************************************/
  PROCEDURE mainline(
    p_transaction_type               IN       VARCHAR2
  , p_forest_file_id                 IN       VARCHAR2
  , p_hva_skey                       IN       NUMBER
  , p_op_scope                       IN       VARCHAR2
  , p_amend_type                     IN       VARCHAR2
  , p_amend_skey                     IN       VARCHAR2
  , p_map_feature_id                 IN       NUMBER)
  IS
    v_amend_skey                       VARCHAR2(100);
    v_ret_forest_file_id               VARCHAR2(15);
    v_ret_hva_skey                     NUMBER(10);
  BEGIN
    v_amend_skey := p_amend_skey;

    IF p_op_scope = 'Geometry' and p_transaction_type = 'Insert' THEN
      add_geom_rec(p_forest_file_id, p_hva_skey, v_ret_forest_file_id, v_ret_hva_skey,
                   p_op_scope, p_amend_type, v_amend_skey, p_map_feature_id);
    ELSIF p_op_scope = 'Geometry' and p_transaction_type = 'Update' THEN
      update_geom_rec(p_forest_file_id, p_hva_skey, v_ret_forest_file_id, v_ret_hva_skey,
                      p_op_scope, p_amend_type, v_amend_skey, p_map_feature_id);
    ELSIF p_op_scope = 'Geometry' and p_transaction_type = 'Delete' THEN
      delete_geom_rec(p_forest_file_id, p_hva_skey, v_ret_forest_file_id, v_ret_hva_skey,
                      p_op_scope, p_amend_type, v_amend_skey, p_map_feature_id);
    ELSIF p_transaction_type = 'Insert' THEN
      add_rec(p_forest_file_id, p_hva_skey, v_ret_forest_file_id, v_ret_hva_skey,
                p_op_scope, p_amend_type, v_amend_skey);
    ELSIF p_transaction_type = 'Update' THEN
      update_rec(p_forest_file_id, p_hva_skey, v_ret_forest_file_id, v_ret_hva_skey,
                p_op_scope, p_amend_type, v_amend_skey);
    ELSE
      --action is delete
      delete_rec(p_forest_file_id, p_hva_skey, v_ret_forest_file_id, v_ret_hva_skey,
                p_op_scope, p_amend_type, v_amend_skey);
    END IF;
  END mainline;
END fta_ilrr_acquirer_plugin_pkg;
/

  CREATE OR REPLACE EDITIONABLE PACKAGE "THE"."PKG_SIL_DATE_CONVERSION" AS
/******************************************************************************
    Package:    PKG_SIL_DATE_CONVERSION

    Purpose:     Procedures to convert date characteristics to either dates from
                 characters or from characters to dates based on passed parms.
                 If any raised error is wanted to be hidden then pass the
                 p_error_ind = 'N' and it will hide any Oracle error conditions.
                 If the date format is not provided for character conversion then
                 the format of 'YYYY-MM-DD' will be used.

    Revision History

    Person             Date        Comments
    -----------------  ----------  --------------------------------
    PDS                2001-10-15  Created
    R.A.Robb           2004-05-14  Added CONVERT_TO_CHAR_TRUNC_TIME and
                                   set defaults for all

******************************************************************************/
    FUNCTION CONVERT_TO_CHAR ( p_value        IN     DATE
                             , p_format       IN     VARCHAR2 DEFAULT 'YYYY-MM-DD'
                             , p_error_ind    IN     VARCHAR2 DEFAULT 'Y') RETURN VARCHAR2;

    FUNCTION CONVERT_TO_CHAR_TRUNC_TIME
                             ( p_value        IN     DATE
                             , p_date_format  IN     VARCHAR2 DEFAULT 'YYYY-MM-DD'
                             , p_time_format  IN     VARCHAR2 DEFAULT 'HH:MI:SS AM'
                             , p_error_ind    IN     VARCHAR2 DEFAULT 'Y') RETURN VARCHAR2;

    FUNCTION CONVERT_TO_DATE (p_value           IN VARCHAR2
                            , p_error_ind       IN VARCHAR2 DEFAULT 'Y') RETURN DATE;

END PKG_SIL_DATE_CONVERSION;
/
CREATE OR REPLACE EDITIONABLE PACKAGE BODY "THE"."PKG_SIL_DATE_CONVERSION" AS

    FUNCTION CONVERT_TO_CHAR_TRUNC_TIME
                             ( p_value        IN     DATE
                             , p_date_format  IN     VARCHAR2 DEFAULT 'YYYY-MM-DD'
                             , p_time_format  IN     VARCHAR2 DEFAULT 'HH:MI:SS AM'
                             , p_error_ind    IN     VARCHAR2 DEFAULT 'Y') RETURN VARCHAR2 IS
       v_return_value   VARCHAR2(50) := NULL;
    BEGIN
       --Don't return time portion if date is same as trunc(date)
       IF TRUNC(p_value) = p_value THEN
          v_return_value := TO_CHAR(p_value,p_date_format);
       ELSE
          v_return_value := TO_CHAR(p_value,p_date_format||' '||p_time_format);
       END IF;
       RETURN (v_return_value);
    EXCEPTION
      WHEN OTHERS THEN
        IF p_error_ind = 'Y' THEN
           RAISE;
        ELSE
           RETURN (NULL);
        END IF;

    END CONVERT_TO_CHAR_TRUNC_TIME;

    FUNCTION CONVERT_TO_CHAR ( p_value        IN     DATE
                             , p_format       IN     VARCHAR2 DEFAULT 'YYYY-MM-DD'
                             , p_error_ind    IN     VARCHAR2 DEFAULT 'Y') RETURN VARCHAR2 IS
       v_date_format    VARCHAR2(50) := 'YYYY-MM-DD';
       p_return_value   VARCHAR2(50) := NULL;
    BEGIN
       IF p_format IS NOT NULL THEN
          v_date_format := p_format;
       ELSE
          v_date_format := 'YYYY-MM-DD';
       END IF;
       p_return_value := TO_CHAR(p_value, v_date_format);
       RETURN (p_return_value);
    EXCEPTION
      WHEN OTHERS THEN
        IF p_error_ind = 'Y' THEN
           RAISE;
        ELSE
           RETURN (NULL);
        END IF;
    END CONVERT_TO_CHAR;

    FUNCTION CONVERT_TO_DATE (p_value           IN VARCHAR2
                            , p_error_ind       IN VARCHAR2 DEFAULT 'Y') RETURN DATE IS
      p_return_date   DATE  := NULL;
      dateFormat      VARCHAR2(50);
    BEGIN
      IF LENGTH(p_value) > 10 THEN
        dateFormat := 'YYYY-MM-DD HH24:MI:SS';
      ELSE
        dateFormat := 'YYYY-MM-DD';
      END IF;

      p_return_date := TO_DATE(p_value, dateFormat);
      RETURN (p_return_date);
    EXCEPTION
      WHEN OTHERS THEN
        IF p_error_ind = 'Y' THEN
           RAISE;
        ELSE
           RETURN (NULL);
        END IF;
    END CONVERT_TO_DATE;
END PKG_SIL_DATE_CONVERSION ;
/

