CREATE OR REPLACE EDITIONABLE PACKAGE BODY "THE"."PKG_ECAS_AUDIT" AS

/******************************************************************************
    Procedure:  UPDATE_EAE_COMMENT

    Purpose:    Updates the Audit Record with the clob value.
******************************************************************************/

  PROCEDURE UPDATE_EAE_COMMENT(P_ECAS_ID                 IN ECAS_AUDIT_EVENT.ECAS_ID%TYPE
                               , P_AUDIT_EVENT_ID          IN VARCHAR2
                               , P_EAE_COMMENTS            IN CLOB
                               , P_USERID                  IN VARCHAR2
                               , P_ERROR_MESSAGE           IN OUT VARCHAR2)
  IS

  l_table_name        VARCHAR2(50) := '';
  l_eae_comment       CLOB;
  l_ads_comment       CLOB;


  BEGIN

    IF P_EAE_COMMENTS IS NOT NULL THEN
      l_table_name := 'ECAS_AUDIT_COMMENT';
      BEGIN

        SELECT AUDIT_COMMENT
        INTO l_eae_comment
        FROM ECAS_AUDIT_COMMENT
        WHERE AUDIT_EVENT_ID = to_number(P_AUDIT_EVENT_ID)
        AND ECAS_ID = P_ECAS_ID
        FOR UPDATE;

		l_eae_comment := l_eae_comment || ' ';

        dbms_lob.writeappend(l_eae_comment, LENGTH(P_EAE_COMMENTS), P_EAE_COMMENTS);
      EXCEPTION
        WHEN NO_DATA_FOUND THEN
          l_eae_comment := EMPTY_CLOB();

          INSERT INTO ECAS_AUDIT_COMMENT (
            ecas_id,
            audit_event_id,
            audit_comment
          ) VALUES (
            p_ecas_id,
            to_number(p_audit_event_id),
            to_clob(p_eae_comments)
          );

      END;
    END IF;


    l_table_name := 'ADS_COMMENT';

    BEGIN
      SELECT APPRAISAL_COMMENT
      INTO l_ads_comment
      FROM ADS_COMMENT
      WHERE ECAS_ID = P_ECAS_ID;
    EXCEPTION
      WHEN NO_DATA_FOUND THEN
        l_ads_comment := EMPTY_CLOB();
    END;

    IF dbms_lob.getlength(l_ads_comment) > 0 THEN
      BEGIN

        --Grab the comment again...
        SELECT AUDIT_COMMENT
        INTO l_eae_comment
        FROM ECAS_AUDIT_COMMENT
        WHERE AUDIT_EVENT_ID = to_number(P_AUDIT_EVENT_ID)
        AND ECAS_ID = P_ECAS_ID
        FOR UPDATE;

        l_ads_comment := chr(10) ||to_char(sysdate,'MM/dd/yyyy')|| ' : ' || P_USERID || ' ' || l_ads_comment || '  ';
        dbms_lob.writeappend(l_eae_comment, LENGTH(l_ads_comment),l_ads_comment );
      --  dbms_lob.append(l_eae_comment,l_ads_comment);
        l_ads_comment := NULL;

      EXCEPTION
        WHEN NO_DATA_FOUND THEN
          INSERT INTO ECAS_AUDIT_COMMENT (
            ecas_id,
            audit_event_id,
            audit_comment
          ) VALUES (
            p_ecas_id,
            to_number(p_audit_event_id),
            l_ads_comment
          );

      END;
    END IF;


  EXCEPTION
    WHEN TOO_MANY_ROWS THEN
      P_ERROR_MESSAGE := P_ERROR_MESSAGE || 'ecas.web.usr.database.record.toomany:PKG_ECAS_AUDIT,UPDATE_EAE_COMMENT,'||TRIM(l_table_name)||','||SQLCODE||';';
    WHEN DUP_VAL_ON_INDEX THEN
      P_ERROR_MESSAGE := P_ERROR_MESSAGE || 'ecas.web.usr.database.record.duplicate:PKG_ECAS_AUDIT,UPDATE_EAE_COMMENT,'||TRIM(l_table_name)||','||SQLCODE||';';
    WHEN NO_DATA_FOUND THEN
      P_ERROR_MESSAGE := P_ERROR_MESSAGE || 'ecas.web.usr.database.record.invalid:PKG_ECAS_AUDIT,UPDATE_EAE_COMMENT,'||TRIM(l_table_name)||';';
    WHEN OTHERS THEN
      P_ERROR_MESSAGE := P_ERROR_MESSAGE || 'ecas.web.usr.database.unexpected:PKG_ECAS_AUDIT,UPDATE_EAE_COMMENT,'||SQLCODE||','||SQLERRM||';';

  END UPDATE_EAE_COMMENT;


/******************************************************************************
    Procedure:  GET_USERID

    Purpose:    Retrieves the userid for a given ECAS_ID and ECAS_ACTION_CODE
                on a given calendar day.
******************************************************************************/

  PROCEDURE GET_USERID(P_USERID                  IN OUT ECAS_AUDIT_EVENT.ENTRY_USERID%TYPE
                     , P_ECAS_ACTION_CODE        IN ECAS_AUDIT_EVENT.ECAS_ACTION_CODE%TYPE
                     , P_ECAS_ID                 IN ECAS_AUDIT_EVENT.ECAS_ID%TYPE
                     , P_TIMESTAMP               IN ECAS_AUDIT_EVENT.ENTRY_TIMESTAMP%TYPE
                     , P_ERROR_MESSAGE           IN OUT VARCHAR2)
  IS

    l_table_name             VARCHAR2(50);

    CURSOR c_userid IS
    SELECT ENTRY_USERID
    FROM ECAS_AUDIT_EVENT
    WHERE ECAS_ID = P_ECAS_ID
    AND ECAS_ACTION_CODE = P_ECAS_ACTION_CODE
    AND Pkg_Sil_Date_Conversion.CONVERT_TO_CHAR(ENTRY_TIMESTAMP,'YYYY-MM-DD', 'Y')
      = Pkg_Sil_Date_Conversion.CONVERT_TO_CHAR(P_TIMESTAMP,'YYYY-MM-DD', 'Y')
    AND ENTRY_TIMESTAMP = (SELECT MAX(ENTRY_TIMESTAMP)
                           FROM ECAS_AUDIT_EVENT
                           WHERE ECAS_ID = P_ECAS_ID
                           AND ECAS_ACTION_CODE = P_ECAS_ACTION_CODE);

  BEGIN

    l_table_name := 'ECAS_AUDIT_EVENT';

    OPEN c_userid;
    FETCH c_userid INTO P_USERID;
    CLOSE c_userid;

  EXCEPTION
    WHEN TOO_MANY_ROWS THEN
      P_ERROR_MESSAGE := P_ERROR_MESSAGE || 'ecas.web.usr.database.record.toomany:PKG_ECAS_AUDIT,GET_USERID,'||TRIM(l_table_name)||','||SQLCODE||';';
    WHEN DUP_VAL_ON_INDEX THEN
      P_ERROR_MESSAGE := P_ERROR_MESSAGE || 'ecas.web.usr.database.record.duplicate:PKG_ECAS_AUDIT,GET_USERID,'||TRIM(l_table_name)||','||SQLCODE||';';
    WHEN NO_DATA_FOUND THEN
      P_ERROR_MESSAGE := P_ERROR_MESSAGE || 'ecas.web.usr.database.record.invalid:PKG_ECAS_AUDIT,GET_USERID,'||TRIM(l_table_name)||';';
    WHEN OTHERS THEN
      P_ERROR_MESSAGE := P_ERROR_MESSAGE || 'ecas.web.usr.database.unexpected:PKG_ECAS_AUDIT,GET_USERID,'||SQLCODE||','||SQLERRM||';';

  END GET_USERID;

/******************************************************************************
    Procedure:  CHECK_EVENT_ID

    Purpose:    Tests to see if an AUDIT_EVENT_ID already exists for a given
              ECAS_ID, ECAS_ACTION_CODE and USERID on a given calendar day.
******************************************************************************/

  PROCEDURE CHECK_EVENT_ID(P_AUDIT_EVENT_ID     IN OUT ECAS_AUDIT_EVENT.AUDIT_EVENT_ID%TYPE
                         , P_ECAS_ID            IN ECAS_AUDIT_EVENT.ECAS_ID%TYPE
                         , P_ECAS_ACTION_CODE   IN ECAS_AUDIT_EVENT.ECAS_ACTION_CODE%TYPE
                         , P_USERID             IN ECAS_AUDIT_EVENT.ENTRY_USERID%TYPE
                         , P_TIMESTAMP          IN ECAS_AUDIT_EVENT.ENTRY_TIMESTAMP%TYPE
                         , P_ERROR_MESSAGE      IN OUT VARCHAR2)
  IS

    l_table_name             VARCHAR2(50);

    CURSOR c_event_id IS
    SELECT AUDIT_EVENT_ID
    FROM ECAS_AUDIT_EVENT
    WHERE ECAS_ID = P_ECAS_ID
    AND ENTRY_USERID = P_USERID
    AND ECAS_ACTION_CODE = P_ECAS_ACTION_CODE
    AND Pkg_Sil_Date_Conversion.CONVERT_TO_CHAR(ENTRY_TIMESTAMP,'YYYY-MM-DD', 'Y')
        = Pkg_Sil_Date_Conversion.CONVERT_TO_CHAR(P_TIMESTAMP,'YYYY-MM-DD', 'Y')
        ORDER BY AUDIT_EVENT_ID DESC --LISA
        ;

  BEGIN

    l_table_name := 'ECAS_AUDIT_EVENT';
    P_AUDIT_EVENT_ID := NULL;

    OPEN c_event_id;
    FETCH c_event_id INTO P_AUDIT_EVENT_ID;
    CLOSE c_event_id;

  EXCEPTION
    WHEN TOO_MANY_ROWS THEN
      P_ERROR_MESSAGE := P_ERROR_MESSAGE || 'ecas.web.usr.database.record.toomany:PKG_ECAS_AUDIT,CHECK_EVENT_ID,'||TRIM(l_table_name)||','||SQLCODE||';';
    WHEN DUP_VAL_ON_INDEX THEN
      P_ERROR_MESSAGE := P_ERROR_MESSAGE || 'ecas.web.usr.database.record.duplicate:PKG_ECAS_AUDIT,CHECK_EVENT_ID,'||TRIM(l_table_name)||','||SQLCODE||';';
    WHEN NO_DATA_FOUND THEN
      P_ERROR_MESSAGE := P_ERROR_MESSAGE || 'ecas.web.usr.database.record.invalid:PKG_ECAS_AUDIT,CHECK_EVENT_ID,'||TRIM(l_table_name)||';';
    WHEN OTHERS THEN
      P_ERROR_MESSAGE := P_ERROR_MESSAGE || 'ecas.web.usr.database.unexpected:PKG_ECAS_AUDIT,CHECK_EVENT_ID,'||SQLCODE||','||SQLERRM||';';

  END CHECK_EVENT_ID;

/******************************************************************************
    Procedure:  ADD_AUDIT_HEADER_WITH_COMMENT

    Purpose:    To add a record to the ECAS_AUDIT_EVENT table, and also copying the ADS.APPRAISAL_COMMENT.
    Date:      By:      REASON:
    March 04/05 LM      Created.

******************************************************************************/

  PROCEDURE ADD_AUDIT_HEADER_WITH_COMMENT(P_ECAS_ID           IN ECAS_AUDIT_EVENT.ECAS_ID%TYPE
                                         , P_ECAS_ACTION_CODE  IN ECAS_AUDIT_EVENT.ECAS_ACTION_CODE%TYPE
                                         , P_USERID            IN ECAS_AUDIT_EVENT.ENTRY_USERID%TYPE
                                         , P_TIMESTAMP         IN ECAS_AUDIT_EVENT.ENTRY_TIMESTAMP%TYPE
                                         , P_EMAIL_SENT_IND    IN ECAS_AUDIT_EVENT.EMAIL_SENT_IND%TYPE
                                         , P_ERROR_MESSAGE     IN OUT VARCHAR2)
  IS

    l_table_name             VARCHAR2(50);
    l_audit_event_id         ECAS_AUDIT_EVENT.AUDIT_EVENT_ID%TYPE;
    l_status                 APPRAISAL_DATA_SUBMISSION.APPRAISAL_STATUS_CODE%TYPE;

    CURSOR c_status IS
    SELECT APPRAISAL_STATUS_CODE
    FROM APPRAISAL_DATA_SUBMISSION
    WHERE ECAS_ID = P_ECAS_ID;

    CURSOR c_event_id IS
    SELECT AUDIT_EVENT_ID
    FROM ECAS_AUDIT_EVENT
    WHERE ECAS_ID = P_ECAS_ID
    AND ENTRY_USERID = P_USERID
    AND ECAS_ACTION_CODE = P_ECAS_ACTION_CODE
    AND Pkg_Sil_Date_Conversion.CONVERT_TO_CHAR(ENTRY_TIMESTAMP,'YYYY-MM-DD', 'Y')
        = Pkg_Sil_Date_Conversion.CONVERT_TO_CHAR(P_TIMESTAMP,'YYYY-MM-DD', 'Y')
    ORDER BY AUDIT_EVENT_ID DESC --LISA
        ;

  BEGIN

    l_table_name := 'ECAS_AUDIT_EVENT';

    OPEN c_status;
    FETCH c_status INTO l_status;
    CLOSE c_status;

    --We want to insert records for all types, to handle the admin updates on ref info
    --IF ((l_status != 'DFT') OR (P_ECAS_ACTION_CODE = 'ADD')) THEN
      OPEN c_event_id;
      FETCH c_event_id INTO l_audit_event_id;

      IF (c_event_id%NOTFOUND AND P_ECAS_ACTION_CODE = 'UPD') OR
         (c_event_id%NOTFOUND AND P_ECAS_ACTION_CODE = 'DEL') OR
         (c_event_id%NOTFOUND AND P_ECAS_ACTION_CODE = 'UPT') OR
         P_ECAS_ACTION_CODE NOT IN ('UPD','DEL', 'UPT') THEN
        SELECT ECAS_AUDIT_EVENT_SEQ.NEXTVAL
        INTO l_audit_event_id
        FROM dual;

        INSERT INTO ECAS_AUDIT_EVENT(AUDIT_EVENT_ID
                                   , ECAS_ACTION_CODE
                                   , ECAS_ID
                                   , ENTRY_TIMESTAMP
                                   , ENTRY_USERID
                                   , EMAIL_SENT_IND)
        VALUES(l_audit_event_id
             , P_ECAS_ACTION_CODE
             , P_ECAS_ID
             , SYSDATE
             , P_USERID
             , P_EMAIL_SENT_IND);

        --Now copy over the ADS.APPRAISAL_COMMENT
        UPDATE_EAE_COMMENT(P_ECAS_ID
                         , l_audit_event_id
                         , NULL
                         , P_USERID
                         , P_ERROR_MESSAGE);

      ELSE
        UPDATE ECAS_AUDIT_EVENT
        SET ENTRY_TIMESTAMP = SYSDATE
        WHERE ECAS_ID = P_ECAS_ID
        AND AUDIT_EVENT_ID = l_audit_event_id
        AND ENTRY_USERID = P_USERID
        AND ECAS_ACTION_CODE = P_ECAS_ACTION_CODE
        AND Pkg_Sil_Date_Conversion.CONVERT_TO_CHAR(ENTRY_TIMESTAMP,'YYYY-MM-DD', 'Y')
           = Pkg_Sil_Date_Conversion.CONVERT_TO_CHAR(P_TIMESTAMP,'YYYY-MM-DD', 'Y');

        UPDATE_EAE_COMMENT(P_ECAS_ID
                         , l_audit_event_id
                         , NULL
                         , P_USERID
                         , P_ERROR_MESSAGE);

      END IF;
      CLOSE c_event_id;
    --END IF;

  EXCEPTION
    WHEN TOO_MANY_ROWS THEN
      P_ERROR_MESSAGE := P_ERROR_MESSAGE || 'ecas.web.usr.database.record.toomany:PKG_ECAS_AUDIT,ADD_AUDIT_HEADER_WITH_COMMENT,'||TRIM(l_table_name)||','||SQLCODE||';';
    WHEN DUP_VAL_ON_INDEX THEN
      P_ERROR_MESSAGE := P_ERROR_MESSAGE || 'ecas.web.usr.database.record.duplicate:PKG_ECAS_AUDIT,ADD_AUDIT_HEADER_WITH_COMMENT,'||TRIM(l_table_name)||','||SQLCODE||';';
    WHEN NO_DATA_FOUND THEN
      P_ERROR_MESSAGE := P_ERROR_MESSAGE || 'ecas.web.usr.database.record.invalid:PKG_ECAS_AUDIT,ADD_AUDIT_HEADER_WITH_COMMENT,'||TRIM(l_table_name)||';';
    WHEN OTHERS THEN
      P_ERROR_MESSAGE := P_ERROR_MESSAGE || 'ecas.web.usr.database.unexpected:PKG_ECAS_AUDIT,ADD_AUDIT_HEADER_WITH_COMMENT,'||SQLCODE||','||SQLERRM||';';

  END ADD_AUDIT_HEADER_WITH_COMMENT;


/******************************************************************************
    Procedure:  ADD_AUDIT_HEADER

    Purpose:    To add a record to the ECAS_AUDIT_EVENT table.
    Date:      By:      REASON:
    June 24/03 LM       Changed to insert a new event all the time except for UPDATE
    Mar 6/05 JM         Added P_INCLUDE_DRAFT for updates that need to be tracked in Draft mode (ie Admin update on ref info).
******************************************************************************/

  PROCEDURE ADD_AUDIT_HEADER(P_ECAS_ID           IN ECAS_AUDIT_EVENT.ECAS_ID%TYPE
                           , P_ECAS_ACTION_CODE  IN ECAS_AUDIT_EVENT.ECAS_ACTION_CODE%TYPE
                           , P_USERID            IN ECAS_AUDIT_EVENT.ENTRY_USERID%TYPE
                           , P_TIMESTAMP         IN ECAS_AUDIT_EVENT.ENTRY_TIMESTAMP%TYPE
                           , P_EMAIL_SENT_IND    IN ECAS_AUDIT_EVENT.EMAIL_SENT_IND%TYPE
                           , P_ERROR_MESSAGE     IN OUT VARCHAR2
                           , P_INCLUDE_DRAFT     IN VARCHAR2 DEFAULT 'N')
  IS

    l_table_name             VARCHAR2(50);
    l_audit_event_id         ECAS_AUDIT_EVENT.AUDIT_EVENT_ID%TYPE;
    l_status                 APPRAISAL_DATA_SUBMISSION.APPRAISAL_STATUS_CODE%TYPE;

    CURSOR c_status IS
    SELECT APPRAISAL_STATUS_CODE
    FROM APPRAISAL_DATA_SUBMISSION
    WHERE ECAS_ID = P_ECAS_ID;

    CURSOR c_event_id IS
    SELECT AUDIT_EVENT_ID
    FROM ECAS_AUDIT_EVENT
    WHERE ECAS_ID = P_ECAS_ID
    AND ENTRY_USERID = P_USERID
    AND ECAS_ACTION_CODE = P_ECAS_ACTION_CODE
    AND Pkg_Sil_Date_Conversion.CONVERT_TO_CHAR(ENTRY_TIMESTAMP,'YYYY-MM-DD', 'Y')
        = Pkg_Sil_Date_Conversion.CONVERT_TO_CHAR(P_TIMESTAMP,'YYYY-MM-DD', 'Y')
                ORDER BY AUDIT_EVENT_ID DESC --LISA
        ;

  BEGIN

    l_table_name := 'ECAS_AUDIT_EVENT';

    OPEN c_status;
    FETCH c_status INTO l_status;
    CLOSE c_status;

    IF ((l_status != 'DFT') OR (P_ECAS_ACTION_CODE = 'ADD')) OR P_INCLUDE_DRAFT = 'Y' THEN
      OPEN c_event_id;
      FETCH c_event_id INTO l_audit_event_id;

      IF (c_event_id%NOTFOUND AND P_ECAS_ACTION_CODE = 'UPD') OR
         (c_event_id%NOTFOUND AND P_ECAS_ACTION_CODE = 'DEL') OR
         (c_event_id%NOTFOUND AND P_ECAS_ACTION_CODE = 'UPT') OR
         P_ECAS_ACTION_CODE NOT IN ('UPD', 'UPT' ,'DEL') THEN
        SELECT ECAS_AUDIT_EVENT_SEQ.NEXTVAL
        INTO l_audit_event_id
        FROM dual;

        INSERT INTO ECAS_AUDIT_EVENT(AUDIT_EVENT_ID
                                   , ECAS_ACTION_CODE
                                   , ECAS_ID
                                   , ENTRY_TIMESTAMP
                                   , ENTRY_USERID
                                   , EMAIL_SENT_IND)
        VALUES(l_audit_event_id
             , P_ECAS_ACTION_CODE
             , P_ECAS_ID
             , SYSDATE
             , P_USERID
             , P_EMAIL_SENT_IND);

      ELSE
        UPDATE ECAS_AUDIT_EVENT
        SET ENTRY_TIMESTAMP = SYSDATE
        WHERE ECAS_ID = P_ECAS_ID
        AND AUDIT_EVENT_ID = l_audit_event_id
        AND ENTRY_USERID = P_USERID
        AND ECAS_ACTION_CODE = P_ECAS_ACTION_CODE
        AND Pkg_Sil_Date_Conversion.CONVERT_TO_CHAR(ENTRY_TIMESTAMP,'YYYY-MM-DD', 'Y')
           = Pkg_Sil_Date_Conversion.CONVERT_TO_CHAR(P_TIMESTAMP,'YYYY-MM-DD', 'Y');
      END IF;
      CLOSE c_event_id;
    END IF;

  EXCEPTION
    WHEN TOO_MANY_ROWS THEN
      P_ERROR_MESSAGE := P_ERROR_MESSAGE || 'ecas.web.usr.database.record.toomany:PKG_ECAS_AUDIT,ADD_AUDIT_HEADER,'||TRIM(l_table_name)||','||SQLCODE||';';
    WHEN DUP_VAL_ON_INDEX THEN
      P_ERROR_MESSAGE := P_ERROR_MESSAGE || 'ecas.web.usr.database.record.duplicate:PKG_ECAS_AUDIT,ADD_AUDIT_HEADER,'||TRIM(l_table_name)||','||SQLCODE||';';
    WHEN NO_DATA_FOUND THEN
      P_ERROR_MESSAGE := P_ERROR_MESSAGE || 'ecas.web.usr.database.record.invalid:PKG_ECAS_AUDIT,ADD_AUDIT_HEADER,'||TRIM(l_table_name)||';';
    WHEN OTHERS THEN
      P_ERROR_MESSAGE := P_ERROR_MESSAGE || 'ecas.web.usr.database.unexpected:PKG_ECAS_AUDIT,ADD_AUDIT_HEADER,'||SQLCODE||','||SQLERRM||';';

  END ADD_AUDIT_HEADER;


/******************************************************************************
    Procedure:  add_copy_event

    Purpose:    To add a record to the ECAS_AUDIT_EVENT table for copy events from the inbox.

******************************************************************************/

  PROCEDURE add_copy_event(  P_NEW_ECAS_ID       IN ECAS_AUDIT_EVENT.ECAS_ID%TYPE
                           , P_OLD_ECAS_ID       IN ECAS_AUDIT_EVENT.ECAS_ID%TYPE
                           , P_USERID            IN ECAS_AUDIT_EVENT.ENTRY_USERID%TYPE
                           , P_TIMESTAMP         IN ECAS_AUDIT_EVENT.ENTRY_TIMESTAMP%TYPE
                           , P_EMAIL_SENT_IND    IN ECAS_AUDIT_EVENT.EMAIL_SENT_IND%TYPE
                           , P_ERROR_MESSAGE     IN OUT VARCHAR2)
  IS

    l_table_name             VARCHAR2(50);
    l_comment                VARCHAR2(50);
    l_audit_event_id         ECAS_AUDIT_EVENT.AUDIT_EVENT_ID%TYPE;

  BEGIN

    l_table_name := 'ECAS_AUDIT_EVENT';
    l_comment := 'Copied from Ecas ID ' || P_OLD_ECAS_ID;

    SELECT ECAS_AUDIT_EVENT_SEQ.NEXTVAL
    INTO l_audit_event_id
    FROM dual;

    INSERT INTO ECAS_AUDIT_EVENT(AUDIT_EVENT_ID
                               , ECAS_ACTION_CODE
                               , ECAS_ID
                               , ENTRY_TIMESTAMP
                               , ENTRY_USERID
                               , EMAIL_SENT_IND)
    VALUES(l_audit_event_id
         , 'CPY'
         , P_NEW_ECAS_ID
         , SYSDATE
         , P_USERID
         , P_EMAIL_SENT_IND);

    INSERT INTO ECAS_AUDIT_COMMENT (ECAS_ID
                                  , AUDIT_EVENT_ID
                                  , AUDIT_COMMENT)
                            VALUES (P_NEW_ECAS_ID
                                  , l_audit_event_id
                                  , to_clob(l_comment) );

  EXCEPTION
    WHEN TOO_MANY_ROWS THEN
      P_ERROR_MESSAGE := P_ERROR_MESSAGE || 'ecas.web.usr.database.record.toomany:PKG_ECAS_AUDIT,add_copy_event,'||TRIM(l_table_name)||','||SQLCODE||';';
    WHEN DUP_VAL_ON_INDEX THEN
      P_ERROR_MESSAGE := P_ERROR_MESSAGE || 'ecas.web.usr.database.record.duplicate:PKG_ECAS_AUDIT,add_copy_event,'||TRIM(l_table_name)||','||SQLCODE||';';
    WHEN NO_DATA_FOUND THEN
      P_ERROR_MESSAGE := P_ERROR_MESSAGE || 'ecas.web.usr.database.record.invalid:PKG_ECAS_AUDIT,add_copy_event,'||TRIM(l_table_name)||';';
    WHEN OTHERS THEN
      P_ERROR_MESSAGE := P_ERROR_MESSAGE || 'ecas.web.usr.database.unexpected:PKG_ECAS_AUDIT,add_copy_event,'||SQLCODE||','||SQLERRM||';';

  END add_copy_event;



/******************************************************************************
    Procedure:  ADD_AUDIT_HEADER

    Purpose:    To add a record to the ECAS_AUDIT_EVENT table.
******************************************************************************/

  PROCEDURE ADD_AUDIT_HEADER(P_ECAS_ID             IN ECAS_AUDIT_EVENT.ECAS_ID%TYPE
                           , P_REVISION_COUNT_ADS  IN APPRAISAL_DATA_SUBMISSION.REVISION_COUNT%TYPE
                           , P_ECAS_ACTION_CODE    IN ECAS_AUDIT_EVENT.ECAS_ACTION_CODE%TYPE
                           , P_SUBMISSION_TYPE     IN VARCHAR
                           , P_CLIENT_LOCN_CODE    IN ECAS_ADMIN_CLIENT.CLIENT_LOCN_CODE%TYPE
                           , P_CLIENT_NUMBER       IN ECAS_ADMIN_CLIENT.CLIENT_NUMBER%TYPE
                           , P_DISTRICT_REP_IND    IN ECAS_ADMIN_CLIENT.DISTRICT_REP_IND%TYPE
                           , P_REGION_REP_IND      IN ECAS_ADMIN_CLIENT.REGION_REP_IND%TYPE
                           , P_USERID              IN ECAS_AUDIT_EVENT.ENTRY_USERID%TYPE
                           , P_TIMESTAMP           IN ECAS_AUDIT_EVENT.ENTRY_TIMESTAMP%TYPE
                           , P_EMAIL_SENT_IND      IN ECAS_AUDIT_EVENT.EMAIL_SENT_IND%TYPE
                           , P_ERROR_MESSAGE       IN OUT VARCHAR2)
  IS

    l_table_name             VARCHAR2(150);
    l_audit_event_id         ECAS_AUDIT_EVENT.AUDIT_EVENT_ID%TYPE;
    l_status                 APPRAISAL_DATA_SUBMISSION.APPRAISAL_STATUS_CODE%TYPE;
    l_sent_to_userid         ECAS_AUDIT_EVENT.SENT_TO_USERID%TYPE;
    l_client_number          APPRAISAL_DATA_SUBMISSION.CLIENT_NUMBER%TYPE;
    l_client_locn_code       APPRAISAL_DATA_SUBMISSION.CLIENT_LOCN_CODE%TYPE;
    l_first_name             APPRAISAL_DATA_SUBMISSION.licensee_rep_first_name%TYPE;
    l_last_name              APPRAISAL_DATA_SUBMISSION.licensee_rep_last_name%TYPE;
    l_temp                   VARCHAR2(32767);

    CURSOR c_status IS
    SELECT APPRAISAL_STATUS_CODE
    FROM APPRAISAL_DATA_SUBMISSION
    WHERE ECAS_ID = P_ECAS_ID;

    CURSOR c_admin_client (l_client_number VARCHAR2, l_locn_code VARCHAR2) IS
    SELECT USER_ID
    FROM ECAS_ADMIN_CLIENT
    WHERE CLIENT_LOCN_CODE = l_locn_code
    AND CLIENT_NUMBER = l_client_number
    AND DISTRICT_REP_IND = P_DISTRICT_REP_IND
    AND REGION_REP_IND = P_REGION_REP_IND
    AND (EXPIRY_DATE IS NULL OR EXPIRY_DATE > SYSDATE);

    CURSOR c_event_id IS
    SELECT AUDIT_EVENT_ID
    FROM ECAS_AUDIT_EVENT
    WHERE ECAS_ID = P_ECAS_ID
    AND ENTRY_USERID = P_USERID
    AND ECAS_ACTION_CODE = P_ECAS_ACTION_CODE
    AND Pkg_Sil_Date_Conversion.CONVERT_TO_CHAR(ENTRY_TIMESTAMP,'YYYY-MM-DD', 'Y')
      = Pkg_Sil_Date_Conversion.CONVERT_TO_CHAR(P_TIMESTAMP,'YYYY-MM-DD', 'Y')
              ORDER BY AUDIT_EVENT_ID DESC --LISA;
                    ;
  BEGIN
    IF P_CLIENT_NUMBER IS NULL OR P_CLIENT_NUMBER = '' THEN
      l_table_name := 'APPRAISAL_DATA_SUBMISSION';

      SELECT CLIENT_NUMBER, CLIENT_LOCN_CODE
      INTO l_client_number, l_client_locn_code
      FROM APPRAISAL_DATA_SUBMISSION
      WHERE ECAS_ID = P_ECAS_ID;

    ELSE
      l_client_number := P_CLIENT_NUMBER;
      l_client_locn_code := P_CLIENT_LOCN_CODE;
    END IF;

    IF (P_SUBMISSION_TYPE = 'ACKNOWLEDGEMENT_SUBMIT') THEN
      l_table_name := 'ECAS_ADMIN_CLIENT';

      OPEN c_admin_client(l_client_number, l_client_locn_code);
      FETCH c_admin_client INTO l_sent_to_userid;
      CLOSE c_admin_client;

    ELSIF (P_SUBMISSION_TYPE = 'CONTROL_SEND') THEN
      l_table_name := 'ECAS_ADMIN_CLIENT';

      OPEN c_admin_client(l_client_number, l_client_locn_code);
      FETCH c_admin_client INTO l_sent_to_userid;
      CLOSE c_admin_client;

    ELSIF (P_SUBMISSION_TYPE = 'CONTROL_RETURN') THEN
      l_table_name := 'ECAS_ADMIN_CLIENT';

      OPEN c_admin_client(l_client_number, l_client_locn_code);
      FETCH c_admin_client INTO l_sent_to_userid;
      CLOSE c_admin_client;

    ELSIF (P_SUBMISSION_TYPE = 'CONTROL_SEND_ISSUE') THEN
      l_table_name := 'ECAS_ADMIN_CLIENT';

      OPEN c_admin_client(l_client_number, l_client_locn_code);
      FETCH c_admin_client INTO l_sent_to_userid;
      CLOSE c_admin_client;

    ELSIF (P_SUBMISSION_TYPE = 'CONTROL_DISTRICT_CLARIFY') THEN
      l_table_name := 'APPRAISAL_DATA_SUBMISSION or RPF_LICENSEE_REP or MOF_USER';

      ECAS_COMMON.GET_LICENSEE_REP (P_ECAS_ID,
                                    l_first_name,
                                    l_last_name,
                                    l_temp);
      l_sent_to_userid := l_last_name||', '||l_first_name;

    ELSIF (P_SUBMISSION_TYPE = 'CONTROL_REGION_CLARIFY') THEN
      l_table_name := 'APPRAISAL_DATA_SUBMISSION or RPF_LICENSEE_REP or MOF_USER';

      ECAS_COMMON.GET_LICENSEE_REP (P_ECAS_ID,
                                    l_first_name,
                                    l_last_name,
                                    l_temp);
      l_sent_to_userid := l_last_name||', '||l_first_name;
    END IF;

    l_table_name := 'APPRAISAL_DATA_SUBMISSION';

    OPEN c_status;
    FETCH c_status INTO l_status;
    CLOSE c_status;

    IF l_status != 'DFT' THEN
      l_table_name := 'ECAS_AUDIT_EVENT';

      OPEN c_event_id;
      FETCH c_event_id INTO l_audit_event_id;

      IF c_event_id%NOTFOUND THEN
        SELECT ECAS_AUDIT_EVENT_SEQ.NEXTVAL
        INTO l_audit_event_id
        FROM dual;

        INSERT INTO ECAS_AUDIT_EVENT(AUDIT_EVENT_ID
                                   , ECAS_ACTION_CODE
                                   , ECAS_ID
                                   , ENTRY_TIMESTAMP
                                   , ENTRY_USERID
                                   , EMAIL_SENT_IND
                                   , SENT_TO_USERID)
        VALUES(l_audit_event_id
             , P_ECAS_ACTION_CODE
             , P_ECAS_ID
             , SYSDATE
             , P_USERID
             , P_EMAIL_SENT_IND
             , l_sent_to_userid);

      ELSE
        UPDATE ECAS_AUDIT_EVENT
        SET ENTRY_TIMESTAMP = SYSDATE
        WHERE ECAS_ID = P_ECAS_ID
        AND AUDIT_EVENT_ID = l_audit_event_id
        AND ENTRY_USERID = P_USERID
        AND ECAS_ACTION_CODE = P_ECAS_ACTION_CODE
        AND Pkg_Sil_Date_Conversion.CONVERT_TO_CHAR(ENTRY_TIMESTAMP,'YYYY-MM-DD', 'Y')
            = Pkg_Sil_Date_Conversion.CONVERT_TO_CHAR(P_TIMESTAMP,'YYYY-MM-DD', 'Y');

      END IF;
      CLOSE c_event_id;

    END IF;

  EXCEPTION
    WHEN TOO_MANY_ROWS THEN
      P_ERROR_MESSAGE := P_ERROR_MESSAGE || 'ecas.web.usr.database.record.toomany:PKG_ECAS_AUDIT,ADD_AUDIT_HEADER,'||TRIM(l_table_name)||','||SQLCODE||';';
    WHEN DUP_VAL_ON_INDEX THEN
      P_ERROR_MESSAGE := P_ERROR_MESSAGE || 'ecas.web.usr.database.record.duplicate:PKG_ECAS_AUDIT,ADD_AUDIT_HEADER,'||TRIM(l_table_name)||','||SQLCODE||';';
    WHEN NO_DATA_FOUND THEN
      P_ERROR_MESSAGE := P_ERROR_MESSAGE || 'ecas.web.usr.database.record.invalid:PKG_ECAS_AUDIT,ADD_AUDIT_HEADER,'||TRIM(l_table_name)||';';
    WHEN OTHERS THEN
      P_ERROR_MESSAGE := P_ERROR_MESSAGE || 'ecas.web.usr.database.unexpected:PKG_ECAS_AUDIT,ADD_AUDIT_HEADER,'||SQLCODE||','||SQLERRM||';';

  END ADD_AUDIT_HEADER;

/******************************************************************************
    Procedure:  ADD_AUDIT_DETAIL

    Purpose:    To add a record to the ECAS_AUDIT_DETAIL table.
******************************************************************************/

  PROCEDURE ADD_AUDIT_DETAIL(P_ECAS_ID          IN ECAS_AUDIT_DETAIL.ECAS_ID%TYPE
