    WHEN DUP_VAL_ON_INDEX THEN
      P_ERROR_MESSAGE := P_ERROR_MESSAGE || 'ecas.web.usr.database.record.duplicate:PKG_ECAS_AUDIT,ADD_AUDIT_DETAIL,'||TRIM(l_table_name)||','||SQLCODE||';';
    WHEN NO_DATA_FOUND THEN
      P_ERROR_MESSAGE := P_ERROR_MESSAGE || 'ecas.web.usr.database.record.invalid:PKG_ECAS_AUDIT,ADD_AUDIT_DETAIL,'||TRIM(l_table_name)||';';
    WHEN OTHERS THEN
      P_ERROR_MESSAGE := P_ERROR_MESSAGE || 'ecas.web.usr.database.unexpected:PKG_ECAS_AUDIT,ADD_AUDIT_DETAIL,'||SQLCODE||','||SQLERRM||';';

  END ADD_AUDIT_DETAIL;


