  CREATE OR REPLACE EDITIONABLE PACKAGE "THE"."SIL_DATE_CONVERSION" AS
/******************************************************************************
    Package:    PKG_SIL_DATE_CONVERSION

    Purpose:     Procedures to convert date characteristics to either dates from
                 characters or from characters to dates based on passed parms.
                 If any raised error is wanted to be hidden then pass the
                 p_error_ind = 'N' and it will hide any Oracle error conditions.
                 If the date format is not provided for character conversion then
                 the format of 'YYYY-MM-DD' will be used.

    Revision History

    Person             Date        Comments
    -----------------  ----------  --------------------------------
    PDS                2001-10-15  Created
    R.A.Robb           2004-05-14  Added CONVERT_TO_CHAR_TRUNC_TIME and
                                   set defaults for all
******************************************************************************/
    FUNCTION CONVERT_TO_CHAR ( p_value        IN     DATE
                             , p_format       IN     VARCHAR2 DEFAULT 'YYYY-MM-DD'
                             , p_error_ind    IN     VARCHAR2 DEFAULT 'Y') RETURN VARCHAR2;

    FUNCTION CONVERT_TO_CHAR_TRUNC_TIME
                             ( p_value        IN     DATE
                             , p_date_format  IN     VARCHAR2 DEFAULT 'YYYY-MM-DD'
                             , p_time_format  IN     VARCHAR2 DEFAULT 'HH:MI:SS AM'
                             , p_error_ind    IN     VARCHAR2 DEFAULT 'Y') RETURN VARCHAR2;

    FUNCTION CONVERT_TO_DATE (p_value           IN VARCHAR2
                            , p_error_ind       IN VARCHAR2 DEFAULT 'Y') RETURN DATE;

END Sil_Date_Conversion;
/
CREATE OR REPLACE EDITIONABLE PACKAGE BODY "THE"."SIL_DATE_CONVERSION" AS

    FUNCTION CONVERT_TO_CHAR_TRUNC_TIME
                             ( p_value        IN     DATE
                             , p_date_format  IN     VARCHAR2 DEFAULT 'YYYY-MM-DD'
                             , p_time_format  IN     VARCHAR2 DEFAULT 'HH:MI:SS AM'
                             , p_error_ind    IN     VARCHAR2 DEFAULT 'Y') RETURN VARCHAR2 IS
       v_return_value   VARCHAR2(50) := NULL;
    BEGIN
       --Don't return time portion if date is same as trunc(date)
       IF TRUNC(p_value) = p_value THEN
          v_return_value := TO_CHAR(p_value,p_date_format);
       ELSE
          v_return_value := TO_CHAR(p_value,p_date_format||' '||p_time_format);
       END IF;
       RETURN (v_return_value);
    EXCEPTION
      WHEN OTHERS THEN
        IF p_error_ind = 'Y' THEN
           RAISE;
        ELSE
           RETURN (NULL);
        END IF;

    END CONVERT_TO_CHAR_TRUNC_TIME;

    FUNCTION CONVERT_TO_CHAR ( p_value        IN     DATE
                             , p_format       IN     VARCHAR2 DEFAULT 'YYYY-MM-DD'
                             , p_error_ind    IN     VARCHAR2 DEFAULT 'Y') RETURN VARCHAR2 IS
       v_date_format    VARCHAR2(50) := 'YYYY-MM-DD';
       p_return_value   VARCHAR2(50) := NULL;
    BEGIN
       IF p_format IS NOT NULL THEN
          v_date_format := p_format;
       ELSE
          v_date_format := 'YYYY-MM-DD';
       END IF;
       p_return_value := TO_CHAR(p_value, v_date_format);
       RETURN (p_return_value);
    EXCEPTION
      WHEN OTHERS THEN
        IF p_error_ind = 'Y' THEN
           RAISE;
        ELSE
           RETURN (NULL);
        END IF;
    END CONVERT_TO_CHAR;

    FUNCTION CONVERT_TO_DATE (p_value           IN VARCHAR2
                            , p_error_ind       IN VARCHAR2 DEFAULT 'Y') RETURN DATE IS
      p_return_date   DATE  := NULL;
      dateFormat      VARCHAR2(50);
    BEGIN
      IF LENGTH(p_value) > 10 THEN
        dateFormat := 'YYYY-MM-DD HH24:MI:SS';
      ELSE
        dateFormat := 'YYYY-MM-DD';
      END IF;

      p_return_date := TO_DATE(p_value, dateFormat);
      RETURN (p_return_date);
    EXCEPTION
      WHEN OTHERS THEN
        IF p_error_ind = 'Y' THEN
           RAISE;
        ELSE
           RETURN (NULL);
        END IF;
    END CONVERT_TO_DATE;
END Sil_Date_Conversion ;
/

  CREATE OR REPLACE EDITIONABLE PACKAGE "THE"."PKG_ECAS_TOMBSTONE" 
IS
/******************************************************************************
    Package:	PKG_ECAS_TOMBSTONE

    Purpose:	Retrieves tombstone data for both Coast and Interior
                tombstones.

    Revision History

    Person             Date       Comments
    -----------------  ---------  --------------------------------
    Pangaea            10/10/2002 Created
	BMacpherson        2004-05-13 Removed occurances of WHEN OTHER THEN RAISE;

******************************************************************************/



PROCEDURE mainline(p_action                             IN OUT VARCHAR2
                   , p_licence                            IN OUT VARCHAR2
                   , p_cutting_permit                     IN OUT VARCHAR2
                   , p_timber_mark                        IN OUT VARCHAR2
                   , p_ecas_id                            IN OUT VARCHAR2
                   , p_effective_date                     IN OUT VARCHAR2
                   , P_MULTI_TIMBER_MARKS_IND             IN OUT VARCHAR2
                   , p_error_message                      IN OUT VARCHAR2);

PROCEDURE mainline(p_action                             IN OUT VARCHAR2
                   , p_licence                            IN OUT VARCHAR2
                   , p_cutting_permit                     IN OUT VARCHAR2
                   , p_timber_mark                        IN OUT VARCHAR2
                   , p_ecas_id                            IN OUT VARCHAR2
                   , p_effective_date                     IN OUT VARCHAR2
                   , p_error_message                      IN OUT VARCHAR2);

END Pkg_Ecas_Tombstone;
/
CREATE OR REPLACE EDITIONABLE PACKAGE BODY "THE"."PKG_ECAS_TOMBSTONE" AS

/******************************************************************************
    Procedure:  GET

    Purpose:	To retrieve specific data based on criteria sent to proc.

******************************************************************************/
  PROCEDURE GET(P_LICENCE                            IN OUT VARCHAR2
              , P_CUTTING_PERMIT                     IN OUT VARCHAR2
              , P_TIMBER_MARK                        IN OUT VARCHAR2
              , P_ECAS_ID                            IN OUT VARCHAR2
              , P_EFFECTIVE_DATE                     IN OUT VARCHAR2
              , P_MULTI_TIMBER_MARKS_IND             IN OUT VARCHAR2
              , P_ERROR_MESSAGE                      IN OUT VARCHAR2)
  IS
     l_table_name        VARCHAR2(50) := 'APPRAISAL_DATA_SUBMISSION';
     l_timber_mark_count INTEGER := 0;
     wrong_criteria      EXCEPTION;
     l_effective_date    DATE;
  BEGIN

    IF P_ECAS_ID IS NOT NULL THEN

      P_MULTI_TIMBER_MARKS_IND := 'N';

      SELECT ADS.FOREST_FILE_ID,
             ADS.CUTTING_PERMIT_ID,
             ADS.ECAS_ID,
             PKG_SIL_DATE_CONVERSION.CONVERT_TO_CHAR(ADS.APPRAISAL_EFFECTIVE_DATE,'YYYY-MM-DD', 'Y')
        INTO P_LICENCE,
             P_CUTTING_PERMIT,
             P_ECAS_ID,
             P_EFFECTIVE_DATE
        FROM APPRAISAL_DATA_SUBMISSION ADS
       WHERE ADS.ECAS_ID = TO_NUMBER(P_ECAS_ID);

      BEGIN
        -- Select the latest timbermark for display
        SELECT STM.TIMBER_MARK
          INTO P_TIMBER_MARK
          FROM APPRAISAL_DATA_SUBMISSION ADS,
               ADS_SUBMITTED_TIMBER_MARK STM
         WHERE ADS.ECAS_ID = to_number(P_ECAS_ID)
           AND ADS.ECAS_ID = STM.ECAS_ID
           AND STM.PRIMARY_MARK_IND = 'Y';
      EXCEPTION
        WHEN NO_DATA_FOUND THEN
          NULL; -- ignore, there may not be a timbermark
      END;

    ELSIF P_TIMBER_MARK IS NOT NULL THEN

      --TIMBER MARK EFFECTIVE DATE MAY OR MAY NOT EXIST.  MUST TRAP FOR THE CASE IT DOESN'T
      BEGIN
          IF P_EFFECTIVE_DATE IS NULL THEN
            -- LOOKUP EFFECTIVE DATE FOR THIS ECAS ID
            SELECT ADS.APPRAISAL_EFFECTIVE_DATE
              INTO l_effective_date
              FROM APPRAISAL_DATA_SUBMISSION ADS, ADS_SUBMITTED_TIMBER_MARK ASTM
             WHERE ASTM.ECAS_ID = ADS.ECAS_ID
               AND ASTM.TIMBER_MARK = P_TIMBER_MARK;
          ELSE
                l_effective_date := PKG_SIL_DATE_CONVERSION.CONVERT_TO_DATE(P_EFFECTIVE_DATE, 'YYYY-MM-DD');
          END IF;
      EXCEPTION
          WHEN NO_DATA_FOUND THEN
                NULL;
      END;

      IF l_effective_date IS NOT NULL THEN
        SELECT ADS.FOREST_FILE_ID,
                 ADS.CUTTING_PERMIT_ID,
                 ADS.ECAS_ID,
                 PKG_SIL_DATE_CONVERSION.CONVERT_TO_CHAR(ADS.APPRAISAL_EFFECTIVE_DATE,'YYYY-MM-DD', 'Y')
          INTO P_LICENCE,
                 P_CUTTING_PERMIT,
                 P_ECAS_ID,
                 P_EFFECTIVE_DATE
          FROM APPRAISAL_DATA_SUBMISSION ADS,
                 ADS_SUBMITTED_TIMBER_MARK STM
         WHERE ADS.ECAS_ID = STM.ECAS_ID
                AND STM.TIMBER_MARK = P_TIMBER_MARK
                AND PKG_SIL_DATE_CONVERSION.CONVERT_TO_CHAR(ADS.APPRAISAL_EFFECTIVE_DATE, 'YYYY-MM-DD', 'Y')  = PKG_SIL_DATE_CONVERSION.CONVERT_TO_CHAR(l_effective_date, 'YYYY-MM-DD', 'Y');
      ELSE
        SELECT ADS.FOREST_FILE_ID,
                 ADS.CUTTING_PERMIT_ID,
                 ADS.ECAS_ID,
                 PKG_SIL_DATE_CONVERSION.CONVERT_TO_CHAR(ADS.APPRAISAL_EFFECTIVE_DATE,'YYYY-MM-DD', 'Y')
          INTO P_LICENCE,
                 P_CUTTING_PERMIT,
                 P_ECAS_ID,
                 P_EFFECTIVE_DATE
          FROM APPRAISAL_DATA_SUBMISSION ADS,
                 ADS_SUBMITTED_TIMBER_MARK STM
         WHERE ADS.ECAS_ID = STM.ECAS_ID
                AND STM.TIMBER_MARK = P_TIMBER_MARK;
       END IF;
    ELSE
      RAISE wrong_criteria;
    END IF;

    -- Set display flag for multitple timbermarks
    SELECT COUNT(*)
      INTO l_timber_mark_count
      FROM ADS_SUBMITTED_TIMBER_MARK ast
     WHERE ast.ECAS_ID = ECAS_ID;

    IF l_timber_mark_count > 1 THEN
      P_MULTI_TIMBER_MARKS_IND := 'Y';
    ELSE
      P_MULTI_TIMBER_MARKS_IND := 'N';
    END IF;

  EXCEPTION
    WHEN TOO_MANY_ROWS THEN
       P_ERROR_MESSAGE := P_ERROR_MESSAGE || 'ecas.web.usr.database.record.toomany:PKG_ECAS_TOMBSTONE,GET,'||TRIM(l_table_name)||','||SQLCODE||';';
    WHEN NO_DATA_FOUND THEN
	   P_ERROR_MESSAGE := P_ERROR_MESSAGE || 'ecas.web.usr.database.record.invalid:PKG_ECAS_TOMBSTONE,GET,'||TRIM(l_table_name)||';';
    WHEN wrong_criteria THEN
       P_ERROR_MESSAGE := P_ERROR_MESSAGE || 'ecas.web.usr.database.unexpected:PKG_ECAS_TOMBSTONE,GET,'||SQLCODE||','||SQLERRM||';';
    WHEN OTHERS THEN
       P_ERROR_MESSAGE := P_ERROR_MESSAGE || 'ecas.web.usr.database.unexpected:PKG_ECAS_TOMBSTONE,GET,'||SQLCODE||','||SQLERRM||';';
  END GET;


/******************************************************************************
    Procedure:  GET_JAVA_TIMBER_MARK_EFFECT_DATE

    Purpose:	Checks that the timber mark exists in ecas.
    NOTE:       DO NOT RETURN MORE THAN ONE ERROR FROM THIS PACKAGE IN P_ERROR_MESSAGE
                This is due to the fact that it is used as a validator in the TombstoneValidatorSet
                in Java and it can only return one error message from a validator.

******************************************************************************/
 PROCEDURE GET_JAVA_TMARK_EFFECT_DATE (
                 P_TIMBER_MARK                                 IN OUT VARCHAR2
               , P_ECAS_ID                                     IN OUT VARCHAR2
               , P_EFFECTIVE_DATE                              IN OUT VARCHAR2
               , P_ERROR_MESSAGE                               IN OUT VARCHAR2)
IS
    TEMP_CODE ADS_SUBMITTED_TIMBER_MARK.TIMBER_MARK%TYPE;
    l_count NUMBER;
BEGIN

    l_count:=0;
    IF P_ECAS_ID IS NULL OR P_ECAS_ID = '' THEN
        IF P_TIMBER_MARK IS NOT NULL AND P_EFFECTIVE_DATE IS NULL THEN

            SELECT COUNT(*)
              INTO l_count
              FROM ADS_SUBMITTED_TIMBER_MARK
             WHERE TIMBER_MARK = P_TIMBER_MARK;

            IF l_count > 1 THEN
                P_ERROR_MESSAGE := 'ecas.web.usr.database.effectivedate.required';
            ELSIF l_count = 0 THEN
                P_ERROR_MESSAGE := 'ecas.web.usr.database.timberMark.notFound';
            ELSIF l_count = 1 THEN
                SELECT ADS.ECAS_ID, ASTM.TIMBER_MARK,  PKG_SIL_DATE_CONVERSION.CONVERT_TO_CHAR(ADS.APPRAISAL_EFFECTIVE_DATE, 'YYYY-MM-DD', 'Y') APPRAISAL_EFFECTIVE_DATE, ASTM.ECAS_ID
                  INTO P_ECAS_ID, P_TIMBER_MARK, P_EFFECTIVE_DATE, P_ECAS_ID
                  FROM APPRAISAL_DATA_SUBMISSION ADS, ADS_SUBMITTED_TIMBER_MARK ASTM
                 WHERE ASTM.ECAS_ID = ADS.ECAS_ID
                   AND ASTM.TIMBER_MARK = P_TIMBER_MARK;
            END IF;
        ELSIF P_TIMBER_MARK IS NOT NULL AND P_EFFECTIVE_DATE IS NOT NULL THEN
                SELECT ADS.ECAS_ID, ASTM.TIMBER_MARK,  PKG_SIL_DATE_CONVERSION.CONVERT_TO_CHAR(ADS.APPRAISAL_EFFECTIVE_DATE, 'YYYY-MM-DD', 'Y') APPRAISAL_EFFECTIVE_DATE
                  INTO P_ECAS_ID, P_TIMBER_MARK, P_EFFECTIVE_DATE
                  FROM APPRAISAL_DATA_SUBMISSION ADS, ADS_SUBMITTED_TIMBER_MARK ASTM
                 WHERE ASTM.ECAS_ID = ADS.ECAS_ID
                   AND ASTM.TIMBER_MARK = P_TIMBER_MARK
                   AND ADS.APPRAISAL_EFFECTIVE_DATE = PKG_SIL_DATE_CONVERSION.CONVERT_TO_DATE(P_EFFECTIVE_DATE, 'N');
        END IF;
    END IF;

    EXCEPTION
	  WHEN NO_DATA_FOUND THEN
		P_ERROR_MESSAGE := 'ecas.web.usr.database.timberMarkEffectiveDate.notFound';
      WHEN OTHERS THEN
        P_ERROR_MESSAGE := 'ecas.web.usr.database.unexpected:PKG_ECAS_TOMBSTONE,GET,'||SQLCODE||','||SQLERRM||';';

END;

/******************************************************************************
    Procedure:  MAINLINE

    Purpose:	Main processing procedure which drives all functionality in the package.
                This procedure will include all parameters needed for all functionality.

******************************************************************************/
  PROCEDURE MAINLINE(P_ACTION                             IN OUT VARCHAR2
                   , P_LICENCE                            IN OUT VARCHAR2
                   , P_CUTTING_PERMIT                     IN OUT VARCHAR2
                   , P_TIMBER_MARK                        IN OUT VARCHAR2
                   , P_ECAS_ID                            IN OUT VARCHAR2
                   , P_EFFECTIVE_DATE                     IN OUT VARCHAR2
                   , P_MULTI_TIMBER_MARKS_IND             IN OUT VARCHAR2
                   , P_ERROR_MESSAGE                      IN OUT VARCHAR2)
  IS
     l_table_name             VARCHAR2(50);
     unknown_function_request  EXCEPTION;

  BEGIN
    P_TIMBER_MARK := UPPER(P_TIMBER_MARK);

    IF P_ACTION = 'GET' THEN
      GET (P_LICENCE,
           P_CUTTING_PERMIT,
           P_TIMBER_MARK,
           P_ECAS_ID,
           P_EFFECTIVE_DATE,
           P_MULTI_TIMBER_MARKS_IND,
           P_ERROR_MESSAGE);
    ELSIF P_ACTION = 'GET_JAVA_TMARK_EFFECT_DATE' THEN
      GET_JAVA_TMARK_EFFECT_DATE (P_TIMBER_MARK,
           P_ECAS_ID,
           P_EFFECTIVE_DATE,
           P_ERROR_MESSAGE);
    ELSE
       RAISE unknown_function_request;
    END IF;

  EXCEPTION
    WHEN unknown_function_request THEN
       P_ERROR_MESSAGE := P_ERROR_MESSAGE || 'ecas.web.usr.database.invalid.function:PKG_ECAS_TOMBSTONE,MAINLINE,'||P_ACTION||';';
    WHEN OTHERS THEN
       P_ERROR_MESSAGE := P_ERROR_MESSAGE || 'ecas.web.usr.database.unexpected:PKG_ECAS_TOMBSTONE,MAINLINE,'||SQLCODE||','||SQLERRM||';';

  END MAINLINE;

  PROCEDURE MAINLINE(P_ACTION                             IN OUT VARCHAR2
                   , P_LICENCE                            IN OUT VARCHAR2
                   , P_CUTTING_PERMIT                     IN OUT VARCHAR2
                   , P_TIMBER_MARK                        IN OUT VARCHAR2
                   , P_ECAS_ID                            IN OUT VARCHAR2
                   , P_EFFECTIVE_DATE                     IN OUT VARCHAR2
                   , P_ERROR_MESSAGE                      IN OUT VARCHAR2)
  IS
    P_MULTI_TIMBER_MARKS_IND VARCHAR2(1);
  BEGIN
            MAINLINE(P_ACTION
                   , P_LICENCE
                   , P_CUTTING_PERMIT
                   , P_TIMBER_MARK
                   , P_ECAS_ID
                   , P_EFFECTIVE_DATE
                   , P_MULTI_TIMBER_MARKS_IND
                   , P_ERROR_MESSAGE);
  END;

END PKG_ECAS_TOMBSTONE;
/

