CREATE OR REPLACE EDITIONABLE PACKAGE BODY "THE"."PKG_ECAS_VALIDATION" AS

/******************************************************************************
    Function:  FORMAT_PHONE_NUMBER

    Purpose:	formats a phone number into (NNN)NNN-NNNN or NNN-NNNN

******************************************************************************/
FUNCTION FORMAT_PHONE_NUMBER
    (phone_num     IN  VARCHAR2
    ) RETURN VARCHAR2
AS
--Variables
  l_formatted    VARCHAR2(15);

BEGIN
       select DECODE(LENGTH(phone_num),
       10 , '(' || SUBSTR(phone_num, 1, 3) || ')' || SUBSTR(phone_num, 4, 3) || '-' || SUBSTR(phone_num, 7, 4),
       7, SUBSTR(phone_num, 1, 3) || '-' || SUBSTR(phone_num, 4, 4), phone_num)
       into l_formatted
       from dual;

  RETURN l_formatted;
END FORMAT_PHONE_NUMBER;

/******************************************************************************
    Function:  UNFORMAT_PHONE_NUMBER

    Purpose:	unformats a phone number from (NNN)NNN-NNNN into NNNNNNNNNN

******************************************************************************/
FUNCTION UNFORMAT_PHONE_NUMBER (phone_num IN  VARCHAR2 ) RETURN VARCHAR2
AS
--Variables
  l_unformatted    VARCHAR2(15);

BEGIN
  l_unformatted := SUBSTR(phone_num, 2, 3) || SUBSTR(phone_num, 6, 3) || SUBSTR(phone_num, 10, 4);

  RETURN l_unformatted;
END UNFORMAT_PHONE_NUMBER;

/******************************************************************************
    Procedure:  CHECK_MGMT_UNIT

    Purpose:	Checks that the management type exists in code_lists
				and if the unit id was optionally entered that the
				cross ref exists for the type/unit combination

******************************************************************************/
  PROCEDURE CHECK_MGMT_UNIT (
   			     P_MGMT_TYPE		   						   IN OUT VARCHAR2
  			   , P_MGMT_UNIT_ID 	   						   IN OUT VARCHAR2
			   , P_ERROR_MESSAGE                               IN OUT VARCHAR2)
  IS

	 -- String indicator for record exists
     l_rec_clt          VARCHAR2(1);

	 -- Exceptions
	 TYPE_NOT_FOUND		EXCEPTION;
	 XREF_NOT_FOUND		EXCEPTION;

  BEGIN
  	 BEGIN
		 /* First check if the type exists */
	     SELECT 'Y' into l_rec_clt
	     from DUAL
	     WHERE EXISTS(SELECT *
	     FROM   CODE_LIST_TABLE
	     WHERE COLUMN_NAME = 'MGMT_UNIT_TYPE'
		   AND CODE_ARGUMENT = P_MGMT_TYPE);

	     IF NOT l_rec_clt = 'Y' THEN
	       RAISE TYPE_NOT_FOUND;
	     END IF;

	    EXCEPTION
		  WHEN TYPE_NOT_FOUND THEN
          	RAISE_APPLICATION_ERROR (-20001, 'PLS: ECAS - record is not on file.');
          WHEN NO_DATA_FOUND THEN
            RAISE_APPLICATION_ERROR (-20001, 'PLS: ECAS - record is not on file.');
	  END;
    BEGIN
		/* Second if the unit was entered check if the xref exists for combination */
		IF P_MGMT_UNIT_ID IS NOT NULL THEN

			SELECT 'Y' into l_rec_clt
			from DUAL
		    WHERE EXISTS(
			    select *
				from CODE_LIST_TABLE cl1
				where  cl1.column_name = (
				   SELECT cl2.expanded_result
				   FROM CODE_LIST_TABLE cl2
				   WHERE cl2.column_name = 'MGMT_UNIT_XREF'
				   AND cl2.code_argument = P_MGMT_TYPE)
				AND cl1.code_argument = P_MGMT_UNIT_ID);

			IF NOT l_rec_clt = 'Y' THEN
		     RAISE XREF_NOT_FOUND;
		    END IF;

		END IF;

	  EXCEPTION
	  WHEN XREF_NOT_FOUND THEN
       	RAISE_APPLICATION_ERROR (-20001, 'PLS: ECAS - record is not on file.');
      WHEN NO_DATA_FOUND THEN
        RAISE_APPLICATION_ERROR (-20001, 'PLS: ECAS - record is not on file.');
    END;

  END CHECK_MGMT_UNIT;
/******************************************************************************
    Procedure:  CHECK_LICENCE

    Purpose:	Checks that the licence is valid (in PROV_FOREST_USE)

******************************************************************************/
  PROCEDURE CHECK_LICENCE (
                 P_FOREST_FILE_ID                              IN OUT VARCHAR2
               , P_ERROR_MESSAGE                               IN OUT VARCHAR2)
  IS

    TEMP_CODE					PROV_FOREST_USE.FOREST_FILE_ID%TYPE;
  BEGIN

	SELECT FOREST_FILE_ID
	INTO TEMP_CODE
	FROM PROV_FOREST_USE
	WHERE FOREST_FILE_ID = P_FOREST_FILE_ID;

   EXCEPTION
	  WHEN NO_DATA_FOUND THEN
		RAISE_APPLICATION_ERROR (-20001, 'PLS: ECAS - record is not on file.');
  END CHECK_LICENCE;

/******************************************************************************
    Procedure:  CHECK_CUTTING_PERMIT

    Purpose:	Checks that the LICENCE / CUTTING_PERMIT combination is valid

******************************************************************************/
  PROCEDURE CHECK_CUTTING_PERMIT (
                 P_FOREST_FILE_ID                              IN OUT VARCHAR2
               , P_CUTTING_PERMIT_ID                           IN OUT VARCHAR2
               , P_ERROR_MESSAGE                               IN OUT VARCHAR2)
  IS

    PFU_TEMP_CODE					PROV_FOREST_USE.FOREST_FILE_ID%TYPE;
    CPI_TEMP_CODE					harvesting_authority.CUTTING_PERMIT_ID%TYPE;

  BEGIN

	SELECT PFU.FOREST_FILE_ID, hva.CUTTING_PERMIT_ID
		INTO PFU_TEMP_CODE,
		 CPI_TEMP_CODE
	  FROM PROV_FOREST_USE PFU
	 INNER JOIN hauling_authority hla on pfu.forest_file_id = hla.forest_file_id
	 inner join harvesting_hauling_xref hhx on hla.timber_mark = hhx.timber_mark
	 inner join harvesting_authority hva on hhx.hva_skey = hva.hva_skey
	 WHERE PFU.FOREST_FILE_ID = P_FOREST_FILE_ID
	   AND hva.CUTTING_PERMIT_ID = P_CUTTING_PERMIT_ID;

   EXCEPTION
	  WHEN NO_DATA_FOUND THEN
		RAISE_APPLICATION_ERROR (-20001, 'PLS: ECAS - record is not on file.');
  END CHECK_CUTTING_PERMIT;

/******************************************************************************
    Procedure:  CHECK_CUT_BLOCK

    Purpose:	Checks that the LICENCE / CUTTING_PERMIT / CUT_BLOCK combination
                is valid

******************************************************************************/
  PROCEDURE CHECK_CUT_BLOCK (
                 P_FOREST_FILE_ID                              IN OUT VARCHAR2
               , P_CUTTING_PERMIT_ID                           IN OUT VARCHAR2
               , P_CUT_BLOCK_ID                                IN OUT VARCHAR2
               , P_ERROR_MESSAGE                               IN OUT VARCHAR2)
  IS

    PFU_TEMP_CODE					PROV_FOREST_USE.FOREST_FILE_ID%TYPE;
    CPI_TEMP_CODE					harvesting_authority.CUTTING_PERMIT_ID%TYPE;
    CB_TEMP_CODE					CUT_BLOCK.CUT_BLOCK_ID%TYPE;

  BEGIN

  IF P_CUTTING_PERMIT_ID IS NOT NULL THEN
	SELECT PFU.FOREST_FILE_ID,
	       hva.CUTTING_PERMIT_ID,
	       CB.CUT_BLOCK_ID
	  INTO PFU_TEMP_CODE,
	       CPI_TEMP_CODE,
	       CB_TEMP_CODE
	  FROM PROV_FOREST_USE PFU
	 INNER JOIN hauling_authority hla on pfu.forest_file_id = hla.forest_file_id
	 inner join harvesting_hauling_xref hhx on hla.timber_mark = hhx.timber_mark
	 inner join harvesting_authority hva on hhx.hva_skey = hva.hva_skey
	 inner join cut_block cb on cb.forest_file_id = hva.forest_file_id
	 where PFU.FOREST_FILE_ID = P_FOREST_FILE_ID
	   AND hva.CUTTING_PERMIT_ID = P_CUTTING_PERMIT_ID
	   AND CB.CUT_BLOCK_ID = P_CUT_BLOCK_ID;
  ELSE
	SELECT PFU.FOREST_FILE_ID,
	       hva.CUTTING_PERMIT_ID,
	       CB.CUT_BLOCK_ID
	  INTO PFU_TEMP_CODE,
	       CPI_TEMP_CODE,
	       CB_TEMP_CODE
	  FROM PROV_FOREST_USE PFU
	 INNER JOIN hauling_authority hla on pfu.forest_file_id = hla.forest_file_id
	 inner join harvesting_hauling_xref hhx on hla.timber_mark = hhx.timber_mark
	 inner join harvesting_authority hva on hhx.hva_skey = hva.hva_skey
	 inner join cut_block cb on cb.forest_file_id = hva.forest_file_id
	 where PFU.FOREST_FILE_ID = P_FOREST_FILE_ID
	   AND CB.CUT_BLOCK_ID = P_CUT_BLOCK_ID;
  END IF;

   EXCEPTION
	  WHEN NO_DATA_FOUND THEN
		RAISE_APPLICATION_ERROR (-20001, 'PLS: ECAS - record is not on file.');
  END CHECK_CUT_BLOCK;

/******************************************************************************
    Procedure:  CHECK_ECAS_ID

    Purpose:	Checks that the Ecas Id entered exists.

******************************************************************************/
  PROCEDURE CHECK_ECAS_ID (
                 P_ECAS_ID                                     IN OUT VARCHAR2
               , P_ERROR_MESSAGE                               IN OUT VARCHAR2)
  IS
    TEMP_CODE APPRAISAL_DATA_SUBMISSION.ECAS_ID%TYPE;
  BEGIN
	SELECT ECAS_ID
	INTO TEMP_CODE
	FROM APPRAISAL_DATA_SUBMISSION
	WHERE ECAS_ID = to_number(P_ECAS_ID);

   EXCEPTION
	  WHEN NO_DATA_FOUND THEN
		--P_ERROR_MESSAGE := 'ecas.web.error.ecasid.not.found;';
		RAISE_APPLICATION_ERROR (-20001, 'PLS: ECAS - record is not on file.');
  END;



/******************************************************************************
    Procedure:  CHECK_TOMSTONE_SECURITY

    Purpose:	Checks that the user is authorized to view this ADS.

******************************************************************************/
  PROCEDURE CHECK_TOMBSTONE_SECURITY (
                 P_ECAS_ID                                     IN OUT VARCHAR2
               , P_TIMBER_MARK                                 IN OUT VARCHAR2
               , P_EFFECTIVE_DATE                              IN OUT VARCHAR2
               , P_USERID                                      IN OUT VARCHAR2
               , P_USER_ROLE                                   IN OUT VARCHAR2
               , P_USER_CLIENT                                 IN OUT VARCHAR2
               , P_USER_CLIENT_LOCN                            IN OUT VARCHAR2
               , P_USER_ORG_UNIT                               IN OUT VARCHAR2
               , P_FORM_TYPE                                   IN OUT VARCHAR2
               , P_IS_MINISTRY_USER                            IN OUT VARCHAR2
               , P_ERROR_MESSAGE                               IN OUT VARCHAR2)
 IS
    vEcasId         APPRAISAL_DATA_SUBMISSION.ECAS_ID%TYPE;
    vTest           APPRAISAL_DATA_SUBMISSION.ECAS_ID%TYPE;
    vAdminDistrict  APPRAISAL_DATA_SUBMISSION.ADMIN_DISTRICT%TYPE;
    vOrgLevelCode   VARCHAR2(1);
    vDummy  VARCHAR2(1);
    vAction VARCHAR2(30);
    vErrors VARCHAR2(4000);
    vAppraisalMethodCode APPRAISAL_DATA_SUBMISSION_CTRL.APPRAISAL_METHOD_CODE%TYPE;
    vEcasStatus    APPRAISAL_DATA_SUBMISSION.APPRAISAL_STATUS_CODE%TYPE;
    l_district_region        VARCHAR2(10);
    l_region_rollup_region   VARCHAR2(10);

    wrong_appraisal_type    EXCEPTION;

    CURSOR orgUnitCursor (l_orgUnit VARCHAR2) is
    SELECT ORG_UNIT_NO, ORG_UNIT_CODE, ORG_LEVEL_CODE, ROLLUP_REGION_NO, ROLLUP_REGION_CODE, ROLLUP_DIST_NO, ROLLUP_DIST_CODE
      FROM ORG_UNIT
     WHERE ORG_UNIT_NO = to_number(l_orgUnit);

     CURSOR adsOrgRollup (l_orgUnit VARCHAR2) is
    SELECT ORG_UNIT_NO, ORG_UNIT_CODE, ORG_LEVEL_CODE, ROLLUP_REGION_NO, ROLLUP_REGION_CODE, ROLLUP_DIST_NO, ROLLUP_DIST_CODE
      FROM ORG_UNIT
     WHERE ORG_UNIT_NO = to_number(l_orgUnit);
 BEGIN
        vEcasId := NULL;
        vTest := NULL;
        vAdminDistrict := NULL;
        vDummy := NULL;
        vErrors := NULL;
        vEcasStatus := NULL;

        -- FIRST CHECK AND SEE IF THE ECAS ID EXISTS.  IF IT DOESN'T A SEPARATE VALIDATION WILL CATCH THIS.
        /* CALL TOMBSTONE, GET THE ECAS ID, TIMBER MARK, EFFECTIVE DATE
           CANT USE OUR P_ERROR_MESSAGE OR THE ERRORS WHEN TOMBSTONE FROM JAVA IS CALLED WILL GET DISPLAYED TWICE,
           HENCE THE REASON FOR USING A LOCAL ERROR MESSAGE */
        vAction := 'GET_JAVA_TMARK_EFFECT_DATE';
        PKG_ECAS_TOMBSTONE.MAINLINE(vAction,vDummy,vDummy,P_TIMBER_MARK,P_ECAS_ID,P_EFFECTIVE_DATE,vErrors);

        /*  THE REASON FOR THE LOCAL ECAS ID IS THAT THE ECAS ID SENT IN MAY NOT EXIST.  WE CANNOT GIVE THIS ERROR
            HERE AS THIS IS CALLED BY JAVA AND THE JAVA SIDE WILL CATCH THAT ERROR IN A SEPARATE VALIDATOR AND WE
            DONT WANT DUPLICATE ERROR MESSAGES */
        BEGIN
            IF vErrors IS NULL THEN
                vEcasId := P_ECAS_ID;
                --GET ADMIN DISTRICT
                SELECT A.ADMIN_DISTRICT, A.APPRAISAL_STATUS_CODE
                  INTO vAdminDistrict, vEcasStatus
                  FROM APPRAISAL_DATA_SUBMISSION A
                 WHERE A.ECAS_ID = vEcasId;
            END IF;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN
                NULL;
        END;

       -- IF APPRAISAL EXISTS, CONTINUE
        IF vEcasId IS NOT NULL THEN
            --CHECK AND MAKE SURE THAT THE ECAS ID IS THE CORRECT TYPE.  IE - CAN'T BRING UP A COAST ECAS ID ON AN INTERIOR SCREEN
            BEGIN
                SELECT APPRAISAL_METHOD_CODE
                  INTO vAppraisalMethodCode
                  FROM APPRAISAL_DATA_SUBMISSION_CTRL
                 WHERE ECAS_ID = to_number(P_ECAS_ID);

                  IF P_FORM_TYPE = 'COAST' AND vAppraisalMethodCode <> 'C' THEN
                        P_ERROR_MESSAGE := 'ecas.web.usr.database.wrong.formTypeCoast';
                        RAISE WRONG_APPRAISAL_TYPE;
                  ELSIF P_FORM_TYPE='INTERIOR' AND vAppraisalMethodCode <> 'I' THEN
                        P_ERROR_MESSAGE := 'ecas.web.usr.database.wrong.formTypeInterior';
                        RAISE WRONG_APPRAISAL_TYPE;
                  END IF;
            EXCEPTION
                WHEN NO_DATA_FOUND THEN -- WILL BE CAUGHT BY APP
                    NULL;
            END;

            -- DO SECURITY CHECK FOR CLIENT: THE USER'S CLIENT MUST MATCH THE ONE FOR THAT ECAS ID ON THE ADS TABLE.
            IF P_USER_CLIENT IS NOT NULL THEN
                BEGIN
                    SELECT ECAS_ID
                      INTO vTest
                      FROM APPRAISAL_DATA_SUBMISSION
                     WHERE ECAS_ID = to_number(P_ECAS_ID)
                       AND CLIENT_NUMBER = P_USER_CLIENT;
                EXCEPTION
                    WHEN NO_DATA_FOUND THEN
                        P_ERROR_MESSAGE := 'ecas.web.usr.database.clientAppraisalRole';
                END;
            -- DO SECURITY CHECK FOR DISTRICT, REGION, HEADQUARTERS
            ELSIF P_USER_ORG_UNIT IS NOT NULL THEN

                IF P_USER_ORG_UNIT IS NOT NULL THEN
                   SELECT TO_CHAR(ads.admin_district) INTO l_district_region FROM APPRAISAL_DATA_SUBMISSION ads WHERE ads.ecas_id = P_ECAS_ID;
                END IF;

                IF l_district_region IS NOT NULL THEN
                   SELECT TO_CHAR(ou.rollup_region_no) INTO l_region_rollup_region FROM ORG_UNIT ou WHERE ou.org_unit_no=l_district_region;
                END IF;

                IF l_district_region IS NOT NULL AND l_region_rollup_region IS NOT NULL THEN
                   IF P_USER_ORG_UNIT NOT LIKE '%|'||l_region_rollup_region||'|%' AND P_USER_ORG_UNIT NOT LIKE '%|'||l_district_region||'|%' THEN
                      P_ERROR_MESSAGE := 'ecas.web.usr.database.error.AppraisalNotAuthorized';
                   END IF;
                END IF;

                /*FOR i IN orgUnitCursor(P_USER_ORG_UNIT) LOOP
                    -- IF ORG IS A DISTRICT THEN MAKE SURE THE USER'S DISTRICT MATCHES THE ADMIN DISTRICT IN ADS.
                    vOrgLevelCode := SUBSTR(i.ORG_UNIT_CODE,1,1);
                    IF vOrgLevelCode = 'D' THEN
                        IF i.ORG_UNIT_NO <> vAdminDistrict THEN
                            P_ERROR_MESSAGE := 'ecas.web.usr.database.error.AppraisalNotAuthorized';
                        END IF;
                    -- IF ORG IS A REGION, ENSURE THE ADS DISTRICT FALLS WITHIN THE REGION
                    ELSIF vOrgLevelCode = 'R' THEN
                        -- CHECK AND MAKE SURE THE ROLLUP REGION FOR THE ADMIN IS THE SAME AS THE REGION'S ORG.
                        -- THIS IS FOR A REGION USER LOGGED ON
                        FOR j IN adsOrgRollup(vAdminDistrict) LOOP
                            IF i.ROLLUP_REGION_CODE <> j.ROLLUP_REGION_CODE THEN
                                P_ERROR_MESSAGE := 'ecas.web.usr.database.error.AppraisalNotAuthorized';
                            END IF;
                        END LOOP;
                    END IF;
                END LOOP;*/
            END IF;

            --Ministry view only users CANNOT see draft appraisals, but non-ministry can.
            IF P_USER_ROLE = 'ECAS_VIEW_ONLY' AND P_IS_MINISTRY_USER = 'Y' THEN
               IF vEcasStatus = 'DFT' THEN
                    P_ERROR_MESSAGE := 'ecas.web.usr.database.appraisal.invalidstatus';
                END IF;
            /*
            ELSIF P_USER_ROLE IN ('ECAS_DISTRICT', 'ECAS_REGION') THEN
                --admin, licensee, rpf, bcts, bcts submit can only view DFT appraisals
                IF vEcasStatus = 'DFT' THEN
                    P_ERROR_MESSAGE := 'ecas.web.usr.database.appraisal.invalidstatus';
                END IF;*/
            ELSIF P_USER_ROLE IN ('ECAS_BCTS', 'ECAS_BCTS_SUBMIT', 'ECAS_LICENSEE', 'ECAS_RPF') THEN
                --BCTS, BCTS_SUBMIT, LICENSEE, and RPFs can't see Scenarios.
                IF vEcasStatus = 'SCN' THEN
                    P_ERROR_MESSAGE := 'ecas.web.usr.database.appraisal.invalidstatus';
                END IF;
            END IF;

        END IF;
 EXCEPTION
 WHEN WRONG_APPRAISAL_TYPE THEN
    NULL;
 END;

END PKG_ECAS_VALIDATION;
