CREATE OR REPLACE EDITIONABLE PACKAGE BODY "THE"."ECAS_COMMON" IS

  PROCEDURE FIND_ALL_ECAS_IDS(P_ECAS_ID IN OUT ref_ecas_id) IS
  BEGIN
    OPEN P_ECAS_ID FOR
      SELECT ADS.ECAS_ID
      FROM APPRAISAL_DATA_SUBMISSION ADS;

  END FIND_ALL_ECAS_IDS;

  /******************************************************************************
      Procedure: FIND_ADS_SPECIES_VOLUMES
      Purpose:
  ******************************************************************************/
  PROCEDURE FIND_ADS_SPECIES_VOLUMES(P_ECAS_ID            IN ADS_SPECIES_VOLUME.ECAS_ID%TYPE,
                                     P_ADS_SPECIES_VOLUME IN OUT ref_ads_species_volume) IS
  BEGIN
    OPEN P_ADS_SPECIES_VOLUME FOR
      SELECT ASV.ECAS_ID,
             ASV.HDBS_TREE_SPECIES,
             ASV.SPECIES_VOLUME,
             ASV.GRADE_SOURCE,
             ASV.DECAY_PCT,
             ASV.STUD_PCT,
             ASV.BURN_PCT,
             ASV.GRADE_PCT,
             ASV.LUMBER_RECOVERY_FACTOR,
             ASV.REVISION_COUNT,
             ASV.ENTRY_USERID,
             ASV.ENTRY_TIMESTAMP,
             ASV.UPDATE_USERID,
             ASV.UPDATE_TIMESTAMP
        FROM ADS_SPECIES_VOLUME ASV
       WHERE ASV.ECAS_ID = P_ECAS_ID;
  END FIND_ADS_SPECIES_VOLUMES;

  /******************************************************************************
      Procedure:  FIND_ADS_BY_ADMIN_DISTRICT
      Purpose: Finds all ADSs that bear the given admin district
  ******************************************************************************/
