             ADS.LICENSEE_REP_ENTERED_DATE,
             ADS.DISTRICT_RECEIVED_DATE,
             ADS.SENT_DATE,
             ADS.CLIENT_NUMBER,
             ADS.CLIENT_LOCN_CODE,
             ADS.SENT_BY_USER_ID,
             ADS.TRANSFER_BY_USER_ID,
             ADS.STATUS_CHANGE_DATE,
             ADS.TRANSFER_DATE,
             ADS.DATA_FIELD_CHECKED_IND,
             ADS.NRST_PT_EFFECTIVE_DATE,
             ADS.CP_CRUISE_CHECKED_IND,
             ADS.FTAS_DATA_VALIDATED_IND,
             ADS.MVI_ELIGIBLE_IND,
             ADS.TOA_ELIGIBLE_IND,
             ADS.MPS_CVP_DIFFERENTIAL,
             ADS.RATE_ADJUSTMENT_TYPE_CODE,
             ADS.NO_CHANGE_IND,
             ADS.STUMPAGE_RATE_EXTENSION_IND,
             ADS.LICENSEE_REP_FIRST_NAME,
             ADS.LICENSEE_REP_MIDDLE_INITIAL,
             ADS.LICENSEE_REP_LAST_NAME,
