             ADS.INTERIOR_DEVELOPMENT_LEVY,
             ADS.REVISION_COUNT,
             ADS.ENTRY_USERID,
             ADS.ENTRY_TIMESTAMP,
             ADS.UPDATE_USERID,
             ADS.UPDATE_TIMESTAMP,
             ADS.REAPPRAISAL_REASON_CODE,
             ADS.RW_VOLUME
        FROM APPRAISAL_DATA_SUBMISSION ADS
       INNER JOIN APPRAISAL_DATA_SUBMISSION_CTRL ADSC
          ON ADS.ECAS_ID = ADSC.ECAS_ID
       WHERE ADS.ADMIN_DISTRICT = P_ADMIN_DISTRICT;

  END FIND_ADS_BY_ADMIN_DISTRICT;

