  PROCEDURE FIND_ECAS_ADMIN_CLIENT(P_USER_ID           IN ECAS_ADMIN_CLIENT.USER_ID%TYPE,
                                   P_CLIENT_NUMBER     IN ECAS_ADMIN_CLIENT.CLIENT_NUMBER%TYPE,
                                   P_CLIENT_LOCN_CODE  IN ECAS_ADMIN_CLIENT.CLIENT_LOCN_CODE%TYPE,
                                   P_ECAS_ADMIN_CLIENT IN OUT ref_ecas_admin_client) IS
  BEGIN
    OPEN P_ECAS_ADMIN_CLIENT FOR
      SELECT EAC.USER_ID,
             EAC.CLIENT_NUMBER,
             EAC.CLIENT_LOCN_CODE,
             EAC.DISTRICT_REP_IND,
             EAC.REGION_REP_IND,
             EAC.EFFECTIVE_DATE,
             EAC.EXPIRY_DATE,
             EAC.REVISION_COUNT,
             EAC.ENTRY_USERID,
             EAC.ENTRY_TIMESTAMP,
             EAC.UPDATE_USERID,
             EAC.UPDATE_TIMESTAMP
        FROM ECAS_ADMIN_CLIENT EAC
       WHERE EAC.USER_ID = P_USER_ID
         AND EAC.CLIENT_NUMBER = P_CLIENT_NUMBER
         AND EAC.CLIENT_LOCN_CODE = P_CLIENT_LOCN_CODE;
  END FIND_ECAS_ADMIN_CLIENT;

  PROCEDURE INSERT_ECAS_ADMIN_CLIENT(P_USER_ID           ECAS_ADMIN_CLIENT.USER_ID%TYPE,
                                     P_CLIENT_NUMBER     ECAS_ADMIN_CLIENT.CLIENT_NUMBER%TYPE,
                                     P_CLIENT_LOCN_CODE  ECAS_ADMIN_CLIENT.CLIENT_LOCN_CODE%TYPE,
                                     P_DISTRICT_REP_IND  ECAS_ADMIN_CLIENT.DISTRICT_REP_IND%TYPE,
                                     P_REGION_REP_IND    ECAS_ADMIN_CLIENT.REGION_REP_IND%TYPE,
                                     P_EXPIRY_DATE       ECAS_ADMIN_CLIENT.EXPIRY_DATE%TYPE,
                                     P_ENTRY_USERID      ECAS_ADMIN_CLIENT.ENTRY_USERID%TYPE,
                                     P_ECAS_ADMIN_CLIENT IN OUT ref_ecas_admin_client) IS
  BEGIN
    INSERT INTO ECAS_ADMIN_CLIENT
      (USER_ID,
       CLIENT_NUMBER,
       CLIENT_LOCN_CODE,
       DISTRICT_REP_IND,
       REGION_REP_IND,
       EFFECTIVE_DATE,
       EXPIRY_DATE,
       REVISION_COUNT,
       ENTRY_USERID,
       ENTRY_TIMESTAMP,
       UPDATE_USERID,
       UPDATE_TIMESTAMP)
    VALUES
      (P_USER_ID,
       P_CLIENT_NUMBER,
       P_CLIENT_LOCN_CODE,
       P_DISTRICT_REP_IND,
       P_REGION_REP_IND,
       trunc(SYSDATE),
       trunc(P_EXPIRY_DATE),
       1,
       P_ENTRY_USERID,
       SYSDATE,
       P_ENTRY_USERID,
       SYSDATE);

    FIND_ECAS_ADMIN_CLIENT(P_USER_ID,
                           P_CLIENT_NUMBER,
                           P_CLIENT_LOCN_CODE,
                           P_ECAS_ADMIN_CLIENT);

  END INSERT_ECAS_ADMIN_CLIENT;

  PROCEDURE UPDATE_ECAS_ADMIN_CLIENT(P_USER_ID          ECAS_ADMIN_CLIENT.USER_ID%TYPE,
                                     P_CLIENT_NUMBER    ECAS_ADMIN_CLIENT.CLIENT_NUMBER%TYPE,
                                     P_CLIENT_LOCN_CODE ECAS_ADMIN_CLIENT.CLIENT_LOCN_CODE%TYPE,
                                     P_DISTRICT_REP_IND ECAS_ADMIN_CLIENT.DISTRICT_REP_IND%TYPE,
                                     P_REGION_REP_IND   ECAS_ADMIN_CLIENT.REGION_REP_IND%TYPE,
                                     P_EXPIRY_DATE      ECAS_ADMIN_CLIENT.EXPIRY_DATE%TYPE,
                                     P_UPDATE_USERID    ECAS_ADMIN_CLIENT.UPDATE_USERID%TYPE) IS
  BEGIN
    UPDATE ECAS_ADMIN_CLIENT EAC
       SET EAC.DISTRICT_REP_IND = P_DISTRICT_REP_IND,
           EAC.REGION_REP_IND   = P_REGION_REP_IND,
           EAC.EXPIRY_DATE      = TRUNC(P_EXPIRY_DATE),
           EAC.REVISION_COUNT   = REVISION_COUNT + 1,
           EAC.UPDATE_USERID    = P_UPDATE_USERID,
           EAC.UPDATE_TIMESTAMP = SYSDATE
     WHERE EAC.USER_ID = P_USER_ID
       AND EAC.CLIENT_NUMBER = P_CLIENT_NUMBER
       AND EAC.CLIENT_LOCN_CODE = P_CLIENT_LOCN_CODE;

  END UPDATE_ECAS_ADMIN_CLIENT;

  /******************************************************************************
      Procedure: FIND_HARVEST_SALE_BY_FFID
      Purpose:   Finds a HARVEST_SALE record by FOREST FILE ID
  ******************************************************************************/
  PROCEDURE FIND_HARVEST_SALE_BY_FFID(P_FFID         IN HARVEST_SALE.FOREST_FILE_ID%TYPE,
                                      P_HARVEST_SALE IN OUT ref_harvest_sale) IS
  BEGIN
    OPEN P_HARVEST_SALE FOR
      SELECT HS.FOREST_FILE_ID,
             HS.SB_FUND_IND,
             HS.SALE_METHOD_CODE,
             HS.SALE_TYPE_CD,
             HS.PLANNED_SALE_DATE,
             HS.TENDER_OPENING_DT,
             HS.PLND_SB_CAT_CODE,
             HS.SOLD_SB_CAT_CODE,
             HS.TOTAL_BIDDERS,
             HS.LUMPSUM_BONUS_AMT,
             HS.CASH_SALE_EST_VOL,
             HS.CASH_SALE_TOT_DOL,
             HS.PAYMENT_METHOD_CD,
             HS.SALVAGE_IND,
             HS.SALE_VOLUME,
             HS.ADMIN_AREA_IND,
             HS.MINOR_FACILITY_IND,
             HS.BCTS_ORG_UNIT,
             HS.ENTRY_USERID,
             HS.ENTRY_TIMESTAMP,
             HS.UPDATE_USERID,
             HS.UPDATE_TIMESTAMP,
             HS.REVISION_COUNT
        FROM HARVEST_SALE HS
       WHERE HS.FOREST_FILE_ID = P_FFID;
  END FIND_HARVEST_SALE_BY_FFID;

  /******************************************************************************
      Procedure: FIND_PROV_FOREST_USE_BY_FFID
      Purpose:   Finds a PROV_FOREST_USE record by FOREST FILE ID
  ******************************************************************************/
  PROCEDURE FIND_PROV_FOREST_USE_BY_FFID(P_FFID         IN PROV_FOREST_USE.FOREST_FILE_ID%TYPE,
                                      P_PROV_FOREST_USE IN OUT ref_prov_forest_use) IS
  BEGIN
    OPEN P_PROV_FOREST_USE FOR
      SELECT PFU.FOREST_FILE_ID,
             PFU.FILE_STATUS_ST,
             PFU.FILE_STATUS_DATE,
             PFU.FILE_TYPE_CODE,
             PFU.FOREST_REGION,
             PFU.MGMT_UNIT_TYPE,
             PFU.ENTRY_USERID,
             PFU.MGMT_UNIT_ID,
             PFU.ENTRY_TIMESTAMP,
             PFU.UPDATE_USERID,
             PFU.UPDATE_TIMESTAMP,
             PFU.REVISION_COUNT,
             PFU.BCTS_ORG_UNIT,
             PFU.SB_FUNDED_IND,
             PFU.DISTRICT_ADMIN_ZONE
        FROM PROV_FOREST_USE PFU
       WHERE PFU.FOREST_FILE_ID = P_FFID;
  END FIND_PROV_FOREST_USE_BY_FFID;

  /******************************************************************************
      Procedure: FIND_HAUL_AUTH_BY_TM
      Purpose:   Finds a Hauling Authority by Timber Mark
  ******************************************************************************/
  PROCEDURE FIND_HAUL_AUTH_BY_TM(P_TIMBER_MARK       IN HAULING_AUTHORITY.TIMBER_MARK%TYPE,
                                 P_HAULING_AUTHORITY IN OUT ref_hauling_authority) IS
  BEGIN
    OPEN P_HAULING_AUTHORITY FOR
      SELECT HA.TIMBER_MARK,
             HA.FOREST_FILE_ID,
             HA.MARKING_METHOD_CODE,
             HA.MARKING_INSTRUMENT_CODE,
             HA.REVISION_COUNT,
             HA.ENTRY_TIMESTAMP,
             HA.UPDATE_USERID,
             HA.UPDATE_TIMESTAMP,
             HA.ENTRY_USERID
        FROM HAULING_AUTHORITY HA
       WHERE HA.TIMBER_MARK = P_TIMBER_MARK;
  END FIND_HAUL_AUTH_BY_TM;

  /******************************************************************************
      Procedure: GET_NON_EXPIRED_USER
      Purpose:   Returns a user only if the user is not expired
  ******************************************************************************/
  PROCEDURE GET_NON_EXPIRED_USER(P_USER_ID   IN VARCHAR2,
                                 p_ref_users in out ref_users) is
  begin
    open p_ref_users for
      SELECT mu.user_id, mu.first_name, mu.last_name, mu.email_address
        FROM mof_user mu
       WHERE mu.user_id = P_USER_ID
         AND (mu.enrolled_expiry_date >= SYSDATE OR
             mu.enrolled_expiry_date IS NULL);

  end GET_NON_EXPIRED_USER;

  /******************************************************************************
      Procedure: GET_ALL_DIST_USERS_FOR_CLIENT
      Purpose:   Gets all district level users in the given org unit that have an ECAS_ADMIN_CLIENT entry for the given client/location
  ******************************************************************************/
  PROCEDURE GET_ALL_DIST_USERS_FOR_CLIENT(p_client_no        IN VARCHAR2,
                                          p_client_locn_code IN VARCHAR2,
                                          p_ref_users        in out ref_users) is
  begin
    open p_ref_users for
      SELECT mu.user_id, mu.first_name, mu.last_name, mu.email_address
        FROM mof_user mu
       inner join ecas_admin_client eac
          on eac.user_id = mu.user_id
       WHERE eac.client_number = p_client_no
         AND eac.client_locn_code = p_client_locn_code
         AND eac.district_rep_ind = 'Y'
         AND eac.region_rep_ind = 'N'
         AND eac.effective_date <= SYSDATE
         AND eac.expiry_date > SYSDATE
         AND (mu.enrolled_expiry_date >= SYSDATE OR
             mu.enrolled_expiry_date IS NULL);

  end GET_ALL_DIST_USERS_FOR_CLIENT;

  /******************************************************************************
      Procedure: GET_ALL_REG_USERS_FOR_CLIENT
      Purpose:   Gets all district level users in the given org unit that have an ECAS_ADMIN_CLIENT entry for the given client/location
  ******************************************************************************/
  PROCEDURE GET_ALL_REG_USERS_FOR_CLIENT(p_client_no        IN VARCHAR2,
                                         p_client_locn_code IN VARCHAR2,
                                         p_ref_users        in out ref_users) is
  begin
    open p_ref_users for
      SELECT mu.user_id, mu.first_name, mu.last_name, mu.email_address
        FROM mof_user mu
       inner join ecas_admin_client eac
          on eac.user_id = mu.user_id
       WHERE eac.client_number = p_client_no
         AND eac.client_locn_code = p_client_locn_code
         AND eac.district_rep_ind = 'N'
         AND eac.region_rep_ind = 'Y'
         AND eac.effective_date <= SYSDATE
         AND eac.expiry_date > SYSDATE
         AND (mu.enrolled_expiry_date >= SYSDATE OR
             mu.enrolled_expiry_date IS NULL);

  end GET_ALL_REG_USERS_FOR_CLIENT;

  /******************************************************************************
      Procedure: GET_ALL_REG_USERS_FOR_DIST
      Purpose:   Gets all region level users in the given org unit that have an ecas_admin_notification entry for the given district org unit
  ******************************************************************************/
  PROCEDURE GET_ALL_REG_USERS_FOR_DIST(p_org_unit_no IN VARCHAR2,
                                       p_ref_users   in out ref_users) is
  begin
    open p_ref_users for
      SELECT mu.user_id, mu.first_name, mu.last_name, mu.email_address
        FROM mof_user mu
       inner join ecas_admin_notification ean
          on mu.user_id = ean.user_id
       WHERE ean.org_unit_no = p_org_unit_no
         AND (mu.enrolled_expiry_date >= SYSDATE OR
             mu.enrolled_expiry_date IS NULL)
         AND ean.effective_date <= SYSDATE
         AND ean.expiry_date > SYSDATE;

  end GET_ALL_REG_USERS_FOR_DIST;

  PROCEDURE GET_SUBMIT_USER(P_ECAS_ID           IN VARCHAR2,
                            P_CLIENT_LOCN_CODE  IN VARCHAR2,
                            P_CLIENT_NUMBER     IN VARCHAR2,
                            P_USER_ROLE         IN VARCHAR2,
                            P_RPF_USER_ID       IN OUT VARCHAR2,
                            P_RPF_NAME          IN OUT VARCHAR2,
                            P_MEMBER_NUMBER     IN OUT VARCHAR2,
                            P_RPF_IND           IN OUT VARCHAR2,
                            P_RFT_IND           IN OUT VARCHAR2,
                            P_RPF_PHONE_NUMBER  IN OUT VARCHAR2,
                            P_RPF_FAX_NUMBER    IN OUT VARCHAR2,
                            P_RPF_EMAIL_ADDRESS IN OUT VARCHAR2,
                            P_REVISION_COUNT    IN VARCHAR2) IS

    l_check VARCHAR2(1);

    CURSOR c_rpf_exists IS
      SELECT 'x'
        FROM APPRAISAL_DATA_SUBMISSION
       WHERE ECAS_ID = to_number(P_ECAS_ID)
         AND REVISION_COUNT = to_number(P_REVISION_COUNT)
         AND RPF_USER_ID IS NOT NULL;

    CURSOR c_rpf_ads IS
      SELECT MU.USER_ID,
             MU.LAST_NAME || ', ' || MU.FIRST_NAME RPF_NAME,
             RLR.MEMBER_NUMBER,
             RLR.RPF_IND,
             RLR.RFT_IND,
             PKG_ECAS_VALIDATION.FORMAT_PHONE_NUMBER(MU.PHONE_NUMBER) RPF_PHONE_NUMBER,
             PKG_ECAS_VALIDATION.FORMAT_PHONE_NUMBER(TO_CHAR(RLR.FAX_NUMBER)) RPF_FAX_NUMBER,
             DECODE(SIGN(mu.enrolled_expiry_date - SYSDATE),
                    -1,
                    '',
                    mu.email_address) RPF_EMAIL_ADDRESS
        FROM APPRAISAL_DATA_SUBMISSION ADS,
             RPF_LICENSEE_REP          RLR,
             MOF_USER                  MU
       WHERE ADS.ECAS_ID = to_number(P_ECAS_ID)
         AND ADS.REVISION_COUNT = to_number(P_REVISION_COUNT)
         AND ADS.RPF_USER_ID = RLR.USER_ID
         AND RLR.USER_ID = MU.USER_ID
         AND (RLR.RPF_IND = 'Y' OR RLR.RFT_IND = 'Y')
         AND RLR.REP_ACTIVE_IND = 'Y';

    CURSOR c_rpf IS
      SELECT MU.USER_ID,
             MU.LAST_NAME || ', ' || MU.FIRST_NAME RPF_NAME,
             RLR.MEMBER_NUMBER,
             RLR.RPF_IND,
             RLR.RFT_IND,
             PKG_ECAS_VALIDATION.FORMAT_PHONE_NUMBER(MU.PHONE_NUMBER) RPF_PHONE_NUMBER,
             PKG_ECAS_VALIDATION.FORMAT_PHONE_NUMBER(TO_CHAR(RLR.FAX_NUMBER)) RPF_FAX_NUMBER,
             DECODE(SIGN(mu.enrolled_expiry_date - SYSDATE),
                    -1,
                    '',
                    mu.email_address) RPF_EMAIL_ADDRESS
        FROM RPF_LICENSEE_REP RLR, MOF_USER MU
       WHERE RLR.USER_ID = MU.USER_ID
         AND RLR.USER_ID = P_RPF_USER_ID
         AND RLR.CLIENT_LOCN_CODE = P_CLIENT_LOCN_CODE
         AND RLR.CLIENT_NUMBER = P_CLIENT_NUMBER
         AND (RLR.RPF_IND = 'Y' OR RLR.RFT_IND = 'Y')
         AND RLR.REP_ACTIVE_IND = 'Y';
  BEGIN
    OPEN c_rpf_exists;
    FETCH c_rpf_exists
      INTO l_check;
    --Retrieve data from APPRAISAL_DATA_SUBMISSION table if it exists
    IF c_rpf_exists%FOUND THEN
      OPEN c_rpf_ads;
      FETCH c_rpf_ads
        INTO P_RPF_USER_ID,
             P_RPF_NAME,
             P_MEMBER_NUMBER,
             P_RPF_IND,
             P_RFT_IND,
             P_RPF_PHONE_NUMBER,
             P_RPF_FAX_NUMBER,
             P_RPF_EMAIL_ADDRESS;
      CLOSE c_rpf_ads;
      -- I couldn't make the licensee fax number null in the select.  due to the union
      -- it must be the same type as the table.  I selected a zero for the case of bcts
      -- as there is no entry in RPF_LICENSEE_REP.  I am now reseting the 0 value to null.
      IF P_RPF_FAX_NUMBER = '0' THEN
        P_RPF_FAX_NUMBER := '';
      END IF;

      --Otherwise, if user is an RPF, retrieve their personal data
    ELSIF (P_USER_ROLE = 'ECAS_RPF' OR P_USER_ROLE = 'ECAS_BCTS_SUBMIT') THEN

      OPEN c_rpf;
      FETCH c_rpf
        INTO P_RPF_USER_ID,
             P_RPF_NAME,
             P_MEMBER_NUMBER,
             P_RPF_IND,
             P_RFT_IND,
             P_RPF_PHONE_NUMBER,
             P_RPF_FAX_NUMBER,
             P_RPF_EMAIL_ADDRESS;
      CLOSE c_rpf;
    END IF;
    CLOSE c_rpf_exists;

  END GET_SUBMIT_USER;

  PROCEDURE GET_DISTRICT_REP_SENT_BY(P_ECAS_ID       IN VARCHAR2,
                                     P_USER_ID       IN OUT VARCHAR2,
                                     P_FIRST_NAME    IN OUT VARCHAR2,
                                     P_LAST_NAME     IN OUT VARCHAR2,
                                     P_EMAIL_ADDRESS IN OUT VARCHAR2) IS
  BEGIN
    SELECT ADS.SENT_BY_USER_ID,
           MU.FIRST_NAME,
           MU.LAST_NAME,
           DECODE(SIGN(MU.ENROLLED_EXPIRY_DATE - SYSDATE),
                  -1,
                  '',
                  MU.EMAIL_ADDRESS) EMAIL_ADDRESS
      INTO P_USER_ID, P_FIRST_NAME, P_LAST_NAME, P_EMAIL_ADDRESS
      FROM APPRAISAL_DATA_SUBMISSION ADS, MOF_USER MU
     WHERE ADS.SENT_BY_USER_ID = MU.USER_ID
       AND ADS.ECAS_ID = to_number(P_ECAS_ID);
  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      null; -- ingnore
  END GET_DISTRICT_REP_SENT_BY;

  PROCEDURE GET_REGION_REP_TRANSFERED_BY(P_ECAS_ID       IN VARCHAR2,
                                         P_USER_ID       IN OUT VARCHAR2,
                                         P_FIRST_NAME    IN OUT VARCHAR2,
                                         P_LAST_NAME     IN OUT VARCHAR2,
                                         P_EMAIL_ADDRESS IN OUT VARCHAR2) IS
  BEGIN
    P_USER_ID       := NULL;
    P_FIRST_NAME    := NULL;
    P_LAST_NAME     := NULL;
    P_EMAIL_ADDRESS := NULL;
    SELECT ADS.TRANSFER_BY_USER_ID,
           MU.FIRST_NAME,
           MU.LAST_NAME,
           DECODE(SIGN(MU.ENROLLED_EXPIRY_DATE - SYSDATE),
                  -1,
                  '',
                  MU.EMAIL_ADDRESS)
      INTO P_USER_ID, P_FIRST_NAME, P_LAST_NAME, P_EMAIL_ADDRESS
      FROM APPRAISAL_DATA_SUBMISSION ADS, MOF_USER MU
     WHERE ADS.TRANSFER_BY_USER_ID = MU.USER_ID
       AND ADS.ECAS_ID = to_number(P_ECAS_ID);
  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      null; -- ingnore
  END GET_REGION_REP_TRANSFERED_BY;

  PROCEDURE ADD_TO_USERS_INBOX(P_ECAS_ID           IN VARCHAR2,
                               P_USER_ID_FOR_INBOX IN VARCHAR2,
                               P_ORG_UNIT_NO       IN VARCHAR2,
                               P_UPDATE_USER_ID    IN VARCHAR2) IS
    fromString      VARCHAR2(32767) := P_USER_ID_FOR_INBOX;
    separatedBy     VARCHAR2(1) := ',';
    markerPos       INTEGER;
    startPos        INTEGER;
    subString       VARCHAR2(32767);
    subStringLength INTEGER;
  BEGIN
    IF (INSTR(P_USER_ID_FOR_INBOX, ',') = 0) THEN
      INSERT INTO ADS_ASSIGNED_TO_USER
      VALUES
        (to_number(P_ECAS_ID),
         P_USER_ID_FOR_INBOX,
         to_number(P_ORG_UNIT_NO),
         1,
         P_UPDATE_USER_ID,
         SYSDATE,
         P_UPDATE_USER_ID,
         SYSDATE);
    ELSE
      startPos  := 1;
      markerPos := INSTR(fromString, separatedBy, startPos);
      /*
       * Iterate through all the sub-strings, based on separatedBy marker
      */
      WHILE markerPos > 0 LOOP
        subStringLength := markerPos - startPos;
        subString       := SUBSTR(fromString, startPos, subStringLength);

        INSERT INTO ADS_ASSIGNED_TO_USER
        VALUES
          (to_number(P_ECAS_ID),
           subString,
           to_number(P_ORG_UNIT_NO),
           1,
           P_UPDATE_USER_ID,
           SYSDATE,
           P_UPDATE_USER_ID,
           SYSDATE);

        startPos := markerPos + 1;
        IF startPos > LENGTH(fromString) THEN
          markerPos := 0;
        ELSE
          markerPos := INSTR(fromString, separatedBy, startPos);
        END IF;
      END LOOP;
      /*
       * Don't forget about the last few characters.
      */
      IF markerPos = 0 AND startPos < LENGTH(fromString) THEN
        subStringLength := LENGTH(fromString) - startPos + 1;
        subString       := SUBSTR(fromString, startPos, subStringLength);

        INSERT INTO ADS_ASSIGNED_TO_USER
        VALUES
          (to_number(P_ECAS_ID),
           subString,
           to_number(P_ORG_UNIT_NO),
           1,
           P_UPDATE_USER_ID,
           SYSDATE,
           P_UPDATE_USER_ID,
           SYSDATE);

      END IF;
    END IF;
  END ADD_TO_USERS_INBOX;

  PROCEDURE REMOVE_FROM_USERS_INBOX(P_ECAS_ID IN VARCHAR2
                                    /*P_INBOX_USER_ID  IN VARCHAR2,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               P_ORG_UNIT_NO    IN VARCHAR2,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               P_UPDATE_USER_ID IN VARCHAR2*/) IS
  BEGIN
    DELETE FROM ADS_ASSIGNED_TO_USER WHERE ECAS_ID = P_ECAS_ID;
  END REMOVE_FROM_USERS_INBOX;

  FUNCTION GET_FIRST_DELIMITED_VALUE(P_VALUE IN OUT VARCHAR2) RETURN VARCHAR2 IS
    fromString  VARCHAR2(32767) := P_VALUE;
    separatedBy VARCHAR2(1) := ',';
    markerPos   INTEGER;
    startPos    INTEGER;
  BEGIN
    startPos  := 1;
    markerPos := INSTR(fromString, separatedBy, startPos);
    RETURN(SUBSTR(fromString, 1, markerPos - 1));
  END;

  PROCEDURE GET_ORG_UNIT_INFO(p_org_unit_no   IN OUT VARCHAR2,
                              p_org_unit_code IN OUT VARCHAR2,
                              p_org_unit_desc IN OUT VARCHAR2) IS
  BEGIN
    SELECT sil_get_org_unit_code(p_org_unit_no)
      INTO p_org_unit_code
      FROM dual;
    SELECT sil_get_org_desc(p_org_unit_code)
      INTO p_org_unit_desc
      FROM dual;
  END GET_ORG_UNIT_INFO;

  PROCEDURE GET_LICENSEE_REP(p_ecas_id       IN VARCHAR2,
                             p_first_name    IN OUT VARCHAR2,
                             p_last_name     IN OUT VARCHAR2,
                             p_email_address IN OUT VARCHAR2) IS
  BEGIN
    SELECT ADS.LICENSEE_REP_FIRST_NAME,
           ADS.LICENSEE_REP_LAST_NAME,
           ADS.LICENSEE_REP_EMAIL_ADDRESS
      INTO p_first_name, p_last_name, p_email_address
      FROM APPRAISAL_DATA_SUBMISSION ADS
     WHERE ADS.ECAS_ID = to_number(p_ecas_id);
