  END;

  PROCEDURE GET_LICENSEE_REP(p_ecas_id       IN VARCHAR2,
                             p_email_address IN OUT VARCHAR2) IS
    l_temp VARCHAR2(32767);
  BEGIN
    GET_LICENSEE_REP(p_ecas_id, l_temp, l_temp, p_email_address);
  END;

  PROCEDURE GET_RPF_INFO(p_ecas_id       IN VARCHAR2,
                         p_user_id       OUT VARCHAR2,
                         p_email_address OUT VARCHAR2) IS
  BEGIN
    SELECT MU.USER_ID, MU.EMAIL_ADDRESS
      INTO p_user_id, p_email_address
      FROM APPRAISAL_DATA_SUBMISSION ADS, MOF_USER MU
     WHERE ADS.ECAS_ID = to_number(P_ECAS_ID)
       AND ADS.RPF_USER_ID = MU.USER_ID
       AND (MU.ENROLLED_EXPIRY_DATE IS NULL OR
           MU.ENROLLED_EXPIRY_DATE >= SYSDATE);
  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      p_email_address := NULL;
  END;

  PROCEDURE GET_RPF_INFO(p_ecas_id       IN VARCHAR2,
                         p_email_address OUT VARCHAR2) IS
    l_temp MOF_USER.USER_ID%TYPE;
  BEGIN
    GET_RPF_INFO(p_ecas_id, l_temp, p_email_address);
  END;

  PROCEDURE GET_USER_SETUP_INFO(p_user_id                IN OUT VARCHAR2,
                                p_user_does_not_exist    IN OUT VARCHAR2,
                                p_user_has_expired       IN OUT VARCHAR2,
                                p_has_org_unit_entry     IN OUT VARCHAR2,
                                p_has_rpf_licensee_entry IN OUT VARCHAR2,
                                p_error_message          IN OUT VARCHAR2) IS
    l_temp MOF_USER.USER_ID%TYPE;
    l_date DATE;
  BEGIN
    p_user_does_not_exist    := 'N';
    p_user_has_expired       := 'N';
    p_has_org_unit_entry     := 'N';
    p_has_rpf_licensee_entry := 'N';
    -- see if user has expired or not
    BEGIN
      SELECT enrolled_expiry_date
        INTO l_date
        FROM mof_user
       WHERE user_id = p_user_id;

      IF l_date IS NOT NULL THEN
        IF l_date > SYSDATE THEN
          p_user_has_expired := 'N';
        ELSE
          p_user_has_expired := 'Y';
        END IF;
      END IF;
    EXCEPTION
      WHEN NO_DATA_FOUND THEN
        p_user_does_not_exist := 'Y';
    END;

    -- see if user has been setup with a default org unit
    BEGIN
      SELECT user_id
        INTO l_temp
        FROM mof_user_org_default
       WHERE user_id = p_user_id
         AND application_acronym = 'ECAS';
      p_has_org_unit_entry := 'Y';
    EXCEPTION
      WHEN NO_DATA_FOUND THEN
        p_has_org_unit_entry := 'N';
    END;

  EXCEPTION
    WHEN OTHERS THEN
      p_error_message := p_error_message ||
                         'ecas.web.usr.database.unexpected:ECAS_COMMON,GET_USER_SETUP_INFO,' ||
                         SQLCODE || ',' || SQLERRM || ';';
  END;

  /******************************************************************************
    Procedure:  MVI_DEFAULT
    Purpose:    To derive the default for mvi eligible indicator.
  ******************************************************************************/
  PROCEDURE MVI_DEFAULT(p_ecas_id          IN VARCHAR2,
                        p_mvi_eligible_ind IN OUT VARCHAR2) IS

    l_sb_fund_ind           PROV_FOREST_USE.SB_FUNDED_IND%TYPE;
    l_forest_file_id        APPRAISAL_DATA_SUBMISSION.FOREST_FILE_ID%TYPE;
    l_rate_calc_method_code APPRAISAL_DATA_SUBMISSION.RATE_CALC_METHOD_CODE%TYPE;
    l_annual_allowable_cut  HARVEST_COMMIT.SCHEDULE_B_AAC%TYPE;
    l_file_type_code        PROV_FOREST_USE.FILE_TYPE_CODE%TYPE;

  BEGIN

    IF p_mvi_eligible_ind IS NULL THEN

      BEGIN
        SELECT RATE_CALC_METHOD_CODE, FOREST_FILE_ID
          INTO l_rate_calc_method_code, l_forest_file_id
          FROM APPRAISAL_DATA_SUBMISSION
         WHERE ECAS_ID = to_number(p_ecas_id);
      EXCEPTION
        WHEN NO_DATA_FOUND THEN
          null; --ignore
      END;

      IF l_forest_file_id IS NOT NULL THEN

        BEGIN
          SELECT pfu.sb_funded_ind
            INTO l_sb_fund_ind
            FROM appraisal_data_submission ads, PROV_FOREST_USE pfu
           WHERE ads.ecas_id = to_number(p_ecas_id)
             AND ads.forest_file_id = pfu.forest_file_id;
        EXCEPTION
          WHEN NO_DATA_FOUND THEN
            l_sb_fund_ind := 'N';
        END;

        BEGIN
          SELECT PFU.FILE_TYPE_CODE, HC.SCHEDULE_B_AAC
            INTO l_file_type_code, l_annual_allowable_cut
            FROM PROV_FOREST_USE PFU, HARVEST_COMMIT HC
           WHERE PFU.FOREST_FILE_ID = HC.FOREST_FILE_ID(+)
             AND PFU.FOREST_FILE_ID = l_forest_file_id;
        EXCEPTION
          WHEN NO_DATA_FOUND THEN
            null; --ignore
        END;

        IF ((l_rate_calc_method_code = 'CVP') AND (l_sb_fund_ind = 'N') AND
           ((l_file_type_code IN ('A01', 'A02', 'A06', 'A30', 'A41')) OR
           ((l_file_type_code = 'A03') AND
           (l_annual_allowable_cut > 10000)))) THEN
          p_mvi_eligible_ind := 'Y';
        ELSE
          p_mvi_eligible_ind := 'N';
        END IF;

      ELSE
        -- forest file not found
        p_mvi_eligible_ind := 'N';

      END IF;

    END IF;

  END MVI_DEFAULT;

  /******************************************************************************
    Procedure:  TOA_DEFAULT
    Purpose:    To derive the default for toa eligible indicator.
  ******************************************************************************/
  PROCEDURE TOA_DEFAULT(p_ecas_id          IN VARCHAR2,
                        p_toa_eligible_ind IN OUT VARCHAR2) IS

    l_forest_file_id        APPRAISAL_DATA_SUBMISSION.FOREST_FILE_ID%TYPE;
    l_sb_fund_ind           PROV_FOREST_USE.SB_FUNDED_IND%TYPE;

  BEGIN

    IF p_toa_eligible_ind IS NULL THEN

      BEGIN
        SELECT FOREST_FILE_ID
          INTO l_forest_file_id
          FROM APPRAISAL_DATA_SUBMISSION
         WHERE ECAS_ID = to_number(p_ecas_id);
      EXCEPTION
        WHEN NO_DATA_FOUND THEN
          null; --ignore
      END;

      IF l_forest_file_id IS NOT NULL THEN

        BEGIN
          SELECT pfu.sb_funded_ind
            INTO l_sb_fund_ind
            FROM appraisal_data_submission ads, PROV_FOREST_USE pfu
           WHERE ads.ecas_id = to_number(p_ecas_id)
             AND ads.forest_file_id = pfu.forest_file_id;
        EXCEPTION
          WHEN NO_DATA_FOUND THEN
            l_sb_fund_ind := ' ';
        END;

        IF (l_sb_fund_ind = 'N') THEN
          p_toa_eligible_ind := 'Y';
        ELSIF (l_sb_fund_ind = 'Y') THEN
          p_toa_eligible_ind := 'N';
        ELSE
          p_toa_eligible_ind := '';
        END IF;

      ELSE
        -- forest file not found
        p_toa_eligible_ind := '';

      END IF;

    END IF;

  END TOA_DEFAULT;

  PROCEDURE GET_RPF_SUBMITTED_DATE(P_ECAS_ID            IN VARCHAR2,
                                   P_RPF_SUBMITTED_DATE IN OUT APPRAISAL_DATA_SUBMISSION.RPF_SUBMITTED_DATE%TYPE) IS
  BEGIN
    P_RPF_SUBMITTED_DATE := NULL;
    SELECT RPF_SUBMITTED_DATE
      INTO P_RPF_SUBMITTED_DATE
      FROM APPRAISAL_DATA_SUBMISSION
     WHERE ECAS_ID = to_number(P_ECAS_ID);
  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      null; -- ignore
  END GET_RPF_SUBMITTED_DATE;

  PROCEDURE GET_DISTRICT_SENT_DATE(P_ECAS_ID   IN VARCHAR2,
                                   P_SENT_DATE IN OUT APPRAISAL_DATA_SUBMISSION.SENT_DATE%TYPE) IS
  BEGIN
    P_SENT_DATE := NULL;
    SELECT SENT_DATE
      INTO P_SENT_DATE
      FROM APPRAISAL_DATA_SUBMISSION
     WHERE ECAS_ID = to_number(P_ECAS_ID);
  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      null; -- ignore
  END GET_DISTRICT_SENT_DATE;

  /******************************************************************************
      Procedure:  TOA_DEFAULT_FTA
      Purpose:    Checks to see if FTA data has been added to derive the default
      		  for toa eligible indicator
    ******************************************************************************/
    PROCEDURE TOA_DEFAULT_FTA(p_ecas_id          IN VARCHAR2,
                              p_toa_eligible_ind IN OUT VARCHAR2) IS
      v_forest_file_id  PROV_FOREST_USE.FOREST_FILE_ID%TYPE;
      v_sb_fund_ind	PROV_FOREST_USE.SB_FUNDED_IND%TYPE;
    BEGIN
      BEGIN
	      SELECT ADS.FOREST_FILE_ID
	      INTO v_forest_file_id
	      FROM APPRAISAL_DATA_SUBMISSION ADS
	      WHERE ADS.ECAS_ID = p_ecas_id;
      EXCEPTION
        WHEN NO_DATA_FOUND THEN
          null; -- continue
      END;

      IF (v_forest_file_id is NULL) THEN
	      BEGIN
		      SELECT pfu.SB_FUNDED_IND
		      INTO v_sb_fund_ind
		      FROM HAULING_AUTHORITY HLA
		      INNER JOIN ADS_SUBMITTED_TIMBER_MARK ASTM ON HLA.TIMBER_MARK = ASTM.TIMBER_MARK
		        AND ASTM.PRIMARY_MARK_IND = 'Y'
		      INNER JOIN PROV_FOREST_USE PFU ON PFU.FOREST_FILE_ID = HLA.FOREST_FILE_ID
		      WHERE ASTM.ECAS_ID = p_ecas_id;
	      EXCEPTION
	         WHEN NO_DATA_FOUND THEN
	           v_sb_fund_ind := ' ';
	      END;

	      IF (v_sb_fund_ind = 'N') THEN
	         p_toa_eligible_ind := 'Y';
	      ELSIF (v_sb_fund_ind = 'Y') THEN
	         p_toa_eligible_ind := 'N';
        ELSE
           p_toa_eligible_ind := '';
	      END IF;
      ELSE
              TOA_DEFAULT(p_ecas_id,
                          p_toa_eligible_ind);
      END IF;
    EXCEPTION
      WHEN NO_DATA_FOUND THEN
        null; -- ignore
    END TOA_DEFAULT_FTA;

  /*
  * Builds an audit comment from the passed status and comment.  p_new_status should be set
  * to the new status of the record, for example 'District Clarify Result'.  If p_new_status
  * has a value, it along with a timestamp will be prepended to the passed comment
  * and returned.  If p_new_status is empty, p_comment will be returned.
  */
  FUNCTION BUILD_AUDIT_COMMENT(p_new_status IN VARCHAR2,
                               p_comment    IN VARCHAR2) RETURN VARCHAR2 IS

  BEGIN

    IF (p_new_status IS NOT NULL) THEN
      RETURN p_new_status || ' on ' || Sil_Date_Conversion.CONVERT_TO_CHAR(SYSDATE) || CHR(13) || CHR(10) || p_comment;
    ELSE
      RETURN p_comment;
    END IF;

  END BUILD_AUDIT_COMMENT;

