  /*********************************************************************************
   FUNCTION:  is_rpf_valid
   Purpose:   check if both RPF and licensee information is available in user tables
  *********************************************************************************/
  FUNCTION is_rpf_valid(p_submit_userid    IN VARCHAR2,
                        p_client_number    IN VARCHAR2,
                        p_client_locn_code IN VARCHAR2) RETURN VARCHAR2 IS
    v_valid VARCHAR2(1);
  BEGIN

    SELECT DECODE(COUNT('x'), 0, 'N', 'Y')
      INTO v_valid
      FROM rpf_licensee_rep rlr, mof_user mu
     WHERE rlr.user_id = mu.user_id
       AND rlr.user_id = p_submit_userid
       AND rlr.client_locn_code = p_client_locn_code
       AND rlr.client_number = p_client_number
       AND (rlr.rpf_ind = 'Y' OR rlr.rft_ind = 'Y')
       AND rlr.rep_active_ind = 'Y';

    RETURN v_valid;

  END is_rpf_valid;

