  /******************************************************************************
      Procedure:  GET_CONIF_SREC_CODES
      Purpose: Gets all of the valid coniferous SRE codes for an appraisal method
  ******************************************************************************/
  PROCEDURE GET_CONIF_SREC_CODES(p_appraisal_method   IN VARCHAR2,
                                 p_app_effective_date IN VARCHAR2,
                                 p_result             IN OUT ref_code) IS
  BEGIN
    OPEN P_RESULT FOR
      SELECT SREC.STAND_RATE_ELIGIBILITY_CODE AS CODE,
             SREC.DESCRIPTION,
             SREC.EFFECTIVE_DATE,
             SREC.EXPIRY_DATE,
             SREC.UPDATE_TIMESTAMP
        FROM STAND_RATE_ELIGIBILITY_CODE SREC
       WHERE SREC.STAND_RATE_ELIGIBILITY_CODE IN
             (SELECT DISTINCT SREX.CONIF_STAND_RATE_ELIG_CODE
                FROM APP_METHOD_STAND_RATE_XREF SREX
               WHERE SREX.APPRAISAL_METHOD_CODE = P_APPRAISAL_METHOD
                 AND SREX.EFFECTIVE_DATE <
                     TO_DATE(p_app_effective_date, 'YYYY-MM-DD')
                 AND SREX.EXPIRY_DATE >=
                     TO_DATE(p_app_effective_date, 'YYYY-MM-DD'))
         AND SREC.EFFECTIVE_DATE <
             TO_DATE(p_app_effective_date, 'YYYY-MM-DD')
         AND SREC.EXPIRY_DATE >=
             TO_DATE(p_app_effective_date, 'YYYY-MM-DD');
  END GET_CONIF_SREC_CODES;

