  /******************************************************************************
      Procedure:  FIND_CLIENT_LOCATION
      Purpose: Retrieve a client location record by client number.
  ******************************************************************************/
  PROCEDURE FIND_CLIENT_LOCATION(P_CLIENT_NUMBER          IN CLIENT_LOCATION.CLIENT_NUMBER%TYPE,
                                 P_LOCATION_CODE          IN CLIENT_LOCATION.CLIENT_LOCN_CODE%TYPE,
                                 P_CLIENT_LOCATION_RETURN IN OUT ref_client_location) IS
  BEGIN
    OPEN P_CLIENT_LOCATION_RETURN FOR
      SELECT L.CLIENT_LOCN_CODE,
             L.CLIENT_NUMBER,
             L.CLIENT_LOCN_NAME,
             L.HDBS_COMPANY_CODE,
             L.ADDRESS_1,
             L.ADDRESS_2,
             L.ADDRESS_3,
             L.CITY,
             L.PROVINCE,
             L.POSTAL_CODE,
             L.COUNTRY,
             L.BUSINESS_PHONE,
             L.HOME_PHONE,
             L.FAX_NUMBER,
             L.LOCN_EXPIRED_IND,
             L.RETURNED_MAIL_DATE,
             L.UPDATE_TIMESTAMP,
             L.UPDATE_USERID,
             L.UPDATE_ORG_UNIT,
             L.ADD_TIMESTAMP,
             L.ADD_USERID,
             L.ADD_ORG_UNIT,
             L.CLI_LOCN_COMMENT,
             FC.CLIENT_NAME AS COMPANY_NAME,
             L.EMAIL_ADDRESS
        FROM CLIENT_LOCATION L
        LEFT JOIN FOREST_CLIENT FC
          ON L.CLIENT_NUMBER = FC.CLIENT_NUMBER
       WHERE L.CLIENT_NUMBER = P_CLIENT_NUMBER
         AND L.CLIENT_LOCN_CODE = P_LOCATION_CODE;
  END FIND_CLIENT_LOCATION;

