             L.HDBS_COMPANY_CODE,
             L.ADDRESS_1,
             L.ADDRESS_2,
             L.ADDRESS_3,
             L.CITY,
             L.PROVINCE,
             L.POSTAL_CODE,
             L.COUNTRY,
             L.BUSINESS_PHONE,
             L.HOME_PHONE,
             L.FAX_NUMBER,
             L.LOCN_EXPIRED_IND,
             L.RETURNED_MAIL_DATE,
             L.UPDATE_TIMESTAMP,
             L.UPDATE_USERID,
             L.UPDATE_ORG_UNIT,
             L.ADD_TIMESTAMP,
             L.ADD_USERID,
             L.ADD_ORG_UNIT,
             L.CLI_LOCN_COMMENT,
             FC.CLIENT_NAME AS COMPANY_NAME,
             L.EMAIL_ADDRESS
        FROM CLIENT_LOCATION L
        LEFT JOIN FOREST_CLIENT FC
          ON L.CLIENT_NUMBER = FC.CLIENT_NUMBER
       WHERE L.CLIENT_NUMBER = P_CLIENT_NUMBER;
  END FIND_CLIENT_LOCATIONS;

  /******************************************************************************
      Procedure: FIND_FOREST_CLIENT
      Purpose: Finds an entry in FOREST_CLIENT by client number
  ******************************************************************************/
  PROCEDURE FIND_FOREST_CLIENT(P_CLIENT_NUMBER IN FOREST_CLIENT.CLIENT_NUMBER%TYPE,
                               P_FOREST_CLIENT IN OUT ref_forest_client) AS
  BEGIN
    OPEN P_FOREST_CLIENT FOR
      SELECT T.REVISION_COUNT,
             T.CLIENT_ACRONYM,
             T.ADD_ORG_UNIT,
             T.LEGAL_FIRST_NAME,
             T.UPDATE_USERID,
             T.CLIENT_IDENTIFICATION,
             T.CLIENT_ID_TYPE_CODE,
             T.CORP_REGN_NMBR,
             T.ADD_TIMESTAMP,
             T.CLIENT_NAME,
             T.WCB_FIRM_NUMBER,
             T.ADD_USERID,
             T.BIRTHDATE,
             T.CLIENT_COMMENT,
             T.CLIENT_NUMBER,
             T.REGISTRY_COMPANY_TYPE_CODE,
             T.OCG_SUPPLIER_NMBR,
             T.UPDATE_TIMESTAMP,
             T.CLIENT_STATUS_CODE,
             T.LEGAL_MIDDLE_NAME,
             T.UPDATE_ORG_UNIT,
             T.CLIENT_TYPE_CODE
        FROM FOREST_CLIENT T
       WHERE T.CLIENT_NUMBER = P_CLIENT_NUMBER;
  END FIND_FOREST_CLIENT;

  /******************************************************************************
      Procedure: FIND_ADS_SO_FOR_ECAS_ID
      Purpose: Gets all of the ADS Specified operations for a given ECAS Id
               NOTE: This procedure will NOT RETURN blended percent SOs
  ******************************************************************************/
  PROCEDURE FIND_ADS_SO_FOR_ECAS_ID(P_ECAS_ID                 IN ADS_SPECIFIED_OPERATION.ECAS_ID%TYPE,
                                    P_ADS_SPECIFIED_OPERATION IN OUT ref_ads_specified_operation) AS
  BEGIN
    OPEN P_ADS_SPECIFIED_OPERATION FOR
      SELECT ASO.ECAS_ID,
             ASO.SPECIFIED_OPERATIONS_PHS_CODE,
             ASO.SPECIFIED_OPERATIONS_CODE AS SPEC_OP_CODE,
             SOC.DESCRIPTION,
             ASO.SPECIFIED_OPERATING_RATE,
             ASO.BLENDED_PCT,
             ASO.COMMENTS,
             ASO.APPLICABLE_VOLUME,
             ASO.APPLICABLE_FRACTION,
             (ADS.Net_Cruise_Volume + ADS.OBLIGATORY_DECIDUOUS_VOLUME) as APPRAISAL_TOTAL_VOLUME,
             ADS.APPRAISAL_EFFECTIVE_DATE,
             ASO.REVISION_COUNT,
             ASO.ENTRY_USERID,
             ASO.ENTRY_TIMESTAMP,
             ASO.UPDATE_USERID,
             ASO.UPDATE_TIMESTAMP
        FROM ADS_SPECIFIED_OPERATION ASO
       INNER JOIN SPECIFIED_OPERATIONS_CODE SOC
          ON ASO.SPECIFIED_OPERATIONS_CODE = SOC.SPECIFIED_OPERATIONS_CODE
       INNER JOIN APPRAISAL_DATA_SUBMISSION ADS
          ON ADS.ECAS_ID = ASO.ECAS_ID
       WHERE ASO.ECAS_ID = P_ECAS_ID
         AND ASO.BLENDED_PCT IS NULL
       ORDER BY SOC.DESCRIPTION;
  END FIND_ADS_SO_FOR_ECAS_ID;

  /******************************************************************************
      Procedure: INIT_ADS_SO_BY_ECAS_ID
      Purpose: Inits the ADS SO so that we can validate based on appraisal volume
      and effective date
  ******************************************************************************/
  PROCEDURE INIT_ADS_SO_BY_ECAS_ID(P_ECAS_ID IN APPRAISAL_DATA_SUBMISSION.ECAS_ID%TYPE,
                                P_ADS_SPECIFIED_OPERATION     IN OUT ref_ads_specified_operation) AS
  BEGIN
    OPEN P_ADS_SPECIFIED_OPERATION FOR
      SELECT ADS.ECAS_ID,
             NULL AS SPECIFIED_OPERATIONS_PHS_CODE,
             NULL AS SPEC_OP_CODE,
             NULL AS DESCRIPTION,
             NULL AS SPECIFIED_OPERATING_RATE,
             NULL AS BLENDED_PCT,
             NULL AS COMMENTS,
             NULL AS APPLICABLE_VOLUME,
             NULL AS APPLICABLE_FRACTION,
             CASE
                WHEN appraisal_status_code = 'BUP' or pfu.sb_funded_ind='Y' THEN
                    CASE
                        WHEN ADS.Conif_Stand_Rate_Elig_Code = 'S' THEN ADS.Net_Cruise_Volume + coalesce(ADS.DECKED_VOLUME,0) + coalesce(ADS.RW_VOLUME,0)
                   ELSE (ADS.Net_Cruise_Volume + coalesce(ADS.DECKED_VOLUME,0) + coalesce(ADS.RW_VOLUME,0) + ADS.OBLIGATORY_DECIDUOUS_VOLUME)
                   END
                ELSE
                    CASE
                        WHEN ADS.Conif_Stand_Rate_Elig_Code = 'S' THEN ADS.Net_Cruise_Volume
                   ELSE (ADS.Net_Cruise_Volume + ADS.OBLIGATORY_DECIDUOUS_VOLUME)
                   END
               END as APPRAISAL_TOTAL_VOLUME,
             ADS.APPRAISAL_EFFECTIVE_DATE,
             NULL AS REVISION_COUNT,
             NULL AS ENTRY_USERID,
             NULL AS ENTRY_TIMESTAMP,
             NULL AS UPDATE_USERID,
             NULL AS UPDATE_TIMESTAMP
        FROM APPRAISAL_DATA_SUBMISSION ADS
        LEFT JOIN PROV_FOREST_USE pfu
      ON ads.forest_file_id = pfu.forest_file_id
          WHERE ADS.ECAS_ID = P_ECAS_ID;
  END INIT_ADS_SO_BY_ECAS_ID;

  /******************************************************************************
      Procedure: FIND_DS_ADS_SO_FOR_ECAS_ID
      Purpose: Gets all of the ADS Specified operations for a given ECAS Id
               NOTE: This procedure will ONLY RETURN blended percent (dispersed salvage) SOs
  ******************************************************************************/
  PROCEDURE FIND_DS_ADS_SO_FOR_ECAS_ID(P_ECAS_ID                 IN ADS_SPECIFIED_OPERATION.ECAS_ID%TYPE,
                                       P_ADS_SPECIFIED_OPERATION IN OUT ref_ads_specified_operation) AS
  BEGIN
    OPEN P_ADS_SPECIFIED_OPERATION FOR
      SELECT ASO.ECAS_ID,
             ASO.SPECIFIED_OPERATIONS_PHS_CODE,
             ASO.SPECIFIED_OPERATIONS_CODE AS SPEC_OP_CODE,
             SOC.DESCRIPTION,
             ASO.SPECIFIED_OPERATING_RATE,
             ASO.BLENDED_PCT,
             ASO.COMMENTS,
             ASO.APPLICABLE_VOLUME,
             ASO.APPLICABLE_FRACTION,
             (ADS.Net_Cruise_Volume + ADS.OBLIGATORY_DECIDUOUS_VOLUME) as APPRAISAL_TOTAL_VOLUME,
             ADS.APPRAISAL_EFFECTIVE_DATE,
             ASO.REVISION_COUNT,
             ASO.ENTRY_USERID,
             ASO.ENTRY_TIMESTAMP,
             ASO.UPDATE_USERID,
             ASO.UPDATE_TIMESTAMP
        FROM ADS_SPECIFIED_OPERATION ASO
       INNER JOIN SPECIFIED_OPERATIONS_CODE SOC
          ON ASO.SPECIFIED_OPERATIONS_CODE = SOC.SPECIFIED_OPERATIONS_CODE
       INNER JOIN APPRAISAL_DATA_SUBMISSION ADS
          ON ADS.ECAS_ID = ASO.ECAS_ID
       WHERE ASO.ECAS_ID = P_ECAS_ID
         AND ASO.BLENDED_PCT IS NOT NULL
       ORDER BY SOC.DESCRIPTION;
  END FIND_DS_ADS_SO_FOR_ECAS_ID;

  /******************************************************************************
      Procedure: FIND_ADS_SO
      Purpose: Gets a specific ADS Specified operation entry
  ******************************************************************************/
  PROCEDURE FIND_ADS_SO(P_ECAS_ID                 IN ADS_SPECIFIED_OPERATION.ECAS_ID%TYPE,
                        P_SOPC                    IN ADS_SPECIFIED_OPERATION.SPECIFIED_OPERATIONS_PHS_CODE%TYPE,
                        P_SOC                     IN ADS_SPECIFIED_OPERATION.SPECIFIED_OPERATIONS_CODE%TYPE,
                        P_ADS_SPECIFIED_OPERATION IN OUT ref_ads_specified_operation) AS
  BEGIN
    OPEN P_ADS_SPECIFIED_OPERATION FOR
      SELECT ASO.ECAS_ID,
             ASO.SPECIFIED_OPERATIONS_PHS_CODE,
             ASO.SPECIFIED_OPERATIONS_CODE AS SPEC_OP_CODE,
             SOC.DESCRIPTION,
             ASO.SPECIFIED_OPERATING_RATE,
             ASO.BLENDED_PCT,
             ASO.COMMENTS,
             ASO.APPLICABLE_VOLUME,
             ASO.APPLICABLE_FRACTION,
             (ADS.Net_Cruise_Volume + ADS.OBLIGATORY_DECIDUOUS_VOLUME) as APPRAISAL_TOTAL_VOLUME,
             ADS.APPRAISAL_EFFECTIVE_DATE,
             ASO.REVISION_COUNT,
             ASO.ENTRY_USERID,
             ASO.ENTRY_TIMESTAMP,
             ASO.UPDATE_USERID,
             ASO.UPDATE_TIMESTAMP
        FROM ADS_SPECIFIED_OPERATION ASO
       INNER JOIN SPECIFIED_OPERATIONS_CODE SOC
          ON ASO.SPECIFIED_OPERATIONS_CODE = SOC.SPECIFIED_OPERATIONS_CODE
       INNER JOIN APPRAISAL_DATA_SUBMISSION ADS
          ON ADS.ECAS_ID = ASO.ECAS_ID
       WHERE ASO.ECAS_ID = P_ECAS_ID
         AND ASO.SPECIFIED_OPERATIONS_PHS_CODE = P_SOPC
         AND ASO.SPECIFIED_OPERATIONS_CODE = P_SOC;
  END FIND_ADS_SO;

  /******************************************************************************
      Procedure: UPDATE_ADS_SO
      Purpose: Updates a specific ADS Specified operation entry
  ******************************************************************************/
  PROCEDURE UPDATE_ADS_SO(P_ECAS_ID          IN ADS_SPECIFIED_OPERATION.ECAS_ID%TYPE,
                          P_SOPC             IN ADS_SPECIFIED_OPERATION.SPECIFIED_OPERATIONS_PHS_CODE%TYPE,
                          P_SOC              IN ADS_SPECIFIED_OPERATION.SPECIFIED_OPERATIONS_CODE%TYPE,
                          P_RATE             IN ADS_SPECIFIED_OPERATION.SPECIFIED_OPERATING_RATE%TYPE,
                          P_BLEND_PCT        IN ADS_SPECIFIED_OPERATION.BLENDED_PCT%TYPE,
                          P_COMMENTS         IN ADS_SPECIFIED_OPERATION.COMMENTS%TYPE,
                          P_APPLICABLE_VOLUME   IN ADS_SPECIFIED_OPERATION.APPLICABLE_VOLUME%TYPE,
                          P_FRACTION                IN ADS_SPECIFIED_OPERATION.APPLICABLE_FRACTION%TYPE,
                          P_REVISION         IN ADS_SPECIFIED_OPERATION.REVISION_COUNT%TYPE,
                          P_UPDATE_USER      IN ADS_SPECIFIED_OPERATION.UPDATE_USERID%TYPE,
                          P_UPDATE_TIMESTAMP IN ADS_SPECIFIED_OPERATION.UPDATE_TIMESTAMP%TYPE) AS
  BEGIN

    update ADS_SPECIFIED_OPERATION ASO
       set ASO.SPECIFIED_OPERATING_RATE = P_RATE,
           ASO.BLENDED_PCT              = P_BLEND_PCT,
           ASO.COMMENTS                 = P_COMMENTS,
           ASO.APPLICABLE_VOLUME        = P_APPLICABLE_VOLUME,
           ASO.APPLICABLE_FRACTION      = P_FRACTION,
           ASO.REVISION_COUNT           = P_REVISION,
           ASO.UPDATE_USERID            = P_UPDATE_USER,
           ASO.UPDATE_TIMESTAMP         = P_UPDATE_TIMESTAMP
     WHERE ASO.ECAS_ID = P_ECAS_ID
       AND ASO.SPECIFIED_OPERATIONS_PHS_CODE = P_SOPC
       AND ASO.SPECIFIED_OPERATIONS_CODE = P_SOC;
  END UPDATE_ADS_SO;

  /******************************************************************************
      Procedure: DELETE_ADS_SO
      Purpose: Deletes a specific ADS Specified operation entry
  ******************************************************************************/
  PROCEDURE DELETE_ADS_SO(P_ECAS_ID IN ADS_SPECIFIED_OPERATION.ECAS_ID%TYPE,
                          P_SOPC    IN ADS_SPECIFIED_OPERATION.SPECIFIED_OPERATIONS_PHS_CODE%TYPE,
                          P_SOC     IN ADS_SPECIFIED_OPERATION.SPECIFIED_OPERATIONS_CODE%TYPE) AS
  BEGIN
    DELETE FROM ADS_SPECIFIED_OPERATION ASO
     WHERE ASO.ECAS_ID = P_ECAS_ID
       AND ASO.SPECIFIED_OPERATIONS_PHS_CODE = P_SOPC
       AND ASO.SPECIFIED_OPERATIONS_CODE = P_SOC;
  END DELETE_ADS_SO;

  /******************************************************************************
      Procedure: INSERT_ADS_SO
      Purpose: Inserts a new ADS Specified operation entry
  ******************************************************************************/
  PROCEDURE INSERT_ADS_SO(P_ECAS_ID                 IN ADS_SPECIFIED_OPERATION.ECAS_ID%TYPE,
                          P_SOPC                    IN ADS_SPECIFIED_OPERATION.SPECIFIED_OPERATIONS_PHS_CODE%TYPE,
                          P_SOC                     IN ADS_SPECIFIED_OPERATION.SPECIFIED_OPERATIONS_CODE%TYPE,
                          P_RATE                    IN ADS_SPECIFIED_OPERATION.SPECIFIED_OPERATING_RATE%TYPE,
                          P_BLEND_PCT               IN ADS_SPECIFIED_OPERATION.BLENDED_PCT%TYPE,
                          P_COMMENTS                IN ADS_SPECIFIED_OPERATION.COMMENTS%TYPE,
                          P_APPLICABLE_VOLUME       IN ADS_SPECIFIED_OPERATION.APPLICABLE_VOLUME%TYPE,
                          P_FRACTION                IN ADS_SPECIFIED_OPERATION.APPLICABLE_FRACTION%TYPE,
                          P_ENTRY_USER              IN ADS_SPECIFIED_OPERATION.ENTRY_USERID%TYPE,
                          P_ENTRY_TIMESTAMP         IN ADS_SPECIFIED_OPERATION.ENTRY_TIMESTAMP%TYPE,
                          P_ADS_SPECIFIED_OPERATION IN OUT ref_ads_specified_operation) AS
  BEGIN
    INSERT INTO ADS_SPECIFIED_OPERATION ASO
      (ASO.ECAS_ID,
       ASO.SPECIFIED_OPERATIONS_PHS_CODE,
       ASO.SPECIFIED_OPERATIONS_CODE,
       ASO.SPECIFIED_OPERATING_RATE,
       ASO.BLENDED_PCT,
       ASO.COMMENTS,
       ASO.APPLICABLE_VOLUME,
       ASO.APPLICABLE_FRACTION,
       ASO.REVISION_COUNT,
       ASO.ENTRY_USERID,
       ASO.ENTRY_TIMESTAMP,
       ASO.UPDATE_USERID,
       ASO.UPDATE_TIMESTAMP)
    VALUES
      (P_ECAS_ID,
       P_SOPC,
       P_SOC,
       P_RATE,
       P_BLEND_PCT,
       P_COMMENTS,
       P_APPLICABLE_VOLUME,
       P_FRACTION,
       1,
       P_ENTRY_USER,
       P_ENTRY_TIMESTAMP,
       P_ENTRY_USER,
       P_ENTRY_TIMESTAMP);

    FIND_ADS_SO(P_ECAS_ID, P_SOPC, P_SOC, P_ADS_SPECIFIED_OPERATION);

  END INSERT_ADS_SO;

