       INNER JOIN ADS_SUBMITTED_TIMBER_MARK ASTM
          ON ADS.ECAS_ID = ASTM.ECAS_ID
         and ASTM.PRIMARY_MARK_IND = 'Y'
       INNER JOIN APPRAISAL_DATA_SUBMISSION_CTRL ADSC
          ON ADS.ECAS_ID = ADSC.ECAS_ID
       WHERE P_TIMBER_MARK = ASTM.Timber_Mark
         and P_EFFECITVE_DATE = ADS.Appraisal_Effective_Date;

  END FIND_ADS_BY_TM_EFF_DATE;

  /******************************************************************************
      Procedure: UPDATE_ADS_STATUS
      Purpose: Updates only the status of a specific ADS entry
  ******************************************************************************/
  PROCEDURE UPDATE_ADS_STATUS(P_ECAS_ID          IN APPRAISAL_DATA_SUBMISSION.ECAS_ID%TYPE,
                              P_STATUS_CODE      IN APPRAISAL_DATA_SUBMISSION.APPRAISAL_STATUS_CODE%TYPE,
                              P_REVISION         IN APPRAISAL_DATA_SUBMISSION.REVISION_COUNT%TYPE,
                              P_UPDATE_USER      IN APPRAISAL_DATA_SUBMISSION.UPDATE_USERID%TYPE,
                              P_UPDATE_TIMESTAMP IN APPRAISAL_DATA_SUBMISSION.UPDATE_TIMESTAMP%TYPE) AS
  BEGIN
    update APPRAISAL_DATA_SUBMISSION ADS
       set ADS.APPRAISAL_STATUS_CODE = P_STATUS_CODE,
           ADS.REVISION_COUNT        = P_REVISION,
           ADS.UPDATE_USERID         = P_UPDATE_USER,
           ADS.UPDATE_TIMESTAMP      = P_UPDATE_TIMESTAMP
     WHERE ADS.ECAS_ID = P_ECAS_ID;
  END UPDATE_ADS_STATUS;

  /******************************************************************************
      Procedure: UPDATE_ADS_CVP_MPS_DIFF
      Purpose: Updates only the MPS/CVP differential of a specific ADS entry
  ******************************************************************************/
  PROCEDURE UPDATE_ADS_CVP_MPS_DIFF(P_ECAS_ID          IN APPRAISAL_DATA_SUBMISSION.ECAS_ID%TYPE,
                                    P_CVP_MPS_DIFF     IN APPRAISAL_DATA_SUBMISSION.MPS_CVP_DIFFERENTIAL%TYPE,
                                    P_REVISION         IN APPRAISAL_DATA_SUBMISSION.REVISION_COUNT%TYPE,
                                    P_UPDATE_USER      IN APPRAISAL_DATA_SUBMISSION.UPDATE_USERID%TYPE,
                                    P_UPDATE_TIMESTAMP IN APPRAISAL_DATA_SUBMISSION.UPDATE_TIMESTAMP%TYPE) AS
  BEGIN
    update APPRAISAL_DATA_SUBMISSION ADS
       set ADS.MPS_CVP_DIFFERENTIAL = P_CVP_MPS_DIFF,
           ADS.REVISION_COUNT       = P_REVISION,
           ADS.UPDATE_USERID        = P_UPDATE_USER,
           ADS.UPDATE_TIMESTAMP     = P_UPDATE_TIMESTAMP
     WHERE ADS.ECAS_ID = P_ECAS_ID;
  END UPDATE_ADS_CVP_MPS_DIFF;

  /******************************************************************************
      Procedure: FIND_ECAS_AUDIT_EVENT
      Purpose:
  ******************************************************************************/
  PROCEDURE FIND_ECAS_AUDIT_EVENT(P_ECAS_ID          IN ECAS_AUDIT_EVENT.ECAS_ID%TYPE,
                                  P_AUDIT_EVENT_ID   IN ECAS_AUDIT_EVENT.AUDIT_EVENT_ID%TYPE,
                                  P_ECAS_AUDIT_EVENT IN OUT ref_ecas_audit_event) AS
  BEGIN
    OPEN P_ECAS_AUDIT_EVENT FOR
      SELECT EAE.ECAS_ID,
             EAE.AUDIT_EVENT_ID,
             EAE.ECAS_SUBMITTED_FILE_ID,
             EAE.ECAS_ACTION_CODE,
             EAE.ENTRY_TIMESTAMP,
             EAE.ENTRY_USERID,
             EAE.EMAIL_SENT_IND,
             EAE.SENT_TO_USERID
        FROM ECAS_AUDIT_EVENT EAE
       WHERE P_ECAS_ID = EAE.ECAS_ID
         AND P_AUDIT_EVENT_ID = EAE.AUDIT_EVENT_ID;
  END FIND_ECAS_AUDIT_EVENT;

  /******************************************************************************
      Procedure: INSERT_ECAS_AUDIT_EVENT
      Purpose:
  ******************************************************************************/
  PROCEDURE INSERT_ECAS_AUDIT_EVENT(P_ECAS_ID                ECAS_AUDIT_EVENT.ECAS_ID%TYPE,
                                    P_ECAS_SUBMITTED_FILE_ID ECAS_AUDIT_EVENT.ECAS_SUBMITTED_FILE_ID%TYPE,
                                    P_ECAS_ACTION_CODE       ECAS_AUDIT_EVENT.ECAS_ACTION_CODE%TYPE,
                                    P_ENTRY_TIMESTAMP        ECAS_AUDIT_EVENT.ENTRY_TIMESTAMP%TYPE,
                                    P_ENTRY_USERID           ECAS_AUDIT_EVENT.ENTRY_USERID%TYPE,
                                    P_EMAIL_SENT_IND         ECAS_AUDIT_EVENT.EMAIL_SENT_IND%TYPE,
                                    P_SENT_TO_USERID         ECAS_AUDIT_EVENT.SENT_TO_USERID%TYPE,
                                    P_ECAS_AUDIT_EVENT       IN OUT ref_ecas_audit_event) AS

    V_AUDIT_EVENT_ID NUMBER;

  BEGIN

    SELECT ECAS_AUDIT_EVENT_SEQ.NEXTVAL INTO V_AUDIT_EVENT_ID FROM DUAL;

    INSERT INTO ECAS_AUDIT_EVENT
      (ECAS_ID,
       AUDIT_EVENT_ID,
       ECAS_SUBMITTED_FILE_ID,
       ECAS_ACTION_CODE,
       ENTRY_TIMESTAMP,
       ENTRY_USERID,
       EMAIL_SENT_IND,
       SENT_TO_USERID)
    VALUES
      (P_ECAS_ID,
       V_AUDIT_EVENT_ID,
       P_ECAS_SUBMITTED_FILE_ID,
       P_ECAS_ACTION_CODE,
       P_ENTRY_TIMESTAMP,
       P_ENTRY_USERID,
       P_EMAIL_SENT_IND,
       P_SENT_TO_USERID);

    FIND_ECAS_AUDIT_EVENT(P_ECAS_ID, V_AUDIT_EVENT_ID, P_ECAS_AUDIT_EVENT);

  END INSERT_ECAS_AUDIT_EVENT;

  /******************************************************************************
      Procedure: FIND_ECAS_AUDIT_DETAIL
      Purpose:
  ******************************************************************************/
  PROCEDURE FIND_ECAS_AUDIT_DETAIL(P_ECAS_ID           IN ECAS_AUDIT_DETAIL.ECAS_ID%TYPE,
                                   P_AUDIT_EVENT_ID    IN ECAS_AUDIT_DETAIL.AUDIT_EVENT_ID%TYPE,
                                   P_AUDIT_DETAIL_ID   IN ECAS_AUDIT_DETAIL.AUDIT_DETAIL_ID%TYPE,
                                   P_ECAS_AUDIT_DETAIL IN OUT ref_ecas_audit_detail) AS
  BEGIN
    OPEN P_ECAS_AUDIT_DETAIL FOR
      SELECT EAD.ECAS_ID,
             EAD.AUDIT_EVENT_ID,
             EAD.AUDIT_DETAIL_ID,
             EAD.BUSINESS_IDENTIFIER,
             EAD.TABLE_NAME,
             EAD.COLUMN_NAME,
             EAD.OLD_VALUE,
             EAD.NEW_VALUE,
             EAD.ENTRY_TIMESTAMP,
             EAD.ENTRY_USERID
        FROM ECAS_AUDIT_DETAIL EAD
       WHERE P_ECAS_ID = EAD.ECAS_ID
         AND P_AUDIT_DETAIL_ID = EAD.AUDIT_DETAIL_ID;
  END FIND_ECAS_AUDIT_DETAIL;

  /******************************************************************************
      Procedure: INSERT_ECAS_AUDIT_DETAIL
      Purpose:
  ******************************************************************************/
  PROCEDURE INSERT_ECAS_AUDIT_DETAIL(P_ECAS_ID             ECAS_AUDIT_DETAIL.ECAS_ID%TYPE,
                                     P_AUDIT_EVENT_ID      ECAS_AUDIT_DETAIL.AUDIT_EVENT_ID%TYPE,
                                     P_BUSINESS_IDENTIFIER ECAS_AUDIT_DETAIL.BUSINESS_IDENTIFIER%TYPE,
                                     P_TABLE_NAME          ECAS_AUDIT_DETAIL.TABLE_NAME%TYPE,
                                     P_COLUMN_NAME         ECAS_AUDIT_DETAIL.COLUMN_NAME%TYPE,
                                     P_OLD_VALUE           ECAS_AUDIT_DETAIL.OLD_VALUE%TYPE,
                                     P_NEW_VALUE           ECAS_AUDIT_DETAIL.NEW_VALUE%TYPE,
                                     P_ENTRY_TIMESTAMP     ECAS_AUDIT_DETAIL.ENTRY_TIMESTAMP%TYPE,
                                     P_ENTRY_USERID        ECAS_AUDIT_DETAIL.ENTRY_USERID%TYPE,
                                     P_ECAS_AUDIT_DETAIL   IN OUT ref_ecas_audit_detail) AS

    V_AUDIT_DETAIL_ID NUMBER;

  BEGIN

    SELECT ECAS_AUDIT_DETAIL_SEQ.NEXTVAL INTO V_AUDIT_DETAIL_ID FROM DUAL;

    INSERT INTO ECAS_AUDIT_DETAIL
      (ECAS_ID,
       AUDIT_EVENT_ID,
       AUDIT_DETAIL_ID,
       BUSINESS_IDENTIFIER,
       TABLE_NAME,
       COLUMN_NAME,
       OLD_VALUE,
       NEW_VALUE,
       ENTRY_TIMESTAMP,
       ENTRY_USERID)
    VALUES
      (P_ECAS_ID,
       P_AUDIT_EVENT_ID,
       V_AUDIT_DETAIL_ID,
       P_BUSINESS_IDENTIFIER,
       P_TABLE_NAME,
       P_COLUMN_NAME,
       P_OLD_VALUE,
       P_NEW_VALUE,
       P_ENTRY_TIMESTAMP,
       P_ENTRY_USERID);

    FIND_ECAS_AUDIT_DETAIL(P_ECAS_ID,
                           P_AUDIT_EVENT_ID,
                           V_AUDIT_DETAIL_ID,
                           P_ECAS_AUDIT_DETAIL);

  END INSERT_ECAS_AUDIT_DETAIL;

  /******************************************************************************
      Procedure:  ADD_MESSAGE
      Purpose:    Appends either an error or warning a message to the list of result messages
                  Used internally by VALIDATE_TM_INTERNAL
  ******************************************************************************/
  PROCEDURE ADD_MESSAGE(P_ERROR_ON_FAIL IN BOOLEAN,
                        P_MESSAGE       VARCHAR2,
                        P_ALL_MESSAGES  IN OUT VARCHAR2) IS
  BEGIN

    P_ALL_MESSAGES := P_ALL_MESSAGES || P_MESSAGE;
    if P_ERROR_ON_FAIL then
      P_ALL_MESSAGES := P_ALL_MESSAGES || ';';
    else
      P_ALL_MESSAGES := P_ALL_MESSAGES || ':~W;';
    end if;
  END ADD_MESSAGE;

  /******************************************************************************
      Procedure:  VALIDATE_TM_INTERNAL
      Purpose:    Checks the FTA status and dates of a given timber mark in FTA.
                  Returns either warnings or fatal error messages.
                  Used internally by CHECK_TM_STATUS and VALIDATE_TM_STATUS
  ******************************************************************************/
  PROCEDURE VALIDATE_TM_INTERNAL(P_TIMBER_MARK   IN VARCHAR2,
                                 P_APP_EFF_DATE  IN DATE,
                                 P_APP_EXP_DATE  IN DATE,
                                 P_ERROR_ON_FAIL IN BOOLEAN,
                                 P_ALL_MESSAGES  IN OUT VARCHAR2) IS
    V_MARK_EXPIRY_DATE DATE;
    V_MARK_EXTEND_DATE DATE;
    V_MARK_CUTOFF_DATE DATE;

    cursor TM_FTA_INFO_CUR(C_TIMBER_MARK VARCHAR2) IS
      SELECT HVA.EXPIRY_DATE,
             HVA.EXTEND_DATE
        FROM HAULING_AUTHORITY HLA
       INNER JOIN HARVESTING_HAULING_XREF HHX
          ON HLA.TIMBER_MARK = HHX.TIMBER_MARK
       INNER JOIN HARVESTING_AUTHORITY HVA
          ON HVA.HVA_SKEY = HHX.HVA_SKEY
       WHERE HHX.PRIMARY_MARK_IND = 'Y'
         AND HLA.TIMBER_MARK = C_TIMBER_MARK;

  BEGIN

    -- get the FTA info for the incoming timber mark
    OPEN TM_FTA_INFO_CUR(P_TIMBER_MARK);
    FETCH TM_FTA_INFO_CUR
      INTO V_MARK_EXPIRY_DATE,
           V_MARK_EXTEND_DATE;
    CLOSE TM_FTA_INFO_CUR;

    -- app dates vs mark dates
    if V_MARK_EXTEND_DATE is null then
      V_MARK_CUTOFF_DATE := V_MARK_EXPIRY_DATE;
    else
      V_MARK_CUTOFF_DATE := V_MARK_EXTEND_DATE;
    end if;

    -- app eff date vs tm expiry date
    if not P_APP_EFF_DATE is null and P_APP_EFF_DATE > V_MARK_CUTOFF_DATE then
      ADD_MESSAGE(P_ERROR_ON_FAIL,
                    'ecas.web.usr.database.effectiveDateAfterTMExpiryDate',
                    P_ALL_MESSAGES);
    end if;

    -- app exp date vs tm expiry date
    if not P_APP_EXP_DATE is null and P_APP_EXP_DATE > V_MARK_CUTOFF_DATE then
      ADD_MESSAGE(P_ERROR_ON_FAIL,
                    'ecas.web.usr.database.expiryDateBeforeTMExpiryDate',
                    P_ALL_MESSAGES);
    end if;

  END VALIDATE_TM_INTERNAL;

  /******************************************************************************
      Procedure:  CHECK_TM_STATUS
      Purpose:    Checks the FTA status and dates of a given timber mark in FTA.
                  Returns warning messages on any failure.
  ******************************************************************************/
  PROCEDURE CHECK_TM_STATUS(P_TIMBER_MARK     IN VARCHAR2,
                            P_APP_EFF_DATE    IN DATE,
                            P_APP_EXP_DATE    IN DATE,
                            P_WARNING_MESSAGE IN OUT VARCHAR2) IS
  BEGIN

    VALIDATE_TM_INTERNAL(P_TIMBER_MARK,
                         P_APP_EFF_DATE,
                         P_APP_EXP_DATE,
                         false,
                         P_WARNING_MESSAGE);
  END CHECK_TM_STATUS;

  /******************************************************************************
      Procedure:  VALIDATE_TM_STATUS
      Purpose:    Checks the FTA status and dates of a given timber mark in FTA.
                  Returns fatal error messages on any failure.
  ******************************************************************************/
  PROCEDURE VALIDATE_TM_STATUS(P_TIMBER_MARK   IN VARCHAR2,
                               P_APP_EFF_DATE  IN DATE,
                               P_APP_EXP_DATE  IN DATE,
                               P_ERROR_MESSAGE IN OUT VARCHAR2) IS
  BEGIN
    VALIDATE_TM_INTERNAL(P_TIMBER_MARK,
                         P_APP_EFF_DATE,
                         P_APP_EXP_DATE,
                         true,
                         P_ERROR_MESSAGE);
  END VALIDATE_TM_STATUS;

  /******************************************************************************
      Procedure:  VALIDATE_APP_DATES_INTERNAL
      Purpose:    Checks the appraisal effective/expiry dates for a given timber mark to ensure the appraisal dates are supported by GAS2.
                  Returns either warnings or fatal error messages.
                  Used internally by CHECK_APP_DATES and VALIDATE_APP_DATES
  ******************************************************************************/
  PROCEDURE VALIDATE_APP_DATES_INTERNAL(P_ECAS_ID         IN VARCHAR2,
                                        P_TIMBER_MARK     IN VARCHAR2,
                                        P_APP_EFF_DATE    IN DATE,
                                        P_APP_EXP_DATE    IN DATE,
                                        P_APP_METHOD_CODE IN VARCHAR2,
                                        P_ERROR_ON_FAIL   IN BOOLEAN,
                                        P_MESSAGES        IN OUT VARCHAR2) IS


  BEGIN
    if P_APP_EFF_DATE is null then
      -- don't bother checking anything further
      ADD_MESSAGE(P_ERROR_ON_FAIL,
                  'ecas.web.usr.database.appraisalEffectiveDateRequired',
                  P_MESSAGES);
    else
      -- app effective date vs gas 2 policy cutoff
      if P_APP_METHOD_CODE = 'I' and
         P_APP_EFF_DATE < TO_DATE('2008-07-01', 'yyyy-mm-dd') then
        ADD_MESSAGE(P_ERROR_ON_FAIL,
                    'ecas.web.usr.database.effectiveDateIsBeforeInteriorGAS2Policy',
                    P_MESSAGES);
      end if;

      if P_APP_METHOD_CODE = 'C' and
         P_APP_EFF_DATE < TO_DATE('2009-01-15', 'yyyy-mm-dd') then
        ADD_MESSAGE(P_ERROR_ON_FAIL,
                    'ecas.web.usr.database.effectiveDateIsBeforeCoastGAS2Policy',
                    P_MESSAGES);
      end if;
    end if;

  END VALIDATE_APP_DATES_INTERNAL;

  /******************************************************************************
      Procedure:  CHECK_APP_DATES
      Purpose:    Checks the appraisal effective/expiry dates for a given timber mark to ensure the appraisal dates are supported by GAS2.
                  Returns warning messages on any failure.
  ******************************************************************************/
  PROCEDURE CHECK_APP_DATES(P_ECAS_ID         IN VARCHAR2,
                            P_TIMBER_MARK     IN VARCHAR2,
                            P_APP_EFF_DATE    IN DATE,
                            P_APP_EXP_DATE    IN DATE,
                            P_APP_METHOD_CODE IN VARCHAR2,
                            P_WARNING_MESSAGE IN OUT VARCHAR2) IS
  BEGIN
    VALIDATE_APP_DATES_INTERNAL(P_ECAS_ID,
                                P_TIMBER_MARK,
                                P_APP_EFF_DATE,
                                P_APP_EXP_DATE,
                                P_APP_METHOD_CODE,
                                false,
                                P_WARNING_MESSAGE);
  END CHECK_APP_DATES;

  /******************************************************************************
      Procedure:  VALIDATE_APP_DATES
      Purpose:    Checks the appraisal effective/expiry dates for a given timber mark to ensure the appraisal dates are supported by GAS2.
                  Returns fatal error messages on any failure.
  ******************************************************************************/
  PROCEDURE VALIDATE_APP_DATES(P_ECAS_ID         IN VARCHAR2,
                               P_TIMBER_MARK     IN VARCHAR2,
                               P_APP_EFF_DATE    IN DATE,
                               P_APP_EXP_DATE    IN DATE,
                               P_APP_METHOD_CODE IN VARCHAR2,
                               P_ERROR_MESSAGE   IN OUT VARCHAR2) IS
  BEGIN
    VALIDATE_APP_DATES_INTERNAL(P_ECAS_ID,
                                P_TIMBER_MARK,
                                P_APP_EFF_DATE,
                                P_APP_EXP_DATE,
                                P_APP_METHOD_CODE,
                                true,
                                P_ERROR_MESSAGE);
  END VALIDATE_APP_DATES;

  /******************************************************************************
      Procedure: GET_USER_EMAIL_PREFERENCE
      Purpose:   Finds the 'EML' preference for a user
  ******************************************************************************/
  PROCEDURE GET_USER_EMAIL_PREFERENCE(P_USER_ID         IN VARCHAR2,
                                      p_user_preference IN OUT ref_ecas_user_preference) IS
  BEGIN
    OPEN p_user_preference FOR
      SELECT EUP.ECAS_USER_PREFERENCE_TYPE_CODE,
             EUP.USER_ID,
             EUP.PREFERENCE_VALUE
        FROM ECAS_USER_PREFERENCE EUP
        WHERE EUP.ECAS_USER_PREFERENCE_TYPE_CODE = 'EML'
         AND EUP.USER_ID = P_USER_ID;
  END GET_USER_EMAIL_PREFERENCE;


    /******************************************************************************
      Procedure: FIND_ECAS_AUDIT_EVENT_ID
      Purpose:
  ******************************************************************************/
  PROCEDURE FIND_ECAS_AUDIT_EVENT_ID(P_ECAS_ID          IN ECAS_AUDIT_EVENT.ECAS_ID%TYPE,
                                    P_ECAS_AUDIT_EVENT IN OUT ref_ecas_audit_event) AS
  BEGIN
    OPEN P_ECAS_AUDIT_EVENT FOR
      SELECT *
      FROM ECAS_AUDIT_EVENT EAE
       WHERE EAE.ECAS_ID =P_ECAS_ID
         AND EAE.ECAS_ACTION_CODE IN
         (SELECT ADS.APPRAISAL_STATUS_CODE FROM APPRAISAL_DATA_SUBMISSION ADS
           WHERE ADS.ECAS_ID = P_ECAS_ID)
          AND EAE.Audit_Event_Id =
         (SELECT MAX(audit_event_id) FROM ECAS_AUDIT_event
           where ecas_action_code in
            (SELECT ADS.APPRAISAL_STATUS_CODE FROM APPRAISAL_DATA_SUBMISSION ADS
           WHERE ADS.ECAS_ID = P_ECAS_ID)
           GROUP BY ECAS_ID HAVING ECAS_ID = P_ECAS_ID
           );
             --  AND EAE.ENTRY_TIMESTAMP = (SELECT MAX(ENTRY_TIMESTAMP) FROM ECAS_AUDIT_event
  END FIND_ECAS_AUDIT_EVENT_ID;


END;
