  , update_timestamp            client_contact.update_timestamp%TYPE
  , update_userid               client_contact.update_userid%TYPE
  , update_org_unit             client_contact.update_org_unit%TYPE
  , add_timestamp               client_contact.add_timestamp%TYPE
  , add_userid                  client_contact.add_userid%TYPE
  , add_org_unit                client_contact.add_org_unit%TYPE);
  r_previous      t_previous;

/******************************************************************************
    Procedure:  get

    Purpose:    SELECT one row from CLIENT_CONTACT

******************************************************************************/
  PROCEDURE get
  (p_client_contact_id   IN VARCHAR2)
  IS
  BEGIN
    SELECT
           client_contact_id
         , client_number
         , client_locn_code
         , bus_contact_code
         , contact_name
         , business_phone
         , cell_phone
         , fax_number
         , email_address
         , update_timestamp
         , update_userid
         , update_org_unit
         , add_timestamp
         , add_userid
         , add_org_unit
         , revision_count
      INTO
           g_client_contact_id
         , g_client_number
         , g_client_locn_code
         , g_bus_contact_code
         , g_contact_name
         , g_business_phone
         , g_cell_phone
         , g_fax_number
         , g_email_address
         , g_update_timestamp
         , g_update_userid
         , g_update_org_unit
         , g_add_timestamp
         , g_add_userid
         , g_add_org_unit
         , g_revision_count
      FROM client_contact
     WHERE client_contact_id = TO_NUMBER(p_client_contact_id);

  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      IF p_client_contact_id IS NOT NULL THEN
       -- record with rowid not found, most likely deleted.
        CLIENT_UTILS.add_error(g_error_message
                             , NULL
                             , 'client.web.usr.database.no.record.found'
                             , NULL);
      END IF;
  END get;


/******************************************************************************
    Procedure:  get_previous

    Purpose:    Get previous (saved) values and populate previous record

******************************************************************************/
  PROCEDURE get_previous
  IS
  BEGIN
    SELECT client_contact_id
         , client_number
         , client_locn_code
         , bus_contact_code
         , contact_name
         , business_phone
         , cell_phone
         , fax_number
         , email_address
         , update_timestamp
         , update_userid
         , update_org_unit
         , add_timestamp
         , add_userid
         , add_org_unit
      INTO r_previous
      FROM client_contact
     WHERE client_contact_id = g_client_contact_id;
  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      NULL;
  END get_previous;

