  /******************************************************************************
      Procedure:  INSERT_FRST_INVC_TXN
      Purpose: Creates an invoice in the FOREST_INVC_TXN table.
  ******************************************************************************/
  PROCEDURE INSERT_FRST_INVC_TXN(P_BILLING_STATUS_ST  IN Forest_Invc_Txn.Billing_Status_St%TYPE,
                                 P_INVOICE_AMOUNT     IN Forest_Invc_Txn.Invoice_Amount%TYPE,
                                 P_INVOICE_TYPE_CODE  IN Forest_Invc_Txn.Invoice_Type_Code%TYPE,
                                 P_INVC_SUB_TYPE_CODE IN Forest_Invc_Txn.Invc_Sub_Type_Code%Type,
                                 P_INVC_CLASS_CODE    IN Forest_Invc_Txn.Invoice_Class_Code%Type,
                                 P_RELATED_INVOICE    IN Forest_Invc_Txn.Related_Invoice%Type,
                                 P_INVOICE_RLN_TYP_CD IN Forest_Invc_Txn.Invoice_Rln_Typ_Cd%TYPE,
                                 P_CLIENT_NUMBER      IN Forest_Invc_Txn.Client_Number%TYPE,
                                 P_CLIENT_LOCN_CODE   IN Forest_Invc_Txn.Client_Locn_Code%TYPE,
                                 P_ENTRY_USERID       IN Forest_Invc_Txn.Entry_Userid%TYPE,
                                 P_RESULT             IN OUT ref_frst_invc_txn) IS

    V_INVOICE_NUMBER Forest_Invc_Txn.Invoice_Number%TYPE;

  BEGIN

    V_INVOICE_NUMBER := 'A' || LPAD(gbms_invoice_seq.nextval, 6, '0');

    INSERT INTO FOREST_INVC_TXN
      (INVOICE_NUMBER,
       BILLING_STATUS_ST,
       INVOICE_AMOUNT,
       INVOICE_CLASS_CODE,
       INVOICE_TYPE_CODE,
       INVC_SUB_TYPE_CODE,
       RELATED_INVOICE,
       INVOICE_RLN_TYP_CD,
       CLIENT_NUMBER,
       CLIENT_LOCN_CODE,
       ENTRY_USERID,
       ENTRY_TIMESTAMP,
       UPDATE_USERID,
       UPDATE_TIMESTAMP)
    VALUES
      (V_INVOICE_NUMBER,
       P_BILLING_STATUS_ST,
       P_INVOICE_AMOUNT,
       P_INVC_CLASS_CODE,
       P_INVOICE_TYPE_CODE,
       P_INVC_SUB_TYPE_CODE,
       P_RELATED_INVOICE,
       P_INVOICE_RLN_TYP_CD,
       P_CLIENT_NUMBER,
       P_CLIENT_LOCN_CODE,
       P_ENTRY_USERID,
       sysdate,
       P_ENTRY_USERID,
       sysdate);

    OPEN P_RESULT FOR
      SELECT *
        from FOREST_INVC_TXN
       where invoice_number = v_invoice_number;

  END INSERT_FRST_INVC_TXN;

  /******************************************************************************
      Procedure:  INSERT_FRST_INVC_TXN_AUDIT
      Purpose: Creates an invoice audit record in the FOREST_INVC_TXN_AUDIT table.
