                                 P_UPDATE_USERID       IN Forest_Invc_Txn.Update_Userid%TYPE,
                                 P_RESULT             IN OUT ref_frst_invc_txn_audit) IS

    V_AUDIT_NUMBER Forest_Invc_Txn_Audit.forest_invc_txn_audit_id%type;

  BEGIN

    V_AUDIT_NUMBER := gbms_forest_invc_audit_seq.nextval;

    INSERT INTO FOREST_INVC_TXN_AUDIT
      (FOREST_INVC_TXN_AUDIT_ID,
       INVOICE_NUMBER,
       BILLING_STATUS_ST,
       INVOICE_AMOUNT,
       Invoice_Class_Code,
       INVOICE_TYPE_CODE,
       INVC_SUB_TYPE_CODE,
       RELATED_INVOICE,
       INVOICE_RLN_TYP_CD,
       CLIENT_NUMBER,
       CLIENT_LOCN_CODE,
       ENTRY_USERID,
       ENTRY_TIMESTAMP,
       UPDATE_USERID,
       UPDATE_TIMESTAMP)
    VALUES
      (V_AUDIT_NUMBER,
       P_INVOICE_NUMBER,
       P_BILLING_STATUS_ST,
       P_INVOICE_AMOUNT,
       P_INVOICE_CLASS_CODE,
       P_INVOICE_TYPE_CODE,
       P_INVC_SUB_TYPE_CODE,
       P_RELATED_INVOICE,
       P_INVOICE_RLN_TYP_CD,
       P_CLIENT_NUMBER,
       P_CLIENT_LOCN_CODE,
       P_ENTRY_USERID,
       sysdate,
       P_UPDATE_USERID,
       sysdate);

    OPEN P_RESULT FOR
      SELECT *
        from FOREST_INVC_TXN_AUDIT
       where invoice_number = p_invoice_number and forest_invc_txn_audit_id = v_audit_number;

  END INSERT_FRST_INVC_TXN_AUDIT;

  /******************************************************************************
      Procedure:  UPDATE_FRST_INVC_TXN
      Purpose: Updates an invoice in the FOREST_INVC_TXN table.
  ******************************************************************************/
  PROCEDURE UPDATE_FRST_INVC_TXN(P_INVOICE_NUMBER     IN Forest_Invc_Txn.Invoice_Number%TYPE,
                                 P_BILLING_STATUS_ST  IN Forest_Invc_Txn.Billing_Status_St%TYPE,
                                 P_INVOICE_AMOUNT     IN Forest_Invc_Txn.Invoice_Amount%TYPE,
                                 P_INVOICE_TYPE_CODE  IN Forest_Invc_Txn.Invoice_Type_Code%TYPE,
                                 P_INVC_SUB_TYPE_CODE IN Forest_Invc_Txn.Invc_Sub_Type_Code%Type,
                                 P_RELATED_INVOICE    IN Forest_Invc_Txn.Related_Invoice%Type,
                                 P_INVOICE_RLN_TYP_CD IN Forest_Invc_Txn.Invoice_Rln_Typ_Cd%TYPE,
                                 P_CLIENT_NUMBER      IN Forest_Invc_Txn.Client_Number%TYPE,
                                 P_CLIENT_LOCN_CODE   IN Forest_Invc_Txn.Client_Locn_Code%TYPE,
                                 P_ENTRY_USERID       IN Forest_Invc_Txn.Entry_Userid%TYPE) IS

    frst_invc_txn_rec FOREST_INVC_TXN%rowtype;

  BEGIN

    select *
      into frst_invc_txn_rec
      from FOREST_INVC_TXN
     where invoice_number = P_INVOICE_NUMBER;

    frst_invc_txn_rec.BILLING_STATUS_ST  := P_BILLING_STATUS_ST;
    frst_invc_txn_rec.INVOICE_AMOUNT     := P_INVOICE_AMOUNT;
    frst_invc_txn_rec.INVOICE_TYPE_CODE  := P_INVOICE_TYPE_CODE;
    frst_invc_txn_rec.INVC_SUB_TYPE_CODE := P_INVC_SUB_TYPE_CODE;
    frst_invc_txn_rec.RELATED_INVOICE    := P_RELATED_INVOICE;
    frst_invc_txn_rec.INVOICE_RLN_TYP_CD := P_INVOICE_RLN_TYP_CD;
    frst_invc_txn_rec.CLIENT_NUMBER      := P_CLIENT_NUMBER;
    frst_invc_txn_rec.CLIENT_LOCN_CODE   := P_CLIENT_LOCN_CODE;
    frst_invc_txn_rec.UPDATE_USERID      := P_ENTRY_USERID;
    frst_invc_txn_rec.UPDATE_TIMESTAMP   := sysdate;

    UPDATE FOREST_INVC_TXN
       set row = frst_invc_txn_rec
     WHERE invoice_number = P_INVOICE_NUMBER;

  END UPDATE_FRST_INVC_TXN;

