      Purpose: Updates an invoice in the GNRL_INVC_TXN table.
  ******************************************************************************/
  PROCEDURE UPDATE_GNRL_INVC_TXN(P_INVOICE_NUMBER IN Gnrl_Invc_Txn.Invoice_Number%TYPE,
                                 P_ORIGIN_ORG_NO  IN Gnrl_Invc_Txn.Origin_Org_No%TYPE,
                                 P_ADMIN_ORG_NO   IN Gnrl_Invc_Txn.Origin_Org_No%TYPE,
                                 P_FOREST_FILE_ID IN Gnrl_Invc_Txn.Forest_File_Id%TYPE,
                                 P_MIN_REF_NUMBER IN Gnrl_Invc_Txn.Ministry_Ref_Num%Type,
                                 P_ENTRY_USERID   IN Gnrl_Invc_Txn.Entry_Userid%TYPE) IS

    gnrl_invc_txn_rec GNRL_INVC_TXN%rowtype;

  BEGIN

    select *
      into gnrl_invc_txn_rec
      from GNRL_INVC_TXN
     where invoice_number = P_INVOICE_NUMBER;

    gnrl_invc_txn_rec.FOREST_FILE_ID   := UPPER(P_FOREST_FILE_ID);
    gnrl_invc_txn_rec.Ministry_Ref_Num := UPPER(P_MIN_REF_NUMBER);
    gnrl_invc_txn_rec.ADMIN_ORG_NO     := P_ADMIN_ORG_NO;
    gnrl_invc_txn_rec.ORIGIN_ORG_NO    := P_ORIGIN_ORG_NO;
    gnrl_invc_txn_rec.UPDATE_USERID    := P_ENTRY_USERID;
    gnrl_invc_txn_rec.UPDATE_TIMESTAMP := sysdate;

    UPDATE GNRL_INVC_TXN
       set row = gnrl_invc_txn_rec
     WHERE invoice_number = P_INVOICE_NUMBER;

  END UPDATE_GNRL_INVC_TXN;

  /******************************************************************************
      Procedure:  FOREST_INVOICE
      Purpose: Updates an invoice in the FOREST_INVOICE table.
  ******************************************************************************/
  PROCEDURE UPDATE_FOREST_INVOICE(P_INVOICE_NUMBER     IN FOREST_INVOICE.Invoice_Number%TYPE,
                                  P_CANCELLATION_IND   IN FOREST_INVOICE.CANCELLATION_IND%TYPE,
                                  P_PAYABLE_BY_CLIENT  IN FOREST_INVOICE.PAYABLE_BY_CLIENT%TYPE,
                                  P_PAYABLE_BY_CLI_LOC IN FOREST_INVOICE.PAYABLE_BY_CLI_LOC%TYPE,
                                  P_INVOICE_AMOUNT     IN FOREST_INVOICE.INVOICE_AMOUNT%Type,
                                  P_INVOICE_DATE       IN FOREST_INVOICE.INVOICE_DATE%Type,
                                  P_INVOICE_TYPE_CODE  IN FOREST_INVOICE.INVOICE_TYPE_CODE%TYPE,
                                  P_INVC_SUB_TYPE_CODE IN FOREST_INVOICE.INVC_SUB_TYPE_CODE%TYPE,
                                  P_CANCELLED_BY_INVC  IN FOREST_INVOICE.CANCELLED_BY_INVC%TYPE,
                                  P_ORG_UNIT_NO        IN FOREST_INVOICE.ORG_UNIT_NO%TYPE,
                                  P_RELATED_INVOICE    IN FOREST_INVOICE.RELATED_INVOICE%TYPE,
                                  P_INVOICE_RLN_TYP_CD IN FOREST_INVOICE.INVOICE_RLN_TYP_CD%TYPE,
                                  P_REL_INVOICE_STS_ST IN FOREST_INVOICE.REL_INVOICE_STS_ST%TYPE,
                                  P_REPLACED_BY_INVC   IN FOREST_INVOICE.REPLACED_BY_INVC%TYPE,
                                  P_SCALE_RETURN_DATE  IN FOREST_INVOICE.SCALE_RETURN_DATE%TYPE,
                                  P_SCALE_SITE_ID_NMBR IN FOREST_INVOICE.SCALE_SITE_ID_NMBR%TYPE,
                                  P_SCALER_LICENCE_NUM IN FOREST_INVOICE.SCALER_LICENCE_NUM%TYPE,
                                  P_VOLUME_ONLY_IND    IN FOREST_INVOICE.VOLUME_ONLY_IND%TYPE,
                                  P_COPY_TO_CLIENT     IN FOREST_INVOICE.COPY_TO_CLIENT%TYPE,
                                  P_COPY_TO_CLI_LOC    IN FOREST_INVOICE.COPY_TO_CLI_LOC%TYPE,
                                  P_ENTRY_USERID       IN FOREST_INVOICE.ENTRY_USERID%TYPE,
                                  P_POSTED_DATE        IN FOREST_INVOICE.POSTED_DATE%TYPE,
                                  P_POSTED_SEQUENCE_NO IN FOREST_INVOICE.POSTED_SEQUENCE_NO%TYPE,
                                  P_SCALED_AT          IN FOREST_INVOICE.SCALED_AT%TYPE) IS

    frst_invc_rec FOREST_INVOICE%rowtype;

  BEGIN

    select *
      into frst_invc_rec
      from FOREST_INVOICE
     where invoice_number = P_INVOICE_NUMBER;

    frst_invc_rec.Cancellation_Ind   := P_CANCELLATION_IND;
    frst_invc_rec.PAYABLE_BY_CLIENT  := P_PAYABLE_BY_CLIENT;
    frst_invc_rec.PAYABLE_BY_CLI_LOC := P_PAYABLE_BY_CLI_LOC;
    frst_invc_rec.INVOICE_AMOUNT     := P_INVOICE_AMOUNT;
    frst_invc_rec.INVOICE_DATE       := P_INVOICE_DATE;
    frst_invc_rec.INVOICE_TYPE_CODE  := P_INVOICE_TYPE_CODE;
    frst_invc_rec.INVC_SUB_TYPE_CODE := P_INVC_SUB_TYPE_CODE;
    frst_invc_rec.CANCELLED_BY_INVC  := P_CANCELLED_BY_INVC;
    frst_invc_rec.ORG_UNIT_NO        := P_ORG_UNIT_NO;
    frst_invc_rec.RELATED_INVOICE    := P_RELATED_INVOICE;
    frst_invc_rec.INVOICE_RLN_TYP_CD := P_INVOICE_RLN_TYP_CD;
    frst_invc_rec.REL_INVOICE_STS_ST := P_REL_INVOICE_STS_ST;
    frst_invc_rec.REPLACED_BY_INVC   := P_REPLACED_BY_INVC;
    frst_invc_rec.SCALE_RETURN_DATE  := P_SCALE_RETURN_DATE;
    frst_invc_rec.SCALE_SITE_ID_NMBR := P_SCALE_SITE_ID_NMBR;
    frst_invc_rec.SCALER_LICENCE_NUM := P_SCALER_LICENCE_NUM;
    frst_invc_rec.VOLUME_ONLY_IND    := P_VOLUME_ONLY_IND;
    frst_invc_rec.COPY_TO_CLIENT     := P_COPY_TO_CLIENT;
    frst_invc_rec.COPY_TO_CLI_LOC    := P_COPY_TO_CLI_LOC;
    frst_invc_rec.UPDATE_USERID      := P_ENTRY_USERID;
    frst_invc_rec.UPDATE_TIMESTAMP   := sysdate;
    frst_invc_rec.POSTED_DATE        := P_POSTED_DATE;
    frst_invc_rec.POSTED_SEQUENCE_NO := P_POSTED_SEQUENCE_NO;
    frst_invc_rec.SCALED_AT          := P_SCALED_AT;

    UPDATE FOREST_INVOICE
       set row = frst_invc_rec
     WHERE invoice_number = P_INVOICE_NUMBER;

  END UPDATE_FOREST_INVOICE;

  /******************************************************************************
