  /******************************************************************************
      Procedure:  UPDATE_NOTATION_TXN
      Purpose: Updates a record in NOTATION_TXN.
  ******************************************************************************/
  PROCEDURE UPDATE_NOTATION_TXN(P_INVOICE_NUMBER  IN NOTATION_TXN.INVOICE_NUMBER%TYPE,
                                P_NOTATION_NUMBER IN NOTATION_TXN.Notation_Number%TYPE,
                                P_NOTATION_TEXT   IN NOTATION_TXN.NOTATION_TEXT%TYPE,
                                P_INTERNAL_IND    IN NOTATION_TXN.Internal_Ind%TYPE,
                                P_UPDATE_USER     IN NOTATION_TXN.Update_Userid%TYPE) IS

    notation_txn_rec notation_txn%rowtype;

  BEGIN

    select *
      into notation_txn_rec
      from notation_txn
     where invoice_number = P_INVOICE_NUMBER
       and notation_number = P_NOTATION_NUMBER;

    notation_txn_rec.notation_text    := P_NOTATION_TEXT;
    notation_txn_rec.update_userid    := P_UPDATE_USER;
    notation_txn_rec.update_timestamp := sysdate;
    notation_txn_rec.internal_ind := P_INTERNAL_IND;

    UPDATE notation_txn
       set row = notation_txn_rec
     WHERE invoice_number = P_INVOICE_NUMBER
       and notation_number = P_NOTATION_NUMBER;

  END UPDATE_NOTATION_TXN;

  /******************************************************************************
      Procedure:  DELETE_NOTATION_TXN
      Purpose: Deletes a record in NOTATION_TXN.
  ******************************************************************************/
  PROCEDURE DELETE_NOTATION_TXN(P_INVOICE_NUMBER  IN NOTATION_TXN.INVOICE_NUMBER%TYPE,
                                P_NOTATION_NUMBER IN NOTATION_TXN.Notation_Number%TYPE) IS

  BEGIN
    delete from NOTATION_TXN nt
     where nt.invoice_number = P_INVOICE_NUMBER
       and nt.notation_number = P_NOTATION_NUMBER;

  END DELETE_NOTATION_TXN;

  /******************************************************************************
      Procedure:  INSERT_NOTATION_TXN
      Purpose: Inserts a record in NOTATION_TXN.
  ******************************************************************************/
  PROCEDURE INSERT_NOTATION_TXN(P_INVOICE_NUMBER IN NOTATION_TXN.INVOICE_NUMBER%TYPE,
                                P_NOTATION_TEXT  IN NOTATION_TXN.NOTATION_TEXT%TYPE,
                                P_INTERNAL_IND   IN NOTATION_TXN.INTERNAL_IND%TYPE,
                                P_ENTRY_USER     IN NOTATION_TXN.Entry_Userid%TYPE,
                                P_RESULT         IN OUT ref_invoice_notation_txn) IS

    v_notation_number notation_txn.notation_number%type;

  BEGIN

    select coalesce(max(notation_number), 0) + 1
      into v_notation_number
      from notation_txn
     where invoice_number = p_invoice_number;

    INSERT INTO notation_txn
      (Invoice_Number,
       NOTATION_NUMBER,
       NOTATION_TEXT,
       INTERNAL_IND,
       ENTRY_USERID,
       ENTRY_TIMESTAMP,
       UPDATE_USERID,
       UPDATE_TIMESTAMP)
    VALUES
      (P_INVOICE_NUMBER,
       v_notation_number,
       P_NOTATION_TEXT,
       P_INTERNAL_IND,
       P_ENTRY_USER,
       sysdate,
       P_ENTRY_USER,
       sysdate);

    commit;

    --return the result
    OPEN P_RESULT FOR
      SELECT *
        from NOTATION_TXN
       where invoice_number = p_invoice_number
         and notation_number = v_notation_number;

  END INSERT_NOTATION_TXN;

