  /******************************************************************************
      Procedure:  INSERT_INVOICE_DTL_TXN
      Purpose: Inserts a record in INVOICE_DTL_TXN.
  ******************************************************************************/
  PROCEDURE INSERT_INVOICE_DTL_TXN(P_INVOICE_NUMBER     IN INVOICE_DTL_TXN.Invoice_Number%type,
                                   P_RESPONSE_CENTRE_CD IN INVOICE_DTL_TXN.Response_Centre_Cd%type,
                                   P_NUMBER_OF_UNITS    IN INVOICE_DTL_TXN.Number_Of_Units%type,
                                   P_UNIT_OF_MEASURE_CD IN INVOICE_DTL_TXN.Unit_Of_Measure_Cd%type,
                                   P_UNIT_RATE          IN INVOICE_DTL_TXN.Unit_Rate%type,
                                   P_EXTENDED_AMOUNT    IN INVOICE_DTL_TXN.Extended_Amount%type,
                                   P_OCG_SUPPLIER_NMBR  IN INVOICE_DTL_TXN.Ocg_Supplier_Nmbr%type,
                                   P_ACK_MASK_ACODE     IN INVOICE_DTL_TXN.ACK_MASK_ACODE%type,
                                   P_ENTRY_USER         IN INVOICE_DTL_TXN.ENTRY_USERID%type,
                                   P_LINE_ITEM_DESCR    IN INVOICE_DTL_TXN.LINE_ITEM_DESCR%type,
                                   P_PST_IND            IN INVOICE_DTL_TXN.PST_IND%type,
                                   P_GST_IND            IN INVOICE_DTL_TXN.GST_IND%type,
                                   P_HST_IND            IN INVOICE_DTL_TXN.HST_IND%type,
                                   P_RESULT             IN OUT ref_invoice_dtl_txn) IS

    v_line_item_number invoice_dtl_txn.line_item_number%type;

  BEGIN

    --determine the next line item number to use
    select coalesce(max(line_item_number), 0) + 1
      into v_line_item_number
      from INVOICE_DTL_TXN
     where invoice_number = P_INVOICE_NUMBER;

    INSERT INTO INVOICE_DTL_TXN
      (INVOICE_NUMBER,
       LINE_ITEM_NUMBER,
       RESPONSE_CENTRE_CD,
       NUMBER_OF_UNITS,
       UNIT_OF_MEASURE_CD,
       UNIT_RATE,
       EXTENDED_AMOUNT,
       OCG_SUPPLIER_NMBR,
       ACK_MASK_ACODE,
       ENTRY_TIMESTAMP,
       ENTRY_USERID,
       UPDATE_TIMESTAMP,
       UPDATE_USERID,
       LINE_ITEM_DESCR,
       PST_IND,
       GST_IND,
       HST_IND)
    VALUES
      (P_INVOICE_NUMBER,
       v_line_item_number,
       P_RESPONSE_CENTRE_CD,
       P_NUMBER_OF_UNITS,
       P_UNIT_OF_MEASURE_CD,
       P_UNIT_RATE,
       P_EXTENDED_AMOUNT,
       P_OCG_SUPPLIER_NMBR,
       upper(P_ACK_MASK_ACODE),
       sysdate,
       P_ENTRY_USER,
       sysdate,
       P_ENTRY_USER,
       P_LINE_ITEM_DESCR,
       P_PST_IND,
       P_GST_IND,
       P_HST_IND);

    commit;

        --update the invoice's total amount, including taxes of all the line items.
    update forest_invc_txn
    set invoice_amount = (select sum(extended_amount) from invoice_dtl_txn where invoice_number = P_INVOICE_NUMBER)
    where invoice_number = P_INVOICE_NUMBER;


    --return the result
    OPEN P_RESULT FOR
      SELECT *
        from INVOICE_DTL_TXN
       where invoice_number = p_invoice_number
         and line_item_number = v_line_item_number;

  END INSERT_INVOICE_DTL_TXN;

  /******************************************************************************
      Procedure:  INSERT_INVOICE_DTL_TXN
      Purpose: Inserts a record in INVOICE_DTL_TXN.
  ******************************************************************************/
  PROCEDURE INSERT_INVOICE_DTL_TXN_AUDIT(P_INVOICE_NUMBER     IN INVOICE_DTL_TXN.Invoice_Number%type,
                                   P_LINE_ITEM_NUMBER   IN INVOICE_DTL_TXN.Line_Item_Number%TYPE,
                                   P_RESPONSE_CENTRE_CD IN INVOICE_DTL_TXN.Response_Centre_Cd%type,
                                   P_NUMBER_OF_UNITS    IN INVOICE_DTL_TXN.Number_Of_Units%type,
                                   P_UNIT_OF_MEASURE_CD IN INVOICE_DTL_TXN.Unit_Of_Measure_Cd%type,
                                   P_UNIT_RATE          IN INVOICE_DTL_TXN.Unit_Rate%type,
                                   P_EXTENDED_AMOUNT    IN INVOICE_DTL_TXN.Extended_Amount%type,
                                   P_OCG_SUPPLIER_NMBR  IN INVOICE_DTL_TXN.Ocg_Supplier_Nmbr%type,
                                   P_ACK_MASK_ACODE     IN INVOICE_DTL_TXN.ACK_MASK_ACODE%type,
                                   P_ENTRY_USER         IN INVOICE_DTL_TXN.ENTRY_USERID%type,
                                   P_UPDATE_USER        IN INVOICE_DTL_TXN.UPDATE_USERID%type,
                                   P_LINE_ITEM_DESCR    IN INVOICE_DTL_TXN.LINE_ITEM_DESCR%type,
                                   P_PST_IND            IN INVOICE_DTL_TXN.PST_IND%type,
                                   P_GST_IND            IN INVOICE_DTL_TXN.GST_IND%type,
                                   P_HST_IND            IN INVOICE_DTL_TXN.HST_IND%type,
                                   P_RESULT             IN OUT ref_invoice_dtl_txn_audit) IS

    v_audit_id invoice_dtl_txn_audit.invoice_dtl_txn_audit_id%type;

  BEGIN

    v_audit_id := GBMS_INVOICE_DTL_TXN_AUDIT_SEQ.Nextval;

    INSERT INTO INVOICE_DTL_TXN_AUDIT
      (INVOICE_DTL_TXN_AUDIT_ID,
       INVOICE_NUMBER,
       LINE_ITEM_NUMBER,
       RESPONSE_CENTRE_CD,
       NUMBER_OF_UNITS,
       UNIT_OF_MEASURE_CD,
       UNIT_RATE,
       EXTENDED_AMOUNT,
       OCG_SUPPLIER_NMBR,
       ACK_MASK_ACODE,
       ENTRY_TIMESTAMP,
       ENTRY_USERID,
       UPDATE_TIMESTAMP,
       UPDATE_USERID,
       LINE_ITEM_DESCR,
       PST_IND,
       GST_IND,
       HST_IND)
    VALUES
      (v_audit_id,
       P_INVOICE_NUMBER,
       P_LINE_ITEM_NUMBER,
       P_RESPONSE_CENTRE_CD,
       P_NUMBER_OF_UNITS,
       P_UNIT_OF_MEASURE_CD,
       P_UNIT_RATE,
       P_EXTENDED_AMOUNT,
       P_OCG_SUPPLIER_NMBR,
       upper(P_ACK_MASK_ACODE),
       sysdate,
       P_ENTRY_USER,
       sysdate,
       P_UPDATE_USER,
       P_LINE_ITEM_DESCR,
       P_PST_IND,
       P_GST_IND,
       P_HST_IND);

    commit;

    --return the result
    OPEN P_RESULT FOR
      SELECT *
        from INVOICE_DTL_TXN_AUDIT
       where invoice_number = p_invoice_number
         and line_item_number = p_line_item_number
         and INVOICE_DTL_TXN_AUDIT_ID = v_audit_id;

  END INSERT_INVOICE_DTL_TXN_AUDIT;


  /******************************************************************************
      Procedure:  UPDATE_INVOICE_DTL_TXN
      Purpose: Updates a record in INVOICE_DTL_TXN.
  ******************************************************************************/
  PROCEDURE UPDATE_INVOICE_DTL_TXN(P_INVOICE_NUMBER     IN INVOICE_DTL_TXN.Invoice_Number%type,
                                   P_LINE_ITEM_NUMBER   IN INVOICE_DTL_TXN.Line_Item_Number%type,
                                   P_RESPONSE_CENTRE_CD IN INVOICE_DTL_TXN.Response_Centre_Cd%type,
                                   P_NUMBER_OF_UNITS    IN INVOICE_DTL_TXN.Number_Of_Units%type,
                                   P_UNIT_OF_MEASURE_CD IN INVOICE_DTL_TXN.Unit_Of_Measure_Cd%type,
                                   P_UNIT_RATE          IN INVOICE_DTL_TXN.Unit_Rate%type,
                                   P_EXTENDED_AMOUNT    IN INVOICE_DTL_TXN.Extended_Amount%type,
                                   P_OCG_SUPPLIER_NMBR  IN INVOICE_DTL_TXN.Ocg_Supplier_Nmbr%type,
                                   P_ACK_MASK_ACODE     IN INVOICE_DTL_TXN.ACK_MASK_ACODE%type,
                                   P_ENTRY_USER         IN INVOICE_DTL_TXN.ENTRY_USERID%type,
                                   P_LINE_ITEM_DESCR    IN INVOICE_DTL_TXN.LINE_ITEM_DESCR%type,
                                   P_PST_IND            IN INVOICE_DTL_TXN.PST_IND%type,
                                   P_GST_IND            IN INVOICE_DTL_TXN.GST_IND%type,
                                   P_HST_IND            IN INVOICE_DTL_TXN.HST_IND%type) IS

  invoice_dtl_txn_rec invoice_dtl_txn%rowtype;

  BEGIN

    select *
      into invoice_dtl_txn_rec
      from invoice_dtl_txn
     where invoice_number = P_INVOICE_NUMBER
       and line_item_number = P_LINE_ITEM_NUMBER;

    invoice_dtl_txn_rec.response_centre_cd := P_RESPONSE_CENTRE_CD;
    invoice_dtl_txn_rec.number_of_units := P_NUMBER_OF_UNITS;
    invoice_dtl_txn_rec.unit_of_measure_cd := P_UNIT_OF_MEASURE_CD;
    invoice_dtl_txn_rec.unit_rate := P_UNIT_RATE;
    invoice_dtl_txn_rec.Extended_Amount := P_EXTENDED_AMOUNT;
    invoice_dtl_txn_rec.Ocg_Supplier_Nmbr := P_OCG_SUPPLIER_NMBR;
    invoice_dtl_txn_rec.ack_mask_acode := upper(P_ACK_MASK_ACODE);
    invoice_dtl_txn_rec.line_item_descr := P_LINE_ITEM_DESCR;
    invoice_dtl_txn_rec.pst_ind := P_PST_IND;
    invoice_dtl_txn_rec.gst_ind := P_GST_IND;
    invoice_dtl_txn_rec.hst_ind := P_HST_IND;
    invoice_dtl_txn_rec.update_userid    := P_ENTRY_USER;
    invoice_dtl_txn_rec.update_timestamp := sysdate;

    UPDATE invoice_dtl_txn
       set row = invoice_dtl_txn_rec
     WHERE invoice_number = P_INVOICE_NUMBER
       and line_item_number = P_LINE_ITEM_NUMBER;

    --update the invoice's total amount, including taxes of all the line items.
    update forest_invc_txn
    set invoice_amount = (select sum(extended_amount) from invoice_dtl_txn where invoice_number = P_INVOICE_NUMBER)
    where invoice_number = P_INVOICE_NUMBER;


  END UPDATE_INVOICE_DTL_TXN;

  /******************************************************************************
      Procedure:  DELETE_INVOICE_DTL_TXN
      Purpose: Deletes a record in INVOICE_DTL_TXN.
  ******************************************************************************/
  PROCEDURE DELETE_INVOICE_DTL_TXN(P_INVOICE_NUMBER   IN INVOICE_DTL_TXN.INVOICE_NUMBER%TYPE,
                                   P_LINE_ITEM_NUMBER IN INVOICE_DTL_TXN.LINE_ITEM_NUMBER%TYPE) IS

  BEGIN
    delete from INVOICE_DTL_TXN IDT
     where IDT.invoice_number = P_INVOICE_NUMBER
       and IDT.Line_Item_Number = P_LINE_ITEM_NUMBER;

    --update the invoice's total amount, including taxes of all the line items.
    update forest_invc_txn
    set invoice_amount = (select sum(extended_amount) from invoice_dtl_txn where invoice_number = P_INVOICE_NUMBER)
    where invoice_number = P_INVOICE_NUMBER;


  END DELETE_INVOICE_DTL_TXN;



end GBMS_PERSISTENCE;
/

  CREATE OR REPLACE EDITIONABLE PACKAGE "THE"."LEXIS_GBMS_INVOICING" is
  -- Author  : bfalk
  -- Created : 10/29/2020
  -- Purpose : Integrates with GBMS to allow LEXIS to create and cancel invoices

  PROCEDURE CANCEL_INVOICE (P_INVOICE_NUMBER   IN GENERAL_INVOICE.INVOICE_NUMBER%TYPE,
                            P_UPDATE_USERID    IN GENERAL_INVOICE.UPDATE_USERID%TYPE);

  PROCEDURE DISCARD_TRANSACTION_INVOICE (P_INVOICE_NUMBER IN GENERAL_INVOICE.INVOICE_NUMBER%TYPE,
                                         P_UPDATE_USERID  IN GENERAL_INVOICE.UPDATE_USERID%TYPE);

  PROCEDURE CANCEL_PRINTED_INVOICE (P_INVOICE_NUMBER IN GENERAL_INVOICE.INVOICE_NUMBER%TYPE,
                                    P_UPDATE_USERID  IN GENERAL_INVOICE.UPDATE_USERID%TYPE,
                                    P_CANCELLATION_INVOICE_NO OUT FOREST_INVC_TXN.INVOICE_NUMBER%TYPE);

  PROCEDURE SET_REPLACEMENT_INVOICE (P_REPLACEMENT_INVOICE_NUMBER IN FOREST_INVOICE.INVOICE_NUMBER%TYPE,
                                     P_ORIGINAL_INVOICE_NUMBER    IN FOREST_INVOICE.INVOICE_NUMBER%TYPE,
                                     P_UPDATE_USERID              IN FOREST_INVOICE.UPDATE_USERID%TYPE,
                                     P_INVOICE                    IN OUT GBMS_PERSISTENCE.ref_frst_invc);

end LEXIS_GBMS_INVOICING;
/
CREATE OR REPLACE EDITIONABLE PACKAGE BODY "THE"."LEXIS_GBMS_INVOICING" is
  /******************************************************************************
      Procedure:  CANCEL_INVOICE
      Purpose: Cancel a printed or transactional invoice from, respectively,
      FOREST_INVOICE, GENERAL_INVOICE, GEN_INVOICE_DETAIL, and INVC_NOTATION, OR
      FOREST_INVC_TXN, GNRL_INVC_TXN, INVOICE_DTL_TXN, and NOTATION_TXN
  ******************************************************************************/
  PROCEDURE CANCEL_INVOICE (P_INVOICE_NUMBER   IN GENERAL_INVOICE.INVOICE_NUMBER%TYPE,
                            P_UPDATE_USERID    IN GENERAL_INVOICE.UPDATE_USERID%TYPE) IS

  printed_invoice_count INTEGER;
  V_CANCELLATION_INVOICE_NO FOREST_INVC_TXN.Invoice_Number%type;

  BEGIN
    SELECT count(*)
    into printed_invoice_count
    from GENERAL_INVOICE GIN
    where GIN.INVOICE_NUMBER = P_INVOICE_NUMBER
    and GIN.CANCELLATION_IND = 'N'; -- Should always be N for LEXIS/GBMS

    IF printed_invoice_count <= 0 THEN
      DISCARD_TRANSACTION_INVOICE(P_INVOICE_NUMBER, P_UPDATE_USERID);
    ELSE
      CANCEL_PRINTED_INVOICE(P_INVOICE_NUMBER, P_UPDATE_USERID, V_CANCELLATION_INVOICE_NO);
    END IF;

  END CANCEL_INVOICE;

  /******************************************************************************
      Procedure:  DISCARD_TRANSACTIONAL_INVOICE
      Purpose: Cancel a transactional invoice from
      FOREST_INVC_TXN, GNRL_INVC_TXN, INVOICE_DTL_TXN, and NOTATION_TXN
  ******************************************************************************/
  PROCEDURE DISCARD_TRANSACTION_INVOICE (P_INVOICE_NUMBER IN GENERAL_INVOICE.INVOICE_NUMBER%TYPE,
                                         P_UPDATE_USERID  IN GENERAL_INVOICE.UPDATE_USERID%TYPE) IS

  BEGIN

    /* Update transactional invoice */
    UPDATE FOREST_INVC_TXN FIT
    SET BILLING_STATUS_ST = 'DSC',
        FIT.UPDATE_USERID = P_UPDATE_USERID,
        FIT.UPDATE_TIMESTAMP = sysdate
    WHERE FIT.INVOICE_NUMBER = P_INVOICE_NUMBER;

    /* If invoice being discarded was responsible for cancelling or replacing a printed invoice,
    need to clear the CANCELLED_BY AND REPLACED_BY columns */
    UPDATE FOREST_INVOICE FIN
    SET FIN.CANCELLED_BY_INVC = NULL,
        FIN.REPLACED_BY_INVC = NULL
    WHERE FIN.INVOICE_NUMBER =
          (SELECT FIT.RELATED_INVOICE
          FROM FOREST_INVC_TXN FIT
          WHERE FIT.INVOICE_NUMBER = P_INVOICE_NUMBER);

  END DISCARD_TRANSACTION_INVOICE;

  /******************************************************************************
      Procedure:  CANCEL_PRINTED_INVOICE
      Purpose: Cancel an original printed invoice from
      FOREST_INVOICE, GENERAL_INVOICE, GEN_INVOICE_DETAIL, and INVC_NOTATION,
      as well as to create both a cancellation and replacement invoice
  ******************************************************************************/
  PROCEDURE CANCEL_PRINTED_INVOICE (P_INVOICE_NUMBER IN GENERAL_INVOICE.INVOICE_NUMBER%TYPE,
                                    P_UPDATE_USERID  IN GENERAL_INVOICE.UPDATE_USERID%TYPE,
                                    P_CANCELLATION_INVOICE_NO OUT FOREST_INVC_TXN.INVOICE_NUMBER%TYPE) IS


  forest_invc_rec     FOREST_INVOICE%ROWTYPE;
  forest_invc_txn_rec FOREST_INVC_TXN%ROWTYPE;
  gnrl_invc_rec       GENERAL_INVOICE%ROWTYPE;
  notation_txn_rec    NOTATION_TXN%ROWTYPE;
  gen_invc_det_rec    GEN_INVOICE_DTL%ROWTYPE;

  new_frst_invc_txn_ref  GBMS_PERSISTENCE.ref_frst_invc_txn;
  new_grnl_invc_txn_ref  GBMS_PERSISTENCE.ref_grnl_invc_txn;
  new_invc_notat_ref     GBMS_PERSISTENCE.ref_invoice_notation_txn;
  new_invc_dtl_txn_ref   GBMS_PERSISTENCE.ref_invoice_dtl_txn;

  CURSOR gnrl_invc_det_items IS
         SELECT * FROM GEN_INVOICE_DTL GID
         WHERE GID.INVOICE_NUMBER = P_INVOICE_NUMBER;

  BEGIN

    -- Create new forest invoice for 'Cancellation Invoice'
    SELECT * INTO forest_invc_rec
    FROM FOREST_INVOICE FIN
    WHERE FIN.INVOICE_NUMBER = P_INVOICE_NUMBER;

    -- Negate original invoice amount
    forest_invc_rec.invoice_amount := 0 - ABS(forest_invc_rec.invoice_amount);

    -- Reference original invoice
    forest_invc_rec.related_invoice := P_INVOICE_NUMBER;

    forest_invc_rec.entry_userid := P_UPDATE_USERID;
    forest_invc_rec.update_userid := P_UPDATE_USERID;
    forest_invc_rec.invoice_rln_typ_cd := 'CAN'; -- 'Cancelled'

    GBMS_PERSISTENCE.INSERT_FRST_INVC_TXN('APP',
                         forest_invc_rec.invoice_amount,
                         forest_invc_rec.invoice_type_code,
                         forest_invc_rec.invc_sub_type_code,
                         forest_invc_rec.invoice_class_code,
                         forest_invc_rec.related_invoice,
                         forest_invc_rec.invoice_rln_typ_cd,
                         forest_invc_rec.payable_by_client,
                         forest_invc_rec.payable_by_cli_loc,
                         forest_invc_rec.entry_userid,
                         new_frst_invc_txn_ref);

    -- Create new general invoice for 'Cancellation Invoice'
    SELECT * INTO gnrl_invc_rec
    FROM GENERAL_INVOICE GIN
    WHERE GIN.INVOICE_NUMBER = P_INVOICE_NUMBER;

    gnrl_invc_rec.entry_userid := P_UPDATE_USERID;

    -- Use newly generated invoice number
    LOOP
      FETCH new_frst_invc_txn_ref INTO forest_invc_txn_rec;
      EXIT WHEN new_frst_invc_txn_ref%NOTFOUND;
      gnrl_invc_rec.invoice_number := forest_invc_txn_rec.INVOICE_NUMBER;
    END LOOP;
    CLOSE new_frst_invc_txn_ref;

    GBMS_PERSISTENCE.INSERT_GNRL_INVC_TXN(gnrl_invc_rec.invoice_number,
                         gnrl_invc_rec.orign_org_unit_no,
                         gnrl_invc_rec.admin_org_unit_no,
                         gnrl_invc_rec.forest_file_id,
                         gnrl_invc_rec.ministry_ref_num,
                         gnrl_invc_rec.entry_userid,
                         new_grnl_invc_txn_ref);

    -- Create new invoice notation
    notation_txn_rec.invoice_number := gnrl_invc_rec.invoice_number;
    notation_txn_rec.notation_text := 'Cancellation of Invoice ' || P_INVOICE_NUMBER;
    notation_txn_rec.internal_ind := 'N';
    notation_txn_rec.entry_userid := P_UPDATE_USERID;

    GBMS_PERSISTENCE.INSERT_NOTATION_TXN(notation_txn_rec.invoice_number,
                        notation_txn_rec.notation_text,
                        notation_txn_rec.internal_ind,
                        notation_txn_rec.entry_userid,
                        new_invc_notat_ref);

    P_CANCELLATION_INVOICE_NO := gnrl_invc_rec.invoice_number;

    -- Create new invoice details
    OPEN gnrl_invc_det_items;

     -- For each line item in invoice detail, construct new transaction invoice detail
    LOOP
      FETCH gnrl_invc_det_items INTO gen_invc_det_rec;
      EXIT WHEN gnrl_invc_det_items%NOTFOUND;

      -- Negate invoice amount
      gen_invc_det_rec.extended_amount := 0 - ABS(gen_invc_det_rec.extended_amount);

      gen_invc_det_rec.entry_userid := P_UPDATE_USERID;
      gen_invc_det_rec.invoice_number := gnrl_invc_rec.invoice_number;

      GBMS_PERSISTENCE.INSERT_INVOICE_DTL_TXN(gen_invc_det_rec.invoice_number,
                             gen_invc_det_rec.response_centre_cd,
                             gen_invc_det_rec.number_of_units,
                             gen_invc_det_rec.unit_of_measure_cd,
                             gen_invc_det_rec.unit_rate,
                             gen_invc_det_rec.extended_amount,
                             gen_invc_det_rec.ocg_supplier_nmbr,
                             gen_invc_det_rec.revenue_classn_cd,
                             gen_invc_det_rec.entry_userid,
                             gen_invc_det_rec.line_item_descr,
                             gen_invc_det_rec.pst_ind,
                             gen_invc_det_rec.gst_ind,
                             gen_invc_det_rec.hst_ind,
                             new_invc_dtl_txn_ref);
    END LOOP;
    CLOSE gnrl_invc_det_items;

    -- Cancellation Invoice created, update Original Invoice
    UPDATE FOREST_INVOICE FIN
    SET CANCELLED_BY_INVC = gnrl_invc_rec.invoice_number,
        FIN.UPDATE_USERID = P_UPDATE_USERID,
        FIN.UPDATE_TIMESTAMP = sysdate
    WHERE FIN.INVOICE_NUMBER = P_INVOICE_NUMBER;

    UPDATE GENERAL_INVOICE GIN
    SET GIN.UPDATE_USERID = P_UPDATE_USERID,
        GIN.UPDATE_TIMESTAMP = sysdate
    WHERE GIN.INVOICE_NUMBER = P_INVOICE_NUMBER;

  END CANCEL_PRINTED_INVOICE;

  /******************************************************************************
      Procedure:  SET_REPLACEMENT_INVOICE
      Purpose: Updates an existing invoice to show that is has been replaced,
      returns original (modified) invoice.
  ******************************************************************************/
  PROCEDURE SET_REPLACEMENT_INVOICE (P_REPLACEMENT_INVOICE_NUMBER IN FOREST_INVOICE.INVOICE_NUMBER%TYPE,
                                     P_ORIGINAL_INVOICE_NUMBER    IN FOREST_INVOICE.INVOICE_NUMBER%TYPE,
                                     P_UPDATE_USERID              IN FOREST_INVOICE.UPDATE_USERID%TYPE,
                                     P_INVOICE                    IN OUT GBMS_PERSISTENCE.ref_frst_invc) IS

    BEGIN
      UPDATE FOREST_INVOICE FIN
      SET FIN.REPLACED_BY_INVC = P_REPLACEMENT_INVOICE_NUMBER,
        FIN.UPDATE_USERID      = P_UPDATE_USERID,
        FIN.UPDATE_TIMESTAMP   = sysdate
      WHERE FIN.INVOICE_NUMBER = P_ORIGINAL_INVOICE_NUMBER;

      OPEN P_INVOICE FOR
      SELECT * FROM FOREST_INVOICE FIN
      WHERE FIN.INVOICE_NUMBER = P_ORIGINAL_INVOICE_NUMBER;

  END SET_REPLACEMENT_INVOICE;

end LEXIS_GBMS_INVOICING;
/

