  TYPE rec_purchase_offers IS RECORD(
    EXPORT_PURCHASE_OFFER_NUMBER export_purchase_offer.EXPORT_PURCHASE_OFFER_NUMBER%TYPE,
    COMPANY_NAME                 export_purchase_offer.COMPANY_NAME%TYPE,
    CONTACT_NAME                 export_purchase_offer.CONTACT_NAME%TYPE,
    PURCHASE_OFFER_AMOUNT        export_purchase_offer.PURCHASE_OFFER_AMOUNT%TYPE,
    PURCHASE_OFFER_DATE          export_purchase_offer.PURCHASE_OFFER_DATE%TYPE,
