  /******************************************************************************
      Procedure:  FIND_ALL_CURRENCY_CONVERSIONS
      Purpose: Find available CURRENCY_CONVERSIONS.
  ******************************************************************************/
  PROCEDURE FIND_ALL_CURRENCY_CONVERSIONS(P_CODES IN OUT ref_currency_type) IS
  BEGIN
    OPEN P_CODES FOR
      SELECT C.CURRENCY_TYPE_CODE,
             C.IN_EFFECT_FROM_DATE,
             C.RATE_TO_CANADIAN,
             C.IN_EFFECT_TO_DATE,
             C.ENTRY_USERID,
             C.ENTRY_TIMESTAMP
        FROM EXPORT_CURRENCY_CONVERSION C
       WHERE SYSDATE BETWEEN IN_EFFECT_FROM_DATE AND IN_EFFECT_TO_DATE
       ORDER BY C.CURRENCY_TYPE_CODE;
  END FIND_ALL_CURRENCY_CONVERSIONS;

  /******************************************************************************
      Procedure:  FIND_CURRENCY_CONVERSION
      Purpose: Find a CURRENCY_CONVERSION.
  ******************************************************************************/
  PROCEDURE FIND_CURRENCY_CONVERSION(P_CODE   IN EXPORT_CURRENCY_CONVERSION.CURRENCY_TYPE_CODE%TYPE,
                                     P_RESULT IN OUT ref_currency_type) IS
  BEGIN
    OPEN P_RESULT FOR
      SELECT C.CURRENCY_TYPE_CODE,
             C.IN_EFFECT_FROM_DATE,
             C.RATE_TO_CANADIAN,
             C.IN_EFFECT_TO_DATE,
             C.ENTRY_USERID,
             C.ENTRY_TIMESTAMP
        FROM EXPORT_CURRENCY_CONVERSION C
       WHERE C.CURRENCY_TYPE_CODE = P_CODE
         AND SYSDATE BETWEEN IN_EFFECT_FROM_DATE AND IN_EFFECT_TO_DATE
       ORDER BY C.CURRENCY_TYPE_CODE;
  END FIND_CURRENCY_CONVERSION;

  /******************************************************************************
      Procedure:  FIND_CONVERSION_FOR_DATE
      Purpose: Find a CURRENCY_CONVERSION for a given date.
  ******************************************************************************/
  PROCEDURE FIND_CONVERSION_FOR_DATE(P_CODE   IN EXPORT_CURRENCY_CONVERSION.CURRENCY_TYPE_CODE%TYPE,
                                     P_DATE   IN EXPORT_CURRENCY_CONVERSION.IN_EFFECT_FROM_DATE%TYPE,
                                     P_RESULT IN OUT ref_currency_type) IS
  BEGIN
    OPEN P_RESULT FOR
      SELECT C.CURRENCY_TYPE_CODE,
             C.IN_EFFECT_FROM_DATE,
             C.RATE_TO_CANADIAN,
             C.IN_EFFECT_TO_DATE,
             C.ENTRY_USERID,
             C.ENTRY_TIMESTAMP
        FROM EXPORT_CURRENCY_CONVERSION C
       WHERE C.CURRENCY_TYPE_CODE = P_CODE
         AND P_DATE BETWEEN IN_EFFECT_FROM_DATE AND IN_EFFECT_TO_DATE
       ORDER BY C.CURRENCY_TYPE_CODE;
  END FIND_CONVERSION_FOR_DATE;

  /******************************************************************************
      Procedure:  FIND_FOREST_DISTRICTS
      Purpose: Find valid forest districts.
  ******************************************************************************/
  PROCEDURE FIND_FOREST_DISTRICTS(P_FOREST_DISTRICTS IN OUT ref_cur_org_unit) IS
  BEGIN
    OPEN P_FOREST_DISTRICTS FOR
      SELECT O.ORG_UNIT_NO,
             O.ORG_UNIT_CODE,
             O.ORG_UNIT_NAME,
             O.LOCATION_CODE,
             O.AREA_CODE,
             O.TELEPHONE_NO,
             O.ORG_LEVEL_CODE,
             O.OFFICE_NAME_CODE,
             O.ROLLUP_REGION_NO,
             O.ROLLUP_REGION_CODE,
             O.ROLLUP_DIST_NO,
             O.ROLLUP_DIST_CODE,
             O.EFFECTIVE_DATE,
             O.EXPIRY_DATE,
             O.UPDATE_TIMESTAMP
        FROM ORG_UNIT O
       WHERE O.ROLLUP_DIST_NO = O.ORG_UNIT_NO
         AND SYSDATE BETWEEN O.EFFECTIVE_DATE AND O.EXPIRY_DATE
       ORDER BY O.ORG_UNIT_NAME;
  END FIND_FOREST_DISTRICTS;

  /******************************************************************************
      Procedure:  FIND_MANAGEMENT_AREAS
      Purpose: Find valid management areas.
  ******************************************************************************/
  PROCEDURE FIND_MANAGEMENT_AREAS(P_MANAGEMENT_AREAS IN OUT ref_cur_org_unit) IS
  BEGIN
    OPEN P_MANAGEMENT_AREAS FOR
      SELECT O.ORG_UNIT_NO,
             O.ORG_UNIT_CODE,
             O.ORG_UNIT_NAME,
             O.LOCATION_CODE,
             O.AREA_CODE,
             O.TELEPHONE_NO,
             O.ORG_LEVEL_CODE,
             O.OFFICE_NAME_CODE,
             O.ROLLUP_REGION_NO,
             O.ROLLUP_REGION_CODE,
             O.ROLLUP_DIST_NO,
             O.ROLLUP_DIST_CODE,
             O.EFFECTIVE_DATE,
             O.EXPIRY_DATE,
             O.UPDATE_TIMESTAMP
        FROM ORG_UNIT O
       WHERE SYSDATE > O.EXPIRY_DATE
         AND LENGTH(O.ORG_UNIT_CODE) = 3
         AND O.ORG_LEVEL_CODE = 'D'
       ORDER BY O.ORG_UNIT_NAME;
  END FIND_MANAGEMENT_AREAS;

  /******************************************************************************
      Procedure:  FIND_MANAGEMENT_AREAS_BY_SLCTN
      Purpose: Find valid management areas based on the forest district provided.
  ******************************************************************************/
  PROCEDURE FIND_MANAGEMENT_AREAS_BY_SLCTN(P_ORG_UNIT_NO      IN ORG_UNIT.ORG_UNIT_NO%TYPE,
                                           P_MANAGEMENT_AREAS IN OUT ref_cur_org_unit) IS
  BEGIN
    OPEN P_MANAGEMENT_AREAS FOR
      SELECT O.ORG_UNIT_NO,
             O.ORG_UNIT_CODE,
             O.ORG_UNIT_NAME,
             O.LOCATION_CODE,
             O.AREA_CODE,
             O.TELEPHONE_NO,
             O.ORG_LEVEL_CODE,
             O.OFFICE_NAME_CODE,
             O.ROLLUP_REGION_NO,
             O.ROLLUP_REGION_CODE,
             O.ROLLUP_DIST_NO,
             O.ROLLUP_DIST_CODE,
             O.EFFECTIVE_DATE,
             O.EXPIRY_DATE,
             O.UPDATE_TIMESTAMP
        FROM ORG_UNIT O
       WHERE O.ROLLUP_DIST_NO = P_ORG_UNIT_NO
         AND SYSDATE > O.EXPIRY_DATE
         AND LENGTH(O.ORG_UNIT_CODE) = 3
         AND O.ORG_LEVEL_CODE = 'D'
       ORDER BY O.ORG_UNIT_NAME;
  END FIND_MANAGEMENT_AREAS_BY_SLCTN;

  /******************************************************************************
      Procedure:  FIND_BUSINESS_AREAS
      Purpose: Find valid forest districts.
