  /******************************************************************************
      Procedure:  FIND_ORG_UNIT_BY_NUMBER
      Purpose: Find an org unit by app number.
  ******************************************************************************/
  PROCEDURE FIND_ORG_UNIT_BY_APP_NMBR(P_APP_NUMBER IN EXPORT_EXEMPTION_APPLICATION.Org_Unit_No%TYPE,
                                    P_ORG_UNIT    IN OUT ref_cur_org_unit) IS

  V_ORG_UNIT ORG_UNIT.ORG_UNIT_NO%TYPE;

  BEGIN

    SELECT EEA.ORG_UNIT_NO INTO V_ORG_UNIT FROM EXPORT_EXEMPTION_APPLICATION EEA WHERE EEA.APPLICATION_NUMBER = P_APP_NUMBER;

    OPEN P_ORG_UNIT FOR
      SELECT O.ORG_UNIT_NO,
             O.ORG_UNIT_CODE,
             O.ORG_UNIT_NAME,
             O.LOCATION_CODE,
             O.AREA_CODE,
             O.TELEPHONE_NO,
             O.ORG_LEVEL_CODE,
             O.OFFICE_NAME_CODE,
             O.ROLLUP_REGION_NO,
             O.ROLLUP_REGION_CODE,
             O.ROLLUP_DIST_NO,
             O.ROLLUP_DIST_CODE,
             O.EFFECTIVE_DATE,
             O.EXPIRY_DATE,
             O.UPDATE_TIMESTAMP
        FROM ORG_UNIT O
       WHERE O.ORG_UNIT_NO = V_ORG_UNIT;
  END FIND_ORG_UNIT_BY_APP_NMBR;

  /******************************************************************************
      Procedure:  FIND_PRTBLE_STORAGE_LOCATIONS
      Purpose: Find valid portable superstructure storage locations.
  ******************************************************************************/
  PROCEDURE FIND_PRTBLE_STORAGE_LOCATIONS(P_PORTABLE_LOCS IN OUT ref_cur_org_unit) IS
  BEGIN
    OPEN P_PORTABLE_LOCS FOR
      SELECT O.ORG_UNIT_NO,
             O.ORG_UNIT_CODE,
             O.ORG_UNIT_NAME,
             O.LOCATION_CODE,
             O.AREA_CODE,
             O.TELEPHONE_NO,
             O.ORG_LEVEL_CODE,
             O.OFFICE_NAME_CODE,
             O.ROLLUP_REGION_NO,
             O.ROLLUP_REGION_CODE,
             O.ROLLUP_DIST_NO,
             O.ROLLUP_DIST_CODE,
             O.EFFECTIVE_DATE,
             O.EXPIRY_DATE,
             O.UPDATE_TIMESTAMP
        FROM ORG_UNIT O
       WHERE O.ORG_LEVEL_CODE IN ('D', 'T')
         AND LENGTH(O.ORG_UNIT_CODE) = 3
         AND SYSDATE BETWEEN O.EFFECTIVE_DATE AND O.EXPIRY_DATE
       ORDER BY O.ORG_UNIT_NAME;
  END FIND_PRTBLE_STORAGE_LOCATIONS;

  /******************************************************************************
