             O.LOCATION_CODE,
             O.AREA_CODE,
             O.TELEPHONE_NO,
             O.ORG_LEVEL_CODE,
             O.OFFICE_NAME_CODE,
             O.ROLLUP_REGION_NO,
             O.ROLLUP_REGION_CODE,
             O.ROLLUP_DIST_NO,
             O.ROLLUP_DIST_CODE,
             O.EFFECTIVE_DATE,
             O.EXPIRY_DATE,
             O.UPDATE_TIMESTAMP
        FROM ORG_UNIT O
       WHERE UPDATE_TIMESTAMP =
             (SELECT MAX(UPDATE_TIMESTAMP)
                FROM ORG_UNIT O
               WHERE (LENGTH(O.ORG_UNIT_CODE) = 3 AND O.ORG_LEVEL_CODE = 'D')
                  OR (O.ROLLUP_DIST_NO = O.ORG_UNIT_NO)
                  OR (O.ORG_LEVEL_CODE = 'T' AND LENGTH(O.ORG_UNIT_CODE) = 3)
                  OR (O.ORG_LEVEL_CODE IN ('D', 'T') AND
                     LENGTH(O.ORG_UNIT_CODE) = 3));
  END FIND_LAST_UPDATED_ORG_UNIT;

  /******************************************************************************
      Procedure:  FIND_ALL_ORG_UNITS
      Purpose: Find the org units used within the application.
  ******************************************************************************/
  PROCEDURE FIND_ALL_ORG_UNITS(P_ORG_UNITS IN OUT ref_cur_org_unit) IS
  BEGIN
    OPEN P_ORG_UNITS FOR
      SELECT O.ORG_UNIT_NO,
             O.ORG_UNIT_CODE,
             O.ORG_UNIT_NAME,
             O.LOCATION_CODE,
             O.AREA_CODE,
             O.TELEPHONE_NO,
             O.ORG_LEVEL_CODE,
             O.OFFICE_NAME_CODE,
             O.ROLLUP_REGION_NO,
             O.ROLLUP_REGION_CODE,
             O.ROLLUP_DIST_NO,
             O.ROLLUP_DIST_CODE,
             O.EFFECTIVE_DATE,
             O.EXPIRY_DATE,
             O.UPDATE_TIMESTAMP
        FROM ORG_UNIT O
       WHERE SYSDATE BETWEEN O.EFFECTIVE_DATE AND O.EXPIRY_DATE
         AND (LENGTH(O.ORG_UNIT_CODE) = 3 AND O.ORG_LEVEL_CODE = 'D')
          OR (O.ROLLUP_DIST_NO = O.ORG_UNIT_NO)
          OR (O.ORG_LEVEL_CODE = 'T' AND LENGTH(O.ORG_UNIT_CODE) = 3)
          OR (O.ORG_LEVEL_CODE IN ('D', 'T') AND
             LENGTH(O.ORG_UNIT_CODE) = 3);
  END FIND_ALL_ORG_UNITS;

  /******************************************************************************
      Procedure:  FIND_ORG_UNIT_BY_CODE
      Purpose: Find the org unit by org unit code.
  ******************************************************************************/
  PROCEDURE FIND_ORG_UNIT_BY_CODE(P_ORG_UNIT_CODE IN ORG_UNIT.ORG_UNIT_CODE%TYPE,
                                  P_ORG_UNIT      IN OUT ref_cur_org_unit) IS
  BEGIN
    OPEN P_ORG_UNIT FOR
      SELECT O.ORG_UNIT_NO,
             O.ORG_UNIT_CODE,
             O.ORG_UNIT_NAME,
             O.LOCATION_CODE,
             O.AREA_CODE,
             O.TELEPHONE_NO,
             O.ORG_LEVEL_CODE,
             O.OFFICE_NAME_CODE,
             O.ROLLUP_REGION_NO,
             O.ROLLUP_REGION_CODE,
             O.ROLLUP_DIST_NO,
             O.ROLLUP_DIST_CODE,
             O.EFFECTIVE_DATE,
             O.EXPIRY_DATE,
             O.UPDATE_TIMESTAMP
        FROM ORG_UNIT O
       WHERE O.ORG_UNIT_CODE = P_ORG_UNIT_CODE;
  END FIND_ORG_UNIT_BY_CODE;

  /******************************************************************************
      Procedure:  COUNT_APPLICATIONS_BY_CRITERIA
      Purpose: Counts the applications using the where clause provided.
  ******************************************************************************/
  PROCEDURE COUNT_APPLICATIONS_BY_CRITERIA(P_WHERE_CLAUSE     IN VARCHAR,
                                           P_PARAMS_ARRAY     IN CBR_VARCHAR2_ARRAY,
                                           P_NUM_PARAMS       IN NUMBER,
                                           P_STRUCTURE_RETURN IN OUT ref_cur_general) IS
  BEGIN
    FIND_BY(GET_APP_COUNT_BASE_SELECT() || P_WHERE_CLAUSE || ')',
            P_PARAMS_ARRAY,
            P_NUM_PARAMS,
            P_STRUCTURE_RETURN);
  END COUNT_APPLICATIONS_BY_CRITERIA;

  /******************************************************************************
      Procedure:  FIND_APPLICATIONS_BY_CRITERIA
      Purpose: Find applications using the where clause provided.
  ******************************************************************************/
  PROCEDURE FIND_APPLICATIONS_BY_CRITERIA(P_WHERE_CLAUSE     IN VARCHAR,
                                          P_PARAMS_ARRAY     IN CBR_VARCHAR2_ARRAY,
                                          P_NUM_PARAMS       IN NUMBER,
                                          P_PAGE             IN NUMBER,
                                          P_STRUCTURE_RETURN IN OUT ref_cur_general) IS
  BEGIN
    FIND_BY(GET_OPEN_PAGINATION_SELECT() || GET_APPLICATION_BASE_SELECT() ||
            P_WHERE_CLAUSE  ||
            GET_CLOSE_PAGINATION_SELECT(P_PAGE),
            P_PARAMS_ARRAY,
            P_NUM_PARAMS,
            P_STRUCTURE_RETURN);
  END FIND_APPLICATIONS_BY_CRITERIA;

  FUNCTION GET_APP_COUNT_BASE_SELECT return VARCHAR2 IS
  BEGIN
    return 'SELECT COUNT(*) AS RESULTS_COUNT FROM (' || GET_APPLICATION_BASE_SELECT();
  END GET_APP_COUNT_BASE_SELECT;

  FUNCTION GET_CLOSE_PAGINATION_SELECT(P_PAGE IN NUMBER) return VARCHAR2 IS
    V_ROW_START NUMBER := (P_PAGE * PAGINATED_RESULTS_SIZE) + 1;
    V_ROW_END   NUMBER := V_ROW_START + PAGINATED_RESULTS_SIZE;
  BEGIN

    return ') a where rownum < ' || V_ROW_END || ') where rnum >= ' || V_ROW_START || ' ';
  END GET_CLOSE_PAGINATION_SELECT;

  FUNCTION GET_OPEN_PAGINATION_SELECT return VARCHAR2 IS
  BEGIN
    return 'select *  from (select a.*, ROWNUM rnum from (';
  END GET_OPEN_PAGINATION_SELECT;

  /******************************************************************************
      Procedure:  GET_APPLICATION_BASE_SELECT
      Purpose: to retrieve the base select of a structure as a string
  ******************************************************************************/
  FUNCTION GET_APPLICATION_BASE_SELECT return VARCHAR2 IS
  BEGIN
    return 'SELECT v.*, NULL AS APPROVAL_DATE FROM EXPORT_EXEMPTION_APP_VIEW v ' ;

  END GET_APPLICATION_BASE_SELECT;

