        using P_PARAMS_ARRAY(1), P_PARAMS_ARRAY(2), P_PARAMS_ARRAY(3), P_PARAMS_ARRAY(4), P_PARAMS_ARRAY(5), P_PARAMS_ARRAY(6), P_PARAMS_ARRAY(7), P_PARAMS_ARRAY(8), P_PARAMS_ARRAY(9), P_PARAMS_ARRAY(10), P_PARAMS_ARRAY(11), P_PARAMS_ARRAY(12), P_PARAMS_ARRAY(13), P_PARAMS_ARRAY(14), P_PARAMS_ARRAY(15), P_PARAMS_ARRAY(16), P_PARAMS_ARRAY(17), P_PARAMS_ARRAY(18), P_PARAMS_ARRAY(19), P_PARAMS_ARRAY(20), P_PARAMS_ARRAY(21), P_PARAMS_ARRAY(22), P_PARAMS_ARRAY(23), P_PARAMS_ARRAY(24), P_PARAMS_ARRAY(25), P_PARAMS_ARRAY(26), P_PARAMS_ARRAY(27), P_PARAMS_ARRAY(28), P_PARAMS_ARRAY(29), P_PARAMS_ARRAY(30), P_PARAMS_ARRAY(31), P_PARAMS_ARRAY(32), P_PARAMS_ARRAY(33);
    elsif P_NUM_PARAMS = 34 then
      OPEN P_RETURN FOR P_QUERY
        using P_PARAMS_ARRAY(1), P_PARAMS_ARRAY(2), P_PARAMS_ARRAY(3), P_PARAMS_ARRAY(4), P_PARAMS_ARRAY(5), P_PARAMS_ARRAY(6), P_PARAMS_ARRAY(7), P_PARAMS_ARRAY(8), P_PARAMS_ARRAY(9), P_PARAMS_ARRAY(10), P_PARAMS_ARRAY(11), P_PARAMS_ARRAY(12), P_PARAMS_ARRAY(13), P_PARAMS_ARRAY(14), P_PARAMS_ARRAY(15), P_PARAMS_ARRAY(16), P_PARAMS_ARRAY(17), P_PARAMS_ARRAY(18), P_PARAMS_ARRAY(19), P_PARAMS_ARRAY(20), P_PARAMS_ARRAY(21), P_PARAMS_ARRAY(22), P_PARAMS_ARRAY(23), P_PARAMS_ARRAY(24), P_PARAMS_ARRAY(25), P_PARAMS_ARRAY(26), P_PARAMS_ARRAY(27), P_PARAMS_ARRAY(28), P_PARAMS_ARRAY(29), P_PARAMS_ARRAY(30), P_PARAMS_ARRAY(31), P_PARAMS_ARRAY(32), P_PARAMS_ARRAY(33), P_PARAMS_ARRAY(34);
    elsif P_NUM_PARAMS = 35 then
      OPEN P_RETURN FOR P_QUERY
        using P_PARAMS_ARRAY(1), P_PARAMS_ARRAY(2), P_PARAMS_ARRAY(3), P_PARAMS_ARRAY(4), P_PARAMS_ARRAY(5), P_PARAMS_ARRAY(6), P_PARAMS_ARRAY(7), P_PARAMS_ARRAY(8), P_PARAMS_ARRAY(9), P_PARAMS_ARRAY(10), P_PARAMS_ARRAY(11), P_PARAMS_ARRAY(12), P_PARAMS_ARRAY(13), P_PARAMS_ARRAY(14), P_PARAMS_ARRAY(15), P_PARAMS_ARRAY(16), P_PARAMS_ARRAY(17), P_PARAMS_ARRAY(18), P_PARAMS_ARRAY(19), P_PARAMS_ARRAY(20), P_PARAMS_ARRAY(21), P_PARAMS_ARRAY(22), P_PARAMS_ARRAY(23), P_PARAMS_ARRAY(24), P_PARAMS_ARRAY(25), P_PARAMS_ARRAY(26), P_PARAMS_ARRAY(27), P_PARAMS_ARRAY(28), P_PARAMS_ARRAY(29), P_PARAMS_ARRAY(30), P_PARAMS_ARRAY(31), P_PARAMS_ARRAY(32), P_PARAMS_ARRAY(33), P_PARAMS_ARRAY(34), P_PARAMS_ARRAY(35);
    end if;

  EXCEPTION
    WHEN OTHERS THEN
      -- RAISE_APPLICATION_ERROR(SQLCODE, SQLCODE || SQLERRM);
      RAISE_APPLICATION_ERROR(-20999, 'Error executing dynamic query: ' || SQLERRM || ', QUERY: ' || P_QUERY, TRUE);
  END FIND_BY;

  /******************************************************************************
      Procedure:  FIND_ALL_EXPIRING_EXEMPTIONS
      Purpose: Find all exemptions.
  ******************************************************************************/
  PROCEDURE FIND_ALL_EXPIRING_EXEMPTIONS(P_EXEMPTIONS IN OUT ref_exemption) IS
    DATE_YESTERDAY EXPORT_EXEMPTION.EXPIRY_DATE%TYPE;

  BEGIN

    SELECT (TRUNC(CURRENT_DATE, 'DD') - 1) INTO DATE_YESTERDAY FROM DUAL;

    OPEN P_EXEMPTIONS FOR
      SELECT EE.EXEMPTION_NUMBER,
             EE.APPROVED_VOLUME,
             EE.APPROVAL_DATE,
             EE.EXPIRY_DATE,
             EE.OTHER_CONDITIONS,
             EE.ENTRY_USERID,
             EE.ENTRY_TIMESTAMP,
             EE.UPDATE_USERID,
             EE.UPDATE_TIMESTAMP,
             EE.EXPORT_EXEMPTION_TYPE_CODE,
             EE.EXPORT_EXEMPTION_STATUS_CODE,
             EESC.DESCRIPTION AS STATUS_DESCRIPTION,
             (EE.APPROVED_VOLUME -
             COALESCE(SUM(ESD.SPECIES_GRADE_VOLUME), 0)) AS VOLUME_REMAINING,
              ES.ADVERTISING_DATE,
              EO.ORG_UNIT_NAME,
              CASE WHEN EE.EXPORT_EXEMPTION_TYPE_CODE = 'M' THEN EEA.AGENT_CLIENT_NUMBER ELSE '' END AGENT_CLIENT_NUMBER,
              CASE WHEN EE.EXPORT_EXEMPTION_TYPE_CODE = 'M' THEN EEA.OWNER_CLIENT_NUMBER ELSE '' END OWNER_CLIENT_NUMBER
        FROM EXPORT_EXEMPTION EE
        LEFT JOIN EXPORT_EXEMPTION_APPLICATION EEA ON EE.EXEMPTION_NUMBER =
                                                      EEA.EXEMPTION_NUMBER
       INNER JOIN EXPORT_EXEMPTION_STATUS_CODE EESC ON EESC.EXPORT_EXEMPTION_STATUS_CODE =
                                                       EE.EXPORT_EXEMPTION_STATUS_CODE
        LEFT JOIN EXPORT_PACKAGE EP ON EP.APPLICATION_NUMBER =
                                       EEA.APPLICATION_NUMBER
        LEFT JOIN EXPORT_SCALE_DETAIL ESD ON ESD.PACKAGE_NUMBER =
                                             EP.PACKAGE_NUMBER
        LEFT JOIN EXPORT_SCHEDULE ES ON EEA.EXPORT_SCHEDULE_ID = ES.EXPORT_SCHEDULE_ID
        LEFT JOIN (
                SELECT EXEMPTION_NUMBER,  LISTAGG(ORG_UNIT_CODE, ', ') WITHIN GROUP (ORDER BY ORG_UNIT_CODE) OVER (PARTITION BY EXEMPTION_NUMBER) AS ORG_UNIT_NAME
                  FROM (
                    SELECT DISTINCT IOU.ORG_UNIT_CODE, IEEA.EXEMPTION_NUMBER
                    FROM EXPORT_EXEMPTION_APPLICATION IEEA
                    INNER JOIN ORG_UNIT IOU ON IOU.ORG_UNIT_NO = IEEA.ORG_UNIT_NO
                    UNION
                    SELECT DISTINCT OOU.ORG_UNIT_CODE, OEO.EXEMPTION_NUMBER
                    FROM OIC_EXEMPTION_ORG_UNIT OEO
                    INNER JOIN ORG_UNIT OOU ON OOU.ORG_UNIT_NO = OEO.ORG_UNIT_NO
                    )
                  ) EO ON EO.EXEMPTION_NUMBER = EE.EXEMPTION_NUMBER

       WHERE EE.EXPORT_EXEMPTION_STATUS_CODE = 'ACT'
         AND EE.EXPIRY_DATE <= DATE_YESTERDAY
       GROUP BY EE.EXEMPTION_NUMBER,
                EE.APPROVED_VOLUME,
                EE.APPROVAL_DATE,
                EE.EXPIRY_DATE,
                EE.OTHER_CONDITIONS,
                EE.ENTRY_USERID,
                EE.ENTRY_TIMESTAMP,
                EE.UPDATE_USERID,
                EE.UPDATE_TIMESTAMP,
                EE.EXPORT_EXEMPTION_TYPE_CODE,
                EE.EXPORT_EXEMPTION_STATUS_CODE,
                EESC.DESCRIPTION,
                ES.ADVERTISING_DATE,
                EO.ORG_UNIT_NAME,
                CASE WHEN EE.EXPORT_EXEMPTION_TYPE_CODE = 'M' THEN EEA.AGENT_CLIENT_NUMBER ELSE '' END,
                CASE WHEN EE.EXPORT_EXEMPTION_TYPE_CODE = 'M' THEN EEA.OWNER_CLIENT_NUMBER ELSE '' END;
  END FIND_ALL_EXPIRING_EXEMPTIONS;

  /******************************************************************************
      Procedure:  FIND_ALL_EXPIRING_PERMITS
      Purpose: Find all expired permits.
  ******************************************************************************/
  PROCEDURE FIND_ALL_EXPIRING_PERMITS(P_PERMITS IN OUT ref_permit_detail) IS
    DATE_YESTERDAY EXPORT_PERMIT_DETAIL.EXPIRY_DATE%TYPE;

  BEGIN

    SELECT (TRUNC(CURRENT_DATE, 'DD') - 1) INTO DATE_YESTERDAY FROM DUAL;

    OPEN P_PERMITS FOR
      SELECT DISTINCT EPD.ENTRY_TIMESTAMP,
                      EPD.UPDATE_USERID,
                      EPD.UPDATE_TIMESTAMP,
                      EPD.EXPORT_TRANSPORT_TYPE_CODE,
                      EPD.EXPORT_SCALE_METHOD_CODE,
                      EPD.CLIENT_LOCN_CODE,
                      EPD.CLIENT_NUMBER,
                      EPD.AGENT_LOCN_CODE,
                      EPD.AGENT_NUMBER,
                      EPD.ORG_UNIT_NO,
                      EPD.EXPORT_PORT_OF_EXPORT_CODE,
                      EPD.EXPORT_PERMIT_STATUS_CODE,
                      EPD.EXPORT_COUNTRY_CODE,
                      EPD.EXPORT_PERMIT_DETAIL_NUMBER,
                      EPD.DESTINATION_COMPANY_NAME,
                      EPD.TRANSPORT_NAME,
                      EPD.ESTIMATED_SHIPPING_DATE,
                      EPD.OTHER_PORT_OF_EXPORT,
                      EPD.APPLICATION_DATE,
                      EPD.RECEIVED_DATE,
                      EPD.EXPORT_PERMIT_ISSUE_DATE,
                      EPD.RECEIPT_NUMBER,
                      EPD.EXPIRY_DATE,
                      EPD.PERMIT_VOLUME,
                      EPD.NUMBER_OF_PIECES,
                      EPD.FEE_IN_LIEU_VOLUME,
                      EPD.FEDERAL_PERMIT_NUMBER,
                      EPD.REMARKS,
                      EPD.EXEMPTION_NUMBER,
                      EPD.ENTRY_USERID,
                      ESI.EXPORT_SALES_INVOICE_NUMBER,
                      ESI.Fee_In_Lieu,
                      EPD.EXPORT_GROWTH_TYPE_CODE,
                      EPSC.DESCRIPTION AS STATUS_DESCRIPTION,
                      EPD.OVERRIDE_FEE AS OVERRIDE_FEE,
                      EPD.OVERRIDE_COMMENT AS OVERRIDE_COMMENT,
                      OU.ORG_UNIT_NAME AS REGION,
                      EPD.OIC_APPLICATION_NUMBER,
                      EPD.OIC_REQUEST_PIECES,
                      EPD.OIC_REQUEST_VOLUME,
                      EPD.EXPORT_PRODUCT_TYPE_CODE
        FROM EXPORT_PERMIT_DETAIL EPD
        LEFT JOIN EXPORT_SALES_INVOICE ESI ON ESI.EXPORT_PERMIT_DETAIL_NUMBER =
                                              EPD.EXPORT_PERMIT_DETAIL_NUMBER
       INNER JOIN EXPORT_PERMIT_STATUS_CODE EPSC ON EPD.EXPORT_PERMIT_STATUS_CODE =
                                                    EPSC.EXPORT_PERMIT_STATUS_CODE
       INNER JOIN EXPORT_EXEMPTION_APPLICATION EEA on EPD.Exemption_Number = EEA.EXEMPTION_NUMBER
       INNER JOIN EXPORT_PACKAGE EP ON EP.APPLICATION_NUMBER = EEA.APPLICATION_NUMBER
       INNER JOIN EXPORT_SCALE_DETAIL ESD ON ESD.PACKAGE_NUMBER = EP.PACKAGE_NUMBER AND ESD.EXPORT_PERMIT_DETAIL_NUMBER = EPD.EXPORT_PERMIT_DETAIL_NUMBER
       LEFT JOIN ORG_UNIT OU ON OU.ORG_UNIT_NO = EPD.ORG_UNIT_NO
       WHERE EPD.EXPORT_PERMIT_STATUS_CODE <> 'EXP' AND EPD.EXPIRY_DATE <= DATE_YESTERDAY;
  END FIND_ALL_EXPIRING_PERMITS;
  /******************************************************************************
      Procedure:  FIND_EXEMPTION_BY_NUMBER
      Purpose: Find an exemption by number.
  ******************************************************************************/
  PROCEDURE FIND_EXEMPTION_BY_NUMBER(P_NUMBER     IN VARCHAR,
                                     P_EXEMPTIONS IN OUT ref_exemption) IS
  BEGIN
    OPEN P_EXEMPTIONS FOR
      SELECT EE.EXEMPTION_NUMBER,
             EE.APPROVED_VOLUME,
             EE.APPROVAL_DATE,
             EE.EXPIRY_DATE,
             EE.OTHER_CONDITIONS,
             EE.ENTRY_USERID,
             EE.ENTRY_TIMESTAMP,
             EE.UPDATE_USERID,
             EE.UPDATE_TIMESTAMP,
             EE.EXPORT_EXEMPTION_TYPE_CODE,
             EE.EXPORT_EXEMPTION_STATUS_CODE,
             EESC.DESCRIPTION AS STATUS_DESCRIPTION,
             (EE.APPROVED_VOLUME -
             COALESCE(SUM(ESD.SPECIES_GRADE_VOLUME), 0)) AS VOLUME_REMAINING,
              ES.ADVERTISING_DATE,
              EO.ORG_UNIT_NAME,
              CASE WHEN EE.EXPORT_EXEMPTION_TYPE_CODE = 'M' THEN EEA.AGENT_CLIENT_NUMBER ELSE '' END AS AGENT_CLIENT_NUMBER,
              CASE WHEN EE.EXPORT_EXEMPTION_TYPE_CODE = 'M' THEN EEA.OWNER_CLIENT_NUMBER ELSE '' END AS OWNER_CLIENT_NUMBER
        FROM EXPORT_EXEMPTION EE
        LEFT JOIN EXPORT_EXEMPTION_APPLICATION EEA ON EE.EXEMPTION_NUMBER =
                                                      EEA.EXEMPTION_NUMBER
       INNER JOIN EXPORT_EXEMPTION_STATUS_CODE EESC ON EESC.EXPORT_EXEMPTION_STATUS_CODE =
                                                       EE.EXPORT_EXEMPTION_STATUS_CODE
        LEFT JOIN EXPORT_PACKAGE EP ON EP.APPLICATION_NUMBER =
                                       EEA.APPLICATION_NUMBER
        LEFT JOIN EXPORT_SCALE_DETAIL ESD ON ESD.PACKAGE_NUMBER =
                                             EP.PACKAGE_NUMBER and esd.export_permit_detail_number is not null
        LEFT JOIN EXPORT_SCHEDULE ES ON EEA.EXPORT_SCHEDULE_ID = ES.EXPORT_SCHEDULE_ID
        LEFT JOIN OIC_EXEMPTION_ORG_UNIT OEO ON OEO.EXEMPTION_NUMBER = EE.EXEMPTION_NUMBER
        LEFT JOIN (
                SELECT EXEMPTION_NUMBER,  LISTAGG(ORG_UNIT_NO, ',') WITHIN GROUP (ORDER BY ORG_UNIT_NO) OVER (PARTITION BY EXEMPTION_NUMBER) AS ORG_UNIT_NAME
                  FROM (
                    SELECT DISTINCT IOU.ORG_UNIT_NO, IEEA.EXEMPTION_NUMBER
                    FROM EXPORT_EXEMPTION_APPLICATION IEEA
                    INNER JOIN ORG_UNIT IOU ON IOU.ORG_UNIT_NO = IEEA.ORG_UNIT_NO
                    UNION
                    SELECT DISTINCT OOU.ORG_UNIT_NO, OEO.EXEMPTION_NUMBER
                    FROM OIC_EXEMPTION_ORG_UNIT OEO
                    INNER JOIN ORG_UNIT OOU ON OOU.ORG_UNIT_NO = OEO.ORG_UNIT_NO
                    )
                  ) EO ON EO.EXEMPTION_NUMBER = EE.EXEMPTION_NUMBER
       WHERE EE.EXEMPTION_NUMBER = P_NUMBER
       GROUP BY EE.EXEMPTION_NUMBER,
                EE.APPROVED_VOLUME,
                EE.APPROVAL_DATE,
                EE.EXPIRY_DATE,
                EE.OTHER_CONDITIONS,
                EE.ENTRY_USERID,
                EE.ENTRY_TIMESTAMP,
                EE.UPDATE_USERID,
                EE.UPDATE_TIMESTAMP,
                EE.EXPORT_EXEMPTION_TYPE_CODE,
                EE.EXPORT_EXEMPTION_STATUS_CODE,
                EESC.DESCRIPTION,
                ES.ADVERTISING_DATE,
                EO.ORG_UNIT_NAME,
                CASE WHEN EE.EXPORT_EXEMPTION_TYPE_CODE = 'M' THEN EEA.AGENT_CLIENT_NUMBER ELSE '' END ,
                CASE WHEN EE.EXPORT_EXEMPTION_TYPE_CODE = 'M' THEN EEA.OWNER_CLIENT_NUMBER ELSE '' END ;
  END FIND_EXEMPTION_BY_NUMBER;

  /******************************************************************************
      Procedure:  FIND_EXEMPTIONS_BY_CRITERIA
      Purpose: Find applications using the where clause provided.
  ******************************************************************************/
  PROCEDURE FIND_EXEMPTIONS_BY_CRITERIA(P_WHERE_CLAUSE     IN VARCHAR,
                                        P_PARAMS_ARRAY     IN CBR_VARCHAR2_ARRAY,
                                        P_NUM_PARAMS       IN NUMBER,
                                        P_PAGE             IN NUMBER,
                                        P_STRUCTURE_RETURN IN OUT ref_cur_general) IS
  BEGIN

    FIND_BY(GET_OPEN_PAGINATION_SELECT() || GET_EXEMPTION_BASE_SELECT() ||
            P_WHERE_CLAUSE ||
            GET_CLOSE_PAGINATION_SELECT(P_PAGE),
            P_PARAMS_ARRAY,
            P_NUM_PARAMS,
            P_STRUCTURE_RETURN);
  END FIND_EXEMPTIONS_BY_CRITERIA;

  /******************************************************************************
      Procedure:  GET_EXEMPTION_BASE_SELECT
      Purpose: to retrieve the base select of a structure as a string
  ******************************************************************************/
  FUNCTION GET_EXEMPTION_BASE_SELECT return VARCHAR2 IS
  BEGIN
    return ' SELECT EE.EXEMPTION_NUMBER AS EXEMPTION_NUMBER, ' ||
            ' EE.APPROVED_VOLUME, ' ||
            ' EE.APPROVAL_DATE, ' ||
            ' EE.EXPIRY_DATE, ' ||
            ' EE.OTHER_CONDITIONS, ' ||
            ' EE.ENTRY_USERID, ' ||
            ' EE.ENTRY_TIMESTAMP, ' ||
            ' EE.UPDATE_USERID, ' ||
            ' EE.UPDATE_TIMESTAMP, ' ||
            ' EE.EXPORT_EXEMPTION_TYPE_CODE, ' ||
            ' EE.EXPORT_EXEMPTION_STATUS_CODE, ' ||
            ' EESC.DESCRIPTION AS STATUS_DESCRIPTION, ' ||
            ' (APPROVED_VOLUME - COALESCE(SUM(PERMIT_VOLUME), 0)) AS VOLUME_REMAINING,  ' ||
            ' CASE WHEN EE.EXPORT_EXEMPTION_TYPE_CODE != ''B'' AND EE.EXPORT_EXEMPTION_TYPE_CODE != ''O'' THEN es.advertising_date ELSE NULL END AS ADVERTISING_DATE,' ||
            ' EO.ORG_UNIT_NAME, ' ||
            ' CASE WHEN EE.EXPORT_EXEMPTION_TYPE_CODE != ''B'' AND EE.EXPORT_EXEMPTION_TYPE_CODE != ''O'' THEN (case when EEA.AGENT_CLIENT_NUMBER is null then '''' else EEA.AGENT_CLIENT_NUMBER end) ELSE '''' END AS AGENT_CLIENT_NUMBER,' ||
            ' CASE WHEN EE.EXPORT_EXEMPTION_TYPE_CODE != ''B'' AND EE.EXPORT_EXEMPTION_TYPE_CODE != ''O'' THEN (case when EEA.OWNER_CLIENT_NUMBER is null then '''' else EEA.OWNER_CLIENT_NUMBER end) ELSE '''' END AS OWNER_CLIENT_NUMBER' ||
            /*' CASE WHEN EE.EXPORT_EXEMPTION_TYPE_CODE = ''M'' OR EE.EXPORT_EXEMPTION_TYPE_CODE = ''O'' THEN EEA.AGENT_CLIENT_NUMBER ELSE ''NA'' END AS AGENT_CLIENT_NUMBER,' ||
            ' CASE WHEN EE.EXPORT_EXEMPTION_TYPE_CODE = ''M'' OR EE.EXPORT_EXEMPTION_TYPE_CODE = ''O'' THEN EEA.OWNER_CLIENT_NUMBER ELSE ''NA'' END AS OWNER_CLIENT_NUMBER' ||*/
              ' FROM EXPORT_EXEMPTION EE ' ||
            ' LEFT JOIN EXPORT_EXEMPTION_APPLICATION EEA ' ||
                   ' ON EE.EXEMPTION_NUMBER = EEA.EXEMPTION_NUMBER ' ||
            ' INNER JOIN EXPORT_EXEMPTION_STATUS_CODE EESC ' ||
                   ' ON EESC.EXPORT_EXEMPTION_STATUS_CODE = EE.EXPORT_EXEMPTION_STATUS_CODE ' ||
            ' LEFT JOIN EXPORT_PERMIT_DETAIL EPD ' ||
                   ' ON EPD.EXEMPTION_NUMBER = EE.EXEMPTION_NUMBER ' ||
            ' LEFT JOIN EXPORT_PACKAGE EP ' ||
                   ' ON EP.APPLICATION_NUMBER = EEA.APPLICATION_NUMBER ' ||
            ' LEFT JOIN EXPORT_SCHEDULE ES ' ||
                   ' ON EEA.EXPORT_SCHEDULE_ID = ES.EXPORT_SCHEDULE_ID ' ||
            ' LEFT JOIN ( ' ||
              ' SELECT EXEMPTION_NUMBER,  LISTAGG(ORG_UNIT_CODE, '', '') WITHIN GROUP (ORDER BY ORG_UNIT_CODE) OVER (PARTITION BY EXEMPTION_NUMBER) AS ORG_UNIT_NAME, ' ||
              ' LISTAGG(ORG_UNIT_NO, '', '') WITHIN GROUP (ORDER BY ORG_UNIT_NO) OVER (PARTITION BY EXEMPTION_NUMBER) AS ORG_UNIT_NO ' ||
              ' FROM (SELECT DISTINCT IOU.ORG_UNIT_CODE, IEEA.EXEMPTION_NUMBER, IOU.ORG_UNIT_NO ' ||
              ' FROM EXPORT_EXEMPTION_APPLICATION IEEA ' ||
              ' INNER JOIN ORG_UNIT IOU ON IOU.ORG_UNIT_NO = IEEA.ORG_UNIT_NO WHERE OIC_INDICATOR = ''N''' ||
              ' UNION ' ||
              ' SELECT DISTINCT OOU.ORG_UNIT_CODE, OEO.EXEMPTION_NUMBER, OOU.ORG_UNIT_NO  ' ||
              ' FROM OIC_EXEMPTION_ORG_UNIT OEO ' ||
              ' INNER JOIN ORG_UNIT OOU ON OOU.ORG_UNIT_NO = OEO.ORG_UNIT_NO  ' ||
            ' )) EO ON EO.EXEMPTION_NUMBER = EE.EXEMPTION_NUMBER ' ;

  END GET_EXEMPTION_BASE_SELECT;

  /******************************************************************************
      Procedure:  GET_EXEMPTION_BASE_GROUP_BY
      Purpose: to retrieve the base select of a structure as a string
  ******************************************************************************/
  FUNCTION GET_EXEMPTION_BASE_GROUP_BY return VARCHAR2 IS
  BEGIN
    return
      ' GROUP BY EE.EXEMPTION_NUMBER,'
   || 'EE.APPROVED_VOLUME,'
   || 'EE.APPROVAL_DATE,'
   || 'EE.EXPIRY_DATE,'
   || 'EE.OTHER_CONDITIONS,'
   || 'EE.ENTRY_USERID,'
   || 'EE.ENTRY_TIMESTAMP,'
   || 'EE.UPDATE_USERID,'
   || 'EE.UPDATE_TIMESTAMP,'
   || 'EE.EXPORT_EXEMPTION_TYPE_CODE,'
   || 'EE.EXPORT_EXEMPTION_STATUS_CODE,'
   || 'CASE'
   || ' WHEN EE.EXPORT_EXEMPTION_TYPE_CODE != ''B'' AND'
   || '     EE.EXPORT_EXEMPTION_TYPE_CODE != ''O'' THEN'
   || '     EEA.AGENT_CLIENT_NUMBER'
   || ' END,'
   || 'EO.ORG_UNIT_NAME,'
   || 'EESC.DESCRIPTION,'
   || 'CASE'
   || ' WHEN EE.EXPORT_EXEMPTION_TYPE_CODE != ''B'' AND EE.EXPORT_EXEMPTION_TYPE_CODE != ''O'' THEN'
   || '     ES.ADVERTISING_DATE'
   || ' ELSE'
   || '     NULL'
   || ' END,'
   || 'CASE'
   || ' WHEN EE.EXPORT_EXEMPTION_TYPE_CODE != ''B'' AND EE.EXPORT_EXEMPTION_TYPE_CODE != ''O'' THEN'
   || '     EEA.OWNER_CLIENT_NUMBER'
   || ' END,'
   || 'CASE'
   || ' WHEN EE.EXPORT_EXEMPTION_TYPE_CODE != ''B'' AND EE.EXPORT_EXEMPTION_TYPE_CODE != ''O'' THEN'
   || '     EEA.AGENT_CLIENT_NUMBER'
   || ' END,'
   || 'CASE'
   || ' WHEN EE.EXPORT_EXEMPTION_TYPE_CODE != ''B'' AND EE.EXPORT_EXEMPTION_TYPE_CODE != ''O'' THEN'
   || '     (case'
   || '      when EEA.AGENT_CLIENT_NUMBER is null then'
   || '           '''''
   || '      ELSE'
   || '           EEA.AGENT_CLIENT_NUMBER'
   || '      end)'
   || ' ELSE'
   || '      '''''
   || ' END,'
   || 'CASE'
   || '      WHEN EE.EXPORT_EXEMPTION_TYPE_CODE != ''B'' AND EE.EXPORT_EXEMPTION_TYPE_CODE != ''O'' THEN'
   || '      (case'
   || '      when EEA.OWNER_CLIENT_NUMBER is null then'
   || '           '''''
   || '      ELSE'
   || '           EEA.OWNER_CLIENT_NUMBER'
   || '      end)'
   || ' ELSE'
   || '      '''''
   || ' END';
  END GET_EXEMPTION_BASE_GROUP_BY;

  /******************************************************************************
      Procedure:  COUNT_EXEMPTIONS_BY_CRITERIA
      Purpose: Counts the applications using the where clause provided.
  ******************************************************************************/
  PROCEDURE COUNT_EXEMPTIONS_BY_CRITERIA(P_WHERE_CLAUSE     IN VARCHAR,
                                         P_PARAMS_ARRAY     IN CBR_VARCHAR2_ARRAY,
                                         P_NUM_PARAMS       IN NUMBER,
                                         P_STRUCTURE_RETURN IN OUT ref_cur_general) IS
  BEGIN

    FIND_BY(GET_EXEMPTION_COUNT_SELECT() || P_WHERE_CLAUSE || GET_EXEMPTION_COUNT_GROUP_BY,
            P_PARAMS_ARRAY,
            P_NUM_PARAMS,
            P_STRUCTURE_RETURN);
  END COUNT_EXEMPTIONS_BY_CRITERIA;

  /******************************************************************************
      Procedure:  GET_EXEMPTION_COUNT_SELECT
      Purpose: to retrieve the base select of a structure as a string
  ******************************************************************************/
  FUNCTION GET_EXEMPTION_COUNT_SELECT return VARCHAR2 IS
  BEGIN
    return 'SELECT COUNT(*) AS RESULTS_COUNT FROM (' || GET_EXEMPTION_BASE_SELECT();
  END GET_EXEMPTION_COUNT_SELECT;

  /******************************************************************************
      Procedure:  GET_EXEMPTION_COUNT_GROUP_BY
      Purpose: to retrieve the base select of a structure as a string
  ******************************************************************************/
  FUNCTION GET_EXEMPTION_COUNT_GROUP_BY return VARCHAR2 IS
  BEGIN
    return GET_EXEMPTION_BASE_GROUP_BY() || ')';
  END GET_EXEMPTION_COUNT_GROUP_BY;

  /******************************************************************************
      Procedure:  FIND_ALL_APPLICATIONS
      Purpose: Find all exemption applications.
  ******************************************************************************/
  PROCEDURE FIND_ALL_APPLICATIONS(P_APPLICATIONS IN OUT ref_application) IS
  BEGIN
    OPEN P_APPLICATIONS FOR
      SELECT DISTINCT EEA.APPLICATION_NUMBER,
                      EEA.FED_APPLICATION_NUMBER,
                      EEA.APPLICATION_DATE,
                      EEA.TERM_DAYS,
                      EEA.RECEIVED_DATE,
                      EEA.EXEMPTION_APPLICATION_VOLUME,
                      EEA.AVERAGE_LOG_VOLUME,
                      EEA.PRODUCT_LOCATION,
                      EEA.ENTRY_USERID,
                      EEA.ENTRY_TIMESTAMP,
                      EEA.UPDATE_USERID,
                      EEA.UPDATE_TIMESTAMP,
                      EEA.EXPORT_SCHEDULE_ID,
                      EEA.AGENT_CLIENT_NUMBER,
                      EEA.AGENT_CLIENT_LOCATION_CODE,
                      EEA.OWNER_CLIENT_NUMBER,
                      EEA.OWNER_CLIENT_LOCATION_CODE,
                      EEA.EXEMPTION_NUMBER,
                      EEA.EXPORT_EXEMPTION_REASON_CODE,
                      EEA.EXPORT_APPLICATION_STATUS_CODE,
                      EEA.EXPORT_APPLICANT_TYPE_CODE,
                      EEA.ORG_UNIT_NO,
                      EEA.EXPORT_PRODUCT_TYPE_CODE,
                      EEA.EXPORT_JURISDICTION_CODE,
                      EEA.EXPORT_GROWTH_TYPE_CODE,
                      EEA.AGENT_CONTACT_NAME,
                      EEA.OWNER_CONTACT_NAME,
                      ES.ADVERTISING_DATE,
                      EASC.DESCRIPTION AS STATUS_DESCRIPTION,
                      EERC.DESCRIPTION AS REASON_DESCRIPTION,
                      EE.EXPORT_EXEMPTION_TYPE_CODE,
                      EETC.DESCRIPTION AS TYPE_DESCRIPTION,
                      FCO.CLIENT_NAME AS OWNER_COMPANY_NAME,
                      AFCO.CLIENT_NAME AS AGENT_COMPNAY_NAME,
                      EATC.DESCRIPTION AS APPLICANT_DESCRIPTION,
                      OU.ORG_UNIT_NAME AS REGION,
                      OU.ORG_UNIT_CODE AS REGION_CODE,
                      NULL AS SHOW_INFO_ICON,
                      NULL AS APPROVAL_DATE,
                      EEA.OIC_INDICATOR

        FROM EXPORT_EXEMPTION_APPLICATION EEA
        LEFT JOIN EXPORT_EXEMPTION EE ON EE.EXEMPTION_NUMBER =
                                         EEA.EXEMPTION_NUMBER
        LEFT JOIN EXPORT_PACKAGE EP ON EP.APPLICATION_NUMBER =
                                       EEA.APPLICATION_NUMBER
       INNER JOIN EXPORT_SCHEDULE ES ON EEA.EXPORT_SCHEDULE_ID =
                                        ES.EXPORT_SCHEDULE_ID
       INNER JOIN EXPORT_APPLICATION_STATUS_CODE EASC ON EEA.EXPORT_APPLICATION_STATUS_CODE =
                                                         EASC.EXPORT_APPLICATION_STATUS_CODE
       INNER JOIN EXPORT_EXEMPTION_REASON_CODE EERC ON EEA.EXPORT_EXEMPTION_REASON_CODE =
                                                       EERC.EXPORT_EXEMPTION_REASON_CODE
       INNER JOIN EXPORT_APPLICANT_TYPE_CODE EATC ON EEA.EXPORT_APPLICANT_TYPE_CODE =
                                                     EATC.EXPORT_APPLICANT_TYPE_CODE
        LEFT JOIN EXPORT_EXEMPTION_TYPE_CODE EETC ON EE.EXPORT_EXEMPTION_TYPE_CODE =
                                                     EETC.EXPORT_EXEMPTION_TYPE_CODE
        LEFT JOIN FOREST_CLIENT FCO ON EEA.OWNER_CLIENT_NUMBER =
                                       FCO.CLIENT_NUMBER
        LEFT JOIN FOREST_CLIENT AFCO ON EEA.AGENT_CLIENT_NUMBER =
                                       AFCO.CLIENT_NUMBER
        LEFT JOIN ORG_UNIT OU ON OU.ORG_UNIT_NO = EEA.ORG_UNIT_NO;
  END FIND_ALL_APPLICATIONS;

  /******************************************************************************
      Procedure:  FIND_APPLICATION_BY_NUMBER
      Purpose: Find an application by number.
  ******************************************************************************/
  PROCEDURE FIND_APPLICATION_BY_NUMBER(P_NUMBER       IN EXPORT_EXEMPTION_APPLICATION.APPLICATION_NUMBER%TYPE,
                                       P_APPLICATIONS IN OUT ref_application) IS
  BEGIN
    OPEN P_APPLICATIONS FOR
      SELECT DISTINCT EEA.APPLICATION_NUMBER,
                      EEA.FED_APPLICATION_NUMBER,
                      EEA.APPLICATION_DATE,
                      EEA.TERM_DAYS,
                      EEA.RECEIVED_DATE,
                      EEA.EXEMPTION_APPLICATION_VOLUME,
                      EEA.AVERAGE_LOG_VOLUME,
                      EEA.PRODUCT_LOCATION,
                      EEA.ENTRY_USERID,
                      EEA.ENTRY_TIMESTAMP,
                      EEA.UPDATE_USERID,
                      EEA.UPDATE_TIMESTAMP,
                      EEA.EXPORT_SCHEDULE_ID,
                      EEA.AGENT_CLIENT_NUMBER,
                      EEA.AGENT_CLIENT_LOCATION_CODE,
                      EEA.OWNER_CLIENT_NUMBER,
                      EEA.OWNER_CLIENT_LOCATION_CODE,
                      EEA.EXEMPTION_NUMBER,
                      EEA.EXPORT_EXEMPTION_REASON_CODE,
                      EEA.EXPORT_APPLICATION_STATUS_CODE,
                      EEA.EXPORT_APPLICANT_TYPE_CODE,
                      EEA.ORG_UNIT_NO,
                      EEA.EXPORT_PRODUCT_TYPE_CODE,
                      EEA.EXPORT_JURISDICTION_CODE,
                      EEA.EXPORT_GROWTH_TYPE_CODE,
                      EEA.AGENT_CONTACT_NAME,
                      EEA.OWNER_CONTACT_NAME,
                      ES.ADVERTISING_DATE,
                      EASC.DESCRIPTION AS STATUS_DESCRIPTION,
                      EERC.DESCRIPTION AS REASON_DESCRIPTION,
                      EE.EXPORT_EXEMPTION_TYPE_CODE,
                      EETC.DESCRIPTION AS TYPE_DESCRIPTION,
                      FCO.CLIENT_NAME AS OWNER_COMPANY_NAME,
                      AFCO.CLIENT_NAME AS AGENT_COMPANY_NAME,
                      EATC.DESCRIPTION AS APPLICANT_DESCRIPTION,
                      OU.ORG_UNIT_NAME AS REGION,
                      OU.ORG_UNIT_CODE AS REGION_CODE,
                      NULL AS SHOW_INFO_ICON,
                      GET_APPLICATION_APPROVAL_DATE(EEA.APPLICATION_NUMBER) AS APPROVAL_DATE,
                      EEA.OIC_INDICATOR

        FROM EXPORT_EXEMPTION_APPLICATION EEA
        LEFT JOIN EXPORT_EXEMPTION EE ON EE.EXEMPTION_NUMBER =
                                         EEA.EXEMPTION_NUMBER
        LEFT JOIN EXPORT_PACKAGE EP ON EP.APPLICATION_NUMBER =
                                       EEA.APPLICATION_NUMBER
       LEFT JOIN EXPORT_SCHEDULE ES ON EEA.EXPORT_SCHEDULE_ID =
                                        ES.EXPORT_SCHEDULE_ID
       INNER JOIN EXPORT_APPLICATION_STATUS_CODE EASC ON EEA.EXPORT_APPLICATION_STATUS_CODE =
                                                         EASC.EXPORT_APPLICATION_STATUS_CODE
       INNER JOIN EXPORT_EXEMPTION_REASON_CODE EERC ON EEA.EXPORT_EXEMPTION_REASON_CODE =
                                                       EERC.EXPORT_EXEMPTION_REASON_CODE
       INNER JOIN EXPORT_APPLICANT_TYPE_CODE EATC ON EEA.EXPORT_APPLICANT_TYPE_CODE =
                                                     EATC.EXPORT_APPLICANT_TYPE_CODE
        LEFT JOIN EXPORT_EXEMPTION_TYPE_CODE EETC ON EE.EXPORT_EXEMPTION_TYPE_CODE =
                                                     EETC.EXPORT_EXEMPTION_TYPE_CODE
        LEFT JOIN FOREST_CLIENT FCO ON EEA.OWNER_CLIENT_NUMBER =
                                       FCO.CLIENT_NUMBER
        LEFT JOIN FOREST_CLIENT AFCO ON AFCO.CLIENT_NUMBER = EEA.AGENT_CLIENT_NUMBER
        LEFT JOIN ORG_UNIT OU ON OU.ORG_UNIT_NO = EEA.ORG_UNIT_NO
       WHERE EEA.APPLICATION_NUMBER = P_NUMBER;
  END FIND_APPLICATION_BY_NUMBER;

