        LEFT JOIN FOREST_CLIENT AFCO ON AFCO.CLIENT_NUMBER = EEA.AGENT_CLIENT_NUMBER
        LEFT JOIN ORG_UNIT OU ON OU.ORG_UNIT_NO = EEA.ORG_UNIT_NO
       WHERE EEA.EXEMPTION_NUMBER = P_NUMBER;
  END FIND_APPLICATION_BY_EXEMPTION;

