  /******************************************************************************
      Procedure:  FIND_PACKAGES_BY_OIC_PERMIT
      Purpose: Find all packages by OIC PERMIT NUMBER.
  ******************************************************************************/
  PROCEDURE FIND_PACKAGES_BY_OIC_PERMIT(P_OIC_PERMIT   IN EXPORT_PERMIT_DETAIL.EXPORT_PERMIT_DETAIL_NUMBER%TYPE,
                                 P_PACKAGES IN OUT ref_package) IS
  BEGIN
    OPEN P_PACKAGES FOR
      SELECT DISTINCT
              P.PACKAGE_NUMBER,
             P.PACKAGE_REPROCESSED_INDICATOR,
             P.PACKAGE_VOLUME,
             P.AVERAGE_LENGTH,
             P.AVERAGE_DIAMETER,
             P.COMMENTS,
             P.PACKAGE_FEE,
             P.ENTRY_USERID,
             P.ENTRY_TIMESTAMP,
             P.UPDATE_USERID,
             P.UPDATE_TIMESTAMP,
             P.APPLICATION_NUMBER,
             P.EXPORT_FED_PERMIT_DETAIL_ID,
             P.EXPORT_INDIAN_RSRV_PRMT_DTL_ID,
             P.EXPORT_PACKAGE_STATUS_CODE,
             P.EXPORT_GROWTH_TYPE_CODE,
             P.EXPORT_PRODUCT_TYPE_CODE
        FROM EXPORT_PACKAGE P
  LEFT JOIN EXPORT_EXEMPTION_APPLICATION EEA ON EEA.APPLICATION_NUMBER = P.APPLICATION_NUMBER
  LEFT JOIN EXPORT_PERMIT_DETAIL EPD ON EPD.OIC_APPLICATION_NUMBER = EEA.APPLICATION_NUMBER
  LEFT JOIN EXPORT_SCALE_DETAIL ESD ON ESD.PACKAGE_NUMBER = P.PACKAGE_NUMBER
       WHERE EPD.EXPORT_PERMIT_DETAIL_NUMBER = P_OIC_PERMIT OR ESD.EXPORT_PERMIT_DETAIL_NUMBER = P_OIC_PERMIT
    ORDER BY P.PACKAGE_NUMBER;
  END FIND_PACKAGES_BY_OIC_PERMIT;

