             P.EXPORT_GROWTH_TYPE_CODE,
             P.EXPORT_PRODUCT_TYPE_CODE
        FROM EXPORT_PACKAGE P INNER JOIN EXPORT_EXEMPTION_APPLICATION EEA ON P.APPLICATION_NUMBER = EEA.APPLICATION_NUMBER
