  /******************************************************************************
      Procedure:  INSERT_PACKAGE
      Purpose: Inserts a package into EXPORT_PACKAGE
  ******************************************************************************/
  PROCEDURE INSERT_PACKAGE(P_PACKAGE_NUMBER              IN EXPORT_PACKAGE.PACKAGE_NUMBER%TYPE,
                           P_APPLICATION_NUMBER          IN EXPORT_PACKAGE.Application_Number%TYPE,
                           P_REPROCESSED_IND             IN EXPORT_PACKAGE.Package_Reprocessed_Indicator%TYPE,
                           P_PACKAGE_VOLUME              IN EXPORT_PACKAGE.Package_Volume%TYPE,
                           P_AVERAGE_LENGTH              IN EXPORT_PACKAGE.Average_Length%TYPE,
                           P_AVERAGE_DIAMETER            IN EXPORT_PACKAGE.Average_Diameter%TYPE,
                           P_COMMENTS                    IN EXPORT_PACKAGE.Comments%TYPE,
                           P_FEE                         IN EXPORT_PACKAGE.Package_Fee%TYPE,
                           P_FED_PERMIT_NUMBER           IN EXPORT_PACKAGE.EXPORT_FED_PERMIT_DETAIL_ID%TYPE,
                           P_EXPORT_INDIAN_RSRV_PRMT_DTL in EXPORT_PACKAGE.EXPORT_INDIAN_RSRV_PRMT_DTL_ID%TYPE,
                           P_STATUS                      IN EXPORT_PACKAGE.Export_Package_Status_Code%TYPE,
                           P_EXPORT_GROWTH_TYPE_CODE     IN EXPORT_PACKAGE.EXPORT_GROWTH_TYPE_CODE%TYPE,
                           P_EXPORT_PRODUCT_TYPE_CODE    IN EXPORT_PACKAGE.EXPORT_PRODUCT_TYPE_CODE%TYPE,
                           P_ENTRY_USERID                IN EXPORT_PACKAGE.ENTRY_USERID%TYPE,
                           P_ENTRY_TIMESTAMP             IN EXPORT_PACKAGE.ENTRY_TIMESTAMP%TYPE,
                           P_UPDATE_USERID               IN EXPORT_PACKAGE.UPDATE_USERID%TYPE,
                           P_UPDATE_TIMESTAMP            IN EXPORT_PACKAGE.UPDATE_TIMESTAMP%TYPE,
                           R_PACKAGE                     IN OUT ref_package) IS

  BEGIN
    INSERT INTO EXPORT_PACKAGE
      (PACKAGE_NUMBER,
       APPLICATION_NUMBER,
       Package_Reprocessed_Indicator,
       Package_Volume,
       Average_Length,
       Average_Diameter,
       Comments,
       Package_Fee,
       EXPORT_FED_PERMIT_DETAIL_ID,
       EXPORT_INDIAN_RSRV_PRMT_DTL_ID,
       Export_Package_Status_Code,
       EXPORT_GROWTH_TYPE_CODE,
       EXPORT_PRODUCT_TYPE_CODE,
       ENTRY_USERID,
       ENTRY_TIMESTAMP,
       UPDATE_USERID,
       UPDATE_TIMESTAMP)
    VALUES
      (P_PACKAGE_NUMBER,
       P_APPLICATION_NUMBER,
       P_REPROCESSED_IND,
       P_PACKAGE_VOLUME,
       P_AVERAGE_LENGTH,
       P_AVERAGE_DIAMETER,
       P_COMMENTS,
       P_FEE,
       P_FED_PERMIT_NUMBER,
       P_EXPORT_INDIAN_RSRV_PRMT_DTL,
       P_STATUS,
       P_EXPORT_GROWTH_TYPE_CODE,
       P_EXPORT_PRODUCT_TYPE_CODE,
       P_ENTRY_USERID,
       P_ENTRY_TIMESTAMP,
       P_UPDATE_USERID,
       P_UPDATE_TIMESTAMP);

    FIND_PACKAGE_BY_NUMBER(P_PACKAGE_NUMBER, R_PACKAGE);

  END INSERT_PACKAGE;

PROCEDURE UPDATE_SCALE(P_EXPORT_SCALE_DETAIL_ID      IN EXPORT_SCALE_DETAIL.EXPORT_SCALE_DETAIL_ID%TYPE,
                       P_EXPORT_PERMIT_DETAIL_NUMBER IN EXPORT_SCALE_DETAIL.EXPORT_PERMIT_DETAIL_NUMBER%TYPE,
                       P_TIMBER_MARK                 IN EXPORT_SCALE_DETAIL.TIMBER_MARK%TYPE,
                       P_PIECES_COUNT                EXPORT_SCALE_DETAIL.PIECES_COUNT%TYPE,
                       P_SPECIES_GRADE_VOLUME        IN EXPORT_SCALE_DETAIL.SPECIES_GRADE_VOLUME%TYPE,
                       P_PACKAGE_NUMBER              IN EXPORT_SCALE_DETAIL.PACKAGE_NUMBER%TYPE,
                       P_EXPORT_SPECIES_CODE         IN EXPORT_SCALE_DETAIL.EXPORT_SPECIES_CODE%TYPE,
                       P_EXPORT_GRADE_CODE           IN EXPORT_SCALE_DETAIL.EXPORT_GRADE_CODE%TYPE,
                       P_ENTRY_USERID                IN EXPORT_SCALE_DETAIL.ENTRY_USERID%TYPE,
                       P_ENTRY_TIMESTAMP             IN EXPORT_SCALE_DETAIL.ENTRY_TIMESTAMP%TYPE,
                       P_UPDATE_USERID               IN EXPORT_SCALE_DETAIL.UPDATE_USERID%TYPE,
                       P_UPDATE_TIMESTAMP            IN EXPORT_SCALE_DETAIL.UPDATE_TIMESTAMP%TYPE) IS

                       V_PERMIT_AUDIT_ID Export_Scale_Detail_Audit.Export_Scale_Detail_Audit_Id%TYPE;
                       V_DO_FIL_REFRESH BOOLEAN;
                       V_PREVIOUS_TM    EXPORT_SCALE_DETAIL.TIMBER_MARK%TYPE;
                       V_PREVIOUS_SP    EXPORT_SCALE_DETAIL.EXPORT_SPECIES_CODE%TYPE;
                       V_PREVIOUS_GD    EXPORT_SCALE_DETAIL.EXPORT_GRADE_CODE%TYPE;
                       V_PREVIOUS_VOLUME EXPORT_SCALE_DETAIL.SPECIES_GRADE_VOLUME%TYPE;
                        V_PERMIT_NUMBER  EXPORT_SCALE_DETAIL.EXPORT_PERMIT_DETAIL_NUMBER%TYPE;
                       V_ORG_UNIT_NO    export_permit_detail.org_unit_no%TYPE;


BEGIN

   V_DO_FIL_REFRESH := FALSE;

   IF P_EXPORT_PERMIT_DETAIL_NUMBER IS NOT NULL THEN

     SELECT esd.timber_mark, esd.export_species_code, esd.export_grade_code, esd.species_grade_volume
     INTO V_PREVIOUS_TM, V_PREVIOUS_SP, V_PREVIOUS_GD, V_PREVIOUS_VOLUME
     FROM Export_Scale_Detail esd WHERE esd.export_scale_detail_id = P_EXPORT_SCALE_DETAIL_ID;
       SELECT epd.export_permit_detail_number, epd.org_unit_no INTO V_PERMIT_NUMBER, V_ORG_UNIT_NO FROM export_permit_detail epd  WHERE epd.export_permit_detail_number = P_EXPORT_PERMIT_DETAIL_NUMBER;
     --commented out this line because of lexis 724
     --IF V_PREVIOUS_TM != P_TIMBER_MARK OR V_PREVIOUS_SP != P_EXPORT_SPECIES_CODE OR V_PREVIOUS_GD != P_EXPORT_GRADE_CODE OR V_PREVIOUS_VOLUME != V_PREVIOUS_VOLUME THEN
      -- IF  (V_ORG_UNIT_NO = 1904  or V_ORG_UNIT_NO = 1905 or V_ORG_UNIT_NO = 1906 or V_ORG_UNIT_NO = 1903 or V_ORG_UNIT_NO = 1907) then
      -- V_DO_FIL_REFRESH := FALSE;
      -- elsif(V_ORG_UNIT_NO =1908 and P_EXPORT_GRADE_CODE in ('1','2','3','4','5','6')) then
      -- V_DO_FIL_REFRESH := FALSE;
      -- else
       V_DO_FIL_REFRESH := TRUE;
     --END IF;
   END IF;

  SELECT EXPORT_SCALE_DETAIL_SEQ.NEXTVAL
      INTO V_PERMIT_AUDIT_ID
      FROM DUAL;

  INSERT INTO Export_Scale_Detail_Audit
    (Export_Scale_Detail_Audit_Id,
     Export_Scale_Detail_Id,
     Timber_Mark,
     Pieces_Count,
     Species_Grade_Volume,
     Package_Number,
     Export_Species_Code,
     Export_Grade_Code,
     Entry_Userid,
     Entry_Timestamp,
     Update_Userid,
     Update_Timestamp,
     Delete_Userid,
     Delete_Timestamp,
     Export_Permit_Detail_Number,
     Average_Market_Price,
     Estimated_Winning_Bid,
     Fee_In_Lieu,
     Multiplication_Factor,
     Scale_Detail_Fee)
    SELECT V_PERMIT_AUDIT_ID,
            Export_Scale_Detail_Id,
            Timber_Mark,
            Pieces_Count,
            Species_Grade_Volume,
            Package_Number,
            Export_Species_Code,
            Export_Grade_Code,
            Entry_Userid,
            Entry_Timestamp,
            Update_Userid,
            Update_Timestamp,
            null,
            null,
            Export_Permit_Detail_Number,
            Average_Market_Price,
            Estimated_Winning_Bid,
            Fee_In_Lieu,
            Multiplication_Factor,
            Scale_Detail_Fee
       FROM Export_Scale_Detail esd
      WHERE esd.export_scale_detail_id = P_EXPORT_SCALE_DETAIL_ID;

  UPDATE Export_Scale_Detail esd
     SET esd.export_permit_detail_number = P_EXPORT_PERMIT_DETAIL_NUMBER,
         esd.timber_mark                 = P_TIMBER_MARK,
         esd.pieces_count                = P_PIECES_COUNT,
         esd.species_grade_volume        = P_SPECIES_GRADE_VOLUME,
         esd.package_number              = P_PACKAGE_NUMBER,
         esd.export_species_code         = P_EXPORT_SPECIES_CODE,
         esd.export_grade_code           = P_EXPORT_GRADE_CODE,
         esd.entry_userid                = P_ENTRY_USERID,
         esd.entry_timestamp             = P_ENTRY_TIMESTAMP,
         esd.update_userid               = P_UPDATE_USERID,
         esd.update_timestamp            = P_UPDATE_TIMESTAMP
   WHERE esd.export_scale_detail_id = P_EXPORT_SCALE_DETAIL_ID;

   IF V_DO_FIL_REFRESH THEN
      SET_FIL_CALULATED_VALUES(P_EXPORT_PERMIT_DETAIL_NUMBER);
   END IF;

END UPDATE_SCALE;


  /******************************************************************************
      Procedure:  UPDATE_PACKAGE
      Purpose: Inserts a package into EXPORT_PACKAGE
  ******************************************************************************/
  PROCEDURE UPDATE_PACKAGE(P_PACKAGE_NUMBER              IN EXPORT_PACKAGE.PACKAGE_NUMBER%TYPE,
                           P_APPLICATION_NUMBER          IN EXPORT_PACKAGE.APPLICATION_NUMBER%TYPE,
                           P_REPROCESSED_IND             IN EXPORT_PACKAGE.PACKAGE_REPROCESSED_INDICATOR%TYPE,
                           P_PACKAGE_VOLUME              IN EXPORT_PACKAGE.PACKAGE_VOLUME%TYPE,
                           P_AVERAGE_LENGTH              IN EXPORT_PACKAGE.AVERAGE_LENGTH%TYPE,
                           P_AVERAGE_DIAMETER            IN EXPORT_PACKAGE.AVERAGE_DIAMETER%TYPE,
                           P_COMMENTS                    IN EXPORT_PACKAGE.COMMENTS%TYPE,
                           P_FEE                         IN EXPORT_PACKAGE.PACKAGE_FEE%TYPE,
                           P_FED_PERMIT_NUMBER           IN EXPORT_PACKAGE.EXPORT_FED_PERMIT_DETAIL_ID%TYPE,
                           P_EXPORT_INDIAN_RSRV_PRMT_DTL IN EXPORT_PACKAGE.EXPORT_INDIAN_RSRV_PRMT_DTL_ID%TYPE,
                           P_STATUS                      IN EXPORT_PACKAGE.EXPORT_PACKAGE_STATUS_CODE%TYPE,
                           P_EXPORT_GROWTH_TYPE_CODE     IN EXPORT_PACKAGE.EXPORT_GROWTH_TYPE_CODE%TYPE,
                           P_EXPORT_PRODUCT_TYPE_CODE    IN EXPORT_PACKAGE.EXPORT_PRODUCT_TYPE_CODE%TYPE,
                           P_ENTRY_USERID                IN EXPORT_PACKAGE.ENTRY_USERID%TYPE,
                           P_ENTRY_TIMESTAMP             IN EXPORT_PACKAGE.ENTRY_TIMESTAMP%TYPE,
                           P_UPDATE_USERID               IN EXPORT_PACKAGE.UPDATE_USERID%TYPE,
                           P_UPDATE_TIMESTAMP            IN EXPORT_PACKAGE.UPDATE_TIMESTAMP%TYPE) IS

    V_PACKAGE_AUDIT_ID EXPORT_PACKAGE_AUDIT.EXPORT_PACKAGE_AUDIT_ID%TYPE;

  BEGIN

    -- copy original record into audit table
    SELECT EXPORT_PACKAGE_AUDIT_SEQ.NEXTVAL
      INTO V_PACKAGE_AUDIT_ID
      FROM DUAL;

    INSERT INTO EXPORT_PACKAGE_AUDIT
      (EXPORT_PACKAGE_AUDIT_ID,
       PACKAGE_NUMBER,
       APPLICATION_NUMBER,
       PACKAGE_REPROCESSED_INDICATOR,
       PACKAGE_VOLUME,
       AVERAGE_LENGTH,
       AVERAGE_DIAMETER,
       COMMENTS,
       PACKAGE_FEE,
       EXPORT_FED_PERMIT_DETAIL_ID,
       EXPORT_INDIAN_RSRV_PRMT_DTL_ID,
       EXPORT_PACKAGE_STATUS_CODE,
       EXPORT_GROWTH_TYPE_CODE,
       EXPORT_PRODUCT_TYPE_CODE,
       ENTRY_USERID,
       ENTRY_TIMESTAMP,
       UPDATE_USERID,
       UPDATE_TIMESTAMP,
       DELETE_USERID,
       DELETE_TIMESTAMP)
      SELECT V_PACKAGE_AUDIT_ID,
             EP.PACKAGE_NUMBER,
             EP.APPLICATION_NUMBER,
             EP.PACKAGE_REPROCESSED_INDICATOR,
             EP.PACKAGE_VOLUME,
             EP.AVERAGE_LENGTH,
             EP.AVERAGE_DIAMETER,
             EP.COMMENTS,
             EP.PACKAGE_FEE,
             EP.EXPORT_FED_PERMIT_DETAIL_ID,
             EP.EXPORT_INDIAN_RSRV_PRMT_DTL_ID,
             EP.EXPORT_PACKAGE_STATUS_CODE,
             EP.EXPORT_GROWTH_TYPE_CODE,
             EP.EXPORT_PRODUCT_TYPE_CODE,
             EP.ENTRY_USERID,
             EP.ENTRY_TIMESTAMP,
             EP.UPDATE_USERID,
             EP.UPDATE_TIMESTAMP,
             NULL,
             NULL
        FROM EXPORT_PACKAGE EP
       WHERE EP.PACKAGE_NUMBER = P_PACKAGE_NUMBER;

    -- update record
    UPDATE EXPORT_PACKAGE EP
       SET EP.PACKAGE_NUMBER                 = P_PACKAGE_NUMBER,
           EP.APPLICATION_NUMBER             = P_APPLICATION_NUMBER,
           EP.PACKAGE_REPROCESSED_INDICATOR  = P_REPROCESSED_IND,
           EP.PACKAGE_VOLUME                 = P_PACKAGE_VOLUME,
           EP.AVERAGE_LENGTH                 = P_AVERAGE_LENGTH,
           EP.AVERAGE_DIAMETER               = P_AVERAGE_DIAMETER,
           EP.COMMENTS                       = P_COMMENTS,
           EP.PACKAGE_FEE                    = P_FEE,
           EP.EXPORT_FED_PERMIT_DETAIL_ID    = P_FED_PERMIT_NUMBER,
           EP.EXPORT_INDIAN_RSRV_PRMT_DTL_ID = P_EXPORT_INDIAN_RSRV_PRMT_DTL,
           EP.EXPORT_PACKAGE_STATUS_CODE     = P_STATUS,
           EP.EXPORT_GROWTH_TYPE_CODE        = P_EXPORT_GROWTH_TYPE_CODE,
           EP.EXPORT_PRODUCT_TYPE_CODE       = P_EXPORT_PRODUCT_TYPE_CODE,
           EP.ENTRY_USERID                   = P_ENTRY_USERID,
           EP.ENTRY_TIMESTAMP                = P_ENTRY_TIMESTAMP,
           EP.UPDATE_USERID                  = P_UPDATE_USERID,
           EP.UPDATE_TIMESTAMP               = P_UPDATE_TIMESTAMP

     WHERE EP.PACKAGE_NUMBER = P_PACKAGE_NUMBER;

  END UPDATE_PACKAGE;

  /******************************************************************************
      Procedure:  FIND_ALL_SCHEDULES
      Purpose: Find all schedules within the application.
  ******************************************************************************/
  PROCEDURE FIND_ALL_SCHEDULES(P_SCHEDULES IN OUT ref_schedule) IS
  BEGIN
    OPEN P_SCHEDULES FOR
      SELECT S.EXPORT_SCHEDULE_ID,
             S.APPLICATION_RECEIPT_DATE,
             S.ADVERTISING_DATE,
             S.OFFER_RECEIPT_DATE,
             S.TEAC_MEETING_DATE,
             S.OFFER_END_DATE,
             S.OFFER_WITHDRAWAL_DATE
        FROM EXPORT_SCHEDULE S;
  END FIND_ALL_SCHEDULES;

  /******************************************************************************
      Procedure:  FIND_CURRENT_SCHEDULES
      Purpose: Find the current schedules as determined by the advertising date.
  ******************************************************************************/
  PROCEDURE FIND_CURRENT_SCHEDULES(P_SCHEDULES IN OUT ref_schedule) IS
  BEGIN
    OPEN P_SCHEDULES FOR
    SELECT *
    FROM (
      SELECT *
        FROM (SELECT ES.EXPORT_SCHEDULE_ID,
                     ES.APPLICATION_RECEIPT_DATE,
                     ES.ADVERTISING_DATE,
                     ES.OFFER_RECEIPT_DATE,
                     ES.TEAC_MEETING_DATE,
                     ES.OFFER_END_DATE,
                     ES.OFFER_WITHDRAWAL_DATE
                FROM EXPORT_SCHEDULE ES
               WHERE trunc(ES.Advertising_Date) <= TRUNC(SYSDATE)
               ORDER BY ES.ADVERTISING_DATE desc)
       WHERE ROWNUM <= 1
      UNION
      SELECT *
        FROM (SELECT ES.EXPORT_SCHEDULE_ID,
                     ES.APPLICATION_RECEIPT_DATE,
                     ES.ADVERTISING_DATE,
                     ES.OFFER_RECEIPT_DATE,
                     ES.TEAC_MEETING_DATE,
                     ES.OFFER_END_DATE,
                     ES.OFFER_WITHDRAWAL_DATE
                FROM EXPORT_SCHEDULE ES
               WHERE TRUNC(ES.Advertising_Date) > TRUNC(SYSDATE)
               ORDER BY ES.ADVERTISING_DATE)
       WHERE ROWNUM <= 1
       ) ORDER BY ADVERTISING_DATE ASC;
  END FIND_CURRENT_SCHEDULES;

  /******************************************************************************
      Procedure:  FIND_NEXT_SCHEDULES
      Purpose: Find the next two schedules as determined by the application reciept date.
  ******************************************************************************/
  PROCEDURE FIND_NEXT_SCHEDULES(P_SCHEDULES IN OUT ref_schedule) IS
  BEGIN
    OPEN P_SCHEDULES FOR
      SELECT *
        FROM (SELECT ES.EXPORT_SCHEDULE_ID,
                     ES.APPLICATION_RECEIPT_DATE,
                     ES.ADVERTISING_DATE,
                     ES.OFFER_RECEIPT_DATE,
                     ES.TEAC_MEETING_DATE,
                     ES.OFFER_END_DATE,
                     ES.OFFER_WITHDRAWAL_DATE
                FROM EXPORT_SCHEDULE ES
               WHERE ES.APPLICATION_RECEIPT_DATE > TRUNC(SYSDATE)
               ORDER BY ES.ADVERTISING_DATE)
       WHERE ROWNUM <= 2;
  END FIND_NEXT_SCHEDULES;

  /******************************************************************************
      Procedure:  FIND_SCHEDULE_BY_ID
      Purpose: Find a schedule by id.
  ******************************************************************************/
  PROCEDURE FIND_SCHEDULE_BY_ID(P_ID        IN EXPORT_SCHEDULE.Export_Schedule_Id%TYPE,
                                P_SCHEDULES IN OUT ref_schedule) IS
  BEGIN
    OPEN P_SCHEDULES FOR
      SELECT S.EXPORT_SCHEDULE_ID,
             S.APPLICATION_RECEIPT_DATE,
             S.ADVERTISING_DATE,
             S.OFFER_RECEIPT_DATE,
             S.TEAC_MEETING_DATE,
             S.OFFER_END_DATE,
