       WHERE S.EXPORT_SCHEDULE_ID = P_ID;
  END FIND_SCHEDULE_BY_ID;

  /******************************************************************************
      Procedure:  FIND_SCHEDULE_BY_APP
      Purpose: Find a schedule by application.
  ******************************************************************************/
  PROCEDURE FIND_SCHEDULE_BY_APP(P_APP_ID    IN EXPORT_EXEMPTION_APPLICATION.APPLICATION_NUMBER%TYPE,
                                 P_SCHEDULES IN OUT ref_schedule) IS
  BEGIN
    OPEN P_SCHEDULES FOR
      SELECT S.EXPORT_SCHEDULE_ID,
             S.APPLICATION_RECEIPT_DATE,
             S.ADVERTISING_DATE,
             S.OFFER_RECEIPT_DATE,
             S.TEAC_MEETING_DATE,
             S.OFFER_END_DATE,
             S.OFFER_WITHDRAWAL_DATE
        FROM EXPORT_SCHEDULE S
       INNER JOIN EXPORT_EXEMPTION_APPLICATION EEA ON EEA.EXPORT_SCHEDULE_ID =
                                                      S.EXPORT_SCHEDULE_ID
       WHERE EEA.APPLICATION_NUMBER = P_APP_ID;
  END FIND_SCHEDULE_BY_APP;

  /******************************************************************************
      Procedure:  FIND_SCHEDULE_BY_ADV_DATE
      Purpose: Find a schedule by id.
  ******************************************************************************/
  PROCEDURE FIND_SCHEDULE_BY_ADV_DATE(P_DATE      IN EXPORT_SCHEDULE.ADVERTISING_DATE%TYPE,
                                      P_SCHEDULES IN OUT ref_schedule) IS
    TARGET_DATE EXPORT_SCHEDULE.ADVERTISING_DATE%TYPE;

  BEGIN

    SELECT TRUNC(P_DATE, 'DD') INTO TARGET_DATE FROM DUAL;

    OPEN P_SCHEDULES FOR
      SELECT S.EXPORT_SCHEDULE_ID,
             S.APPLICATION_RECEIPT_DATE,
             S.ADVERTISING_DATE,
             S.OFFER_RECEIPT_DATE,
             S.TEAC_MEETING_DATE,
             S.OFFER_END_DATE,
             S.OFFER_WITHDRAWAL_DATE
        FROM EXPORT_SCHEDULE S
       WHERE S.ADVERTISING_DATE = TARGET_DATE;
  END FIND_SCHEDULE_BY_ADV_DATE;

  /******************************************************************************
      Procedure:  FIND_REMARK_BY_NUMBER
      Purpose: Find a REMARK by number.
