  /******************************************************************************
      Procedure:  FIND_PURCHASE_OFFERS_BY_NUM
      Purpose: Find a purchase offer by number.
  ******************************************************************************/
  PROCEDURE FIND_PURCHASE_OFFERS_BY_NUM(P_NUMBER IN EXPORT_PURCHASE_OFFER.EXPORT_PURCHASE_OFFER_NUMBER%TYPE,
                                        P_OFFER  IN OUT ref_purchase_offer) IS
  BEGIN
    OPEN P_OFFER FOR
      SELECT PO.EXPORT_PURCHASE_OFFER_NUMBER,
             PO.COMPANY_NAME,
             PO.CONTACT_NAME,
             PO.PURCHASE_OFFER_AMOUNT,
             PO.PURCHASE_OFFER_DATE,
             PO.OFFER_WITHDRAWAL_DATE,
             PO.TEAC_REVIEW_DATE,
             PO.FAIR_OFFER_INDICATOR,
             PO.VALID_OFFER_INDICATOR,
             PO.OFFER_REMARK,
             PO.APPROVAL_INDICATOR,
             PO.WITHDRAW_REASON,
             PO.MANUFACTURING_FACILITY_INFO,
             PO.ENTRY_USERID,
             PO.ENTRY_TIMESTAMP,
             PO.UPDATE_USERID,
             PO.UPDATE_TIMESTAMP,
             EEA.APPLICATION_NUMBER,
             PO.PACKAGE_NUMBER,
             PO.EXPORT_JURISDICTION_CODE,
             ES.ADVERTISING_DATE,
             PO.OFFERING_CLIENT_NUMBER,
             PO.PICKUP_LOCATION,
             OU.ORG_UNIT_CODE AS REGION,
             PO.OFFER_CONDITION,
             ES.OFFER_END_DATE,
             PO.EXPORT_PURCHASE_VOLUME
        FROM EXPORT_PURCHASE_OFFER PO
       INNER JOIN EXPORT_EXEMPTION_APPLICATION EEA ON EEA.APPLICATION_NUMBER =
                                                      PO.APPLICATION_NUMBER
       LEFT JOIN EXPORT_PACKAGE EP ON EP.PACKAGE_NUMBER =
                                       PO.PACKAGE_NUMBER
       LEFT JOIN EXPORT_SCHEDULE ES ON ES.EXPORT_SCHEDULE_ID =
                                        EEA.EXPORT_SCHEDULE_ID
       LEFT JOIN ORG_UNIT OU ON OU.ORG_UNIT_NO = EEA.ORG_UNIT_NO
       WHERE PO.EXPORT_PURCHASE_OFFER_NUMBER = P_NUMBER;
  END FIND_PURCHASE_OFFERS_BY_NUM;

