  /******************************************************************************
      Procedure:  FIND_POS_BY_CRITERIA
      Purpose: Find purchase offers using the where clause provided.
  ******************************************************************************/

  PROCEDURE FIND_POS_BY_CRITERIA(P_WHERE_CLAUSE     IN VARCHAR,
                                 P_PARAMS_ARRAY     IN CBR_VARCHAR2_ARRAY,
                                 P_NUM_PARAMS       IN NUMBER,
                                 P_PAGE             IN NUMBER,
                                 P_STRUCTURE_RETURN IN OUT ref_cur_general) IS
  BEGIN
    FIND_BY(GET_OPEN_PAGINATION_SELECT() || GET_PO_BASE_SELECT() ||
            P_WHERE_CLAUSE ||
            GET_CLOSE_PAGINATION_SELECT(P_PAGE),
            P_PARAMS_ARRAY,
            P_NUM_PARAMS,
            P_STRUCTURE_RETURN);
  END FIND_POS_BY_CRITERIA;

  /******************************************************************************
      Procedure:  GET_PO_BASE_SELECT
      Purpose: to retrieve the base select of a structure as a string
  ******************************************************************************/
  FUNCTION GET_PO_BASE_SELECT return VARCHAR2 IS
  BEGIN
    return
      'SELECT EEA.OWNER_CLIENT_NUMBER,' ||
      '       EEA.AGENT_CLIENT_NUMBER,' ||
      '       PO.EXPORT_PURCHASE_OFFER_NUMBER,' ||
      '       PO.COMPANY_NAME,' ||
      '       PO.CONTACT_NAME,' ||
      '       PO.PURCHASE_OFFER_AMOUNT,' ||
      '       PO.PURCHASE_OFFER_DATE,' ||
      '       PO.OFFER_WITHDRAWAL_DATE,' ||
      '       PO.TEAC_REVIEW_DATE,' ||
      '       PO.FAIR_OFFER_INDICATOR,' ||
      '       PO.VALID_OFFER_INDICATOR,' ||
      '       PO.OFFER_REMARK,' ||
      '       PO.APPROVAL_INDICATOR,' ||
      '       PO.WITHDRAW_REASON,' ||
      '       PO.MANUFACTURING_FACILITY_INFO,' ||
      '       PO.ENTRY_USERID,' ||
      '       PO.ENTRY_TIMESTAMP,' ||
      '       PO.UPDATE_USERID,' ||
      '       PO.UPDATE_TIMESTAMP,' ||
      '       EEA.APPLICATION_NUMBER,' ||
      '       PO.PACKAGE_NUMBER,' ||
      '       PO.EXPORT_JURISDICTION_CODE,' ||
      '       ES.ADVERTISING_DATE,' ||
      '       PO.OFFERING_CLIENT_NUMBER,' ||
      '       PO.PICKUP_LOCATION,' ||
      '       OU.ORG_UNIT_CODE AS REGION,' ||
      '       PO.OFFER_CONDITION,' ||
      '       ES.OFFER_END_DATE,' ||
      '       PO.EXPORT_PURCHASE_VOLUME' ||
      '  FROM EXPORT_PURCHASE_OFFER PO' ||
      ' INNER JOIN EXPORT_EXEMPTION_APPLICATION EEA' ||
      '    ON EEA.APPLICATION_NUMBER = PO.APPLICATION_NUMBER' ||
      ' LEFT JOIN EXPORT_PACKAGE EP' ||
      '    ON EP.PACKAGE_NUMBER = PO.PACKAGE_NUMBER' ||
      '  LEFT JOIN EXPORT_SCHEDULE ES' ||
      '    ON ES.EXPORT_SCHEDULE_ID = EEA.EXPORT_SCHEDULE_ID' ||
      '  LEFT JOIN ORG_UNIT OU' ||
      '    ON OU.ORG_UNIT_NO = EEA.ORG_UNIT_NO';
  END GET_PO_BASE_SELECT;

  /******************************************************************************
      Procedure:  COUNT_POS_BY_CRITERIA
      Purpose: Counts the applications using the where clause provided.
  ******************************************************************************/
  PROCEDURE COUNT_POS_BY_CRITERIA(P_WHERE_CLAUSE     IN VARCHAR,
                                  P_PARAMS_ARRAY     IN CBR_VARCHAR2_ARRAY,
                                  P_NUM_PARAMS       IN NUMBER,
                                  P_STRUCTURE_RETURN IN OUT ref_cur_general) IS
  BEGIN
    FIND_BY(GET_PO_COUNT_BASE_SELECT() || P_WHERE_CLAUSE || ')',
            P_PARAMS_ARRAY,
            P_NUM_PARAMS,
            P_STRUCTURE_RETURN);
  END COUNT_POS_BY_CRITERIA;

  FUNCTION GET_PO_COUNT_BASE_SELECT return VARCHAR2 IS
  BEGIN
    return 'SELECT COUNT(*) AS RESULTS_COUNT FROM (' || GET_PO_BASE_SELECT();
  END GET_PO_COUNT_BASE_SELECT;

  /******************************************************************************
      Procedure:  FIND_RATE_BY_EXEMPTION
      Purpose: Find a rate by exemption.
  ******************************************************************************/
  PROCEDURE FIND_RATE_BY_EXEMPTION(E_NUMBER IN VARCHAR,
                                   E_RATE   IN OUT ref_exemption_rate) IS
  BEGIN
    OPEN E_RATE FOR
      SELECT R.EXEMPTION_NUMBER,
             R.FIXED_EXEMPTION_RATE,
             R.UPDATE_USERID,
             R.UPDATE_TIMESTAMP,
             R.ENTRY_USERID,
             R.ENTRY_TIMESTAMP
        FROM EXPORT_EXEMPTION_RATE R
       WHERE R.EXEMPTION_NUMBER = E_NUMBER;
  END FIND_RATE_BY_EXEMPTION;

  /******************************************************************************
      Procedure:  FIND_SCALE_DETAIL_BY_ID
      Purpose: Find a scale detail by id.
  ******************************************************************************/
  PROCEDURE FIND_SCALE_DETAIL_BY_ID(P_SCALE_ID IN VARCHAR,
                                    R_SCALE    IN OUT ref_scale_detail) IS
  BEGIN
    OPEN R_SCALE FOR
      SELECT SD.EXPORT_SCALE_DETAIL_ID,
             SD.PIECES_COUNT,
             SD.SPECIES_GRADE_VOLUME,
             SD.ENTRY_USERID,
             SD.ENTRY_TIMESTAMP,
             SD.UPDATE_USERID,
             SD.UPDATE_TIMESTAMP,
             SD.TIMBER_MARK,
             SD.EXPORT_SPECIES_CODE,
             SD.EXPORT_GRADE_CODE,
             EP.APPLICATION_NUMBER,
             SD.PACKAGE_NUMBER,
             SD.EXPORT_PERMIT_DETAIL_NUMBER,
             HVA.CASCADE_SPLIT_CODE,
             SD.ESTIMATED_WINNING_BID as EWB,
             SD.FEE_IN_LIEU as FIL,
             SD.MULTIPLICATION_FACTOR as MF
        FROM EXPORT_SCALE_DETAIL SD
       INNER JOIN EXPORT_PACKAGE EP ON SD.Package_Number =
                                       EP.Package_Number
       LEFT JOIN HARVESTING_HAULING_XREF HHX ON HHX.TIMBER_MARK  = SD.TIMBER_MARK
       LEFT JOIN HARVESTING_AUTHORITY HVA ON HHX.HVA_SKEY = HVA.HVA_SKEY
       WHERE SD.EXPORT_SCALE_DETAIL_ID = P_SCALE_ID;
  END FIND_SCALE_DETAIL_BY_ID;

