                      OU.ORG_UNIT_NAME AS REGION,
                      EPD.OIC_APPLICATION_NUMBER,
                      EPD.OIC_REQUEST_PIECES,
                      EPD.OIC_REQUEST_VOLUME,
                      EPD.EXPORT_PRODUCT_TYPE_CODE
        FROM EXPORT_PERMIT_DETAIL EPD
        LEFT JOIN EXPORT_SALES_INVOICE ESI ON ESI.EXPORT_PERMIT_DETAIL_NUMBER =
                                              EPD.EXPORT_PERMIT_DETAIL_NUMBER
       INNER JOIN EXPORT_PERMIT_STATUS_CODE EPSC ON EPD.EXPORT_PERMIT_STATUS_CODE =
                                                    EPSC.EXPORT_PERMIT_STATUS_CODE
       INNER JOIN EXPORT_EXEMPTION_APPLICATION EEA on EPD.Exemption_Number = EEA.EXEMPTION_NUMBER
       LEFT JOIN EXPORT_PACKAGE EP ON EP.APPLICATION_NUMBER = EEA.APPLICATION_NUMBER
       LEFT JOIN EXPORT_SCALE_DETAIL ESD ON ESD.PACKAGE_NUMBER = EP.PACKAGE_NUMBER AND ESD.EXPORT_PERMIT_DETAIL_NUMBER = EPD.EXPORT_PERMIT_DETAIL_NUMBER
       LEFT JOIN ORG_UNIT OU ON OU.ORG_UNIT_NO = EPD.ORG_UNIT_NO
       WHERE EPD.OIC_APPLICATION_NUMBER = P_OIC_APP_ID;
  END FIND_PERMIT_DET_BY_OIC_APP;

  /******************************************************************************
      Procedure:  FIND_PERMIT_DET_BY_EXMP
      Purpose: Find export permit details by application.
  ******************************************************************************/
  PROCEDURE FIND_PERMIT_DET_BY_EXMP(P_EXEMPTION_ID IN EXPORT_PERMIT_DETAIL.EXEMPTION_NUMBER%TYPE,
                                    R_PERMIT       IN OUT ref_permit_detail) IS
  BEGIN
    OPEN R_PERMIT FOR
      SELECT DISTINCT EPD.ENTRY_TIMESTAMP,
                      EPD.UPDATE_USERID,
                      EPD.UPDATE_TIMESTAMP,
                      EPD.EXPORT_TRANSPORT_TYPE_CODE,
                      EPD.EXPORT_SCALE_METHOD_CODE,
                      EPD.CLIENT_LOCN_CODE,
                      EPD.CLIENT_NUMBER,
                      EPD.AGENT_LOCN_CODE,
                      EPD.AGENT_NUMBER,
                      EPD.ORG_UNIT_NO,
                      EPD.EXPORT_PORT_OF_EXPORT_CODE,
                      EPD.EXPORT_PERMIT_STATUS_CODE,
                      EPD.EXPORT_COUNTRY_CODE,
                      EPD.EXPORT_PERMIT_DETAIL_NUMBER,
                      EPD.DESTINATION_COMPANY_NAME,
                      EPD.TRANSPORT_NAME,
                      EPD.ESTIMATED_SHIPPING_DATE,
                      EPD.OTHER_PORT_OF_EXPORT,
                      EPD.APPLICATION_DATE,
                      EPD.RECEIVED_DATE,
                      EPD.EXPORT_PERMIT_ISSUE_DATE,
                      EPD.RECEIPT_NUMBER,
                      EPD.EXPIRY_DATE,
                      EPD.PERMIT_VOLUME,
                      EPD.NUMBER_OF_PIECES,
                      EPD.FEE_IN_LIEU_VOLUME,
                      EPD.FEDERAL_PERMIT_NUMBER,
                      EPD.REMARKS,
                      EPD.EXEMPTION_NUMBER,
                      EPD.ENTRY_USERID,
                      null as EXPORT_SALES_INVOICE_NUMBER,
                      null as FEE_IN_LIEU,
                      EPD.EXPORT_GROWTH_TYPE_CODE,
                      EPSC.DESCRIPTION AS STATUS_DESCRIPTION,
                      EPD.OVERRIDE_FEE,
                      EPD.OVERRIDE_COMMENT,
                      OU.ORG_UNIT_NAME AS REGION,
                      EPD.OIC_APPLICATION_NUMBER,
                      EPD.OIC_REQUEST_PIECES,
                      EPD.OIC_REQUEST_VOLUME,
                      EPD.EXPORT_PRODUCT_TYPE_CODE
        FROM EXPORT_PERMIT_DETAIL EPD
       INNER JOIN EXPORT_PERMIT_STATUS_CODE EPSC ON EPD.EXPORT_PERMIT_STATUS_CODE =
                                                    EPSC.EXPORT_PERMIT_STATUS_CODE
       LEFT JOIN ORG_UNIT OU ON OU.ORG_UNIT_NO = EPD.ORG_UNIT_NO
       WHERE EPD.EXEMPTION_NUMBER = P_EXEMPTION_ID;
  END FIND_PERMIT_DET_BY_EXMP;

  /******************************************************************************
      Procedure:  FIND_PERMIT_BY_CRITERIA
      Purpose: Find applications using the where clause provided.
  ******************************************************************************/

  PROCEDURE FIND_PERMIT_BY_CRITERIA(P_WHERE_CLAUSE     IN VARCHAR,
                                    P_PARAMS_ARRAY     IN CBR_VARCHAR2_ARRAY,
                                    P_NUM_PARAMS       IN NUMBER,
                                    P_PAGE             IN NUMBER,
                                    P_STRUCTURE_RETURN IN OUT ref_cur_general) IS
  BEGIN
    FIND_BY(GET_OPEN_PAGINATION_SELECT() || GET_PERMIT_BASE_SELECT() ||
            P_WHERE_CLAUSE ||
            GET_CLOSE_PAGINATION_SELECT(P_PAGE),
            P_PARAMS_ARRAY,
            P_NUM_PARAMS,
            P_STRUCTURE_RETURN);
  END FIND_PERMIT_BY_CRITERIA;

  /******************************************************************************
      Procedure:  GET_PERMIT_BASE_SELECT
      Purpose: to retrieve the base select of a structure as a string
  ******************************************************************************/
  FUNCTION GET_PERMIT_BASE_SELECT return VARCHAR2 IS
  BEGIN
    return 'SELECT DISTINCT EPD.ENTRY_TIMESTAMP,' ||
              ' EPD.UPDATE_USERID,' ||
              ' EPD.UPDATE_TIMESTAMP,' ||
              ' EPD.EXPORT_TRANSPORT_TYPE_CODE,' ||
              ' EPD.EXPORT_SCALE_METHOD_CODE,' ||
              ' EPD.CLIENT_LOCN_CODE,' ||
              ' (CASE WHEN EPD.CLIENT_NUMBER IS NULL THEN ' ||
              ' '''' ELSE EPD.CLIENT_NUMBER END) AS CLIENT_NUMBER,' ||
              ' EPD.AGENT_LOCN_CODE,' ||
              ' (CASE WHEN EPD.AGENT_NUMBER IS NULL THEN ' ||
              ' '''' ELSE EPD.AGENT_NUMBER END) AS AGENT_NUMBER,' ||
              ' EPD.ORG_UNIT_NO,' ||
              ' EPD.EXPORT_PORT_OF_EXPORT_CODE,' ||
              ' EPD.EXPORT_PERMIT_STATUS_CODE,' ||
              ' EPD.EXPORT_COUNTRY_CODE,' ||
              ' EPD.EXPORT_PERMIT_DETAIL_NUMBER,' ||
              ' EPD.DESTINATION_COMPANY_NAME,' ||
              ' EPD.TRANSPORT_NAME,' ||
              ' EPD.ESTIMATED_SHIPPING_DATE,' ||
              ' EPD.OTHER_PORT_OF_EXPORT,' ||
              ' EPD.APPLICATION_DATE,' ||
              ' EPD.RECEIVED_DATE,' ||
              ' EPD.EXPORT_PERMIT_ISSUE_DATE,' ||
              ' EPD.RECEIPT_NUMBER,' ||
              ' EPD.EXPIRY_DATE,' ||
              ' EPD.PERMIT_VOLUME,' ||
              ' EPD.NUMBER_OF_PIECES,' ||
              ' EPD.FEE_IN_LIEU_VOLUME,' ||
              ' EPD.FEDERAL_PERMIT_NUMBER,' ||
              ' EPD.REMARKS,' ||
              ' EPD.EXEMPTION_NUMBER,' ||
              ' EPD.ENTRY_USERID,' ||
              ' null AS EXPORT_SALES_INVOICE_NUMBER,' ||
              ' null AS FEE_IN_LIEU,' ||
              ' EPD.EXPORT_GROWTH_TYPE_CODE,' ||
              ' EPSC.DESCRIPTION AS STATUS_DESCRIPTION,' ||
              ' EPD.OVERRIDE_FEE AS OVERRIDE_FEE,' ||
              ' EPD.OVERRIDE_COMMENT,' ||
              ' OU.ORG_UNIT_CODE AS REGION,' ||
              ' EPD.OIC_APPLICATION_NUMBER,' ||
              ' EPD.OIC_REQUEST_PIECES,' ||
              ' EPD.OIC_REQUEST_VOLUME,' ||
              ' EPD.EXPORT_PRODUCT_TYPE_CODE' ||
        '  FROM EXPORT_PERMIT_DETAIL EPD' ||
        '  LEFT JOIN EXPORT_SALES_INVOICE ESI' ||
        '    ON ESI.EXPORT_PERMIT_DETAIL_NUMBER = EPD.EXPORT_PERMIT_DETAIL_NUMBER' ||
        ' LEFT JOIN EXPORT_EXEMPTION_APPLICATION EP' ||
        '    ON EP.EXEMPTION_NUMBER = EPD.EXEMPTION_NUMBER' ||
        ' INNER JOIN EXPORT_PERMIT_STATUS_CODE EPSC' ||
        '    ON EPD.EXPORT_PERMIT_STATUS_CODE = EPSC.EXPORT_PERMIT_STATUS_CODE' ||
        ' LEFT JOIN EXPORT_SCALE_DETAIL ESD' ||
        '    ON ESD.Export_Permit_Detail_Number = EPD.EXPORT_PERMIT_DETAIL_NUMBER' ||
        '  LEFT JOIN ORG_UNIT OU' ||
        '    ON OU.ORG_UNIT_NO = EPD.ORG_UNIT_NO';
  END GET_PERMIT_BASE_SELECT;

  /******************************************************************************
      Procedure:  COUNT_PERMIT_BY_CRITERIA
      Purpose: Counts the applications using the where clause provided.
  ******************************************************************************/
  PROCEDURE COUNT_PERMIT_BY_CRITERIA(P_WHERE_CLAUSE     IN VARCHAR,
                                     P_PARAMS_ARRAY     IN CBR_VARCHAR2_ARRAY,
                                     P_NUM_PARAMS       IN NUMBER,
                                     P_STRUCTURE_RETURN IN OUT ref_cur_general) IS
  BEGIN
    FIND_BY(GET_PERMIT_COUNT_BASE_SELECT() || P_WHERE_CLAUSE || ')',
            P_PARAMS_ARRAY,
            P_NUM_PARAMS,
            P_STRUCTURE_RETURN);
  END COUNT_PERMIT_BY_CRITERIA;

  FUNCTION GET_PERMIT_COUNT_BASE_SELECT return VARCHAR2 IS
  BEGIN
    return 'SELECT COUNT(*) AS RESULTS_COUNT FROM (' || GET_PERMIT_BASE_SELECT();
  END GET_PERMIT_COUNT_BASE_SELECT;

  /******************************************************************************
      Procedure:  FIND_FED_PERMIT_BY_CRITERIA
      Purpose: Find applications using the where clause provided.
  ******************************************************************************/

  PROCEDURE FIND_FED_PERMIT_BY_CRITERIA(P_WHERE_CLAUSE     IN VARCHAR,
                                        P_PARAMS_ARRAY     IN CBR_VARCHAR2_ARRAY,
                                        P_NUM_PARAMS       IN NUMBER,
                                        P_PAGE             IN NUMBER,
                                        P_STRUCTURE_RETURN IN OUT ref_cur_general) IS
  BEGIN
    FIND_BY(GET_OPEN_PAGINATION_SELECT() || GET_FED_PERMIT_BASE_SELECT() ||
            P_WHERE_CLAUSE || ' ORDER BY EFPD.APPLICATION_DATE DESC ' ||
            GET_CLOSE_PAGINATION_SELECT(P_PAGE),
            P_PARAMS_ARRAY,
            P_NUM_PARAMS,
            P_STRUCTURE_RETURN);
  END FIND_FED_PERMIT_BY_CRITERIA;

