  /******************************************************************************
      Procedure:  FIND_INVOICE_BY_ID
      Purpose: Find a sales invoice by id.
  ******************************************************************************/
  PROCEDURE FIND_INVOICE_BY_ID(P_INVOICE_ID IN EXPORT_SALES_INVOICE.EXPORT_SALES_INVOICE_NUMBER%TYPE,
                               P_PERMIT_ID  IN EXPORT_SALES_INVOICE.EXPORT_PERMIT_DETAIL_NUMBER%TYPE,
                               R_INVOICE    IN OUT ref_sales_invoice) IS
  BEGIN
    OPEN R_INVOICE FOR
      SELECT ESI.EXPORT_SALES_INVOICE_NUMBER,
             ESI.EXPORT_VALUE,
             ESI.CURRENCY_CONVERSION_RATE,
             ESI.FEE_IN_LIEU,
             ESI.ENTRY_USERID,
             ESI.ENTRY_TIMESTAMP,
             ESI.UPDATE_USERID,
             ESI.UPDATE_TIMESTAMP,
             ESI.EXPORT_PERMIT_DETAIL_NUMBER
        FROM EXPORT_SALES_INVOICE ESI
       WHERE ESI.EXPORT_SALES_INVOICE_NUMBER = P_INVOICE_ID
         AND ESI.EXPORT_PERMIT_DETAIL_NUMBER = P_PERMIT_ID;
  END FIND_INVOICE_BY_ID;

  /******************************************************************************
      Procedure:  FIND_INVOICES_BY_PERMIT
      Purpose: Find all sales invoices by permit.
  ******************************************************************************/
  PROCEDURE FIND_INVOICES_BY_PERMIT(P_PERMIT_ID IN EXPORT_SALES_INVOICE.EXPORT_PERMIT_DETAIL_NUMBER%TYPE,
                                    R_INVOICE   IN OUT ref_sales_invoice) IS
  BEGIN
    OPEN R_INVOICE FOR
      SELECT ESI.EXPORT_SALES_INVOICE_NUMBER,
             ESI.EXPORT_VALUE,
             ESI.CURRENCY_CONVERSION_RATE,
             ESI.FEE_IN_LIEU,
