       WHERE ESI.EXPORT_PERMIT_DETAIL_NUMBER = P_PERMIT_ID;
  END FIND_INVOICES_BY_PERMIT;

  /******************************************************************************
      Procedure:  FIND_LOG_AMVS_BY_DATE
      Purpose: Find all log amvs for a given date. The given date is truncated to the
          first of the month.
  ******************************************************************************/
  PROCEDURE FIND_LOG_AMVS_BY_DATE(P_DATE    IN DATE,
                                  R_LOG_AMV IN OUT ref_log_amv) IS
    TARGET_DATE EXPORT_LOG_AMV.EFFECTIVE_DATE%TYPE;

  BEGIN

    SELECT TRUNC(P_DATE, 'MONTH') INTO TARGET_DATE FROM DUAL;

    OPEN R_LOG_AMV FOR
      SELECT ELA.EFFECTIVE_DATE,
             ELA.AVERAGE_MARKET_PRICE,
             ELA.REVISION_COUNT,
             ELA.EXPORT_GRADE_CODE,
             ELA.EXPORT_SPECIES_CODE,
             ELA.EXPORT_GROWTH_TYPE_CODE
        FROM EXPORT_LOG_AMV ELA
       WHERE ELA.EFFECTIVE_DATE = TARGET_DATE;
  END FIND_LOG_AMVS_BY_DATE;

  /******************************************************************************
      Procedure:  FIND_LOG_AMV
      Purpose: Find a specific log amv. The given date is truncated to the
          first of the month.
  ******************************************************************************/
  PROCEDURE FIND_LOG_AMV(P_DATE    IN DATE,
                         P_SPECIES IN VARCHAR,
                         P_GRADE   IN VARCHAR,
                         P_GROWTH  IN VARCHAR,
                         R_LOG_AMV IN OUT ref_log_amv) IS
    V_GRADE     EXPORT_LOG_AMV.EXPORT_GRADE_CODE%TYPE;
    TARGET_DATE EXPORT_LOG_AMV.EFFECTIVE_DATE%TYPE;

  BEGIN

    SELECT TRUNC(P_DATE, 'MONTH') INTO TARGET_DATE FROM DUAL;

    IF P_GRADE = '' OR P_GRADE IS NULL THEN
      V_GRADE := ' ';
    ELSE
      V_GRADE := P_GRADE;
    END IF;

    OPEN R_LOG_AMV FOR
      SELECT ELA.EFFECTIVE_DATE,
             ELA.AVERAGE_MARKET_PRICE,
             ELA.REVISION_COUNT,
             ELA.EXPORT_GRADE_CODE,
             ELA.EXPORT_SPECIES_CODE,
             ELA.EXPORT_GROWTH_TYPE_CODE
        FROM EXPORT_LOG_AMV ELA
       WHERE (SELECT MAX(ELA.EFFECTIVE_DATE)
                FROM EXPORT_LOG_AMV ELA
               WHERE ELA.EFFECTIVE_DATE <= P_DATE
                 AND ELA.EXPORT_SPECIES_CODE = P_SPECIES
                 AND ELA.EXPORT_GRADE_CODE = V_GRADE) = ELA.EFFECTIVE_DATE
         AND NOT ELA.EFFECTIVE_DATE > TARGET_DATE
         AND ELA.EXPORT_SPECIES_CODE = P_SPECIES
         AND ELA.EXPORT_GRADE_CODE = V_GRADE
         AND ELA.EXPORT_GROWTH_TYPE_CODE = P_GROWTH;
  END FIND_LOG_AMV;

    /******************************************************************************
      Procedure:  FIND_LOG_AMV
      Purpose: Find a specific log amv. The given date is truncated to the
          first of the month.
  ******************************************************************************/
  PROCEDURE FIND_LOG_AMV(P_SCALE_ID IN EXPORT_SCALE_DETAIL.EXPORT_SCALE_DETAIL_ID%TYPE,
                         R_LOG_AMV IN OUT ref_log_amv) IS
    V_GRADE     EXPORT_LOG_AMV.EXPORT_GRADE_CODE%TYPE;
    V_SPECIES EXPORT_LOG_AMV.EXPORT_SPECIES_CODE%TYPE;
    TARGET_DATE EXPORT_LOG_AMV.EFFECTIVE_DATE%TYPE;

    V_PERMIT_NUMBER EXPORT_PERMIT_DETAIL.EXPORT_PERMIT_DETAIL_NUMBER%TYPE;
    V_PACKAGE_NUMBER EXPORT_PACKAGE.PACKAGE_NUMBER%TYPE;
    V_PERMIT_APP_DATE EXPORT_PERMIT_DETAIL.APPLICATION_DATE%TYPE;
    V_APP_NUMBER EXPORT_EXEMPTION_APPLICATION.APPLICATION_NUMBER%TYPE;
    V_GROWTH EXPORT_LOG_AMV.EXPORT_GROWTH_TYPE_CODE%TYPE;

  BEGIN

    SELECT ESD.EXPORT_PERMIT_DETAIL_NUMBER INTO V_PERMIT_NUMBER FROM EXPORT_SCALE_DETAIL ESD WHERE ESD.EXPORT_SCALE_DETAIL_ID = P_SCALE_ID;
    SELECT ESD.EXPORT_SPECIES_CODE INTO V_SPECIES FROM EXPORT_SCALE_DETAIL ESD WHERE ESD.EXPORT_SCALE_DETAIL_ID = P_SCALE_ID;
    SELECT ESD.EXPORT_GRADE_CODE INTO V_GRADE FROM EXPORT_SCALE_DETAIL ESD WHERE ESD.EXPORT_SCALE_DETAIL_ID = P_SCALE_ID;
    SELECT EPD.APPLICATION_DATE INTO V_PERMIT_APP_DATE FROM EXPORT_PERMIT_DETAIL EPD WHERE EPD.EXPORT_PERMIT_DETAIL_NUMBER = V_PERMIT_NUMBER;
    SELECT ESD.PACKAGE_NUMBER INTO V_PACKAGE_NUMBER FROM EXPORT_SCALE_DETAIL ESD WHERE ESD.EXPORT_SCALE_DETAIL_ID = P_SCALE_ID;
    SELECT EP.APPLICATION_NUMBER INTO V_APP_NUMBER FROM EXPORT_PACKAGE EP WHERE EP.PACKAGE_NUMBER = V_PACKAGE_NUMBER;
    SELECT TRUNC(V_PERMIT_APP_DATE, 'MONTH') INTO TARGET_DATE FROM DUAL;

    IF V_APP_NUMBER = '' OR V_APP_NUMBER IS NULL THEN
      SELECT EPD.EXPORT_GROWTH_TYPE_CODE INTO V_GROWTH FROM EXPORT_PERMIT_DETAIL EPD WHERE EPD.EXPORT_PERMIT_DETAIL_NUMBER = V_PERMIT_NUMBER;
    ELSE
      SELECT EEA.EXPORT_GROWTH_TYPE_CODE INTO V_GROWTH FROM EXPORT_EXEMPTION_APPLICATION EEA WHERE EEA.APPLICATION_NUMBER = V_APP_NUMBER;
    END IF;

    IF V_GRADE = '' OR V_GRADE IS NULL THEN
      V_GRADE := ' ';
    END IF;

    OPEN R_LOG_AMV FOR
      SELECT ELA.EFFECTIVE_DATE,
             ELA.AVERAGE_MARKET_PRICE,
             ELA.REVISION_COUNT,
             ELA.EXPORT_GRADE_CODE,
             ELA.EXPORT_SPECIES_CODE,
             ELA.EXPORT_GROWTH_TYPE_CODE
        FROM EXPORT_LOG_AMV ELA
       WHERE (SELECT MAX(ELA.EFFECTIVE_DATE)
                FROM EXPORT_LOG_AMV ELA
               WHERE ELA.EFFECTIVE_DATE <= V_PERMIT_APP_DATE
                 AND ELA.EXPORT_SPECIES_CODE = V_SPECIES
                 AND ELA.EXPORT_GRADE_CODE = V_GRADE) = ELA.EFFECTIVE_DATE
         AND NOT ELA.EFFECTIVE_DATE > TARGET_DATE
         AND ELA.EXPORT_SPECIES_CODE = V_SPECIES
         AND ELA.EXPORT_GRADE_CODE = V_GRADE
         AND ELA.EXPORT_GROWTH_TYPE_CODE = V_GROWTH;
  END FIND_LOG_AMV;

      /******************************************************************************
      Procedure:  FIND_LOG_AMV
      Purpose: Find a specific log amv. The given date is truncated to the
          first of the month.
  ******************************************************************************/
  FUNCTION TEMP_FIND_LOG_AMV(P_SCALE_ID IN EXPORT_SCALE_DETAIL.EXPORT_SCALE_DETAIL_ID%TYPE) RETURN NUMBER IS
    V_GRADE     EXPORT_LOG_AMV.EXPORT_GRADE_CODE%TYPE;
    V_SPECIES EXPORT_LOG_AMV.EXPORT_SPECIES_CODE%TYPE;
    TARGET_DATE EXPORT_LOG_AMV.EFFECTIVE_DATE%TYPE;

    V_PERMIT_NUMBER EXPORT_PERMIT_DETAIL.EXPORT_PERMIT_DETAIL_NUMBER%TYPE;
    V_PACKAGE_NUMBER EXPORT_PACKAGE.PACKAGE_NUMBER%TYPE;
    V_PERMIT_APP_DATE EXPORT_PERMIT_DETAIL.APPLICATION_DATE%TYPE;
    V_APP_NUMBER EXPORT_EXEMPTION_APPLICATION.APPLICATION_NUMBER%TYPE;
    V_GROWTH EXPORT_LOG_AMV.EXPORT_GROWTH_TYPE_CODE%TYPE;
  R_LOG_AMV ref_log_amv;
  BEGIN

    SELECT ESD.EXPORT_PERMIT_DETAIL_NUMBER INTO V_PERMIT_NUMBER FROM EXPORT_SCALE_DETAIL ESD WHERE ESD.EXPORT_SCALE_DETAIL_ID = P_SCALE_ID;
    SELECT ESD.EXPORT_SPECIES_CODE INTO V_SPECIES FROM EXPORT_SCALE_DETAIL ESD WHERE ESD.EXPORT_SCALE_DETAIL_ID = P_SCALE_ID;
    SELECT ESD.EXPORT_GRADE_CODE INTO V_GRADE FROM EXPORT_SCALE_DETAIL ESD WHERE ESD.EXPORT_SCALE_DETAIL_ID = P_SCALE_ID;
    SELECT EPD.APPLICATION_DATE INTO V_PERMIT_APP_DATE FROM EXPORT_PERMIT_DETAIL EPD WHERE EPD.EXPORT_PERMIT_DETAIL_NUMBER = V_PERMIT_NUMBER;
    SELECT ESD.PACKAGE_NUMBER INTO V_PACKAGE_NUMBER FROM EXPORT_SCALE_DETAIL ESD WHERE ESD.EXPORT_SCALE_DETAIL_ID = P_SCALE_ID;
    SELECT EP.APPLICATION_NUMBER INTO V_APP_NUMBER FROM EXPORT_PACKAGE EP WHERE EP.PACKAGE_NUMBER = V_PACKAGE_NUMBER;
    SELECT TRUNC(V_PERMIT_APP_DATE, 'MONTH') INTO TARGET_DATE FROM DUAL;

    IF V_APP_NUMBER = '' OR V_APP_NUMBER IS NULL THEN
      SELECT EPD.EXPORT_GROWTH_TYPE_CODE INTO V_GROWTH FROM EXPORT_PERMIT_DETAIL EPD WHERE EPD.EXPORT_PERMIT_DETAIL_NUMBER = V_PERMIT_NUMBER;
    ELSE
      SELECT EEA.EXPORT_GROWTH_TYPE_CODE INTO V_GROWTH FROM EXPORT_EXEMPTION_APPLICATION EEA WHERE EEA.APPLICATION_NUMBER = V_APP_NUMBER;
    END IF;

    IF V_GRADE = '' OR V_GRADE IS NULL THEN
      V_GRADE := ' ';
    END IF;

    OPEN R_LOG_AMV FOR
      SELECT ELA.EFFECTIVE_DATE,
             ELA.AVERAGE_MARKET_PRICE,
             ELA.REVISION_COUNT,
             ELA.EXPORT_GRADE_CODE,
             ELA.EXPORT_SPECIES_CODE,
             ELA.EXPORT_GROWTH_TYPE_CODE
        FROM EXPORT_LOG_AMV ELA
       WHERE (SELECT MAX(ELA.EFFECTIVE_DATE)
                FROM EXPORT_LOG_AMV ELA
               WHERE ELA.EFFECTIVE_DATE <= V_PERMIT_APP_DATE
                 AND ELA.EXPORT_SPECIES_CODE = V_SPECIES
                 AND ELA.EXPORT_GRADE_CODE = V_GRADE) = ELA.EFFECTIVE_DATE
         AND NOT ELA.EFFECTIVE_DATE > TARGET_DATE
         AND ELA.EXPORT_SPECIES_CODE = V_SPECIES
         AND ELA.EXPORT_GRADE_CODE = V_GRADE
         AND ELA.EXPORT_GROWTH_TYPE_CODE = V_GROWTH;
         if r_log_amv is null then
            return P_SCALE_ID;
         else return 0;
         end if;

        EXCEPTION WHEN OTHERS THEN RETURN P_SCALE_ID;

  END TEMP_FIND_LOG_AMV;

  /******************************************************************************
      Procedure:  FIND_ALL_TIMBER_MARKS
      Purpose: Find all the timber marks.
  ******************************************************************************/
  PROCEDURE FIND_ALL_TIMBER_MARKS(R_MARKS IN OUT ref_timber_mark) IS
  BEGIN
    OPEN R_MARKS FOR
      SELECT HA.TIMBER_MARK,
             HARA.HARVEST_AUTH_STATUS_CODE AS MARK_STATUS_ST,
             HA.FOREST_FILE_ID,
             PFU.FILE_TYPE_CODE
        FROM HAULING_AUTHORITY HA
        LEFT JOIN PROV_FOREST_USE PFU ON HA.FOREST_FILE_ID =
                                         PFU.FOREST_FILE_ID
        LEFT JOIN HARVESTING_HAULING_XREF HHX ON HA.TIMBER_MARK =
                                                 HHX.TIMBER_MARK
        LEFT JOIN HARVESTING_AUTHORITY HARA ON HHX.HVA_SKEY = HARA.HVA_SKEY;
  END FIND_ALL_TIMBER_MARKS;

  /******************************************************************************
      Procedure:  FIND_TIMBER_MARK
      Purpose: Find a timber mark.
  ******************************************************************************/
  PROCEDURE FIND_TIMBER_MARK(P_MARK  IN VARCHAR,
                             R_MARKS IN OUT ref_timber_mark) IS
  BEGIN
    OPEN R_MARKS FOR

      SELECT HAULING_AUTHORITY.TIMBER_MARK,
             HARVESTING_AUTHORITY.HARVEST_AUTH_STATUS_CODE AS MARK_STATUS_ST,
             HAULING_AUTHORITY.FOREST_FILE_ID,
             PROV_FOREST_USE.FILE_TYPE_CODE
        FROM HAULING_AUTHORITY
        JOIN HARVESTING_HAULING_XREF
          ON HAULING_AUTHORITY.TIMBER_MARK = HARVESTING_HAULING_XREF.TIMBER_MARK
        JOIN HARVESTING_AUTHORITY
          ON HARVESTING_HAULING_XREF.HVA_SKEY = HARVESTING_AUTHORITY.HVA_SKEY
        JOIN PROV_FOREST_USE
          ON HAULING_AUTHORITY.FOREST_FILE_ID = PROV_FOREST_USE.FOREST_FILE_ID
       where HAULING_AUTHORITY.TIMBER_MARK = P_MARK
      --FOR PRIVATE MARKS the mark info comes from the certificate
      UNION
      SELECT HAULING_AUTHORITY.TIMBER_MARK,
             PRIVATE_MARK_CERTIFICATE.PRIVATE_MARK_STATUS_CODE,
             HAULING_AUTHORITY.FOREST_FILE_ID,
             PROV_FOREST_USE.FILE_TYPE_CODE
        FROM HAULING_AUTHORITY
        JOIN PRIVATE_MARK_CERTIFICATE
          ON HAULING_AUTHORITY.FOREST_FILE_ID =
             PRIVATE_MARK_CERTIFICATE.FOREST_FILE_ID
        JOIN PROV_FOREST_USE
          ON HAULING_AUTHORITY.FOREST_FILE_ID = PROV_FOREST_USE.FOREST_FILE_ID
       where HAULING_AUTHORITY.TIMBER_MARK = P_MARK
      --for ROAD TIMBER MARKS the mark info comes from the overarching licence
      UNION
      SELECT HAULING_AUTHORITY.TIMBER_MARK,
             PROV_FOREST_USE.FILE_STATUS_ST,
             HAULING_AUTHORITY.FOREST_FILE_ID,
             PROV_FOREST_USE.FILE_TYPE_CODE
        FROM HAULING_AUTHORITY
        JOIN BLANKET_ROAD_MARK
          ON HAULING_AUTHORITY.TIMBER_MARK = BLANKET_ROAD_MARK.TIMBER_MARK
        JOIN PROV_FOREST_USE
          ON HAULING_AUTHORITY.FOREST_FILE_ID = PROV_FOREST_USE.FOREST_FILE_ID
       WHERE HAULING_AUTHORITY.TIMBER_MARK = P_MARK;





  END FIND_TIMBER_MARK;

  /******************************************************************************
      Procedure:  FIND_TIMBER_MARK_BY_ORG_UNITS
      Purpose: Find a timber mark.
  ******************************************************************************/
  PROCEDURE FIND_TIMBER_MARK_BY_ORG_UNITS(P_MARK  IN VARCHAR,
                             P_ORG_ID IN EXPORT_PERMIT_DETAIL.ORG_UNIT_NO%TYPE,
                             R_MARKS IN OUT ref_timber_mark) IS
  BEGIN
    OPEN R_MARKS FOR

      SELECT HAULING_AUTHORITY.TIMBER_MARK,
             HARVESTING_AUTHORITY.HARVEST_AUTH_STATUS_CODE AS MARK_STATUS_ST,
             HAULING_AUTHORITY.FOREST_FILE_ID,
             PROV_FOREST_USE.FILE_TYPE_CODE
        FROM HAULING_AUTHORITY
        JOIN HARVESTING_HAULING_XREF
          ON HAULING_AUTHORITY.TIMBER_MARK = HARVESTING_HAULING_XREF.TIMBER_MARK
        JOIN HARVESTING_AUTHORITY
          ON HARVESTING_HAULING_XREF.HVA_SKEY = HARVESTING_AUTHORITY.HVA_SKEY
        JOIN PROV_FOREST_USE
          ON HAULING_AUTHORITY.FOREST_FILE_ID = PROV_FOREST_USE.FOREST_FILE_ID
        JOIN ORG_UNIT
          ON PROV_FOREST_USE.FOREST_REGION = ORG_UNIT.ORG_UNIT_NO
       where HAULING_AUTHORITY.TIMBER_MARK = P_MARK
         AND ORG_UNIT.Rollup_Region_No IN (
             SELECT M1.ORG_UNIT_NO
             FROM LEXIS_ORG_UNIT_GROUPING M1
             JOIN LEXIS_ORG_UNIT_GROUPING M2
             ON M1.GROUPING = M2.GROUPING
             WHERE M2.ORG_UNIT_NO= P_ORG_ID)
      --FOR PRIVATE MARKS the mark info comes from the certificate
      UNION
      SELECT HAULING_AUTHORITY.TIMBER_MARK,
             PRIVATE_MARK_CERTIFICATE.PRIVATE_MARK_STATUS_CODE,
             HAULING_AUTHORITY.FOREST_FILE_ID,
             PROV_FOREST_USE.FILE_TYPE_CODE
        FROM HAULING_AUTHORITY
        JOIN PRIVATE_MARK_CERTIFICATE
          ON HAULING_AUTHORITY.FOREST_FILE_ID =
             PRIVATE_MARK_CERTIFICATE.FOREST_FILE_ID
        JOIN PROV_FOREST_USE
          ON HAULING_AUTHORITY.FOREST_FILE_ID = PROV_FOREST_USE.FOREST_FILE_ID
        JOIN ORG_UNIT
          ON PROV_FOREST_USE.FOREST_REGION = ORG_UNIT.ORG_UNIT_NO
       where HAULING_AUTHORITY.TIMBER_MARK = P_MARK
         AND ORG_UNIT.Rollup_Region_No IN (
             SELECT M1.ORG_UNIT_NO
             FROM LEXIS_ORG_UNIT_GROUPING M1
             JOIN LEXIS_ORG_UNIT_GROUPING M2
             ON M1.GROUPING = M2.GROUPING
             WHERE M2.ORG_UNIT_NO= P_ORG_ID)
      --for ROAD TIMBER MARKS the mark info comes from the overarching licence
      UNION
      SELECT HAULING_AUTHORITY.TIMBER_MARK,
             PROV_FOREST_USE.FILE_STATUS_ST,
             HAULING_AUTHORITY.FOREST_FILE_ID,
             PROV_FOREST_USE.FILE_TYPE_CODE
        FROM HAULING_AUTHORITY
        JOIN BLANKET_ROAD_MARK
          ON HAULING_AUTHORITY.TIMBER_MARK = BLANKET_ROAD_MARK.TIMBER_MARK
        JOIN PROV_FOREST_USE
          ON HAULING_AUTHORITY.FOREST_FILE_ID = PROV_FOREST_USE.FOREST_FILE_ID
        JOIN ORG_UNIT
          ON PROV_FOREST_USE.FOREST_REGION = ORG_UNIT.ORG_UNIT_NO
       WHERE HAULING_AUTHORITY.TIMBER_MARK = P_MARK
         AND ORG_UNIT.Rollup_Region_No IN (
             SELECT M1.ORG_UNIT_NO
             FROM LEXIS_ORG_UNIT_GROUPING M1
             JOIN LEXIS_ORG_UNIT_GROUPING M2
             ON M1.GROUPING = M2.GROUPING
             WHERE M2.ORG_UNIT_NO= P_ORG_ID);

  END FIND_TIMBER_MARK_BY_ORG_UNITS;

  /******************************************************************************
      Procedure:  FIND_VALID_BOIC_TIMBER_MARK
      Purpose: Returns the timber if it's valid for this BOIC.
  ******************************************************************************/
  PROCEDURE FIND_VALID_BOIC_TIMBER_MARK(P_MARK  IN VARCHAR,
                             P_EXEMPTION_NUMBER IN EXPORT_EXEMPTION.EXEMPTION_NUMBER%TYPE,
                             R_MARKS IN OUT LEXIS.ref_timber_mark) IS
  BEGIN
    OPEN R_MARKS FOR

      SELECT HAULING_AUTHORITY.TIMBER_MARK,
             HARVESTING_AUTHORITY.HARVEST_AUTH_STATUS_CODE AS MARK_STATUS_ST,
             HAULING_AUTHORITY.FOREST_FILE_ID,
             PROV_FOREST_USE.FILE_TYPE_CODE
        FROM HAULING_AUTHORITY
        JOIN HARVESTING_HAULING_XREF
          ON HAULING_AUTHORITY.TIMBER_MARK = HARVESTING_HAULING_XREF.TIMBER_MARK
        JOIN HARVESTING_AUTHORITY
          ON HARVESTING_HAULING_XREF.HVA_SKEY = HARVESTING_AUTHORITY.HVA_SKEY
        JOIN PROV_FOREST_USE
          ON HAULING_AUTHORITY.FOREST_FILE_ID = PROV_FOREST_USE.FOREST_FILE_ID
        JOIN ORG_UNIT
          ON PROV_FOREST_USE.FOREST_REGION = ORG_UNIT.ORG_UNIT_NO
       where HAULING_AUTHORITY.TIMBER_MARK = P_MARK
         AND ORG_UNIT.Rollup_Region_No IN (
             SELECT M1.ORG_UNIT_NO
             FROM LEXIS_ORG_UNIT_GROUPING M1
             JOIN LEXIS_ORG_UNIT_GROUPING M2
             ON M1.GROUPING = M2.GROUPING
             WHERE M2.ORG_UNIT_NO IN (SELECT ORG_UNIT_NO FROM OIC_EXEMPTION_ORG_UNIT WHERE EXEMPTION_NUMBER = P_EXEMPTION_NUMBER))
      --FOR PRIVATE MARKS the mark info comes from the certificate
      UNION
      SELECT HAULING_AUTHORITY.TIMBER_MARK,
             PRIVATE_MARK_CERTIFICATE.PRIVATE_MARK_STATUS_CODE,
             HAULING_AUTHORITY.FOREST_FILE_ID,
             PROV_FOREST_USE.FILE_TYPE_CODE
        FROM HAULING_AUTHORITY
        JOIN PRIVATE_MARK_CERTIFICATE
          ON HAULING_AUTHORITY.FOREST_FILE_ID =
             PRIVATE_MARK_CERTIFICATE.FOREST_FILE_ID
        JOIN PROV_FOREST_USE
          ON HAULING_AUTHORITY.FOREST_FILE_ID = PROV_FOREST_USE.FOREST_FILE_ID
        JOIN ORG_UNIT
          ON PROV_FOREST_USE.FOREST_REGION = ORG_UNIT.ORG_UNIT_NO
       where HAULING_AUTHORITY.TIMBER_MARK = P_MARK
         AND ORG_UNIT.Rollup_Region_No IN (
             SELECT M1.ORG_UNIT_NO
             FROM LEXIS_ORG_UNIT_GROUPING M1
             JOIN LEXIS_ORG_UNIT_GROUPING M2
             ON M1.GROUPING = M2.GROUPING
             WHERE M2.ORG_UNIT_NO IN (SELECT ORG_UNIT_NO FROM OIC_EXEMPTION_ORG_UNIT WHERE EXEMPTION_NUMBER = P_EXEMPTION_NUMBER))
      --for ROAD TIMBER MARKS the mark info comes from the overarching licence
      UNION
      SELECT HAULING_AUTHORITY.TIMBER_MARK,
             PROV_FOREST_USE.FILE_STATUS_ST,
             HAULING_AUTHORITY.FOREST_FILE_ID,
             PROV_FOREST_USE.FILE_TYPE_CODE
        FROM HAULING_AUTHORITY
        JOIN BLANKET_ROAD_MARK
          ON HAULING_AUTHORITY.TIMBER_MARK = BLANKET_ROAD_MARK.TIMBER_MARK
        JOIN PROV_FOREST_USE
          ON HAULING_AUTHORITY.FOREST_FILE_ID = PROV_FOREST_USE.FOREST_FILE_ID
        JOIN ORG_UNIT
          ON PROV_FOREST_USE.FOREST_REGION = ORG_UNIT.ORG_UNIT_NO
       WHERE HAULING_AUTHORITY.TIMBER_MARK = P_MARK
         AND ORG_UNIT.Rollup_Region_No IN (
             SELECT M1.ORG_UNIT_NO
             FROM LEXIS_ORG_UNIT_GROUPING M1
             JOIN LEXIS_ORG_UNIT_GROUPING M2
             ON M1.GROUPING = M2.GROUPING
             WHERE M2.ORG_UNIT_NO IN (SELECT ORG_UNIT_NO FROM OIC_EXEMPTION_ORG_UNIT WHERE EXEMPTION_NUMBER = P_EXEMPTION_NUMBER));

  END FIND_VALID_BOIC_TIMBER_MARK;

