  /******************************************************************************
      Procedure:  FIND_EXEMPTION_ORG_UNIT
      Purpose: Find an ORG UNIT FOR OIC EXEMPTION by EXEMPTION NUMBER.
  ******************************************************************************/
  PROCEDURE FIND_EXEMPTION_ORG_UNIT(P_EXEMPTION_NUMBER   IN OIC_EXEMPTION_ORG_UNIT.EXEMPTION_NUMBER%TYPE,
                                R_EXEMPTION_ORG_UNIT IN OUT ref_exemption_org_unit) IS
  BEGIN
    OPEN R_EXEMPTION_ORG_UNIT FOR
      SELECT OEO.EXEMPTION_NUMBER, OU.ORG_UNIT_NO, OU.ORG_UNIT_CODE
        FROM OIC_EXEMPTION_ORG_UNIT OEO
        INNER JOIN ORG_UNIT OU ON OU.ORG_UNIT_NO = OEO.ORG_UNIT_NO
       WHERE OEO.EXEMPTION_NUMBER = P_EXEMPTION_NUMBER;
  END FIND_EXEMPTION_ORG_UNIT;

  /******************************************************************************
      Procedure:  FIND_SPEC_GRAD_LIKE_EXCOL
      Purpose: Find an species/grade/enduse by excol value.
  ******************************************************************************/
  PROCEDURE FIND_SPEC_GRAD_LIKE_EXCOL(P_EXCOL     IN SPECIES_GRADE_ENDUSE_RGN_XREF.EXCOL_TRANSLATION_VALUE%TYPE,
                                      P_REGION    IN SPECIES_GRADE_ENDUSE_RGN_XREF.ORG_UNIT_NO%TYPE,
                                      R_SPCE_GRAD IN OUT ref_species_grade_enduse) IS
  BEGIN
    OPEN R_SPCE_GRAD FOR
      SELECT SGE.EXPORT_SPECIES_CODE,
             SGE.SPECIES_GRADE_ENDUSE_REGION_ID,
             SGE.EXCOL_TRANSLATION_VALUE,
             SGE.EXPORT_END_USE_CODE,
             SGE.ORG_UNIT_NO,
             SGE.EXPORT_GRADE_CODE
        FROM SPECIES_GRADE_ENDUSE_RGN_XREF SGE
       WHERE SGE.EXCOL_TRANSLATION_VALUE LIKE P_EXCOL || '%'
         AND SGE.ORG_UNIT_NO = P_REGION;
  END FIND_SPEC_GRAD_LIKE_EXCOL;

