  /******************************************************************************
      Procedure:  FIND_CANDIDATE_EXCOL_VALUES
      Purpose: Find a species/grade/enduse by org unit number and species code.
  ******************************************************************************/
  PROCEDURE FIND_CANDIDATE_EXCOL_VALUES(P_CODE_PATTERN IN VARCHAR2,
                                        P_SPECIES      IN SPECIES_GRADE_ENDUSE_RGN_XREF.EXPORT_SPECIES_CODE%TYPE,
                                        P_END_USE      IN SPECIES_GRADE_ENDUSE_RGN_XREF.export_end_use_code%TYPE,
                                        P_REGION       IN SPECIES_GRADE_ENDUSE_RGN_XREF.ORG_UNIT_NO%TYPE,
                                        R_EXCOL_VALUE  IN OUT ref_excol_translation) IS
    V_CODE_PATTERN_2 VARCHAR2(25);
  BEGIN

    -- add this pattern so that 'double' enduses can be found, e.g. 'CE/UT SH' and 'FI/PL (LG)'
    V_CODE_PATTERN_2 := P_CODE_PATTERN || ' %';

    OPEN R_EXCOL_VALUE FOR
      SELECT DISTINCT T.EXCOL_TRANSLATION_VALUE
        FROM SPECIES_GRADE_ENDUSE_RGN_XREF T
       WHERE (T.EXCOL_TRANSLATION_VALUE LIKE P_CODE_PATTERN OR
             T.EXCOL_TRANSLATION_VALUE LIKE V_CODE_PATTERN_2)
         AND T.EXPORT_SPECIES_CODE = P_SPECIES
         AND T.EXPORT_END_USE_CODE = P_END_USE
         AND T.ORG_UNIT_NO = P_REGION;
  END FIND_CANDIDATE_EXCOL_VALUES;

  /******************************************************************************
      Procedure:  FIND_CANDIDATE_END_USES
      Purpose: Find all enduses by org unit number and species code.
  ******************************************************************************/
  PROCEDURE FIND_CANDIDATE_END_USES(P_CODE_PATTERN IN VARCHAR2,
                                    P_SPECIES      IN SPECIES_GRADE_ENDUSE_RGN_XREF.EXPORT_SPECIES_CODE%TYPE,
                                    P_REGION       IN SPECIES_GRADE_ENDUSE_RGN_XREF.ORG_UNIT_NO%TYPE,
                                    R_EXCOL_VALUE  IN OUT ref_excol_translation) IS
    V_CODE_PATTERN_2 VARCHAR2(25);
  BEGIN

    -- add this pattern so that 'double' enduses can be found, e.g. 'CE/UT SH' and 'FI/PL (LG)'
    V_CODE_PATTERN_2 := P_CODE_PATTERN || '%';

    OPEN R_EXCOL_VALUE FOR
      SELECT DISTINCT T.EXPORT_END_USE_CODE AS EXCOL_TRANSLATION_VALUE
        FROM SPECIES_GRADE_ENDUSE_RGN_XREF T
       WHERE (T.EXCOL_TRANSLATION_VALUE LIKE P_CODE_PATTERN OR
             T.EXCOL_TRANSLATION_VALUE LIKE V_CODE_PATTERN_2)
         AND T.EXPORT_SPECIES_CODE = P_SPECIES
         AND T.ORG_UNIT_NO = P_REGION;
  END FIND_CANDIDATE_END_USES;

  /******************************************************************************
      Procedure:  FIND_CANDIDATE_EXCOL_COMBOS
      Purpose: Find all species/grade/enduse combination candidates by org unit number and species code.
  ******************************************************************************/
  PROCEDURE FIND_CANDIDATE_EXCOL_COMBOS(P_CODE_PATTERN IN VARCHAR2,
                                        P_SPECIES      IN SPECIES_GRADE_ENDUSE_RGN_XREF.EXPORT_SPECIES_CODE%TYPE,
                                        P_REGION       IN SPECIES_GRADE_ENDUSE_RGN_XREF.ORG_UNIT_NO%TYPE,
                                        R_EXCOL_VALUE  IN OUT ref_excol_translation) IS
  BEGIN

    OPEN R_EXCOL_VALUE FOR
      SELECT DISTINCT T.EXCOL_TRANSLATION_VALUE
        FROM SPECIES_GRADE_ENDUSE_RGN_XREF T
       WHERE T.EXCOL_TRANSLATION_VALUE LIKE P_CODE_PATTERN
         AND T.EXPORT_SPECIES_CODE = P_SPECIES
         AND T.ORG_UNIT_NO = P_REGION;
  END FIND_CANDIDATE_EXCOL_COMBOS;

  /******************************************************************************
      Procedure:  INSERT_EXEMPTION_APPLICATION
      Purpose: Updates an existing exemption application
  ******************************************************************************/
  PROCEDURE INSERT_EXEMPTION_APPLICATION(P_APPLICATION_DATE             IN EXPORT_EXEMPTION_APPLICATION.APPLICATION_DATE%TYPE,
                                         P_FED_APP_NUMBER               IN EXPORT_EXEMPTION_APPLICATION.FED_APPLICATION_NUMBER%TYPE,
                                         P_TERM_DAYS                    IN EXPORT_EXEMPTION_APPLICATION.TERM_DAYS%TYPE,
                                         P_RECEIVED_DATE                IN EXPORT_EXEMPTION_APPLICATION.RECEIVED_DATE%TYPE,
                                         P_EXEMPTION_APPLICATION_VOLUME IN EXPORT_EXEMPTION_APPLICATION.EXEMPTION_APPLICATION_VOLUME%TYPE,
                                         P_AVERAGE_LOG_VOLUME           IN EXPORT_EXEMPTION_APPLICATION.AVERAGE_LOG_VOLUME%TYPE,
                                         P_PRODUCT_LOCATION             IN EXPORT_EXEMPTION_APPLICATION.PRODUCT_LOCATION%TYPE,
                                         P_ENTRY_USERID                 IN EXPORT_EXEMPTION_APPLICATION.ENTRY_USERID%TYPE,
                                         P_ENTRY_TIMESTAMP              IN EXPORT_EXEMPTION_APPLICATION.ENTRY_TIMESTAMP%TYPE,
                                         P_UPDATE_USERID                IN EXPORT_EXEMPTION_APPLICATION.UPDATE_USERID%TYPE,
                                         P_UPDATE_TIMESTAMP             IN EXPORT_EXEMPTION_APPLICATION.UPDATE_TIMESTAMP%TYPE,
                                         P_EXPORT_SCHEDULE_ID           IN EXPORT_EXEMPTION_APPLICATION.EXPORT_SCHEDULE_ID%TYPE,
                                         P_AGENT_CLIENT_NUMBER          IN EXPORT_EXEMPTION_APPLICATION.AGENT_CLIENT_NUMBER%TYPE,
                                         P_AGENT_CLIENT_LOCATION_CODE   IN EXPORT_EXEMPTION_APPLICATION.AGENT_CLIENT_LOCATION_CODE%TYPE,
                                         P_OWNER_CLIENT_NUMBER          IN EXPORT_EXEMPTION_APPLICATION.OWNER_CLIENT_NUMBER%TYPE,
                                         P_OWNER_CLIENT_LOCATION_CODE   IN EXPORT_EXEMPTION_APPLICATION.OWNER_CLIENT_LOCATION_CODE%TYPE,
                                         P_EXEMPTION_NUMBER             IN EXPORT_EXEMPTION_APPLICATION.EXEMPTION_NUMBER%TYPE,
                                         P_EXPORT_EXEMPTION_REASON_CODE IN EXPORT_EXEMPTION_APPLICATION.EXPORT_EXEMPTION_REASON_CODE%TYPE,
                                         P_EXPORT_APPLICATION_STATUS_CO IN EXPORT_EXEMPTION_APPLICATION.EXPORT_APPLICATION_STATUS_CODE%TYPE,
                                         P_EXPORT_APPLICANT_TYPE_CODE   IN EXPORT_EXEMPTION_APPLICATION.EXPORT_APPLICANT_TYPE_CODE%TYPE,
                                         P_ORG_UNIT_NO                  IN EXPORT_EXEMPTION_APPLICATION.ORG_UNIT_NO%TYPE,
                                         P_EXPORT_PRODUCT_TYPE_CODE     IN EXPORT_EXEMPTION_APPLICATION.EXPORT_PRODUCT_TYPE_CODE%TYPE,
                                         P_EXPORT_JURISDICTION_CODE     IN EXPORT_EXEMPTION_APPLICATION.EXPORT_JURISDICTION_CODE%TYPE,
                                         P_EXPORT_GROWTH_TYPE_CODE      IN EXPORT_EXEMPTION_APPLICATION.EXPORT_GROWTH_TYPE_CODE%TYPE,
                                         P_AGENT_CONTACT_NAME           IN EXPORT_EXEMPTION_APPLICATION.AGENT_CONTACT_NAME%TYPE,
                                         P_OWNER_CONTACT_NAME           IN EXPORT_EXEMPTION_APPLICATION.OWNER_CONTACT_NAME%TYPE,
                                         P_OIC_INDICATOR                IN EXPORT_EXEMPTION_APPLICATION.OIC_INDICATOR%TYPE,
                                         P_APPLICATIONS                 IN OUT ref_application) IS

    V_APPLICATION_NUMBER EXPORT_EXEMPTION_APPLICATION.APPLICATION_NUMBER%TYPE;

  BEGIN
    SELECT EXPORT_EXEMPTION_APP_SEQ.NEXTVAL
      INTO V_APPLICATION_NUMBER
      FROM DUAL;

    INSERT INTO EXPORT_EXEMPTION_APPLICATION EEA
      (APPLICATION_NUMBER,
       FED_APPLICATION_NUMBER,
       APPLICATION_DATE,
       TERM_DAYS,
       RECEIVED_DATE,
       EXEMPTION_APPLICATION_VOLUME,
       AVERAGE_LOG_VOLUME,
       PRODUCT_LOCATION,
       ENTRY_USERID,
       ENTRY_TIMESTAMP,
       UPDATE_USERID,
       UPDATE_TIMESTAMP,
       EXPORT_SCHEDULE_ID,
       AGENT_CLIENT_NUMBER,
       AGENT_CLIENT_LOCATION_CODE,
       OWNER_CLIENT_NUMBER,
       OWNER_CLIENT_LOCATION_CODE,
       EXEMPTION_NUMBER,
       EXPORT_EXEMPTION_REASON_CODE,
       EXPORT_APPLICATION_STATUS_CODE,
       EXPORT_APPLICANT_TYPE_CODE,
       ORG_UNIT_NO,
       EXPORT_PRODUCT_TYPE_CODE,
       EXPORT_JURISDICTION_CODE,
       EXPORT_GROWTH_TYPE_CODE,
       AGENT_CONTACT_NAME,
       OWNER_CONTACT_NAME,
       OIC_INDICATOR)
    VALUES
      (V_APPLICATION_NUMBER,
       P_FED_APP_NUMBER,
       P_APPLICATION_DATE,
       P_TERM_DAYS,
       P_RECEIVED_DATE,
       P_EXEMPTION_APPLICATION_VOLUME,
       P_AVERAGE_LOG_VOLUME,
       P_PRODUCT_LOCATION,
       P_ENTRY_USERID,
       P_ENTRY_TIMESTAMP,
       P_UPDATE_USERID,
       P_UPDATE_TIMESTAMP,
       P_EXPORT_SCHEDULE_ID,
       P_AGENT_CLIENT_NUMBER,
       P_AGENT_CLIENT_LOCATION_CODE,
       P_OWNER_CLIENT_NUMBER,
       P_OWNER_CLIENT_LOCATION_CODE,
       P_EXEMPTION_NUMBER,
       P_EXPORT_EXEMPTION_REASON_CODE,
       P_EXPORT_APPLICATION_STATUS_CO,
       P_EXPORT_APPLICANT_TYPE_CODE,
       P_ORG_UNIT_NO,
       P_EXPORT_PRODUCT_TYPE_CODE,
       P_EXPORT_JURISDICTION_CODE,
       P_EXPORT_GROWTH_TYPE_CODE,
       P_AGENT_CONTACT_NAME,
       P_OWNER_CONTACT_NAME,
       P_OIC_INDICATOR);

    OPEN P_APPLICATIONS FOR
      SELECT DISTINCT EEA.APPLICATION_NUMBER,
                      EEA.FED_APPLICATION_NUMBER,
                      EEA.APPLICATION_DATE,
                      EEA.TERM_DAYS,
                      EEA.RECEIVED_DATE,
                      EEA.EXEMPTION_APPLICATION_VOLUME,
                      EEA.AVERAGE_LOG_VOLUME,
                      EEA.PRODUCT_LOCATION,
                      EEA.ENTRY_USERID,
                      EEA.ENTRY_TIMESTAMP,
                      EEA.UPDATE_USERID,
                      EEA.UPDATE_TIMESTAMP,
                      EEA.EXPORT_SCHEDULE_ID,
                      EEA.AGENT_CLIENT_NUMBER,
                      EEA.AGENT_CLIENT_LOCATION_CODE,
                      EEA.OWNER_CLIENT_NUMBER,
                      EEA.OWNER_CLIENT_LOCATION_CODE,
                      EEA.EXEMPTION_NUMBER,
                      EEA.EXPORT_EXEMPTION_REASON_CODE,
                      EEA.EXPORT_APPLICATION_STATUS_CODE,
                      EEA.EXPORT_APPLICANT_TYPE_CODE,
                      EEA.ORG_UNIT_NO,
                      EEA.EXPORT_PRODUCT_TYPE_CODE,
                      EEA.EXPORT_JURISDICTION_CODE,
                      EEA.EXPORT_GROWTH_TYPE_CODE,
                      EEA.AGENT_CONTACT_NAME,
                      EEA.OWNER_CONTACT_NAME,
                      ES.ADVERTISING_DATE,
                      EASC.DESCRIPTION AS STATUS_DESCRIPTION,
                      EERC.DESCRIPTION AS REASON_DESCRIPTION,
                      EE.EXPORT_EXEMPTION_TYPE_CODE,
                      EETC.DESCRIPTION AS TYPE_DESCRIPTION,
                      FCO.CLIENT_NAME AS OWNER_COMPANY_NAME,
                      AFCO.CLIENT_NAME AS AGENT_COMPANY_NAME,
                      EATC.DESCRIPTION AS APPLICANT_DESCRIPTION,
                      OU.ORG_UNIT_NAME AS REGION,
                      OU.ORG_UNIT_CODE AS REGION_CODE,
                      NULL AS SHOW_INFO_ICON,
                      GET_APPLICATION_APPROVAL_DATE(EEA.APPLICATION_NUMBER) AS APPROVAL_DATE,
                      EEA.OIC_INDICATOR
        FROM EXPORT_EXEMPTION_APPLICATION EEA
        LEFT JOIN EXPORT_EXEMPTION EE ON EE.EXEMPTION_NUMBER =
                                         EEA.EXEMPTION_NUMBER
        LEFT JOIN EXPORT_PACKAGE EP ON EP.APPLICATION_NUMBER =
                                       EEA.APPLICATION_NUMBER
       LEFT JOIN EXPORT_SCHEDULE ES ON EEA.EXPORT_SCHEDULE_ID =
                                        ES.EXPORT_SCHEDULE_ID
       INNER JOIN EXPORT_APPLICATION_STATUS_CODE EASC ON EEA.EXPORT_APPLICATION_STATUS_CODE =
                                                         EASC.EXPORT_APPLICATION_STATUS_CODE
       INNER JOIN EXPORT_EXEMPTION_REASON_CODE EERC ON EEA.EXPORT_EXEMPTION_REASON_CODE =
                                                       EERC.EXPORT_EXEMPTION_REASON_CODE
       INNER JOIN EXPORT_APPLICANT_TYPE_CODE EATC ON EEA.EXPORT_APPLICANT_TYPE_CODE =
                                                     EATC.EXPORT_APPLICANT_TYPE_CODE
        LEFT JOIN EXPORT_EXEMPTION_TYPE_CODE EETC ON EE.EXPORT_EXEMPTION_TYPE_CODE =
                                                     EETC.EXPORT_EXEMPTION_TYPE_CODE
        LEFT JOIN FOREST_CLIENT FCO ON EEA.OWNER_CLIENT_NUMBER =
                                       FCO.CLIENT_NUMBER
        LEFT JOIN FOREST_CLIENT AFCO ON EEA.AGENT_CLIENT_NUMBER =
                                       AFCO.CLIENT_NUMBER
        LEFT JOIN ORG_UNIT OU ON OU.ORG_UNIT_NO = EEA.ORG_UNIT_NO
       WHERE EEA.APPLICATION_NUMBER = V_APPLICATION_NUMBER;

  END INSERT_EXEMPTION_APPLICATION;

  /******************************************************************************
      Procedure:  UPDATE_EXEMPTION_APPLICATION
      Purpose: Updates an existing exemption application
  ******************************************************************************/
  PROCEDURE UPDATE_EXEMPTION_APPLICATION(P_APPLICATION_NUMBER           IN EXPORT_EXEMPTION_APPLICATION.APPLICATION_NUMBER%TYPE,
                                         P_FED_APP_NUMBER               IN EXPORT_EXEMPTION_APPLICATION.FED_APPLICATION_NUMBER%TYPE,
                                         P_APPLICATION_DATE             IN EXPORT_EXEMPTION_APPLICATION.APPLICATION_DATE%TYPE,
                                         P_TERM_DAYS                    IN EXPORT_EXEMPTION_APPLICATION.TERM_DAYS%TYPE,
                                         P_RECEIVED_DATE                IN EXPORT_EXEMPTION_APPLICATION.RECEIVED_DATE%TYPE,
                                         P_EXEMPTION_APPLICATION_VOLUME IN EXPORT_EXEMPTION_APPLICATION.EXEMPTION_APPLICATION_VOLUME%TYPE,
                                         P_AVERAGE_LOG_VOLUME           IN EXPORT_EXEMPTION_APPLICATION.AVERAGE_LOG_VOLUME%TYPE,
                                         P_PRODUCT_LOCATION             IN EXPORT_EXEMPTION_APPLICATION.PRODUCT_LOCATION%TYPE,
                                         P_ENTRY_USERID                 IN EXPORT_EXEMPTION_APPLICATION.ENTRY_USERID%TYPE,
                                         P_ENTRY_TIMESTAMP              IN EXPORT_EXEMPTION_APPLICATION.ENTRY_TIMESTAMP%TYPE,
                                         P_UPDATE_USERID                IN EXPORT_EXEMPTION_APPLICATION.UPDATE_USERID%TYPE,
                                         P_UPDATE_TIMESTAMP             IN EXPORT_EXEMPTION_APPLICATION.UPDATE_TIMESTAMP%TYPE,
                                         P_EXPORT_SCHEDULE_ID           IN EXPORT_EXEMPTION_APPLICATION.EXPORT_SCHEDULE_ID%TYPE,
                                         P_AGENT_CLIENT_NUMBER          IN EXPORT_EXEMPTION_APPLICATION.AGENT_CLIENT_NUMBER%TYPE,
                                         P_AGENT_CLIENT_LOCATION_CODE   IN EXPORT_EXEMPTION_APPLICATION.AGENT_CLIENT_LOCATION_CODE%TYPE,
                                         P_OWNER_CLIENT_NUMBER          IN EXPORT_EXEMPTION_APPLICATION.OWNER_CLIENT_NUMBER%TYPE,
                                         P_OWNER_CLIENT_LOCATION_CODE   IN EXPORT_EXEMPTION_APPLICATION.OWNER_CLIENT_LOCATION_CODE%TYPE,
                                         P_EXEMPTION_NUMBER             IN EXPORT_EXEMPTION_APPLICATION.EXEMPTION_NUMBER%TYPE,
                                         P_EXPORT_EXEMPTION_REASON_CODE IN EXPORT_EXEMPTION_APPLICATION.EXPORT_EXEMPTION_REASON_CODE%TYPE,
                                         P_EXPORT_APPLICATION_STATUS_CO IN EXPORT_EXEMPTION_APPLICATION.EXPORT_APPLICATION_STATUS_CODE%TYPE,
                                         P_EXPORT_APPLICANT_TYPE_CODE   IN EXPORT_EXEMPTION_APPLICATION.EXPORT_APPLICANT_TYPE_CODE%TYPE,
                                         P_ORG_UNIT_NO                  IN EXPORT_EXEMPTION_APPLICATION.ORG_UNIT_NO%TYPE,
                                         P_EXPORT_PRODUCT_TYPE_CODE     IN EXPORT_EXEMPTION_APPLICATION.EXPORT_PRODUCT_TYPE_CODE%TYPE,
                                         P_EXPORT_JURISDICTION_CODE     IN EXPORT_EXEMPTION_APPLICATION.EXPORT_JURISDICTION_CODE%TYPE,
                                         P_EXPORT_GROWTH_TYPE_CODE      IN EXPORT_EXEMPTION_APPLICATION.EXPORT_GROWTH_TYPE_CODE%TYPE,
                                         P_AGENT_CONTACT_NAME           IN EXPORT_EXEMPTION_APPLICATION.AGENT_CONTACT_NAME%TYPE,
                                         P_OWNER_CONTACT_NAME           IN EXPORT_EXEMPTION_APPLICATION.OWNER_CONTACT_NAME%TYPE,
                                         P_OIC_INDICATOR                IN EXPORT_EXEMPTION_APPLICATION.OIC_INDICATOR%TYPE) IS

    V_AUDIT_ID EXPORT_EXEMPTION_APPL_AUDIT.EXPORT_EXEMPTION_APPL_AUDIT_ID%TYPE;

  BEGIN

    SELECT EXPORT_EXEMPTION_APP_AUDIT_SEQ.NEXTVAL
      INTO V_AUDIT_ID
      FROM DUAL;

    INSERT INTO EXPORT_EXEMPTION_APPL_AUDIT
      (EXPORT_EXEMPTION_APPL_AUDIT_ID,
       APPLICATION_NUMBER,
       FED_APPLICATION_NUMBER,
       APPLICATION_DATE,
       RECEIVED_DATE,
       TERM_DAYS,
       EXEMPTION_APPLICATION_VOLUME,
       AVERAGE_LOG_VOLUME,
       EXPORT_SCHEDULE_ID,
       PRODUCT_LOCATION,
       AGENT_CONTACT_NAME,
       AGENT_CLIENT_NUMBER,
       OWNER_CONTACT_NAME,
       OWNER_CLIENT_NUMBER,
       EXEMPTION_NUMBER,
       ORG_UNIT_NO,
       AGENT_CLIENT_LOCATION_CODE,
       OWNER_CLIENT_LOCATION_CODE,
       EXPORT_EXEMPTION_REASON_CODE,
       EXPORT_APPLICATION_STATUS_CODE,
       EXPORT_APPLICANT_TYPE_CODE,
       EXPORT_PRODUCT_TYPE_CODE,
       EXPORT_JURISDICTION_CODE,
       EXPORT_GROWTH_TYPE_CODE,
       OIC_INDICATOR,
       ENTRY_USERID,
       ENTRY_TIMESTAMP,
       UPDATE_USERID,
       UPDATE_TIMESTAMP,
       DELETE_USERID,
       DELETE_TIMESTAMP)
      SELECT V_AUDIT_ID,
             EEA.APPLICATION_NUMBER,
             EEA.FED_APPLICATION_NUMBER,
             EEA.APPLICATION_DATE,
             EEA.RECEIVED_DATE,
             EEA.TERM_DAYS,
             EEA.EXEMPTION_APPLICATION_VOLUME,
             EEA.AVERAGE_LOG_VOLUME,
             EEA.EXPORT_SCHEDULE_ID,
             EEA.PRODUCT_LOCATION,
             EEA.AGENT_CONTACT_NAME,
             EEA.AGENT_CLIENT_NUMBER,
             EEA.OWNER_CONTACT_NAME,
             EEA.OWNER_CLIENT_NUMBER,
             EEA.EXEMPTION_NUMBER,
             EEA.ORG_UNIT_NO,
             EEA.AGENT_CLIENT_LOCATION_CODE,
             EEA.OWNER_CLIENT_LOCATION_CODE,
             EEA.EXPORT_EXEMPTION_REASON_CODE,
             EEA.EXPORT_APPLICATION_STATUS_CODE,
             EEA.EXPORT_APPLICANT_TYPE_CODE,
             EEA.EXPORT_PRODUCT_TYPE_CODE,
             EEA.EXPORT_JURISDICTION_CODE,
             EEA.EXPORT_GROWTH_TYPE_CODE,
             EEA.OIC_INDICATOR,
             EEA.ENTRY_USERID,
             EEA.ENTRY_TIMESTAMP,
             EEA.UPDATE_USERID,
             EEA.UPDATE_TIMESTAMP,
             NULL,
             NULL
        FROM EXPORT_EXEMPTION_APPLICATION EEA
       WHERE EEA.APPLICATION_NUMBER = P_APPLICATION_NUMBER;

    UPDATE EXPORT_EXEMPTION_APPLICATION EEA
       SET FED_APPLICATION_NUMBER         = P_FED_APP_NUMBER,
           APPLICATION_DATE               = P_APPLICATION_DATE,
           TERM_DAYS                      = P_TERM_DAYS,
           RECEIVED_DATE                  = P_RECEIVED_DATE,
           EXEMPTION_APPLICATION_VOLUME   = P_EXEMPTION_APPLICATION_VOLUME,
           AVERAGE_LOG_VOLUME             = P_AVERAGE_LOG_VOLUME,
           PRODUCT_LOCATION               = P_PRODUCT_LOCATION,
           ENTRY_USERID                   = P_ENTRY_USERID,
           ENTRY_TIMESTAMP                = P_ENTRY_TIMESTAMP,
           UPDATE_USERID                  = P_UPDATE_USERID,
           UPDATE_TIMESTAMP               = P_UPDATE_TIMESTAMP,
           EXPORT_SCHEDULE_ID             = P_EXPORT_SCHEDULE_ID,
           AGENT_CLIENT_NUMBER            = P_AGENT_CLIENT_NUMBER,
           AGENT_CLIENT_LOCATION_CODE     = P_AGENT_CLIENT_LOCATION_CODE,
           OWNER_CLIENT_NUMBER            = P_OWNER_CLIENT_NUMBER,
           OWNER_CLIENT_LOCATION_CODE     = P_OWNER_CLIENT_LOCATION_CODE,
           EXEMPTION_NUMBER               = P_EXEMPTION_NUMBER,
           EXPORT_EXEMPTION_REASON_CODE   = P_EXPORT_EXEMPTION_REASON_CODE,
           EXPORT_APPLICATION_STATUS_CODE = P_EXPORT_APPLICATION_STATUS_CO,
           EXPORT_APPLICANT_TYPE_CODE     = P_EXPORT_APPLICANT_TYPE_CODE,
           ORG_UNIT_NO                    = P_ORG_UNIT_NO,
           EXPORT_PRODUCT_TYPE_CODE       = P_EXPORT_PRODUCT_TYPE_CODE,
           EXPORT_JURISDICTION_CODE       = P_EXPORT_JURISDICTION_CODE,
           EXPORT_GROWTH_TYPE_CODE        = P_EXPORT_GROWTH_TYPE_CODE,
           AGENT_CONTACT_NAME             = P_AGENT_CONTACT_NAME,
           OWNER_CONTACT_NAME             = P_OWNER_CONTACT_NAME,
           OIC_INDICATOR                  = P_OIC_INDICATOR
     WHERE EEA.APPLICATION_NUMBER = P_APPLICATION_NUMBER;
  END UPDATE_EXEMPTION_APPLICATION;

  /******************************************************************************
      Procedure:  INSERT_EXEMPTION_APP_REMARK
      Purpose: Inserts a new exemption application remark
  ******************************************************************************/
  PROCEDURE INSERT_EXEMPTION_APP_REMARK(P_REMARK_DATE        IN EXPORT_EXEMPTION_APP_REMARKS.REMARK_DATE%TYPE,
                                        P_REMARK             IN EXPORT_EXEMPTION_APP_REMARKS.REMARK%TYPE,
                                        P_ENTRY_USERID       IN EXPORT_EXEMPTION_APP_REMARKS.ENTRY_USERID%TYPE,
                                        P_ENTRY_TIMESTAMP    IN EXPORT_EXEMPTION_APP_REMARKS.ENTRY_TIMESTAMP%TYPE,
                                        P_APPLICATION_NUMBER IN EXPORT_EXEMPTION_APP_REMARKS.APPLICATION_NUMBER%TYPE,
                                        P_REMARKS            IN OUT ref_remark) IS

    V_REMARK_NUMBER EXPORT_EXEMPTION_APPLICATION.APPLICATION_NUMBER%TYPE;

  BEGIN
    SELECT EXEMPTION_APP_REMARKS_SEQ.NEXTVAL
      INTO V_REMARK_NUMBER
      FROM DUAL;

    INSERT INTO EXPORT_EXEMPTION_APP_REMARKS EEAR
      (EXPORT_EXMPTN_APPL_REMARK_NMBR,
       REMARK_DATE,
       REMARK,
       ENTRY_USERID,
       ENTRY_TIMESTAMP,
       APPLICATION_NUMBER)
    VALUES
      (V_REMARK_NUMBER,
       P_REMARK_DATE,
       P_REMARK,
       P_ENTRY_USERID,
       P_ENTRY_TIMESTAMP,
       P_APPLICATION_NUMBER);

    OPEN P_REMARKS FOR
      SELECT R.EXPORT_EXMPTN_APPL_REMARK_NMBR,
             R.REMARK_DATE,
             R.REMARK,
             R.ENTRY_USERID,
             R.ENTRY_TIMESTAMP,
             R.UPDATE_USERID,
             R.UPDATE_TIMESTAMP,
             R.APPLICATION_NUMBER
        FROM EXPORT_EXEMPTION_APP_REMARKS R
       WHERE R.EXPORT_EXMPTN_APPL_REMARK_NMBR = V_REMARK_NUMBER;

  END INSERT_EXEMPTION_APP_REMARK;

  /******************************************************************************
      Procedure:  UPDATE_EXEMPTION_APP_REMARK
      Purpose: Inserts a new exemption application remark
  ******************************************************************************/
  PROCEDURE UPDATE_EXEMPTION_APP_REMARK(P_EXPORT_EXMPTN_APPL_REMARK_NM in EXPORT_EXEMPTION_APP_REMARKS.EXPORT_EXMPTN_APPL_REMARK_NMBR%TYPE,
                                        P_REMARK_DATE                  IN EXPORT_EXEMPTION_APP_REMARKS.REMARK_DATE%TYPE,
                                        P_REMARK                       IN EXPORT_EXEMPTION_APP_REMARKS.REMARK%TYPE,
                                        P_UPDATE_USERID                IN EXPORT_EXEMPTION_APP_REMARKS.UPDATE_USERID%TYPE,
                                        P_UPDATE_TIMESTAMP             IN EXPORT_EXEMPTION_APP_REMARKS.UPDATE_TIMESTAMP%TYPE,
                                        P_APPLICATION_NUMBER           IN EXPORT_EXEMPTION_APP_REMARKS.APPLICATION_NUMBER%TYPE) IS

  BEGIN
    UPDATE EXPORT_EXEMPTION_APP_REMARKS EEAR
       SET EXPORT_EXMPTN_APPL_REMARK_NMBR = P_EXPORT_EXMPTN_APPL_REMARK_NM,
           REMARK_DATE                    = P_REMARK_DATE,
           REMARK                         = P_REMARK,
           UPDATE_USERID                  = P_UPDATE_USERID,
           UPDATE_TIMESTAMP               = P_UPDATE_TIMESTAMP,
           APPLICATION_NUMBER             = P_APPLICATION_NUMBER
     WHERE EEAR.EXPORT_EXMPTN_APPL_REMARK_NMBR =
           P_EXPORT_EXMPTN_APPL_REMARK_NM;

  END UPDATE_EXEMPTION_APP_REMARK;

  /******************************************************************************
      Procedure:  INSERT_SCALE_DETAIL
      Purpose: Inserts a new scale detail
  ******************************************************************************/
  PROCEDURE INSERT_SCALE_DETAIL(P_TIMBER_MARK          IN export_scale_detail.TIMBER_MARK%TYPE,
                                P_PIECES_COUNT         IN export_scale_detail.PIECES_COUNT%TYPE,
                                P_SPECIES_GRADE_VOLUME IN export_scale_detail.SPECIES_GRADE_VOLUME%TYPE,
                                P_ENTRY_USERID         IN export_scale_detail.ENTRY_USERID%TYPE,
                                P_ENTRY_TIMESTAMP      IN export_scale_detail.ENTRY_TIMESTAMP%TYPE,
                                P_UPDATE_USERID        IN export_scale_detail.UPDATE_USERID%TYPE,
                                P_UPDATE_TIMESTAMP     IN export_scale_detail.UPDATE_TIMESTAMP%TYPE,
                                P_PACKAGE_NUMBER       IN export_scale_detail.PACKAGE_NUMBER%TYPE,
                                P_EXPORT_SPECIES_CODE  IN export_scale_detail.EXPORT_SPECIES_CODE%TYPE,
                                P_EXPORT_GRADE_CODE    IN export_scale_detail.EXPORT_GRADE_CODE%TYPE,
                                P_EXPORT_PERMIT_DETAIL_NUMBER IN export_scale_detail.Export_Permit_Detail_Number%TYPE,
                                P_EXEMPTION_OVERRIDE_RATE      IN export_scale_detail.EXEMPTION_OVERRIDE_RATE%TYPE,
                                R_SCALE                IN OUT ref_scale_detail) IS

    V_ID export_scale_detail.EXPORT_SCALE_DETAIL_ID%TYPE;
      V_PERMIT_NUMBER  EXPORT_SCALE_DETAIL.EXPORT_PERMIT_DETAIL_NUMBER%TYPE;
    V_ORG_UNIT_NO    export_permit_detail.org_unit_no%TYPE;


  BEGIN
    SELECT EXPORT_SCALE_DETAIL_SEQ.NEXTVAL INTO V_ID FROM DUAL;

    INSERT INTO export_scale_detail ESD
      (EXPORT_SCALE_DETAIL_ID,
       TIMBER_MARK,
       PIECES_COUNT,
       SPECIES_GRADE_VOLUME,
       ENTRY_USERID,
       ENTRY_TIMESTAMP,
       UPDATE_USERID,
       UPDATE_TIMESTAMP,
       PACKAGE_NUMBER,
       EXPORT_SPECIES_CODE,
       EXPORT_GRADE_CODE,
       EXPORT_PERMIT_DETAIL_NUMBER,
       EXEMPTION_OVERRIDE_RATE
       )
    VALUES
      (V_ID,
       P_TIMBER_MARK,
       P_PIECES_COUNT,
       P_SPECIES_GRADE_VOLUME,
       P_ENTRY_USERID,
       P_ENTRY_TIMESTAMP,
       P_UPDATE_USERID,
       P_UPDATE_TIMESTAMP,
       P_PACKAGE_NUMBER,
       P_EXPORT_SPECIES_CODE,
       P_EXPORT_GRADE_CODE,
       P_EXPORT_PERMIT_DETAIL_NUMBER,
       CASE WHEN P_EXEMPTION_OVERRIDE_RATE = 0  THEN null ELSE P_EXEMPTION_OVERRIDE_RATE END);

 IF P_EXPORT_PERMIT_DETAIL_NUMBER is not null THEN
  SELECT epd.export_permit_detail_number, epd.org_unit_no INTO V_PERMIT_NUMBER, V_ORG_UNIT_NO FROM export_permit_detail epd  WHERE epd.export_permit_detail_number = P_EXPORT_PERMIT_DETAIL_NUMBER;

    -- IF (V_ORG_UNIT_NO != 1904 or V_ORG_UNIT_NO != 1905 or V_ORG_UNIT_NO != 1906 or V_ORG_UNIT_NO != 1903 or V_ORG_UNIT_NO != 1907) THEN

      SET_FIL_CALULATED_VALUES(P_EXPORT_PERMIT_DETAIL_NUMBER);
     --  elsif(V_ORG_UNIT_NO =1908 and P_EXPORT_GRADE_CODE not in ('1','2','3','4','5','6')) then
     --  SET_FIL_CALULATED_VALUES(P_EXPORT_PERMIT_DETAIL_NUMBER);

     -- end if;
   END IF;

    OPEN R_SCALE FOR
      SELECT SD.EXPORT_SCALE_DETAIL_ID,
             SD.PIECES_COUNT,
             SD.SPECIES_GRADE_VOLUME,
             SD.ENTRY_USERID,
             SD.ENTRY_TIMESTAMP,
             SD.UPDATE_USERID,
             SD.UPDATE_TIMESTAMP,
             SD.TIMBER_MARK,
             SD.EXPORT_SPECIES_CODE,
             SD.EXPORT_GRADE_CODE,
             EP.APPLICATION_NUMBER,
             SD.PACKAGE_NUMBER,
             SD.EXPORT_PERMIT_DETAIL_NUMBER,
             HVA.CASCADE_SPLIT_CODE,
             SD.ESTIMATED_WINNING_BID AS EWB,
             SD.FEE_IN_LIEU AS FIL,
             SD.MULTIPLICATION_FACTOR AS MF
        FROM EXPORT_SCALE_DETAIL SD
       INNER JOIN EXPORT_PACKAGE EP ON SD.Package_Number =
                                       EP.Package_Number
       LEFT JOIN HARVESTING_HAULING_XREF HHX ON HHX.TIMBER_MARK  = SD.TIMBER_MARK
       LEFT JOIN HARVESTING_AUTHORITY HVA ON HHX.HVA_SKEY = HVA.HVA_SKEY
       WHERE SD.EXPORT_SCALE_DETAIL_ID = V_ID;

  END INSERT_SCALE_DETAIL;

  /******************************************************************************
      Procedure:  DELETE_SCALE_DETAIL
      Purpose: Deletes a scale detail
  ******************************************************************************/
  PROCEDURE DELETE_SCALE_DETAIL(P_EXPORT_SCALE_DETAIL_ID IN export_scale_detail.EXPORT_SCALE_DETAIL_ID%TYPE,
                                P_DELETE_USERID          IN export_scale_detail.ENTRY_USERID%TYPE) IS

    V_SCALE_AUDIT_ID export_scale_detail_audit.EXPORT_SCALE_DETAIL_AUDIT_ID%TYPE;
    V_DELETE_USERID  EXPORT_SCALE_DETAIL_AUDIT.DELETE_USERID%TYPE;

  BEGIN

    SELECT EXPORT_SCALE_AUDIT_SEQ.NEXTVAL INTO V_SCALE_AUDIT_ID FROM DUAL;
    V_DELETE_USERID := P_DELETE_USERID;

    -- fetch the record to be deleted into the audit table
    INSERT INTO EXPORT_SCALE_DETAIL_AUDIT
      (EXPORT_SCALE_DETAIL_AUDIT_ID,
       EXPORT_SCALE_DETAIL_ID,
       TIMBER_MARK,
       PIECES_COUNT,
       SPECIES_GRADE_VOLUME,
       PACKAGE_NUMBER,
       EXPORT_SPECIES_CODE,
       EXPORT_GRADE_CODE,
       ENTRY_USERID,
       ENTRY_TIMESTAMP,
       UPDATE_USERID,
       UPDATE_TIMESTAMP,
       DELETE_USERID,
       DELETE_TIMESTAMP,
       EXPORT_PERMIT_DETAIL_NUMBER,
       AVERAGE_MARKET_PRICE,
       ESTIMATED_WINNING_BID,
       FEE_IN_LIEU,
       MULTIPLICATION_FACTOR,
       SCALE_DETAIL_FEE)
      SELECT V_SCALE_AUDIT_ID,
             ESD.EXPORT_SCALE_DETAIL_ID,
             ESD.TIMBER_MARK,
             ESD.PIECES_COUNT,
             ESD.SPECIES_GRADE_VOLUME,
             ESD.PACKAGE_NUMBER,
             ESD.EXPORT_SPECIES_CODE,
             ESD.EXPORT_GRADE_CODE,
             ESD.ENTRY_USERID,
             ESD.ENTRY_TIMESTAMP,
             ESD.UPDATE_USERID,
             ESD.UPDATE_TIMESTAMP,
             V_DELETE_USERID,
             SYSDATE,
             ESD.EXPORT_PERMIT_DETAIL_NUMBER,
             ESD.AVERAGE_MARKET_PRICE,
             ESD.ESTIMATED_WINNING_BID,
             ESD.FEE_IN_LIEU,
             ESD.MULTIPLICATION_FACTOR,
             ESD.SCALE_DETAIL_FEE
        FROM EXPORT_SCALE_DETAIL ESD
       WHERE ESD.EXPORT_SCALE_DETAIL_ID = P_EXPORT_SCALE_DETAIL_ID;

    -- delete the record
    DELETE FROM EXPORT_SCALE_DETAIL ESD
     WHERE P_EXPORT_SCALE_DETAIL_ID = ESD.EXPORT_SCALE_DETAIL_ID;

  END DELETE_SCALE_DETAIL;

  /******************************************************************************
      Procedure:  DELETE_PACKAGE
      Purpose: Deletes a PACKAGE
  ******************************************************************************/
  PROCEDURE DELETE_PACKAGE(P_PACKAGE_NUMBER IN EXPORT_PACKAGE.PACKAGE_NUMBER%TYPE,
                                P_DELETE_USERID          IN EXPORT_PACKAGE.ENTRY_USERID%TYPE) IS

    V_PACKAGE_AUDIT_ID EXPORT_PACKAGE_AUDIT.EXPORT_PACKAGE_AUDIT_ID%TYPE;
    V_DELETE_USERID  EXPORT_PACKAGE_AUDIT.DELETE_USERID%TYPE;

  BEGIN

    SELECT EXPORT_PACKAGE_AUDIT_SEQ.NEXTVAL INTO V_PACKAGE_AUDIT_ID FROM DUAL;
    V_DELETE_USERID := P_DELETE_USERID;

    -- fetch the record to be deleted into the audit table
    INSERT INTO EXPORT_PACKAGE_AUDIT
      (EXPORT_PACKAGE_AUDIT_ID,
       PACKAGE_NUMBER,
       APPLICATION_NUMBER,
       Package_Reprocessed_Indicator,
       Package_Volume,
       Average_Length,
       Average_Diameter,
       Comments,
       Package_Fee,
       EXPORT_FED_PERMIT_DETAIL_ID,
       EXPORT_INDIAN_RSRV_PRMT_DTL_ID,
       Export_Package_Status_Code,
       ENTRY_USERID,
       ENTRY_TIMESTAMP,
       UPDATE_USERID,
       UPDATE_TIMESTAMP,
       DELETE_USERID,
       DELETE_TIMESTAMP)
      SELECT V_PACKAGE_AUDIT_ID,
             EP.PACKAGE_NUMBER,
             EP.APPLICATION_NUMBER,
             EP.Package_Reprocessed_Indicator,
             EP.Package_Volume,
             EP.Average_Length,
             EP.Average_Diameter,
             EP.Comments,
             EP.Package_Fee,
             EP.EXPORT_FED_PERMIT_DETAIL_ID,
             EP.EXPORT_INDIAN_RSRV_PRMT_DTL_ID,
             EP.Export_Package_Status_Code,
             EP.ENTRY_USERID,
             EP.ENTRY_TIMESTAMP,
             EP.UPDATE_USERID,
             EP.UPDATE_TIMESTAMP,
             V_DELETE_USERID,
             SYSDATE
        FROM EXPORT_PACKAGE EP
       WHERE EP.PACKAGE_NUMBER = P_PACKAGE_NUMBER;

    DELETE_END_USE_PACKAGE(P_PACKAGE_NUMBER);

    -- delete the record
    DELETE FROM EXPORT_PACKAGE EP
       WHERE EP.PACKAGE_NUMBER = P_PACKAGE_NUMBER;

  END DELETE_PACKAGE;

  /******************************************************************************
      Procedure:  INSERT_EXEMPTION
      Purpose: Adds a new exemption
  ******************************************************************************/
  PROCEDURE INSERT_EXEMPTION(P_EXEMPTION_NUMBER             IN EXPORT_EXEMPTION.EXEMPTION_NUMBER%TYPE,
                             P_APPROVED_VOLUME              IN EXPORT_EXEMPTION.APPROVED_VOLUME%TYPE,
                             P_APPROVAL_DATE                IN EXPORT_EXEMPTION.APPROVAL_DATE%TYPE,
                             P_EXPIRY_DATE                  IN EXPORT_EXEMPTION.EXPIRY_DATE%TYPE,
                             P_OTHER_CONDITIONS             IN EXPORT_EXEMPTION.OTHER_CONDITIONS%TYPE,
                             P_EXPORT_EXEMPTION_TYPE_CODE   IN EXPORT_EXEMPTION.EXPORT_EXEMPTION_TYPE_CODE%TYPE,
                             P_EXPORT_EXEMPTION_STATUS_CODE IN EXPORT_EXEMPTION.EXPORT_EXEMPTION_STATUS_CODE%TYPE,
                             P_ENTRY_USERID                 IN EXPORT_EXEMPTION.ENTRY_USERID%TYPE,
                             P_ENTRY_TIMESTAMP              IN EXPORT_EXEMPTION.ENTRY_TIMESTAMP%TYPE,
                             P_UPDATE_USERID                IN EXPORT_EXEMPTION.UPDATE_USERID%TYPE,
                             P_UPDATE_TIMESTAMP             IN EXPORT_EXEMPTION.UPDATE_TIMESTAMP%TYPE,
                             P_EXEMPTION                    IN OUT ref_exemption) IS

    V_EXEMPTION_NUMBER EXPORT_EXEMPTION.EXEMPTION_NUMBER%TYPE;

  BEGIN

    IF P_EXEMPTION_NUMBER IS NOT NULL THEN
      V_EXEMPTION_NUMBER := P_EXEMPTION_NUMBER;
    ELSE
      SELECT to_char(sysdate, 'YY') || '-' || EXPORT_EXEMPTION_SEQ.NEXTVAL
        INTO V_EXEMPTION_NUMBER
        FROM DUAL;
    END IF;

    INSERT INTO EXPORT_EXEMPTION EE
      (EXEMPTION_NUMBER,
       APPROVED_VOLUME,
       APPROVAL_DATE,
       EXPIRY_DATE,
       OTHER_CONDITIONS,
       EXPORT_EXEMPTION_TYPE_CODE,
       EXPORT_EXEMPTION_STATUS_CODE,
       ENTRY_USERID,
       ENTRY_TIMESTAMP,
       UPDATE_USERID,
       UPDATE_TIMESTAMP)
    VALUES
      (V_EXEMPTION_NUMBER,
       P_APPROVED_VOLUME,
       P_APPROVAL_DATE,
       P_EXPIRY_DATE,
       P_OTHER_CONDITIONS,
       P_EXPORT_EXEMPTION_TYPE_CODE,
       P_EXPORT_EXEMPTION_STATUS_CODE,
       P_ENTRY_USERID,
       P_ENTRY_TIMESTAMP,
       P_UPDATE_USERID,
       P_UPDATE_TIMESTAMP);

    FIND_EXEMPTION_BY_NUMBER(V_EXEMPTION_NUMBER, P_EXEMPTION);

  END INSERT_EXEMPTION;

  /******************************************************************************
      Procedure:  UPDATE_EXEMPTION
      Purpose: Updates an existing exemption
  ******************************************************************************/
  PROCEDURE UPDATE_EXEMPTION(P_EXEMPTION_NUMBER             IN EXPORT_EXEMPTION.EXEMPTION_NUMBER%TYPE,
                             P_APPROVED_VOLUME              IN EXPORT_EXEMPTION.APPROVED_VOLUME%TYPE,
                             P_APPROVAL_DATE                IN EXPORT_EXEMPTION.APPROVAL_DATE%TYPE,
                             P_EXPIRY_DATE                  IN EXPORT_EXEMPTION.EXPIRY_DATE%TYPE,
                             P_OTHER_CONDITIONS             IN EXPORT_EXEMPTION.OTHER_CONDITIONS%TYPE,
                             P_EXPORT_EXEMPTION_TYPE_CODE   IN EXPORT_EXEMPTION.EXPORT_EXEMPTION_TYPE_CODE%TYPE,
                             P_EXPORT_EXEMPTION_STATUS_CODE IN EXPORT_EXEMPTION.EXPORT_EXEMPTION_STATUS_CODE%TYPE,
                             P_ENTRY_USERID                 IN EXPORT_EXEMPTION.ENTRY_USERID%TYPE,
                             P_ENTRY_TIMESTAMP              IN EXPORT_EXEMPTION.ENTRY_TIMESTAMP%TYPE,
                             P_UPDATE_USERID                IN EXPORT_EXEMPTION.UPDATE_USERID%TYPE,
                             P_UPDATE_TIMESTAMP             IN EXPORT_EXEMPTION.UPDATE_TIMESTAMP%TYPE,
                             P_OLD_EXEMPTION_NUMBER         IN EXPORT_EXEMPTION.EXEMPTION_NUMBER%TYPE) IS

    V_AUDIT_ID EXPORT_EXEMPTION_AUDIT.EXPORT_EXEMPTION_AUDIT_ID%TYPE;

  BEGIN

    SELECT EXPORT_EXEMPTION_AUDIT_SEQ.NEXTVAL INTO V_AUDIT_ID FROM DUAL;

    INSERT INTO EXPORT_EXEMPTION_AUDIT
      (EXPORT_EXEMPTION_AUDIT_ID,
       EXEMPTION_NUMBER,
       APPROVED_VOLUME,
       EXPORT_EXEMPTION_TYPE_CODE,
       EXPORT_EXEMPTION_STATUS_CODE,
       APPROVAL_DATE,
       EXPIRY_DATE,
       OTHER_CONDITIONS,
       ENTRY_USERID,
       ENTRY_TIMESTAMP,
       UPDATE_USERID,
       UPDATE_TIMESTAMP,
       DELETE_USERID,
       DELETE_TIMESTAMP)
      SELECT V_AUDIT_ID,
             EE.EXEMPTION_NUMBER,
             EE.APPROVED_VOLUME,
             EE.EXPORT_EXEMPTION_TYPE_CODE,
             EE.EXPORT_EXEMPTION_STATUS_CODE,
             EE.APPROVAL_DATE,
             EE.EXPIRY_DATE,
             EE.OTHER_CONDITIONS,
             EE.ENTRY_USERID,
             EE.ENTRY_TIMESTAMP,
             EE.UPDATE_USERID,
             EE.UPDATE_TIMESTAMP,
             NULL,
             NULL
        FROM EXPORT_EXEMPTION EE
       WHERE EE.EXEMPTION_NUMBER = P_OLD_EXEMPTION_NUMBER;

      UPDATE EXPORT_EXEMPTION_RATE EER
       SET EER.EXEMPTION_NUMBER = P_EXEMPTION_NUMBER,
           EER.UPDATE_USERID    = P_UPDATE_USERID,
           EER.UPDATE_TIMESTAMP = P_UPDATE_TIMESTAMP
     WHERE EER.EXEMPTION_NUMBER = P_OLD_EXEMPTION_NUMBER;

      UPDATE EXPORT_EXEMPT_FILE_ATTCHMNT EEFA
       SET EEFA.EXEMPTION_NUMBER = P_EXEMPTION_NUMBER
     WHERE EEFA.EXEMPTION_NUMBER = P_OLD_EXEMPTION_NUMBER;

      UPDATE OIC_EXEMPTION_ORG_UNIT OEOU
       SET OEOU.EXEMPTION_NUMBER = P_EXEMPTION_NUMBER
     WHERE OEOU.EXEMPTION_NUMBER = P_OLD_EXEMPTION_NUMBER;

    UPDATE EXPORT_EXEMPTION_APPLICATION EEA
     SET EEA.EXEMPTION_NUMBER = P_EXEMPTION_NUMBER
     WHERE EEA.EXEMPTION_NUMBER = P_OLD_EXEMPTION_NUMBER;

   UPDATE EXPORT_PERMIT_DETAIL EPD
     SET EPD.EXEMPTION_NUMBER = P_EXEMPTION_NUMBER
     WHERE EPD.EXEMPTION_NUMBER = P_OLD_EXEMPTION_NUMBER;

    UPDATE EXPORT_EXEMPTION EE
       SET APPROVED_VOLUME              = P_APPROVED_VOLUME,
           APPROVAL_DATE                = P_APPROVAL_DATE,
           EXPIRY_DATE                  = P_EXPIRY_DATE,
           OTHER_CONDITIONS             = P_OTHER_CONDITIONS,
           EXPORT_EXEMPTION_TYPE_CODE   = P_EXPORT_EXEMPTION_TYPE_CODE,
           EXPORT_EXEMPTION_STATUS_CODE = P_EXPORT_EXEMPTION_STATUS_CODE,
           ENTRY_USERID                 = P_ENTRY_USERID,
           ENTRY_TIMESTAMP              = P_ENTRY_TIMESTAMP,
           UPDATE_USERID                = P_UPDATE_USERID,
           UPDATE_TIMESTAMP             = P_UPDATE_TIMESTAMP,
           EXEMPTION_NUMBER             = P_EXEMPTION_NUMBER
     WHERE EE.EXEMPTION_NUMBER = P_OLD_EXEMPTION_NUMBER;
  END UPDATE_EXEMPTION;

  /******************************************************************************
      Procedure:  DELETE_EXEMPTION
      Purpose: Deletes an existing exemption
  ******************************************************************************/
  PROCEDURE DELETE_EXEMPTION(P_EXEMPTION_NUMBER IN EXPORT_EXEMPTION.EXEMPTION_NUMBER%TYPE) IS
  V_ROW_COUNT number;
  BEGIN

    SELECT count(T.EXEMPTION_NUMBER)
      INTO V_ROW_COUNT
      from EXPORT_EXEMPTION_APPLICATION T
     WHERE T.EXEMPTION_NUMBER = P_EXEMPTION_NUMBER;
    if V_ROW_COUNT > 0 THEN
         DELETE FROM EXPORT_EXEMPTION_APPLICATION EEA
         WHERE EEA.EXEMPTION_NUMBER = P_EXEMPTION_NUMBER;
    END IF;
    SELECT count(T.EXEMPTION_NUMBER)
      INTO V_ROW_COUNT
      from EXPORT_EXEMPTION_RATE T
     WHERE T.EXEMPTION_NUMBER = P_EXEMPTION_NUMBER;
    if V_ROW_COUNT > 0 THEN
         DELETE FROM EXPORT_EXEMPTION_RATE EER
         WHERE EER.EXEMPTION_NUMBER = P_EXEMPTION_NUMBER;
    END IF;
    SELECT count(T.EXEMPTION_NUMBER)
      INTO V_ROW_COUNT
      from EXPORT_EXEMPT_FILE_ATTCHMNT T
     WHERE T.EXEMPTION_NUMBER = P_EXEMPTION_NUMBER;
    if V_ROW_COUNT > 0 THEN
         DELETE FROM EXPORT_EXEMPT_FILE_ATTCHMNT EEFA
         WHERE EEFA.EXEMPTION_NUMBER = P_EXEMPTION_NUMBER;
    END IF;
    SELECT count(T.EXEMPTION_NUMBER)
      INTO V_ROW_COUNT
      from EXPORT_PERMIT_DETAIL T
     WHERE T.EXEMPTION_NUMBER = P_EXEMPTION_NUMBER;
    if V_ROW_COUNT > 0 THEN
         DELETE FROM EXPORT_PERMIT_DETAIL EPD
         WHERE EPD.EXEMPTION_NUMBER = P_EXEMPTION_NUMBER;
    END IF;
    SELECT count(T.EXEMPTION_NUMBER)
      INTO V_ROW_COUNT
      from OIC_EXEMPTION_ORG_UNIT T
     WHERE T.EXEMPTION_NUMBER = P_EXEMPTION_NUMBER;
    if V_ROW_COUNT > 0 THEN
         DELETE FROM OIC_EXEMPTION_ORG_UNIT OEOU
         WHERE OEOU.EXEMPTION_NUMBER = P_EXEMPTION_NUMBER;
    END IF;

    DELETE FROM EXPORT_EXEMPTION EE
     WHERE EE.EXEMPTION_NUMBER = P_EXEMPTION_NUMBER;

  END DELETE_EXEMPTION;

