       P_CLIENT_LOCATION_CODE,
       P_AGENT_NUMBER,
       P_AGENT_LOCATION_CODE,
       P_EXEMPTION_NUMBER,
       P_ORG_UNIT_NO,
       P_EXPORT_PORT_OF_EXPORT_CODE,
       P_EXPORT_PERMIT_STATUS_CODE,
       P_EXPORT_GROWTH_TYPE_CODE,
       P_EXPORT_COUNTRY_CODE,
       P_OVERRIDE_FEE,
       P_OVERRIDE_COMMENT,
       P_OIC_APPLICATION_NUMBER,
       P_OIC_REQUEST_PIECES,
       P_OIC_REQUEST_VOLUME,
       P_EXPORT_PRODUCT_TYPE_CODE);

    FIND_PERMIT_DET_BY_ID(V_P_NUMBER, R_PERMIT_DETAIL);

  END INSERT_PERMIT_DETAIL;

  /******************************************************************************
      Procedure:  UPDATE_PERMIT_DETAIL
      Purpose: Updates a provincial permit
  ******************************************************************************/
  PROCEDURE UPDATE_PERMIT_DETAIL(P_EXPORT_PERMIT_DETAIL_NUMBER IN EXPORT_PERMIT_DETAIL.EXPORT_PERMIT_DETAIL_NUMBER%TYPE,
                                 P_DESTINATION_COMPANY_NAME    IN EXPORT_PERMIT_DETAIL.DESTINATION_COMPANY_NAME%TYPE,
                                 P_TRANSPORT_NAME              IN EXPORT_PERMIT_DETAIL.TRANSPORT_NAME%TYPE,
                                 P_ESTIMATED_SHIPPING_DATE     IN EXPORT_PERMIT_DETAIL.ESTIMATED_SHIPPING_DATE%TYPE,
                                 P_OTHER_PORT_OF_EXPORT        IN EXPORT_PERMIT_DETAIL.OTHER_PORT_OF_EXPORT%TYPE,
                                 P_APPLICATION_DATE            IN EXPORT_PERMIT_DETAIL.APPLICATION_DATE%TYPE,
                                 P_RECEIVED_DATE               IN EXPORT_PERMIT_DETAIL.RECEIVED_DATE%TYPE,
                                 P_EXPORT_PERMIT_ISSUE_DATE    IN OUT EXPORT_PERMIT_DETAIL.EXPORT_PERMIT_ISSUE_DATE%TYPE,
                                 P_RECEIPT_NUMBER              IN EXPORT_PERMIT_DETAIL.RECEIPT_NUMBER%TYPE,
                                 P_EXPIRY_DATE                 IN EXPORT_PERMIT_DETAIL.EXPIRY_DATE%TYPE,
                                 P_PERMIT_VOLUME               IN EXPORT_PERMIT_DETAIL.PERMIT_VOLUME%TYPE,
                                 P_NUMBER_OF_PIECES            IN EXPORT_PERMIT_DETAIL.NUMBER_OF_PIECES%TYPE,
                                 P_FEE_IN_LIEU_VOLUME          IN EXPORT_PERMIT_DETAIL.FEE_IN_LIEU_VOLUME%TYPE,
                                 P_FEDERAL_PERMIT_NUMBER       IN EXPORT_PERMIT_DETAIL.FEDERAL_PERMIT_NUMBER%TYPE,
                                 P_REMARKS                     IN EXPORT_PERMIT_DETAIL.REMARKS%TYPE,
                                 P_ENTRY_USERID                IN EXPORT_PERMIT_DETAIL.ENTRY_USERID%TYPE,
                                 P_ENTRY_TIMESTAMP             IN EXPORT_PERMIT_DETAIL.ENTRY_TIMESTAMP%TYPE,
                                 P_UPDATE_USERID               IN EXPORT_PERMIT_DETAIL.UPDATE_USERID%TYPE,
                                 P_UPDATE_TIMESTAMP            IN EXPORT_PERMIT_DETAIL.UPDATE_TIMESTAMP%TYPE,
                                 P_EXPORT_TRANSPORT_TYPE_CODE  IN EXPORT_PERMIT_DETAIL.EXPORT_TRANSPORT_TYPE_CODE%TYPE,
                                 P_EXPORT_SCALE_METHOD_CODE    IN EXPORT_PERMIT_DETAIL.EXPORT_SCALE_METHOD_CODE%TYPE,
                                 P_CLIENT_NUMBER               IN EXPORT_PERMIT_DETAIL.CLIENT_NUMBER%TYPE,
                                 P_CLIENT_LOCATION_CODE        IN EXPORT_PERMIT_DETAIL.CLIENT_LOCN_CODE%TYPE,
                                 P_AGENT_NUMBER                IN EXPORT_PERMIT_DETAIL.AGENT_NUMBER%TYPE,
                                 P_AGENT_LOCATION_CODE         IN EXPORT_PERMIT_DETAIL.AGENT_LOCN_CODE%TYPE,
                                 P_EXEMPTION_NUMBER            IN EXPORT_PERMIT_DETAIL.EXEMPTION_NUMBER%TYPE,
                                 P_ORG_UNIT_NO                 IN EXPORT_PERMIT_DETAIL.ORG_UNIT_NO%TYPE,
                                 P_EXPORT_PORT_OF_EXPORT_CODE  IN EXPORT_PERMIT_DETAIL.EXPORT_PORT_OF_EXPORT_CODE%TYPE,
                                 P_EXPORT_PERMIT_STATUS_CODE   IN EXPORT_PERMIT_DETAIL.EXPORT_PERMIT_STATUS_CODE%TYPE,
                                 P_EXPORT_GROWTH_TYPE_CODE     IN EXPORT_PERMIT_DETAIL.EXPORT_GROWTH_TYPE_CODE%TYPE,
                                 P_EXPORT_COUNTRY_CODE         IN EXPORT_PERMIT_DETAIL.EXPORT_COUNTRY_CODE%TYPE,
                                 P_OVERRIDE_FEE                IN EXPORT_PERMIT_DETAIL.OVERRIDE_FEE%TYPE,
                                 P_OVERRIDE_COMMENT            IN EXPORT_PERMIT_DETAIL.OVERRIDE_COMMENT%TYPE,
                                 P_OIC_APPLICATION_NUMBER      IN EXPORT_PERMIT_DETAIL.OIC_APPLICATION_NUMBER%TYPE,
                                 P_OIC_REQUEST_PIECES         IN EXPORT_PERMIT_DETAIL.OIC_REQUEST_PIECES%TYPE,
                                 P_OIC_REQUEST_VOLUME         IN EXPORT_PERMIT_DETAIL.OIC_REQUEST_VOLUME%TYPE,
                                 P_EXPORT_PRODUCT_TYPE_CODE    IN EXPORT_PERMIT_DETAIL.EXPORT_PRODUCT_TYPE_CODE%TYPE,
                                 P_TWO_ELEVEN_IMPLEMENT_DATE IN DATE) IS

    V_PERMIT_AUDIT_ID EXPORT_PERMIT_AUDIT.EXPORT_PERMIT_AUDIT_ID%TYPE;
    V_DO_FIL_REFRESH BOOLEAN;
    V_PREVIOUS_PERMIT_VOLUME EXPORT_PERMIT_DETAIL.PERMIT_VOLUME%TYPE;
    V_PREVIOUS_OVERRIDE_FEE EXPORT_PERMIT_DETAIL.Override_Fee%TYPE;
    V_PREVIOUS_APPLICATION_DATE EXPORT_PERMIT_DETAIL.APPLICATION_DATE%TYPE;
    V_PREVIOUS_ISSUE_DATE EXPORT_PERMIT_DETAIL.EXPORT_PERMIT_ISSUE_DATE%TYPE;
    V_PREVIOUS_EXPORT_STATUS_CODE EXPORT_PERMIT_DETAIL.EXPORT_PERMIT_STATUS_CODE%TYPE;
    V_ORG_UNIT_NO EXPORT_PERMIT_DETAIL.ORG_UNIT_NO%TYPE;
    V_GRADE_CODE    EXPORT_SCALE_DETAIL.EXPORT_GRADE_CODE%TYPE;
    V_EXEMPTION_NUMBER  EXPORT_PERMIT_DETAIL.EXEMPTION_NUMBER%TYPE;
    v_exemption_type_code    export_exemption.export_exemption_type_code%type;
    V_PREVIOUS_COUNTRY_CODE    EXPORT_PERMIT_DETAIL.export_country_code%type;
    V_PREVIOUS_TOTAL_FEE   EXPORT_PERMIT_DETAIL.PERMIT_TOTAL_FEE%type;
  BEGIN
    V_DO_FIL_REFRESH := FALSE;

    SELECT epd.permit_volume, epd.override_fee, epd.application_date, epd.export_permit_issue_date, epd.export_permit_status_code , epd.org_unit_no , epd.exemption_number, epd.export_country_code,epd.permit_total_fee
     INTO V_PREVIOUS_PERMIT_VOLUME, V_PREVIOUS_OVERRIDE_FEE, V_PREVIOUS_APPLICATION_DATE, V_PREVIOUS_ISSUE_DATE, V_PREVIOUS_EXPORT_STATUS_CODE, V_ORG_UNIT_NO, V_EXEMPTION_NUMBER, V_PREVIOUS_COUNTRY_CODE,V_PREVIOUS_TOTAL_FEE
     FROM EXPORT_PERMIT_DETAIL epd WHERE epd.export_permit_detail_number = P_EXPORT_PERMIT_DETAIL_NUMBER;

      select ee.export_exemption_type_code into v_exemption_type_code from export_exemption ee where ee.exemption_number=V_EXEMPTION_NUMBER;

    --set issue date to null if pushing back
    IF ((V_PREVIOUS_EXPORT_STATUS_CODE = 'CAN' OR V_PREVIOUS_EXPORT_STATUS_CODE = 'COM') AND P_EXPORT_PERMIT_STATUS_CODE = 'ACT') THEN
      P_EXPORT_PERMIT_ISSUE_DATE := null;
    END IF;

     IF (V_PREVIOUS_PERMIT_VOLUME != P_PERMIT_VOLUME AND P_APPLICATION_DATE >= P_TWO_ELEVEN_IMPLEMENT_DATE)
       OR ((case when V_PREVIOUS_OVERRIDE_FEE is null then 0 else V_PREVIOUS_OVERRIDE_FEE end != CASE WHEN P_OVERRIDE_FEE is null THEN 0 ELSE P_OVERRIDE_FEE END) AND (P_APPLICATION_DATE >= P_TWO_ELEVEN_IMPLEMENT_DATE))
       OR P_APPLICATION_DATE IS NULL OR (((V_PREVIOUS_COUNTRY_CODE ='CA' AND V_PREVIOUS_TOTAL_FEE IS NOT NULL) OR P_EXPORT_COUNTRY_CODE !=V_PREVIOUS_COUNTRY_CODE) AND P_APPLICATION_DATE >= P_TWO_ELEVEN_IMPLEMENT_DATE) THEN
            V_DO_FIL_REFRESH := TRUE;
    END IF;
    SELECT EXPORT_PERMIT_AUDIT_SEQ.NEXTVAL
      INTO V_PERMIT_AUDIT_ID
      FROM DUAL;

    INSERT INTO EXPORT_PERMIT_AUDIT
      (EXPORT_PERMIT_AUDIT_ID,
       EXPORT_PERMIT_DETAIL_NUMBER,
       DESTINATION_COMPANY_NAME,
       TRANSPORT_NAME,
       ESTIMATED_SHIPPING_DATE,
       OTHER_PORT_OF_EXPORT,
       APPLICATION_DATE,
       RECEIVED_DATE,
       EXPORT_PERMIT_ISSUE_DATE,
       RECEIPT_NUMBER,
       EXPIRY_DATE,
       PERMIT_VOLUME,
       NUMBER_OF_PIECES,
       FEE_IN_LIEU_VOLUME,
       FEDERAL_PERMIT_NUMBER,
       REMARKS,
       CLIENT_NUMBER,
       CLIENT_LOCN_CODE,
       AGENT_NUMBER,
       AGENT_LOCN_CODE,
       EXEMPTION_NUMBER,
       ORG_UNIT_NO,
       EXPORT_SCALE_METHOD_CODE,
       EXPORT_TRANSPORT_TYPE_CODE,
       EXPORT_PORT_OF_EXPORT_CODE,
       EXPORT_PERMIT_STATUS_CODE,
       EXPORT_COUNTRY_CODE,
       EXPORT_GROWTH_TYPE_CODE,
       OVERRIDE_FEE,
       OVERRIDE_COMMENT,
       OIC_APPLICATION_NUMBER,
       OIC_REQUEST_PIECES,
       OIC_REQUEST_VOLUME,
       ENTRY_USERID,
       ENTRY_TIMESTAMP,
       UPDATE_USERID,
       UPDATE_TIMESTAMP,
       DELETE_USERID,
       DELETE_TIMESTAMP,
       PERMIT_TOTAL_FEE,
       PERMIT_OVERRIDE_FEE_IND)
      SELECT V_PERMIT_AUDIT_ID,
             EPD.EXPORT_PERMIT_DETAIL_NUMBER,
             EPD.DESTINATION_COMPANY_NAME,
             EPD.TRANSPORT_NAME,
             EPD.ESTIMATED_SHIPPING_DATE,
             EPD.OTHER_PORT_OF_EXPORT,
             EPD.APPLICATION_DATE,
             EPD.RECEIVED_DATE,
             EPD.EXPORT_PERMIT_ISSUE_DATE,
             EPD.RECEIPT_NUMBER,
             EPD.EXPIRY_DATE,
             EPD.PERMIT_VOLUME,
             EPD.NUMBER_OF_PIECES,
             EPD.FEE_IN_LIEU_VOLUME,
             EPD.FEDERAL_PERMIT_NUMBER,
             EPD.REMARKS,
             EPD.CLIENT_NUMBER,
             EPD.CLIENT_LOCN_CODE,
             EPD.AGENT_NUMBER,
             EPD.AGENT_LOCN_CODE,
             EPD.EXEMPTION_NUMBER,
             EPD.ORG_UNIT_NO,
             EPD.EXPORT_SCALE_METHOD_CODE,
             EPD.EXPORT_TRANSPORT_TYPE_CODE,
             EPD.EXPORT_PORT_OF_EXPORT_CODE,
             EPD.EXPORT_PERMIT_STATUS_CODE,
             EPD.EXPORT_COUNTRY_CODE,
             EPD.EXPORT_GROWTH_TYPE_CODE,
             EPD.OVERRIDE_FEE,
             EPD.OVERRIDE_COMMENT,
             EPD.OIC_APPLICATION_NUMBER,
             EPD.OIC_REQUEST_PIECES,
             EPD.OIC_REQUEST_VOLUME,
             EPD.ENTRY_USERID,
             EPD.ENTRY_TIMESTAMP,
             EPD.UPDATE_USERID,
             EPD.UPDATE_TIMESTAMP,
             NULL,
             NULL,
             EPD.PERMIT_TOTAL_FEE,
             EPD.PERMIT_OVERRIDE_FEE_IND
        FROM EXPORT_PERMIT_DETAIL EPD
       WHERE EPD.EXPORT_PERMIT_DETAIL_NUMBER =
             P_EXPORT_PERMIT_DETAIL_NUMBER;


    UPDATE EXPORT_PERMIT_DETAIL EPD
       SET DESTINATION_COMPANY_NAME   = P_DESTINATION_COMPANY_NAME,
           TRANSPORT_NAME             = P_TRANSPORT_NAME,
           ESTIMATED_SHIPPING_DATE    = P_ESTIMATED_SHIPPING_DATE,
           OTHER_PORT_OF_EXPORT       = P_OTHER_PORT_OF_EXPORT,
           APPLICATION_DATE           = P_APPLICATION_DATE,
           RECEIVED_DATE              = P_RECEIVED_DATE,
           EXPORT_PERMIT_ISSUE_DATE   = P_EXPORT_PERMIT_ISSUE_DATE,
           RECEIPT_NUMBER             = P_RECEIPT_NUMBER,
           EXPIRY_DATE                = P_EXPIRY_DATE,
           PERMIT_VOLUME              = P_PERMIT_VOLUME,
           NUMBER_OF_PIECES           = P_NUMBER_OF_PIECES,
           FEE_IN_LIEU_VOLUME         = P_FEE_IN_LIEU_VOLUME,
           FEDERAL_PERMIT_NUMBER      = P_FEDERAL_PERMIT_NUMBER,
           REMARKS                    = P_REMARKS,
           ENTRY_USERID               = P_ENTRY_USERID,
           ENTRY_TIMESTAMP            = P_ENTRY_TIMESTAMP,
           UPDATE_USERID              = P_UPDATE_USERID,
           UPDATE_TIMESTAMP           = P_UPDATE_TIMESTAMP,
           EXPORT_TRANSPORT_TYPE_CODE = P_EXPORT_TRANSPORT_TYPE_CODE,
           EXPORT_SCALE_METHOD_CODE   = P_EXPORT_SCALE_METHOD_CODE,
           CLIENT_NUMBER              = P_CLIENT_NUMBER,
           CLIENT_LOCN_CODE           = P_CLIENT_LOCATION_CODE,
           AGENT_NUMBER               = P_AGENT_NUMBER,
           AGENT_LOCN_CODE            = P_AGENT_LOCATION_CODE,
           EXEMPTION_NUMBER           = P_EXEMPTION_NUMBER,
           ORG_UNIT_NO                = P_ORG_UNIT_NO,
           EXPORT_PORT_OF_EXPORT_CODE = P_EXPORT_PORT_OF_EXPORT_CODE,
           EXPORT_PERMIT_STATUS_CODE  = P_EXPORT_PERMIT_STATUS_CODE,
           EXPORT_COUNTRY_CODE        = P_EXPORT_COUNTRY_CODE,
           EXPORT_GROWTH_TYPE_CODE    = P_EXPORT_GROWTH_TYPE_CODE,
           OVERRIDE_FEE               = P_OVERRIDE_FEE,
           OVERRIDE_COMMENT           = P_OVERRIDE_COMMENT,
           OIC_APPLICATION_NUMBER     = P_OIC_APPLICATION_NUMBER,
           OIC_REQUEST_PIECES         = P_OIC_REQUEST_PIECES,
           OIC_REQUEST_VOLUME         = P_OIC_REQUEST_VOLUME,
           EXPORT_PRODUCT_TYPE_CODE   = P_EXPORT_PRODUCT_TYPE_CODE,
           PERMIT_OVERRIDE_FEE_IND    = CASE WHEN P_OVERRIDE_FEE IS NULL or P_OVERRIDE_FEE = '0' THEN 'N' ELSE 'Y' END
     WHERE EPD.EXPORT_PERMIT_DETAIL_NUMBER = P_EXPORT_PERMIT_DETAIL_NUMBER;


     IF V_DO_FIL_REFRESH THEN

      SET_FIL_CALULATED_VALUES(P_EXPORT_PERMIT_DETAIL_NUMBER);

   END IF;

  END UPDATE_PERMIT_DETAIL;

  /******************************************************************************
      Procedure:  INSERT_SALES_INVOICE
      Purpose: Adds a new sales invoice
  ******************************************************************************/
  PROCEDURE INSERT_SALES_INVOICE(P_EXPORT_SALES_INVOICE_NUMBER IN EXPORT_SALES_INVOICE.EXPORT_SALES_INVOICE_NUMBER%TYPE,
                                 P_EXPORT_PERMIT_DETAIL_NUMBER IN EXPORT_SALES_INVOICE.EXPORT_PERMIT_DETAIL_NUMBER%TYPE,
                                 P_EXPORT_VALUE                IN EXPORT_SALES_INVOICE.EXPORT_VALUE%TYPE,
                                 P_CURRENCY_CONVERSION_RATE    IN EXPORT_SALES_INVOICE.CURRENCY_CONVERSION_RATE%TYPE,
                                 P_FEE_IN_LIEU                 IN EXPORT_SALES_INVOICE.FEE_IN_LIEU%TYPE,
                                 P_ENTRY_USERID                IN EXPORT_SALES_INVOICE.ENTRY_USERID%TYPE,
                                 P_ENTRY_TIMESTAMP             IN EXPORT_SALES_INVOICE.ENTRY_TIMESTAMP%TYPE,
                                 P_UPDATE_USERID               IN EXPORT_SALES_INVOICE.UPDATE_USERID%TYPE,
                                 P_UPDATE_TIMESTAMP            IN EXPORT_SALES_INVOICE.UPDATE_TIMESTAMP%TYPE,
                                 R_INVOICE                     IN OUT ref_sales_invoice) IS

  BEGIN
    INSERT INTO EXPORT_SALES_INVOICE ESI
      (EXPORT_SALES_INVOICE_NUMBER,
       EXPORT_PERMIT_DETAIL_NUMBER,
       EXPORT_VALUE,
       CURRENCY_CONVERSION_RATE,
       FEE_IN_LIEU,
       ENTRY_USERID,
       ENTRY_TIMESTAMP,
       UPDATE_USERID,
       UPDATE_TIMESTAMP)
    VALUES
      (P_EXPORT_SALES_INVOICE_NUMBER,
       P_EXPORT_PERMIT_DETAIL_NUMBER,
       P_EXPORT_VALUE,
       P_CURRENCY_CONVERSION_RATE,
       P_FEE_IN_LIEU,
       P_ENTRY_USERID,
       P_ENTRY_TIMESTAMP,
       P_UPDATE_USERID,
       P_UPDATE_TIMESTAMP);

    FIND_INVOICE_BY_ID(P_EXPORT_SALES_INVOICE_NUMBER,
                       P_EXPORT_PERMIT_DETAIL_NUMBER,
                       R_INVOICE);

  END INSERT_SALES_INVOICE;

  /******************************************************************************
      Procedure:  FIND_FILE_ATTACHMENT_DETAIL
      Purpose: Retrieves file attachment details.
  ******************************************************************************/
  PROCEDURE FIND_FILE_ATTACHMENT_DETAIL(P_FILE_ID                IN EXPORT_FILE_ATTACHMENT.EXPORT_ATTACHMENT_ID%TYPE,
                                        P_FILE_ATTACHMENT_RETURN IN OUT ref_file_attachment_detail) IS
  BEGIN

    OPEN P_FILE_ATTACHMENT_RETURN FOR
      SELECT F.EXPORT_ATTACHMENT_ID,
             F.FILE_NAME,
             F.DESCRIPTION,
             F.EXPORT_FILE_TYPE_CODE,
             F.EXPORT_ATTACHMENT_TYPE_CODE,
             F.EXPORT_FILE_MIME_TYPE_CODE,
             F.Entry_Userid,
             F.Entry_Timestamp,
             F.Update_Userid,
             F.Update_Timestamp
        FROM EXPORT_FILE_ATTACHMENT F
       WHERE F.EXPORT_ATTACHMENT_ID = P_FILE_ID;

  END FIND_FILE_ATTACHMENT_DETAIL;

  /******************************************************************************
      Procedure:  INSERT_FILE_ATTACHMENT_DETAIL
      Purpose: Insert file attachment details.
  ******************************************************************************/
  PROCEDURE INSERT_FILE_ATTACHMENT_DETAIL(P_EXPORT_ATTACHMENT_ID   IN EXPORT_FILE_ATTACHMENT.EXPORT_ATTACHMENT_ID%TYPE,
                                          P_FILE_NAME              IN EXPORT_FILE_ATTACHMENT.File_Name%TYPE,
                                          P_FILE_DESCRIPTION       IN EXPORT_FILE_ATTACHMENT.DESCRIPTION%TYPE,
                                          P_FILE_ATTACHMENT_TYPE   IN EXPORT_FILE_ATTACHMENT.EXPORT_ATTACHMENT_TYPE_CODE%TYPE,
                                          P_FILE_EXTENSION_CODE    IN EXPORT_FILE_ATTACHMENT.EXPORT_FILE_TYPE_CODE%TYPE,
                                          P_ENTRY_USER             IN EXPORT_FILE_ATTACHMENT.ENTRY_USERID%TYPE,
                                          P_ENTRY_DATE             IN EXPORT_FILE_ATTACHMENT.Entry_Timestamp%TYPE,
                                          P_UPDATE_USER            IN EXPORT_FILE_ATTACHMENT.Update_Userid%TYPE,
                                          P_UPDATE_DATE            IN EXPORT_FILE_ATTACHMENT.Update_Timestamp%TYPE,
                                          P_FILE_ATTACHMENT_RETURN IN OUT ref_file_attachment_detail) IS
  BEGIN

    INSERT INTO EXPORT_FILE_ATTACHMENT
      (EXPORT_ATTACHMENT_ID,
       File_Name,
       DESCRIPTION,
       EXPORT_FILE_TYPE_CODE,
       EXPORT_File_Mime_Type_Code,
       EXPORT_ATTACHMENT_TYPE_CODE,
       Entry_Userid,
       Entry_Timestamp,
       Update_Userid,
       Update_Timestamp)
    VALUES
      (P_EXPORT_ATTACHMENT_ID,
       P_FILE_NAME,
       P_FILE_DESCRIPTION,
       P_FILE_EXTENSION_CODE,
       P_FILE_EXTENSION_CODE,
       P_FILE_ATTACHMENT_TYPE,
       P_ENTRY_USER,
       P_ENTRY_DATE,
       P_UPDATE_USER,
       P_UPDATE_DATE);

    FIND_FILE_ATTACHMENT_DETAIL(P_EXPORT_ATTACHMENT_ID,
                                P_FILE_ATTACHMENT_RETURN);
  END INSERT_FILE_ATTACHMENT_DETAIL;

  /******************************************************************************
      Procedure: FIND_APPL_FILE_ATTACHMENT_DETAILS
      Purpose: Retrieves the file attachments ids for the application number
  ******************************************************************************/
  PROCEDURE FIND_APPL_FILE_DETAILS(P_APPLICATION_NUMBER IN EXPORT_APPL_FILE_ATTCHMNT.APPLICATION_NUMBER%TYPE,
                                   P_DETAIL             IN OUT ref_file_attachment_detail) AS
  BEGIN
    OPEN P_DETAIL FOR
      SELECT T.EXPORT_ATTACHMENT_ID,
             D.FILE_NAME,
             D.DESCRIPTION,
             D.EXPORT_FILE_TYPE_CODE,
             D.EXPORT_ATTACHMENT_TYPE_CODE,
             D.EXPORT_FILE_MIME_TYPE_CODE,
             D.Entry_Userid,
             D.Entry_Timestamp,
             D.Update_Userid,
             D.Update_Timestamp
        from EXPORT_APPL_FILE_ATTCHMNT T
       INNER JOIN EXPORT_FILE_ATTACHMENT D ON T.EXPORT_ATTACHMENT_ID =
                                              D.EXPORT_ATTACHMENT_ID
       where t.application_number = P_APPLICATION_NUMBER;
  END FIND_APPL_FILE_DETAILS;

  /******************************************************************************
      Procedure: FIND_APPL_FILE_ATTACHMENT
      Purpose: Retrieves the file attachments for the application number
  ******************************************************************************/
  PROCEDURE FIND_APPL_FILE_ATTACHMENT(P_ID   IN EXPORT_APPL_FILE_ATTCHMNT.EXPORT_ATTACHMENT_ID%TYPE,
                                      P_FILE IN OUT ref_appl_file_attachment) AS
  BEGIN
    OPEN P_FILE FOR
      SELECT T.EXPORT_EXEMPTION_FILE
        FROM EXPORT_APPL_FILE_ATTCHMNT T
       WHERE T.EXPORT_ATTACHMENT_ID = P_ID;
  END FIND_APPL_FILE_ATTACHMENT;

  /******************************************************************************
      Procedure:  INSERT_APPL_FILE_ATTACHMENT
      Purpose: Set the file attachment for the associated file id.
  ******************************************************************************/
  PROCEDURE INSERT_APPL_FILE_ATTACHMENT(P_APPLICATION_NUMBER     IN EXPORT_APPL_FILE_ATTCHMNT.APPLICATION_NUMBER%TYPE,
                                        P_FILE_NAME              IN EXPORT_FILE_ATTACHMENT.File_Name%TYPE,
                                        P_DESCRIPTION            IN EXPORT_FILE_ATTACHMENT.Description%TYPE,
                                        P_FILE_ATTACHMENT_TYPE   IN EXPORT_FILE_ATTACHMENT.EXPORT_ATTACHMENT_TYPE_CODE%TYPE,
                                        P_FILE_EXTENSION_CODE    IN EXPORT_FILE_ATTACHMENT.EXPORT_FILE_TYPE_CODE%TYPE,
                                        P_ENTRY_USER             IN EXPORT_FILE_ATTACHMENT.ENTRY_USERID%TYPE,
                                        P_ENTRY_DATE             IN EXPORT_FILE_ATTACHMENT.Entry_Timestamp%TYPE,
                                        P_UPDATE_USER            IN EXPORT_FILE_ATTACHMENT.Update_Userid%TYPE,
                                        P_UPDATE_DATE            IN EXPORT_FILE_ATTACHMENT.Update_Timestamp%TYPE,
                                        P_FILE                   IN EXPORT_APPL_FILE_ATTCHMNT.EXPORT_EXEMPTION_FILE%TYPE,
                                        P_FILE_ATTACHMENT_RETURN IN OUT ref_file_attachment_detail) AS
    V_FILE_ID EXPORT_FILE_ATTACHMENT.EXPORT_ATTACHMENT_ID%TYPE;
  BEGIN
    SELECT EXPORT_ATTACHMENT_ID_SEQ.NEXTVAL INTO V_FILE_ID FROM DUAL;

    INSERT_FILE_ATTACHMENT_DETAIL(V_FILE_ID,
                                  P_FILE_NAME,
                                  P_DESCRIPTION,
                                  P_FILE_ATTACHMENT_TYPE,
                                  P_FILE_EXTENSION_CODE,
                                  P_ENTRY_USER,
                                  P_ENTRY_DATE,
                                  P_UPDATE_USER,
                                  P_UPDATE_DATE,
                                  P_FILE_ATTACHMENT_RETURN);

    INSERT INTO EXPORT_APPL_FILE_ATTCHMNT
      (EXPORT_ATTACHMENT_ID, EXPORT_EXEMPTION_FILE, APPLICATION_NUMBER)
    values
      (V_FILE_ID, P_FILE, P_APPLICATION_NUMBER);
  END INSERT_APPL_FILE_ATTACHMENT;

  /******************************************************************************
      Procedure: FIND_APPL_FILE_ATTACHMENT_DETAILS
      Purpose: Retrieves the file attachments ids for the application number
  ******************************************************************************/
  PROCEDURE FIND_PERMIT_FILE_DETAILS(P_PERMIT_NUMBER IN Export_Permit_File_Attachment.Export_Permit_Detail_Number%TYPE,
                                     P_DETAIL        IN OUT ref_file_attachment_detail) AS
  BEGIN
    OPEN P_DETAIL FOR
      SELECT T.EXPORT_ATTACHMENT_ID,
             D.FILE_NAME,
             D.DESCRIPTION,
             D.EXPORT_FILE_TYPE_CODE,
             D.EXPORT_ATTACHMENT_TYPE_CODE,
             D.EXPORT_FILE_MIME_TYPE_CODE,
             D.Entry_Userid,
             D.Entry_Timestamp,
             D.Update_Userid,
             D.Update_Timestamp
        from EXPORT_PERMIT_FILE_ATTACHMENT T
       INNER JOIN EXPORT_FILE_ATTACHMENT D ON T.EXPORT_ATTACHMENT_ID =
                                              D.EXPORT_ATTACHMENT_ID
       where t.export_permit_detail_number = P_PERMIT_NUMBER
      UNION
      SELECT T.EXPORT_ATTACHMENT_ID,
             D.FILE_NAME,
             D.DESCRIPTION,
             D.EXPORT_FILE_TYPE_CODE,
             D.EXPORT_ATTACHMENT_TYPE_CODE,
             D.EXPORT_FILE_MIME_TYPE_CODE,
             D.Entry_Userid,
             D.Entry_Timestamp,
             D.Update_Userid,
             D.Update_Timestamp
        from Export_Sales_Invce_File_Attach T
       INNER JOIN EXPORT_FILE_ATTACHMENT D ON T.EXPORT_ATTACHMENT_ID =
                                              D.EXPORT_ATTACHMENT_ID
       where t.export_permit_detail_number = P_PERMIT_NUMBER;
  END FIND_PERMIT_FILE_DETAILS;

  /******************************************************************************
      Procedure: FIND_APPL_FILE_ATTACHMENT
      Purpose: Retrieves the file attachments for the application number
  ******************************************************************************/
  PROCEDURE FIND_PERMIT_FILE_ATTACHMENT(P_ID   IN EXPORT_PERMIT_FILE_ATTACHMENT.EXPORT_ATTACHMENT_ID%TYPE,
                                        P_FILE IN OUT ref_permit_file_attachment) AS
  BEGIN
    OPEN P_FILE FOR
      SELECT T.EXPORT_PERMIT_FILE
        FROM EXPORT_PERMIT_FILE_ATTACHMENT T
       WHERE T.EXPORT_ATTACHMENT_ID = P_ID;
  END FIND_PERMIT_FILE_ATTACHMENT;

 /******************************************************************************
      Procedure: FIND_EXEMPT_FILE_DETAILS
      Purpose: Retrieves the file attachments ids for the application number
  ******************************************************************************/
  PROCEDURE FIND_EXEMPT_FILE_DETAILS(P_EXEMPTION_NUMBER IN Export_EXEMPT_File_Attchmnt.EXEMPTION_Number%TYPE,
                                     P_DETAIL        IN OUT ref_file_attachment_detail) AS
  BEGIN
    OPEN P_DETAIL FOR
      SELECT T.EXPORT_ATTACHMENT_ID,
             D.FILE_NAME,
             D.DESCRIPTION,
             D.EXPORT_FILE_TYPE_CODE,
             D.EXPORT_ATTACHMENT_TYPE_CODE,
             D.EXPORT_FILE_MIME_TYPE_CODE,
             D.Entry_Userid,
             D.Entry_Timestamp,
             D.Update_Userid,
             D.Update_Timestamp
        FROM EXPORT_EXEMPT_FILE_ATTCHMNT T
       INNER JOIN EXPORT_FILE_ATTACHMENT D ON T.EXPORT_ATTACHMENT_ID =
                                              D.EXPORT_ATTACHMENT_ID
       WHERE t.EXEMPTION_NUMBER = P_EXEMPTION_NUMBER;
  END FIND_EXEMPT_FILE_DETAILS;

  /******************************************************************************
      Procedure: FIND_EXEMPT_FILE_ATTCHMNT
      Purpose: Retrieves the file attachments for the application number
  ******************************************************************************/
  PROCEDURE FIND_EXEMPT_FILE_ATTCHMNT(P_ID   IN EXPORT_EXEMPT_FILE_ATTCHMNT.EXPORT_ATTACHMENT_ID%TYPE,
                                        P_FILE IN OUT ref_exempt_file_attachment) AS
  BEGIN
    OPEN P_FILE FOR
      SELECT T.EXPORT_EXEMPTION_FILE
        FROM EXPORT_EXEMPT_FILE_ATTCHMNT T
       WHERE T.EXPORT_ATTACHMENT_ID = P_ID;
  END FIND_EXEMPT_FILE_ATTCHMNT;

  /******************************************************************************
      Procedure: FIND_FILE_ATTACHMENT
      Purpose: Retrieves the file attachments for file id
  ******************************************************************************/
  PROCEDURE FIND_FILE_ATTACHMENT(P_ID   IN NUMBER,
                                 P_FILE IN OUT ref_export_file_attachment) AS

    V_ROW_COUNT number;

  BEGIN

    SELECT count(T.EXPORT_ATTACHMENT_ID)
      INTO V_ROW_COUNT
      from EXPORT_PERMIT_FILE_ATTACHMENT T
     WHERE T.EXPORT_ATTACHMENT_ID = P_ID;
    if V_ROW_COUNT > 0 THEN

      OPEN P_FILE FOR
        SELECT T.EXPORT_PERMIT_FILE
          FROM EXPORT_PERMIT_FILE_ATTACHMENT T
         WHERE T.EXPORT_ATTACHMENT_ID = P_ID;
    END IF;
    SELECT count(T.EXPORT_ATTACHMENT_ID)
      INTO V_ROW_COUNT
      from EXPORT_APPL_FILE_ATTCHMNT T
     WHERE T.EXPORT_ATTACHMENT_ID = P_ID;
    if V_ROW_COUNT > 0 THEN

      OPEN P_FILE FOR
        SELECT T.EXPORT_EXEMPTION_FILE
          FROM EXPORT_APPL_FILE_ATTCHMNT T
         WHERE T.EXPORT_ATTACHMENT_ID = P_ID;
    END IF;
    SELECT count(T.EXPORT_ATTACHMENT_ID)
      INTO V_ROW_COUNT
      from Export_Sales_Invce_File_Attach T
     WHERE T.EXPORT_ATTACHMENT_ID = P_ID;
    if V_ROW_COUNT > 0 THEN
      OPEN P_FILE FOR
        SELECT T.EXPORT_INVOICE_FILE
          FROM Export_Sales_Invce_File_Attach T
         WHERE T.EXPORT_ATTACHMENT_ID = P_ID;
    END IF;
    SELECT count(T.EXPORT_ATTACHMENT_ID)
      INTO V_ROW_COUNT
      from EXPORT_EXEMPT_FILE_ATTCHMNT T
     WHERE T.EXPORT_ATTACHMENT_ID = P_ID;
    if V_ROW_COUNT > 0 THEN
      OPEN P_FILE FOR
        SELECT T.EXPORT_EXEMPTION_FILE
          FROM EXPORT_EXEMPT_FILE_ATTCHMNT T
         WHERE T.EXPORT_ATTACHMENT_ID = P_ID;
    END IF;
  END FIND_FILE_ATTACHMENT;

