      Purpose: Deletes the file attachment for the associated file id.
  ******************************************************************************/
  PROCEDURE DELETE_PERMIT_FILE_ATTACHMENT(P_FILE_ID IN EXPORT_PERMIT_FILE_ATTACHMENT.EXPORT_ATTACHMENT_ID%TYPE) AS

  BEGIN

    DELETE FROM EXPORT_PERMIT_FILE_ATTACHMENT
     WHERE EXPORT_ATTACHMENT_ID = P_FILE_ID;

