  END DELETE_PERMIT_FILE_ATTACHMENT;

  /******************************************************************************
      Procedure:  DELETE_INVOICE_FILE_ATTACHMENT
      Purpose: Deletes the file attachment for the associated file id.
  ******************************************************************************/
  PROCEDURE DELETE_INVOICE_FILE_ATTACHMENT(P_FILE_ID IN EXPORT_SALES_INVCE_FILE_ATTACH.EXPORT_ATTACHMENT_ID%TYPE) AS

    V_INVOICE_ID EXPORT_SALES_INVCE_FILE_ATTACH.EXPORT_SALES_INVOICE_NUMBER%TYPE;
    V_PERMIT_ID EXPORT_SALES_INVCE_FILE_ATTACH.EXPORT_PERMIT_DETAIL_NUMBER%TYPE;

  BEGIN

    -- get the invoice and permit id
    SELECT T.EXPORT_SALES_INVOICE_NUMBER, T.EXPORT_PERMIT_DETAIL_NUMBER
      INTO V_INVOICE_ID, V_PERMIT_ID
      FROM EXPORT_SALES_INVCE_FILE_ATTACH T
     WHERE T.EXPORT_ATTACHMENT_ID = P_FILE_ID;

    -- delete the attachment
    DELETE FROM EXPORT_SALES_INVCE_FILE_ATTACH
     WHERE EXPORT_ATTACHMENT_ID = P_FILE_ID;

    -- delete the invoice
    DELETE FROM EXPORT_SALES_INVOICE
     WHERE EXPORT_SALES_INVOICE_NUMBER = V_INVOICE_ID
     AND EXPORT_PERMIT_DETAIL_NUMBER = V_PERMIT_ID;

    -- delete the attachment metadata
    DELETE_FILE_ATTACHMENT_DETAIL(P_FILE_ID);

  END DELETE_INVOICE_FILE_ATTACHMENT;

  /******************************************************************************
      Procedure:  DELETE_EXEMPT_FILE_ATTACHMENT
      Purpose: Deletes the file attachment for the associated file id.
  ******************************************************************************/
  PROCEDURE DELETE_EXEMPT_FILE_ATTACHMENT(P_FILE_ID IN EXPORT_EXEMPT_FILE_ATTCHMNT.EXPORT_ATTACHMENT_ID%TYPE) AS

  BEGIN

    DELETE FROM EXPORT_EXEMPT_FILE_ATTCHMNT
     WHERE EXPORT_ATTACHMENT_ID = P_FILE_ID;

    DELETE_FILE_ATTACHMENT_DETAIL(P_FILE_ID);

  END DELETE_EXEMPT_FILE_ATTACHMENT;

