      Procedure:  INSERT_APPL_FILE_ATTACHMENT
      Purpose: Set the file attachment for the associated file id.
  ******************************************************************************/
  PROCEDURE INSERT_PERMIT_FILE_ATTACHMENT(P_PERMIT_NUMBER          IN EXPORT_PERMIT_FILE_ATTACHMENT.EXPORT_PERMIT_DETAIL_NUMBER%TYPE,
                                          P_FILE_NAME              IN EXPORT_FILE_ATTACHMENT.File_Name%TYPE,
                                          P_DESCRIPTION            IN EXPORT_FILE_ATTACHMENT.Description%TYPE,
                                          P_FILE_ATTACHMENT_TYPE   IN EXPORT_FILE_ATTACHMENT.EXPORT_ATTACHMENT_TYPE_CODE%TYPE,
                                          P_FILE_EXTENSION_CODE    IN EXPORT_FILE_ATTACHMENT.EXPORT_FILE_TYPE_CODE%TYPE,
                                          P_ENTRY_USER             IN EXPORT_FILE_ATTACHMENT.ENTRY_USERID%TYPE,
                                          P_ENTRY_DATE             IN EXPORT_FILE_ATTACHMENT.Entry_Timestamp%TYPE,
                                          P_UPDATE_USER            IN EXPORT_FILE_ATTACHMENT.Update_Userid%TYPE,
                                          P_UPDATE_DATE            IN EXPORT_FILE_ATTACHMENT.Update_Timestamp%TYPE,
                                          P_FILE                   IN EXPORT_APPL_FILE_ATTCHMNT.EXPORT_EXEMPTION_FILE%TYPE,
                                          P_FILE_ATTACHMENT_RETURN IN OUT ref_file_attachment_detail) AS
    V_FILE_ID EXPORT_FILE_ATTACHMENT.EXPORT_ATTACHMENT_ID%TYPE;
  BEGIN
    SELECT EXPORT_ATTACHMENT_ID_SEQ.NEXTVAL INTO V_FILE_ID FROM DUAL;

    INSERT_FILE_ATTACHMENT_DETAIL(V_FILE_ID,
                                  P_FILE_NAME,
                                  P_DESCRIPTION,
                                  P_FILE_ATTACHMENT_TYPE,
                                  P_FILE_EXTENSION_CODE,
                                  P_ENTRY_USER,
                                  P_ENTRY_DATE,
                                  P_UPDATE_USER,
                                  P_UPDATE_DATE,
                                  P_FILE_ATTACHMENT_RETURN);

    INSERT INTO EXPORT_PERMIT_FILE_ATTACHMENT
      (EXPORT_ATTACHMENT_ID,
       EXPORT_PERMIT_FILE,
       EXPORT_PERMIT_DETAIL_NUMBER)
    values
      (V_FILE_ID, P_FILE, P_PERMIT_NUMBER);
  END INSERT_PERMIT_FILE_ATTACHMENT;

