  ******************************************************************************/
  PROCEDURE INSERT_FEDERAL_PERMIT(P_EXPORT_PERMIT_ISSUE_DATE   IN export_federal_permit_detail.EXPORT_PERMIT_ISSUE_DATE%TYPE,
                                  P_ESTIMATED_SHIPPING_DATE    IN export_federal_permit_detail.ESTIMATED_SHIPPING_DATE%TYPE,
                                  P_OTHER_PORT_OF_EXPORT       IN export_federal_permit_detail.OTHER_PORT_OF_EXPORT%TYPE,
                                  P_TRANSPORT_NAME             IN export_federal_permit_detail.TRANSPORT_NAME%TYPE,
                                  P_ENTRY_USERID               IN export_federal_permit_detail.ENTRY_USERID%TYPE,
                                  P_ENTRY_TIMESTAMP            IN export_federal_permit_detail.ENTRY_TIMESTAMP%TYPE,
                                  P_EXPORT_TRANSPORT_TYPE_CODE IN export_federal_permit_detail.EXPORT_TRANSPORT_TYPE_CODE%TYPE,
                                  P_EXPORT_COUNTRY_CODE        IN export_federal_permit_detail.EXPORT_COUNTRY_CODE%TYPE,
                                  P_EXPORT_PORT_OF_EXPORT_CODE IN export_federal_permit_detail.EXPORT_PORT_OF_EXPORT_CODE%TYPE,
                                  P_APPLICATION_DATE           IN export_federal_permit_detail.APPLICATION_DATE%TYPE,
                                  P_ORG_UNIT_NUMBER            IN export_federal_permit_detail.ORG_UNIT_NO%TYPE,
                                  P_CLIENT_LOCN_CODE           IN export_federal_permit_detail.CLIENT_LOCN_CODE%TYPE,
                                  P_CLIENT_NUMBER              IN export_federal_permit_detail.CLIENT_NUMBER%TYPE,
                                  R_PERMIT                     IN OUT ref_federal_permit) AS

    V_PERMIT_ID export_federal_permit_detail.EXPORT_FED_PERMIT_DETAIL_ID%TYPE;
  BEGIN
    SELECT EXPORT_FED_PERMIT_DETAIL_SEQ.NEXTVAL INTO V_PERMIT_ID FROM DUAL;

    INSERT INTO export_federal_permit_detail
      (EXPORT_FED_PERMIT_DETAIL_ID,
       EXPORT_PERMIT_ISSUE_DATE,
       ESTIMATED_SHIPPING_DATE,
       OTHER_PORT_OF_EXPORT,
       TRANSPORT_NAME,
       ENTRY_USERID,
       ENTRY_TIMESTAMP,
       UPDATE_USERID,
       UPDATE_TIMESTAMP,
       EXPORT_TRANSPORT_TYPE_CODE,
       EXPORT_COUNTRY_CODE,
       EXPORT_PORT_OF_EXPORT_CODE,
       APPLICATION_DATE,
       ORG_UNIT_NO,
       CLIENT_LOCN_CODE,
       CLIENT_NUMBER)
    values
      (V_PERMIT_ID,
       P_EXPORT_PERMIT_ISSUE_DATE,
       P_ESTIMATED_SHIPPING_DATE,
       P_OTHER_PORT_OF_EXPORT,
       P_TRANSPORT_NAME,
       P_ENTRY_USERID,
       P_ENTRY_TIMESTAMP,
       null,
       null,
       P_EXPORT_TRANSPORT_TYPE_CODE,
       P_EXPORT_COUNTRY_CODE,
       P_EXPORT_PORT_OF_EXPORT_CODE,
       P_APPLICATION_DATE,
       P_ORG_UNIT_NUMBER,
       P_CLIENT_LOCN_CODE,
       P_CLIENT_NUMBER);

    FIND_F_PERM_DET_BY_ID(V_PERMIT_ID, R_PERMIT);

  END INSERT_FEDERAL_PERMIT;

  /******************************************************************************
      Procedure:  UPDATE_FEDERAL_PERMIT
      Purpose: Updates an existing Federal Permit Detail
  ******************************************************************************/
  PROCEDURE UPDATE_FEDERAL_PERMIT(P_EXPORT_FED_PERMIT_DETAIL_ID IN EXPORT_FEDERAL_PERMIT_DETAIL.EXPORT_FED_PERMIT_DETAIL_ID%TYPE,
                                  P_EXPORT_PERMIT_ISSUE_DATE    IN EXPORT_FEDERAL_PERMIT_DETAIL.EXPORT_PERMIT_ISSUE_DATE%TYPE,
                                  P_ESTIMATED_SHIPPING_DATE     IN EXPORT_FEDERAL_PERMIT_DETAIL.ESTIMATED_SHIPPING_DATE%TYPE,
                                  P_OTHER_PORT_OF_EXPORT        IN EXPORT_FEDERAL_PERMIT_DETAIL.OTHER_PORT_OF_EXPORT%TYPE,
                                  P_TRANSPORT_NAME              IN EXPORT_FEDERAL_PERMIT_DETAIL.TRANSPORT_NAME%TYPE,
                                  P_UPDATE_USERID               IN EXPORT_FEDERAL_PERMIT_DETAIL.UPDATE_USERID%TYPE,
                                  P_UPDATE_TIMESTAMP            IN EXPORT_FEDERAL_PERMIT_DETAIL.UPDATE_TIMESTAMP%TYPE,
                                  P_EXPORT_TRANSPORT_TYPE_CODE  IN EXPORT_FEDERAL_PERMIT_DETAIL.EXPORT_TRANSPORT_TYPE_CODE%TYPE,
                                  P_EXPORT_COUNTRY_CODE         IN EXPORT_FEDERAL_PERMIT_DETAIL.EXPORT_COUNTRY_CODE%TYPE,
                                  P_EXPORT_PORT_OF_EXPORT_CODE  IN EXPORT_FEDERAL_PERMIT_DETAIL.EXPORT_PORT_OF_EXPORT_CODE%TYPE,
                                  P_APPLICATION_DATE            IN EXPORT_FEDERAL_PERMIT_DETAIL.APPLICATION_DATE%TYPE,
                                  P_ORG_UNIT_NUMBER             IN EXPORT_FEDERAL_PERMIT_DETAIL.ORG_UNIT_NO%TYPE,
                                  P_CLIENT_LOCN_CODE            IN EXPORT_FEDERAL_PERMIT_DETAIL.CLIENT_LOCN_CODE%TYPE,
                                  P_CLIENT_NUMBER               IN EXPORT_FEDERAL_PERMIT_DETAIL.CLIENT_NUMBER%TYPE) AS

    V_PERMIT_AUDIT_ID EXPORT_FEDERAL_PERMIT_AUDIT.EXPORT_FED_PERMIT_AUDIT_ID%TYPE;

  BEGIN

    -- copy original record into audit table
    SELECT EXPORT_PERMIT_AUDIT_SEQ.NEXTVAL
      INTO V_PERMIT_AUDIT_ID
      FROM DUAL;

    INSERT INTO EXPORT_FEDERAL_PERMIT_AUDIT
      (EXPORT_FED_PERMIT_AUDIT_ID,
       EXPORT_FED_PERMIT_DETAIL_ID,
       CLIENT_NUMBER,
       CLIENT_LOCN_CODE,
       APPLICATION_DATE,
       OTHER_PORT_OF_EXPORT,
       EXPORT_PERMIT_ISSUE_DATE,
       ESTIMATED_SHIPPING_DATE,
       TRANSPORT_NAME,
       ORG_UNIT_NO,
       EXPORT_TRANSPORT_TYPE_CODE,
       EXPORT_COUNTRY_CODE,
       EXPORT_PORT_OF_EXPORT_CODE,
       ENTRY_USERID,
       ENTRY_TIMESTAMP,
       UPDATE_USERID,
       UPDATE_TIMESTAMP,
       DELETE_USERID,
       DELETE_TIMESTAMP)
      SELECT V_PERMIT_AUDIT_ID,
             EFPD.EXPORT_FED_PERMIT_DETAIL_ID,
             EFPD.CLIENT_NUMBER,
             EFPD.CLIENT_LOCN_CODE,
             EFPD.APPLICATION_DATE,
             EFPD.OTHER_PORT_OF_EXPORT,
             EFPD.EXPORT_PERMIT_ISSUE_DATE,
             EFPD.ESTIMATED_SHIPPING_DATE,
             EFPD.TRANSPORT_NAME,
             EFPD.ORG_UNIT_NO,
             EFPD.EXPORT_TRANSPORT_TYPE_CODE,
             EFPD.EXPORT_COUNTRY_CODE,
             EFPD.EXPORT_PORT_OF_EXPORT_CODE,
             EFPD.ENTRY_USERID,
             EFPD.ENTRY_TIMESTAMP,
             EFPD.UPDATE_USERID,
             EFPD.UPDATE_TIMESTAMP,
             NULL,
             NULL
        FROM EXPORT_FEDERAL_PERMIT_DETAIL EFPD
       WHERE EFPD.EXPORT_FED_PERMIT_DETAIL_ID =
             P_EXPORT_FED_PERMIT_DETAIL_ID;

    -- update record
    UPDATE EXPORT_FEDERAL_PERMIT_DETAIL
       SET EXPORT_PERMIT_ISSUE_DATE   = P_EXPORT_PERMIT_ISSUE_DATE,
           ESTIMATED_SHIPPING_DATE    = P_ESTIMATED_SHIPPING_DATE,
           OTHER_PORT_OF_EXPORT       = P_OTHER_PORT_OF_EXPORT,
           TRANSPORT_NAME             = P_TRANSPORT_NAME,
           UPDATE_USERID              = P_UPDATE_USERID,
           UPDATE_TIMESTAMP           = P_UPDATE_TIMESTAMP,
           EXPORT_TRANSPORT_TYPE_CODE = P_EXPORT_TRANSPORT_TYPE_CODE,
           EXPORT_COUNTRY_CODE        = P_EXPORT_COUNTRY_CODE,
           EXPORT_PORT_OF_EXPORT_CODE = P_EXPORT_PORT_OF_EXPORT_CODE,
           APPLICATION_DATE           = P_APPLICATION_DATE,
           ORG_UNIT_NO                = P_ORG_UNIT_NUMBER,
           CLIENT_LOCN_CODE           = P_CLIENT_LOCN_CODE,
           CLIENT_NUMBER              = P_CLIENT_NUMBER
     WHERE P_EXPORT_FED_PERMIT_DETAIL_ID = EXPORT_FED_PERMIT_DETAIL_ID;

  END UPDATE_FEDERAL_PERMIT;

