  ******************************************************************************/
  PROCEDURE INSERT_RESERVE_PERMIT(P_EXPORT_INDIAN_RSRV_PRMT_DTL IN EXPORT_INDIAN_RSRV_PRMT_DTL.EXPORT_INDIAN_RSRV_PRMT_DTL_ID%TYPE,
                                  P_EXPORT_PERMIT_ISSUE_DATE    IN EXPORT_INDIAN_RSRV_PRMT_DTL.EXPORT_PERMIT_ISSUE_DATE%TYPE,
                                  P_ESTIMATED_SHIPPING_DATE     IN EXPORT_INDIAN_RSRV_PRMT_DTL.ESTIMATED_SHIPPING_DATE%TYPE,
                                  P_OTHER_PORT_OF_EXPORT        IN EXPORT_INDIAN_RSRV_PRMT_DTL.OTHER_PORT_OF_EXPORT%TYPE,
                                  P_TRANSPORT_NAME              IN EXPORT_INDIAN_RSRV_PRMT_DTL.TRANSPORT_NAME%TYPE,
                                  P_ENTRY_USERID                IN EXPORT_INDIAN_RSRV_PRMT_DTL.ENTRY_USERID%TYPE,
                                  P_ENTRY_TIMESTAMP             IN EXPORT_INDIAN_RSRV_PRMT_DTL.ENTRY_TIMESTAMP%TYPE,
                                  P_EXPORT_TRANSPORT_TYPE_CODE  IN EXPORT_INDIAN_RSRV_PRMT_DTL.EXPORT_TRANSPORT_TYPE_CODE%TYPE,
                                  P_EXPORT_COUNTRY_CODE         IN EXPORT_INDIAN_RSRV_PRMT_DTL.EXPORT_COUNTRY_CODE%TYPE,
                                  P_EXPORT_PORT_OF_EXPORT_CODE  IN EXPORT_INDIAN_RSRV_PRMT_DTL.EXPORT_PORT_OF_EXPORT_CODE%TYPE,
                                  P_APPLICATION_DATE            IN EXPORT_INDIAN_RSRV_PRMT_DTL.APPLICATION_DATE%TYPE,
                                  P_ORG_UNIT_NUMBER             IN EXPORT_INDIAN_RSRV_PRMT_DTL.ORG_UNIT_NO%TYPE,
                                  P_CLIENT_LOCN_CODE            IN EXPORT_INDIAN_RSRV_PRMT_DTL.CLIENT_LOCN_CODE%TYPE,
                                  P_CLIENT_NUMBER               IN EXPORT_INDIAN_RSRV_PRMT_DTL.CLIENT_NUMBER%TYPE,
                                  R_PERMIT                      IN OUT ref_reserve_permit) AS

    V_PERMIT_ID EXPORT_INDIAN_RSRV_PRMT_DTL.EXPORT_INDIAN_RSRV_PRMT_DTL_ID%TYPE;
  BEGIN

    IF (P_EXPORT_INDIAN_RSRV_PRMT_DTL IS NULL) THEN
      SELECT EXPORT_FED_PERMIT_DETAIL_SEQ.NEXTVAL
        INTO V_PERMIT_ID
        FROM DUAL;
    ELSE
      V_PERMIT_ID := P_EXPORT_INDIAN_RSRV_PRMT_DTL;
    END IF;

    INSERT INTO EXPORT_INDIAN_RSRV_PRMT_DTL
      (EXPORT_INDIAN_RSRV_PRMT_DTL_ID,
       EXPORT_PERMIT_ISSUE_DATE,
       ESTIMATED_SHIPPING_DATE,
       OTHER_PORT_OF_EXPORT,
       TRANSPORT_NAME,
       ENTRY_USERID,
       ENTRY_TIMESTAMP,
       UPDATE_USERID,
       UPDATE_TIMESTAMP,
       EXPORT_TRANSPORT_TYPE_CODE,
       EXPORT_COUNTRY_CODE,
       EXPORT_PORT_OF_EXPORT_CODE,
       APPLICATION_DATE,
       ORG_UNIT_NO,
       CLIENT_LOCN_CODE,
       CLIENT_NUMBER)
    values
      (V_PERMIT_ID,
       P_EXPORT_PERMIT_ISSUE_DATE,
       P_ESTIMATED_SHIPPING_DATE,
       P_OTHER_PORT_OF_EXPORT,
       P_TRANSPORT_NAME,
       P_ENTRY_USERID,
       P_ENTRY_TIMESTAMP,
       null,
       null,
       P_EXPORT_TRANSPORT_TYPE_CODE,
       P_EXPORT_COUNTRY_CODE,
       P_EXPORT_PORT_OF_EXPORT_CODE,
       P_APPLICATION_DATE,
       P_ORG_UNIT_NUMBER,
       P_CLIENT_LOCN_CODE,
       P_CLIENT_NUMBER);

    FIND_IR_PERM_DET_BY_ID(V_PERMIT_ID, R_PERMIT);

  END INSERT_RESERVE_PERMIT;

  /******************************************************************************
      Procedure:  UPDATE_RESERVE_PERMIT
      Purpose: Updates an existing Indian Reserve Permit Detail
  ******************************************************************************/
  PROCEDURE UPDATE_RESERVE_PERMIT(P_EXPORT_INDIAN_RSRV_PRMT_DTL IN EXPORT_INDIAN_RSRV_PRMT_DTL.EXPORT_INDIAN_RSRV_PRMT_DTL_ID%TYPE,
                                  P_EXPORT_PERMIT_ISSUE_DATE    IN EXPORT_INDIAN_RSRV_PRMT_DTL.EXPORT_PERMIT_ISSUE_DATE%TYPE,
                                  P_ESTIMATED_SHIPPING_DATE     IN EXPORT_INDIAN_RSRV_PRMT_DTL.ESTIMATED_SHIPPING_DATE%TYPE,
                                  P_OTHER_PORT_OF_EXPORT        IN EXPORT_INDIAN_RSRV_PRMT_DTL.OTHER_PORT_OF_EXPORT%TYPE,
                                  P_TRANSPORT_NAME              IN EXPORT_INDIAN_RSRV_PRMT_DTL.TRANSPORT_NAME%TYPE,
                                  P_UPDATE_USERID               IN EXPORT_INDIAN_RSRV_PRMT_DTL.UPDATE_USERID%TYPE,
                                  P_UPDATE_TIMESTAMP            IN EXPORT_INDIAN_RSRV_PRMT_DTL.UPDATE_TIMESTAMP%TYPE,
                                  P_EXPORT_TRANSPORT_TYPE_CODE  IN EXPORT_INDIAN_RSRV_PRMT_DTL.EXPORT_TRANSPORT_TYPE_CODE%TYPE,
                                  P_EXPORT_COUNTRY_CODE         IN EXPORT_INDIAN_RSRV_PRMT_DTL.EXPORT_COUNTRY_CODE%TYPE,
                                  P_EXPORT_PORT_OF_EXPORT_CODE  IN EXPORT_INDIAN_RSRV_PRMT_DTL.EXPORT_PORT_OF_EXPORT_CODE%TYPE,
                                  P_APPLICATION_DATE            IN EXPORT_INDIAN_RSRV_PRMT_DTL.APPLICATION_DATE%TYPE,
                                  P_ORG_UNIT_NUMBER             IN EXPORT_INDIAN_RSRV_PRMT_DTL.ORG_UNIT_NO%TYPE,
                                  P_CLIENT_LOCN_CODE            IN EXPORT_INDIAN_RSRV_PRMT_DTL.CLIENT_LOCN_CODE%TYPE,
                                  P_CLIENT_NUMBER               IN EXPORT_INDIAN_RSRV_PRMT_DTL.CLIENT_NUMBER%TYPE) AS

    V_PERMIT_AUDIT_ID EXPORT_INDIAN_RSRV_PRMT_AUDIT.EXPORT_INDIAN_RES_PRM_AUDIT_ID%TYPE;

  BEGIN

    -- copy original record into audit table
    SELECT EXPORT_RSRV_PERMIT_AUDIT_SEQ.NEXTVAL
      INTO V_PERMIT_AUDIT_ID
      FROM DUAL;

    insert into EXPORT_INDIAN_RSRV_PRMT_AUDIT
      (EXPORT_INDIAN_RES_PRM_AUDIT_ID,
       EXPORT_INDIAN_RSRV_PRMT_DTL_ID,
       APPLICATION_DATE,
       EXPORT_PERMIT_ISSUE_DATE,
       ESTIMATED_SHIPPING_DATE,
       OTHER_PORT_OF_EXPORT,
       TRANSPORT_NAME,
       EXPORT_TRANSPORT_TYPE_CODE,
       EXPORT_PORT_OF_EXPORT_CODE,
       EXPORT_COUNTRY_CODE,
       ORG_UNIT_NO,
       CLIENT_NUMBER,
       CLIENT_LOCN_CODE,
       ENTRY_USERID,
       ENTRY_TIMESTAMP,
       UPDATE_USERID,
       UPDATE_TIMESTAMP,
       DELETE_USERID,
       DELETE_TIMESTAMP)
      select V_PERMIT_AUDIT_ID,
             EIRPD.EXPORT_INDIAN_RSRV_PRMT_DTL_ID,
             EIRPD.APPLICATION_DATE,
             EIRPD.EXPORT_PERMIT_ISSUE_DATE,
             EIRPD.ESTIMATED_SHIPPING_DATE,
             EIRPD.OTHER_PORT_OF_EXPORT,
             EIRPD.TRANSPORT_NAME,
             EIRPD.EXPORT_TRANSPORT_TYPE_CODE,
             EIRPD.EXPORT_PORT_OF_EXPORT_CODE,
             EIRPD.EXPORT_COUNTRY_CODE,
             EIRPD.ORG_UNIT_NO,
             EIRPD.CLIENT_NUMBER,
             EIRPD.CLIENT_LOCN_CODE,
             EIRPD.ENTRY_USERID,
             EIRPD.ENTRY_TIMESTAMP,
             EIRPD.UPDATE_USERID,
             EIRPD.UPDATE_TIMESTAMP,
             NULL,
             NULL
        from EXPORT_INDIAN_RSRV_PRMT_DTL EIRPD
       WHERE EIRPD.EXPORT_INDIAN_RSRV_PRMT_DTL_ID =
             P_EXPORT_INDIAN_RSRV_PRMT_DTL;

    UPDATE EXPORT_INDIAN_RSRV_PRMT_DTL
       set EXPORT_PERMIT_ISSUE_DATE   = P_EXPORT_PERMIT_ISSUE_DATE,
           ESTIMATED_SHIPPING_DATE    = P_ESTIMATED_SHIPPING_DATE,
           OTHER_PORT_OF_EXPORT       = P_OTHER_PORT_OF_EXPORT,
           TRANSPORT_NAME             = P_TRANSPORT_NAME,
           UPDATE_USERID              = P_UPDATE_USERID,
           UPDATE_TIMESTAMP           = P_UPDATE_TIMESTAMP,
           EXPORT_TRANSPORT_TYPE_CODE = P_EXPORT_TRANSPORT_TYPE_CODE,
           EXPORT_COUNTRY_CODE        = P_EXPORT_COUNTRY_CODE,
           EXPORT_PORT_OF_EXPORT_CODE = P_EXPORT_PORT_OF_EXPORT_CODE,
           APPLICATION_DATE           = P_APPLICATION_DATE,
           ORG_UNIT_NO                = P_ORG_UNIT_NUMBER,
           CLIENT_LOCN_CODE           = P_CLIENT_LOCN_CODE,
           CLIENT_NUMBER              = P_CLIENT_NUMBER
     where P_EXPORT_INDIAN_RSRV_PRMT_DTL = EXPORT_INDIAN_RSRV_PRMT_DTL_ID;

  END UPDATE_RESERVE_PERMIT;

  /******************************************************************************
      Procedure: FIND_FOREST_CLIENT
      Purpose:
  ******************************************************************************/
  PROCEDURE FIND_FOREST_CLIENT(P_CLIENT_NUMBER IN FOREST_CLIENT.CLIENT_NUMBER%TYPE,
                               P_FOREST_CLIENT IN OUT ref_forest_client) AS
  BEGIN
    OPEN P_FOREST_CLIENT FOR
      SELECT T.REVISION_COUNT,
             T.CLIENT_ACRONYM,
             T.ADD_ORG_UNIT,
             T.LEGAL_FIRST_NAME,
             T.UPDATE_USERID,
             T.CLIENT_IDENTIFICATION,
             T.CLIENT_ID_TYPE_CODE,
             T.CORP_REGN_NMBR,
             T.ADD_TIMESTAMP,
             T.CLIENT_NAME,
             T.WCB_FIRM_NUMBER,
             T.ADD_USERID,
             T.BIRTHDATE,
             T.CLIENT_COMMENT,
             T.CLIENT_NUMBER,
             T.REGISTRY_COMPANY_TYPE_CODE,
             T.OCG_SUPPLIER_NMBR,
             T.UPDATE_TIMESTAMP,
             T.CLIENT_STATUS_CODE,
             T.LEGAL_MIDDLE_NAME,
             T.UPDATE_ORG_UNIT,
             T.CLIENT_TYPE_CODE
        FROM FOREST_CLIENT T
       WHERE T.CLIENT_NUMBER = P_CLIENT_NUMBER;
  END FIND_FOREST_CLIENT;

  /******************************************************************************
      Procedure: INSERT_EXEMPTION_RATE
      Purpose:
  ******************************************************************************/
  PROCEDURE INSERT_EXEMPTION_RATE(P_EXEMPTION_NUMBER     IN EXPORT_EXEMPTION_RATE.EXEMPTION_NUMBER%TYPE,
                                  P_FIXED_EXEMPTION_RATE IN EXPORT_EXEMPTION_RATE.FIXED_EXEMPTION_RATE%TYPE,
                                  P_ENTRY_USERID         IN EXPORT_EXEMPTION_RATE.ENTRY_USERID%TYPE,
                                  P_ENTRY_TIMESTAMP      IN EXPORT_EXEMPTION_RATE.ENTRY_TIMESTAMP%TYPE,
                                  R_RATE                 IN OUT REF_EXEMPTION_RATE) IS
  BEGIN

    INSERT INTO EXPORT_EXEMPTION_RATE
      (EXEMPTION_NUMBER,
       FIXED_EXEMPTION_RATE,
       ENTRY_USERID,
       ENTRY_TIMESTAMP)
    VALUES
      (P_EXEMPTION_NUMBER,
       P_FIXED_EXEMPTION_RATE,
       P_ENTRY_USERID,
       P_ENTRY_TIMESTAMP);

    FIND_RATE_BY_EXEMPTION(P_EXEMPTION_NUMBER, R_RATE);

  END INSERT_EXEMPTION_RATE;

  /******************************************************************************
      Procedure: UPDATE_EXEMPTION_RATE
      Purpose:
  ******************************************************************************/
  PROCEDURE UPDATE_EXEMPTION_RATE(P_EXEMPTION_NUMBER     IN EXPORT_EXEMPTION_RATE.EXEMPTION_NUMBER%TYPE,
                                  P_FIXED_EXEMPTION_RATE IN EXPORT_EXEMPTION_RATE.FIXED_EXEMPTION_RATE%TYPE,
                                  P_UPDATE_USERID        IN EXPORT_EXEMPTION_RATE.UPDATE_USERID%TYPE,
                                  P_UPDATE_TIMESTAMP     IN EXPORT_EXEMPTION_RATE.UPDATE_TIMESTAMP%TYPE) IS
  BEGIN

    UPDATE EXPORT_EXEMPTION_RATE EER
       SET EER.FIXED_EXEMPTION_RATE = P_FIXED_EXEMPTION_RATE,
           EER.UPDATE_USERID        = P_UPDATE_USERID,
           EER.UPDATE_TIMESTAMP     = P_UPDATE_TIMESTAMP
     WHERE EER.EXEMPTION_NUMBER = P_EXEMPTION_NUMBER;

  END UPDATE_EXEMPTION_RATE;

  /******************************************************************************
      Procedure: DELETE_EXEMPTION_RATE
      Purpose:
  ******************************************************************************/
  PROCEDURE DELETE_EXEMPTION_RATE(P_EXEMPTION_NUMBER IN EXPORT_EXEMPTION_RATE.EXEMPTION_NUMBER%TYPE) IS
  BEGIN

    DELETE FROM EXPORT_EXEMPTION_RATE EER
     WHERE EER.EXEMPTION_NUMBER = P_EXEMPTION_NUMBER;

  END DELETE_EXEMPTION_RATE;

  /******************************************************************************
      Procedure: IS_BLANKET_OIC
      Purpose: Determines if the exemption is of type blanket-oic
               An exemption is blanket OIC if its type is OIC and it has no applications
  ******************************************************************************/
  PROCEDURE IS_BLANKET_OIC(P_EXEMPTION_NUMBER IN EXPORT_EXEMPTION_RATE.EXEMPTION_NUMBER%TYPE,
                           P_IS_BLANKET_OIC IN OUT ref_cur_general) IS
  BEGIN

    open P_IS_BLANKET_OIC
    for select count(*) as RESULTS_COUNT
    from export_exemption t
    where t.exemption_number = P_EXEMPTION_NUMBER and t.export_exemption_type_code = 'O';

  END IS_BLANKET_OIC;

    /******************************************************************************
      Procedure: IS_APP_UMANU
      Purpose: Determines if the application is of type unmanu
  ******************************************************************************/
  PROCEDURE IS_APP_UMANU(P_APPLICATION_NUMBER IN EXPORT_EXEMPTION_APPLICATION.APPLICATION_NUMBER%TYPE,
                           P_IS_UNMANU IN OUT ref_cur_general) IS
  BEGIN
    open P_IS_UNMANU
    for select count(*) as RESULTS_COUNT
    from export_exemption_application eea
    where eea.application_number = P_APPLICATION_NUMBER and eea.export_product_type_code = 'T';
  END IS_APP_UMANU;

  /******************************************************************************
      Procedure:  FIND_ALL_FEE_POLICIES
      Purpose: Find all policies.
  ******************************************************************************/
  PROCEDURE FIND_ALL_FEE_POLICIES(P_SORT_ORDER IN varchar2,
                                  P_PAGE       IN NUMBER,
                                  P_FEE_POLICIES IN OUT ref_cur_general) IS

  v_query varchar2(150);
  V_ROW_START NUMBER;
   V_ROW_END   NUMBER;
  BEGIN

    V_ROW_START := (P_PAGE * PAGINATED_RESULTS_SIZE) + 1;
    V_ROW_END   := V_ROW_START + PAGINATED_RESULTS_SIZE;

      if P_SORT_ORDER = 'org_unit_no asc' then
        open P_FEE_POLICIES for
        select *  from (select a.*, ROWNUM rnum from (
        select *
        from LEXIS_FEE_POLICY lfp
        order by lfp.org_unit_no asc) a where rownum < V_ROW_END) where rnum >= V_ROW_START;

      elsif P_SORT_ORDER = 'effective_date asc' then
        open P_FEE_POLICIES for
        select *  from (select a.*, ROWNUM rnum from (
        select *
        from LEXIS_FEE_POLICY lfp
        order by effective_date asc) a where rownum < V_ROW_END) where rnum >= V_ROW_START;
      elsif P_SORT_ORDER = 'percent_increase asc' then
        open P_FEE_POLICIES for
        select *  from (select a.*, ROWNUM rnum from (
        select *
        from LEXIS_FEE_POLICY lfp
        order by percent_increase asc) a where rownum < V_ROW_END) where rnum >= V_ROW_START;
      elsif P_SORT_ORDER = 'org_unit_no desc' then
        open P_FEE_POLICIES for
        select *  from (select a.*, ROWNUM rnum from (
        select *
        from LEXIS_FEE_POLICY lfp
        order by lfp.org_unit_no desc) a where rownum < V_ROW_END) where rnum >= V_ROW_START;
      elsif P_SORT_ORDER = 'effective_date desc' then
        open P_FEE_POLICIES for
        select *  from (select a.*, ROWNUM rnum from (
        select *
        from LEXIS_FEE_POLICY lfp
        order by effective_date desc) a where rownum < V_ROW_END) where rnum >= V_ROW_START;
      elsif P_SORT_ORDER = 'percent_increase desc' then
        open P_FEE_POLICIES for
        select *  from (select a.*, ROWNUM rnum from (
        select *
        from LEXIS_FEE_POLICY lfp
        order by percent_increase desc) a where rownum < V_ROW_END) where rnum >= V_ROW_START;
      end if;


--    else

--    end if;

--    open P_FEE_POLICIES



  END FIND_ALL_FEE_POLICIES;

   /******************************************************************************
      Procedure:  FIND_ALL_FEE_POLICIES
      Purpose: Find all policies.
  ******************************************************************************/
  PROCEDURE FIND_ALL_FIL_POLICIES(P_SORT_ORDER IN varchar2,
                                  P_PAGE       IN NUMBER,
                                  P_FIL_POLICIES IN OUT ref_cur_general) IS

  v_query varchar2(150);
  V_ROW_START NUMBER;
   V_ROW_END   NUMBER;
  BEGIN

    V_ROW_START := (P_PAGE * PAGINATED_RESULTS_SIZE) + 1;
    V_ROW_END   := V_ROW_START + PAGINATED_RESULTS_SIZE;

      if P_SORT_ORDER = 'effective_date asc' then
        open P_FIL_POLICIES for
        select *  from (select a.*, ROWNUM rnum from (
        select *
        from FEE_IN_LIEU_PERCENT lfp
        order by effective_date asc) a where rownum < V_ROW_END) where rnum >= V_ROW_START;
      elsif P_SORT_ORDER = 'fil_percent asc' then
        open P_FIL_POLICIES for
        select *  from (select a.*, ROWNUM rnum from (
        select *
        from FEE_IN_LIEU_PERCENT lfp
        order by FEE_IN_LIEU_PERCENT asc) a where rownum < V_ROW_END) where rnum >= V_ROW_START;
      elsif P_SORT_ORDER = 'effective_date desc' then
        open P_FIL_POLICIES for
        select *  from (select a.*, ROWNUM rnum from (
        select *
        from FEE_IN_LIEU_PERCENT lfp
        order by effective_date desc) a where rownum < V_ROW_END) where rnum >= V_ROW_START;
      elsif P_SORT_ORDER = 'fil_percent desc' then
        open P_FIL_POLICIES for
        select *  from (select a.*, ROWNUM rnum from (
        select *
        from FEE_IN_LIEU_PERCENT lfp
        order by FEE_IN_LIEU_PERCENT desc) a where rownum < V_ROW_END) where rnum >= V_ROW_START;
      else
        open P_FIL_POLICIES for
        select *  from (select a.*, ROWNUM rnum from (
        select *
        from FEE_IN_LIEU_PERCENT lfp
        order by effective_date DESC) a where rownum < V_ROW_END) where rnum >= V_ROW_START;
      end if;


--    else

--    end if;

--    open P_FEE_POLICIES



  END FIND_ALL_FIL_POLICIES;

    /******************************************************************************
      Procedure:  FIND_FEE_POLICY_BY_ID
      Purpose: Find a specific fee policy.
  ******************************************************************************/
  PROCEDURE FIND_FEE_POLICY_BY_ID(P_FEE_POLICY_ID   IN  LEXIS_FEE_POLICY.LEXIS_FEE_POLICY_ID%TYPE,
                                  P_FEE_POLICY      IN OUT ref_lexis_fee_policy) IS
  BEGIN
    open P_FEE_POLICY for
    select *
    from LEXIS_FEE_POLICY
    where LEXIS_FEE_POLICY_ID = P_FEE_POLICY_ID;

  END FIND_FEE_POLICY_BY_ID;

      /******************************************************************************
      Procedure:  FIND_FEE_POLICY_BY_ID
      Purpose: Find a specific fee policy.
  ******************************************************************************/
  PROCEDURE FIND_FIL_POLICY_BY_ID(P_FEE_IN_LIEU_PERCENT_ID   IN  FEE_IN_LIEU_PERCENT.FEE_IN_LIEU_PERCENT_ID%TYPE,
                                  P_FIL_POLICY      IN OUT ref_lexis_fil_policy) IS
