  BEGIN
    delete from LEXIS_FEE_POLICY
    where LEXIS_FEE_POLICY_ID = P_FEE_POLICY_ID;

  END DELETE_FEE_POLICY;

        /******************************************************************************
      Procedure:  FIND_FEE_POLICY_BY_ID
      Purpose: Find a specific fee policy.
  ******************************************************************************/
  PROCEDURE DELETE_FIL_POLICY(P_FEE_IN_LIEU_PERCENT_ID   IN  FEE_IN_LIEU_PERCENT.FEE_IN_LIEU_PERCENT_ID%TYPE) IS
  BEGIN
    delete from FEE_IN_LIEU_PERCENT
    where FEE_IN_LIEU_PERCENT_ID = P_FEE_IN_LIEU_PERCENT_ID;

