  /******************************************************************************
      Procedure:  INSERT_FEE_POLICY
      Purpose: Inserts a policy into LEXIS_FEE_POLICY
  ******************************************************************************/
  PROCEDURE INSERT_FEE_POLICY(P_EFFECTIVE_DATE              IN LEXIS_FEE_POLICY.EFFECTIVE_DATE%TYPE,
                           P_ORG_UNIT_NO                 IN LEXIS_FEE_POLICY.ORG_UNIT_NO%TYPE,
                           P_PERCENT_INCREASE            IN LEXIS_FEE_POLICY.PERCENT_INCREASE%TYPE,
                           P_ENTRY_USERID                IN LEXIS_FEE_POLICY.ENTRY_USERID%TYPE,
                           R_POLICY                      IN OUT ref_lexis_fee_policy) IS

  V_FEE_POLICY_ID LEXIS_FEE_POLICY.LEXIS_FEE_POLICY_ID%TYPE;

  BEGIN

    SELECT LEXIS_FEE_POLICY_ID_SEQ.Nextval
      INTO V_FEE_POLICY_ID
      FROM DUAL;

    INSERT INTO LEXIS_FEE_POLICY
      (LEXIS_FEE_POLICY_ID,
       ORG_UNIT_NO,
       EFFECTIVE_DATE,
       PERCENT_INCREASE,
       ENTRY_USERID,
       ENTRY_TIMESTAMP,
       UPDATE_USERID,
       UPDATE_TIMESTAMP)
    VALUES
      (V_FEE_POLICY_ID,
       P_ORG_UNIT_NO,
       P_EFFECTIVE_DATE,
       P_PERCENT_INCREASE,
       P_ENTRY_USERID,
       sysdate,
       P_ENTRY_USERID,
       sysdate);

    FIND_FEE_POLICY_BY_ID(V_FEE_POLICY_ID, R_POLICY);

  END INSERT_FEE_POLICY;

  /******************************************************************************
      Procedure:  INSERT_FEE_POLICY
      Purpose: Inserts a policy into LEXIS_FEE_POLICY
  ******************************************************************************/
  PROCEDURE INSERT_FIL_POLICY(P_EFFECTIVE_DATE              IN FEE_IN_LIEU_PERCENT.EFFECTIVE_DATE%TYPE,
                           P_FEE_IN_LIEU_PERCENT         IN FEE_IN_LIEU_PERCENT.FEE_IN_LIEU_PERCENT%TYPE,
                           P_ENTRY_USERID                IN FEE_IN_LIEU_PERCENT.ENTRY_USERID%TYPE,
                           R_POLICY                      IN OUT ref_lexis_fil_policy) IS

  V_FEE_IN_LIEU_PERCENT_ID FEE_IN_LIEU_PERCENT.FEE_IN_LIEU_PERCENT_ID%TYPE;

  BEGIN

    SELECT FEE_IN_LIEU_PERCENT_SEQ.Nextval
      INTO V_FEE_IN_LIEU_PERCENT_ID
      FROM DUAL;

    INSERT INTO FEE_IN_LIEU_PERCENT
      (FEE_IN_LIEU_PERCENT_ID,
       EFFECTIVE_DATE,
       FEE_IN_LIEU_PERCENT,
       ENTRY_USERID,
       ENTRY_TIMESTAMP,
       UPDATE_USERID,
       UPDATE_TIMESTAMP)
    VALUES
      (V_FEE_IN_LIEU_PERCENT_ID,
       P_EFFECTIVE_DATE,
       P_FEE_IN_LIEU_PERCENT,
       P_ENTRY_USERID,
       sysdate,
       P_ENTRY_USERID,
       sysdate);

    FIND_FIL_POLICY_BY_ID(V_FEE_IN_LIEU_PERCENT_ID, R_POLICY);

  END INSERT_FIL_POLICY;

  /******************************************************************************
      Procedure:  UPDATE_FEE_POLICY
      Purpose: Update a policy in LEXIS_FEE_POLICY
  ******************************************************************************/
  PROCEDURE UPDATE_FEE_POLICY(P_LEXIS_FEE_POLICY_ID  IN LEXIS_FEE_POLICY.LEXIS_FEE_POLICY_ID%TYPE,
                           P_EFFECTIVE_DATE              IN LEXIS_FEE_POLICY.EFFECTIVE_DATE%TYPE,
                           P_ORG_UNIT_NO                 IN LEXIS_FEE_POLICY.ORG_UNIT_NO%TYPE,
                           P_PERCENT_INCREASE            IN LEXIS_FEE_POLICY.PERCENT_INCREASE%TYPE,
                           P_UPDATE_USERID                IN LEXIS_FEE_POLICY.UPDATE_USERID%TYPE) IS

  fee_policy_rec lexis_fee_policy%rowtype;

  BEGIN

    select *
    into fee_policy_rec
    from LEXIS_FEE_POLICY fp
    where fp.lexis_fee_policy_id = P_LEXIS_FEE_POLICY_ID;

    fee_policy_rec.effective_date := P_EFFECTIVE_DATE;
    fee_policy_rec.percent_increase := P_PERCENT_INCREASE;
    fee_policy_rec.org_unit_no := P_ORG_UNIT_NO;
    fee_policy_rec.update_userid := P_UPDATE_USERID;
    fee_policy_rec.update_timestamp := sysdate;

    UPDATE LEXIS_FEE_POLICY
       set row = fee_policy_rec
     WHERE LEXIS_FEE_POLICY_ID = P_LEXIS_FEE_POLICY_ID;


  END UPDATE_FEE_POLICY;

    /******************************************************************************
      Procedure:  UPDATE_FEE_POLICY
      Purpose: Update a policy in LEXIS_FEE_POLICY
  ******************************************************************************/
  PROCEDURE UPDATE_FIL_POLICY(P_FEE_IN_LIEU_PERCENT_ID  IN FEE_IN_LIEU_PERCENT.FEE_IN_LIEU_PERCENT_ID%TYPE,
                           P_EFFECTIVE_DATE              IN FEE_IN_LIEU_PERCENT.EFFECTIVE_DATE%TYPE,
                           P_FEE_IN_LIEU_PERCENT            IN FEE_IN_LIEU_PERCENT.FEE_IN_LIEU_PERCENT%TYPE,
                           P_UPDATE_USERID                IN FEE_IN_LIEU_PERCENT.UPDATE_USERID%TYPE) IS

  fil_policy_rec FEE_IN_LIEU_PERCENT%rowtype;

  BEGIN

    select *
    into fil_policy_rec
    from FEE_IN_LIEU_PERCENT fp
    where fp.FEE_IN_LIEU_PERCENT_ID = P_FEE_IN_LIEU_PERCENT_ID;

    fil_policy_rec.effective_date := P_EFFECTIVE_DATE;
    fil_policy_rec.FEE_IN_LIEU_PERCENT := P_FEE_IN_LIEU_PERCENT;
    fil_policy_rec.update_userid := P_UPDATE_USERID;
    fil_policy_rec.update_timestamp := sysdate;

    UPDATE FEE_IN_LIEU_PERCENT
       set row = fil_policy_rec
     WHERE FEE_IN_LIEU_PERCENT_ID = P_FEE_IN_LIEU_PERCENT_ID;


  END UPDATE_FIL_POLICY;

