  /******************************************************************************
      Procedure:  FIND_FEE_POLICY
      Purpose: Finds a specific fee policy
  ******************************************************************************/
    PROCEDURE FIND_FEE_POLICY(P_EFFECTIVE_DATE     IN LEXIS_FEE_POLICY.EFFECTIVE_DATE%type,
                              P_ORG_UNIT_NO        IN LEXIS_FEE_POLICY.Org_Unit_No%type,
                              P_POLICY             IN OUT lexis.ref_lexis_fee_policy) IS
    begin

      open P_POLICY for
    select *
    from LEXIS_FEE_POLICY lfp
    where lfp.effective_date = P_EFFECTIVE_DATE and lfp.org_unit_no = P_ORG_UNIT_NO;

    end FIND_FEE_POLICY;

    /******************************************************************************
      Procedure:  FIND_FEE_POLICY
      Purpose: Finds a specific fee policy
  ******************************************************************************/
    PROCEDURE FIND_FIL_POLICY(P_EFFECTIVE_DATE     IN FEE_IN_LIEU_PERCENT.EFFECTIVE_DATE%type,
                              P_POLICY             IN OUT lexis.ref_lexis_fil_policy) IS
    begin

      open P_POLICY for
    select *
    from FEE_IN_LIEU_PERCENT lfp
    where lfp.effective_date = P_EFFECTIVE_DATE;

    end FIND_FIL_POLICY;

  /******************************************************************************
      Procedure:  GET_POLICY_FACTOR
      Purpose: Finds a specific fee policy factor
  ******************************************************************************/
  procedure GET_POLICY_FACTOR(P_DATE in date,
                              P_ORG_UNIT in lexis_fee_policy.org_unit_no%type,
                              P_RETURN in out lexis.ref_lexis_fee_policy) is
    v_percent_increase lexis_fee_policy.percent_increase%type;
    v_id lexis_fee_policy.lexis_fee_policy_id%type;
    BEGIN
    select lfp.lexis_fee_policy_id
    into v_id
    from lexis_fee_policy lfp,
    (
     select max(ilfp.effective_date) as effective_date
               from lexis_fee_policy ilfp
              where ilfp.org_unit_no = P_ORG_UNIT
                and ilfp.effective_date <= P_DATE

     ) mp

    where mp.effective_date = lfp.effective_date
    and lfp.org_unit_no = P_ORG_UNIT;

    open p_return for
    select *
    from lexis_fee_policy
    where lexis_fee_policy_id = v_id;

    end GET_POLICY_FACTOR;

      /******************************************************************************
      Procedure:  GET_POLICY_FACTOR
      Purpose: Finds a specific fee policy factor
  ******************************************************************************/
  procedure GET_POLICY_PERCENT(P_DATE in date,
                              P_RETURN in out lexis.ref_lexis_fil_policy) is

    v_fee_in_lieu_percent FEE_IN_LIEU_PERCENT.FEE_IN_LIEU_PERCENT%type;
    v_id FEE_IN_LIEU_PERCENT.FEE_IN_LIEU_PERCENT_ID%type;
    BEGIN
    select filp.FEE_IN_LIEU_PERCENT_ID
    into v_id
    from FEE_IN_LIEU_PERCENT filp,
    (
     select max(ilfp.effective_date) as effective_date
               from FEE_IN_LIEU_PERCENT ilfp
                where ilfp.effective_date <= P_DATE

     ) mp

    where filp.effective_date = filp.effective_date;

    open p_return for
    select *
    from FEE_IN_LIEU_PERCENT
    where FEE_IN_LIEU_PERCENT_ID = v_id;

    end GET_POLICY_PERCENT;

