  /******************************************************************************
      Procedure: IS_PERMIT_MU44
      Purpose: Determines if the permit contains any timber mark from MU 44
  ******************************************************************************/
  PROCEDURE IS_PERMIT_MU44(P_PERMIT_NUMBER IN EXPORT_PERMIT_DETAIL.EXPORT_PERMIT_DETAIL_NUMBER%TYPE,
                           P_IS_MU44 IN OUT ref_cur_general) IS
  BEGIN
    OPEN P_IS_MU44
    FOR SELECT COUNT( SD.Export_Permit_Detail_Number) AS RESULTS_COUNT
      FROM HAULING_AUTHORITY HA
    INNER JOIN HARVESTING_HAULING_XREF XR
            ON HA.TIMBER_MARK = XR.TIMBER_MARK
    INNER JOIN HARVESTING_AUTHORITY HVA
            ON XR.HVA_SKEY = HVA.HVA_SKEY AND HVA.MGMT_UNIT_ID = '44'
    INNER JOIN EXPORT_SCALE_DETAIL SD
            ON SD.TIMBER_MARK = HA.TIMBER_MARK
         WHERE SD.EXPORT_PERMIT_DETAIL_NUMBER = P_PERMIT_NUMBER;
  END IS_PERMIT_MU44;

  /******************************************************************************
      Procedure: IS_EXEMPTION_MU44
      Purpose: Determines if the exemption contains any timber mark from MU 44
  ******************************************************************************/
  PROCEDURE IS_EXEMPTION_MU44(P_EXEMPTION_NUMBER IN EXPORT_EXEMPTION.EXEMPTION_NUMBER%TYPE,
                           P_IS_MU44 IN OUT ref_cur_general) IS
  BEGIN
    OPEN P_IS_MU44
    FOR SELECT COUNT( SD.EXPORT_SCALE_DETAIL_ID) AS RESULTS_COUNT
      FROM HAULING_AUTHORITY HA
    INNER JOIN HARVESTING_HAULING_XREF XR
            ON HA.TIMBER_MARK = XR.TIMBER_MARK
    INNER JOIN HARVESTING_AUTHORITY HVA
            ON XR.HVA_SKEY = HVA.HVA_SKEY AND HVA.MGMT_UNIT_ID = '44'
    INNER JOIN EXPORT_SCALE_DETAIL SD
            ON SD.TIMBER_MARK = HA.TIMBER_MARK
    INNER JOIN EXPORT_PACKAGE PK
            ON PK.PACKAGE_NUMBER = SD.PACKAGE_NUMBER
    INNER JOIN EXPORT_EXEMPTION_APPLICATION EA
            ON EA.APPLICATION_NUMBER = PK.APPLICATION_NUMBER
         WHERE EA.EXEMPTION_NUMBER = P_EXEMPTION_NUMBER;
  END IS_EXEMPTION_MU44;

    /******************************************************************************
      Procedure: IS_APPLICATION_MU44
      Purpose: Determines if the application contains any timber mark from MU 44
  ******************************************************************************/
  PROCEDURE IS_APPLICATION_MU44(P_APPLICATION_NUMBER IN EXPORT_EXEMPTION_APPLICATION.APPLICATION_NUMBER%TYPE,
                           P_IS_MU44 IN OUT ref_cur_general) IS
  BEGIN
    OPEN P_IS_MU44
    FOR SELECT COUNT( SD.EXPORT_SCALE_DETAIL_ID) AS RESULTS_COUNT
      FROM HAULING_AUTHORITY HA
    INNER JOIN HARVESTING_HAULING_XREF XR
            ON HA.TIMBER_MARK = XR.TIMBER_MARK
    INNER JOIN HARVESTING_AUTHORITY HVA
            ON XR.HVA_SKEY = HVA.HVA_SKEY AND HVA.MGMT_UNIT_ID = '44'
    INNER JOIN EXPORT_SCALE_DETAIL SD
            ON SD.TIMBER_MARK = HA.TIMBER_MARK
    INNER JOIN EXPORT_PACKAGE PK
            ON PK.PACKAGE_NUMBER = SD.PACKAGE_NUMBER
         WHERE PK.APPLICATION_NUMBER = P_APPLICATION_NUMBER;
  END IS_APPLICATION_MU44;

  /*********************************************************************
     Function: GET_APPLICATION_APPROVAL_DATE
     Purpose: Get application approval date from the audit table
  *********************************************************************/
  FUNCTION GET_APPLICATION_APPROVAL_DATE (P_APPLICATION_NUMBER IN EXPORT_EXEMPTION_APPLICATION.APPLICATION_NUMBER%TYPE) return DATE IS
    V_APPROVAL_DATE DATE;
  BEGIN
        SELECT MAX(TT.entry_timestamp) INTO V_APPROVAL_DATE
    FROM (
        SELECT T.application_number, T.export_application_status_code, rank() over(PARTITION BY application_number ORDER BY entry_timestamp ASC) AS rnk, entry_timestamp
        FROM (
          SELECT application_number, nvl( update_timestamp, entry_timestamp) AS entry_timestamp, export_application_status_code
          FROM export_exemption_application
          WHERE export_application_status_code = 'APP'
          UNION ALL
          SELECT application_number, nvl( update_timestamp, entry_timestamp) AS entry_timestamp, export_application_status_code
          FROM export_exemption_appl_audit
          WHERE export_application_status_code = 'APP'
        ) T
      ) TT where TT.rnk = 1

      AND TT.APPLICATION_NUMBER = P_APPLICATION_NUMBER;

    return V_APPROVAL_DATE;
  END GET_APPLICATION_APPROVAL_DATE;



