  ******************************************************************************/
  PROCEDURE INSERT_EXPORT_PERMIT_INV_DET(P_PERMIT_INVOICE_NUMBER        IN EXPORT_PERMIT_INVOICE_DETAIL.PERMIT_INVOICE_NUMBER%TYPE,
                                                P_TIMBER_MARK                  IN EXPORT_PERMIT_INVOICE_DETAIL.TIMBER_MARK%TYPE,
                                                P_EXPORT_SPECIES_CODE          IN EXPORT_PERMIT_INVOICE_DETAIL.EXPORT_SPECIES_CODE%TYPE,
                                                P_EXPORT_GRADE_CODE            IN EXPORT_PERMIT_INVOICE_DETAIL.EXPORT_GRADE_CODE%TYPE,
                                                P_VOLUME                       IN EXPORT_PERMIT_INVOICE_DETAIL.VOLUME%TYPE,
                                                P_AMOUNT                       IN EXPORT_PERMIT_INVOICE_DETAIL.AMOUNT%TYPE,
                                                P_AMV_RATE                     IN EXPORT_PERMIT_INVOICE_DETAIL.AMV_RATE%TYPE,
                                                P_FEE_POLICY_ADMIN             IN EXPORT_PERMIT_INVOICE_DETAIL.FEE_POLICY_ADMIN%TYPE,
