                                                R_EXPORT_PERMIT_INVOICE_DETAIL IN OUT REF_PERMIT_INVOICE_DETAIL) IS

    V_PERMIT_INVOICE_DETAIL_NUMBER EXPORT_PERMIT_INVOICE_DETAIL.PERMIT_INVOICE_DETAIL_NUMBER%TYPE;
  BEGIN
    SELECT EXPORT_PERMIT_INVOICE_DET_SEQ.NEXTVAL
    INTO V_PERMIT_INVOICE_DETAIL_NUMBER
    FROM DUAL;

    INSERT INTO EXPORT_PERMIT_INVOICE_DETAIL
    (PERMIT_INVOICE_DETAIL_NUMBER,
     PERMIT_INVOICE_NUMBER,
     TIMBER_MARK,
     EXPORT_SPECIES_CODE,
     EXPORT_GRADE_CODE,
     VOLUME,
     AMOUNT,
     AMV_RATE,
     FEE_POLICY_ADMIN,
     FEE_PERCENTAGE,
     ENTRY_USERID,
     ENTRY_TIMESTAMP)
     VALUES
     (V_PERMIT_INVOICE_DETAIL_NUMBER,
     P_PERMIT_INVOICE_NUMBER,
     P_TIMBER_MARK,
     P_EXPORT_SPECIES_CODE,
     P_EXPORT_GRADE_CODE,
     P_VOLUME,
     P_AMOUNT,
     P_AMV_RATE,
     P_FEE_POLICY_ADMIN,
     P_FEE_PERCENTAGE,
     P_ENTRY_USERID,
     SYSDATE);

     FIND_EXPORT_PERMIT_INV_DET(P_PERMIT_INVOICE_NUMBER, R_EXPORT_PERMIT_INVOICE_DETAIL);

  END INSERT_EXPORT_PERMIT_INV_DET;

