  /******************************************************************************
      Procedure:  INSERT_EXPORT_PERMIT_INVOICE
      Purpose:
  ******************************************************************************/
  PROCEDURE INSERT_EXPORT_PERMIT_INVOICE(P_EXPORT_PERMIT_DETAIL_NUMBER  IN EXPORT_PERMIT_INVOICE.EXPORT_PERMIT_DETAIL_NUMBER%TYPE,
                                         P_GBMS_INVOICE_NUMBER          IN EXPORT_PERMIT_INVOICE.GBMS_INVOICE_NUMBER%TYPE,
                                         P_INVOICE_TOTAL                IN EXPORT_PERMIT_INVOICE.INVOICE_TOTAL%TYPE,
                                         P_CLIENT_NUMBER                IN EXPORT_PERMIT_INVOICE.CLIENT_NUMBER%TYPE,
                                         P_CLIENT_LOCN_CODE             IN EXPORT_PERMIT_INVOICE.CLIENT_LOCN_CODE%TYPE,
                                         P_EXEMPTION_OVERRIDE_RATE      IN EXPORT_PERMIT_INVOICE.EXEMPTION_OVERRIDE_RATE%TYPE,
                                         P_PERMIT_OVERRIDE_AMOUNT       IN EXPORT_PERMIT_INVOICE.PERMIT_OVERRIDE_AMOUNT%TYPE,
                                         P_ORIGIN_ORG_NO                IN EXPORT_PERMIT_INVOICE.ORIGIN_ORG_NO%TYPE,
                                         P_ADMIN_ORG_NO                 IN EXPORT_PERMIT_INVOICE.ADMIN_ORG_NO%TYPE,
                                         P_ACK_MASK_ACODE               IN EXPORT_PERMIT_INVOICE.ACK_MASK_ACODE%TYPE,
                                         P_SUBMIT_USERID                IN EXPORT_PERMIT_INVOICE.SUBMIT_USERID%TYPE,
                                         R_PERMIT_INVOICES              IN OUT ref_permit_invoice) IS

  V_EXPORT_PERMIT_INVOICE_NUMBER EXPORT_PERMIT_INVOICE.PERMIT_INVOICE_NUMBER%TYPE;

  BEGIN
    SELECT EXPORT_PERMIT_INVOICE_SEQ.NEXTVAL
      INTO V_EXPORT_PERMIT_INVOICE_NUMBER
      FROM DUAL;

    INSERT INTO EXPORT_PERMIT_INVOICE
      (PERMIT_INVOICE_NUMBER,
       EXPORT_PERMIT_DETAIL_NUMBER,
       GBMS_INVOICE_NUMBER,
       INVOICE_TOTAL,
       CLIENT_NUMBER,
       CLIENT_LOCN_CODE,
       EXEMPTION_OVERRIDE_RATE,
       PERMIT_OVERRIDE_AMOUNT,
       ORIGIN_ORG_NO,
       ADMIN_ORG_NO,
       ACK_MASK_ACODE,
       SUBMIT_TIMESTAMP,
       CANCEL_TIMESTAMP,
       SUBMIT_USERID,
       CANCEL_USERID,
       ENTRY_USERID,
       ENTRY_TIMESTAMP,
       UPDATE_USERID,
       UPDATE_TIMESTAMP)
    VALUES
      (V_EXPORT_PERMIT_INVOICE_NUMBER,
       P_EXPORT_PERMIT_DETAIL_NUMBER,
       P_GBMS_INVOICE_NUMBER,
       P_INVOICE_TOTAL,
       P_CLIENT_NUMBER,
       P_CLIENT_LOCN_CODE,
       P_EXEMPTION_OVERRIDE_RATE,
       P_PERMIT_OVERRIDE_AMOUNT,
       P_ORIGIN_ORG_NO,
       P_ADMIN_ORG_NO,
       P_ACK_MASK_ACODE,
       SYSDATE,
       NULL,
       P_SUBMIT_USERID,
       NULL,
       P_SUBMIT_USERID,
       SYSDATE,
       NULL,
       NULL);

    FIND_EXPORT_PERMIT_INVOICE(P_EXPORT_PERMIT_DETAIL_NUMBER, R_PERMIT_INVOICES);

  END INSERT_EXPORT_PERMIT_INVOICE;


  /******************************************************************************
      Procedure:  CANCEL_EXPORT_PERMIT_INVOICE
      Purpose:
  ******************************************************************************/
  PROCEDURE UPDATE_EXPORT_PERMIT_INVOICE(P_EXPORT_PERMIT_INVOICE_NUMBER  IN EXPORT_PERMIT_INVOICE.PERMIT_INVOICE_NUMBER%TYPE,
                                         P_GBMS_INVOICE_NUMBER IN EXPORT_PERMIT_INVOICE.GBMS_INVOICE_NUMBER%TYPE,
                                         P_CANCEL_USERID IN EXPORT_PERMIT_INVOICE.CANCEL_USERID%TYPE) IS
        V_PERMIT_AUDIT_ID EXPORT_PERMIT_INVOICE_AUDIT.EXPORT_PERMIT_INVOICE_AUDIT_ID%TYPE;
  BEGIN
 SELECT EXPORT_PERMIT_INVOICE_AUDT_SEQ.NEXTVAL
      INTO V_PERMIT_AUDIT_ID
      FROM DUAL;

      INSERT INTO EXPORT_PERMIT_INVOICE_AUDIT
                    (EXPORT_PERMIT_INVOICE_AUDIT_ID,
                    PERMIT_INVOICE_NUMBER,
                    EXPORT_PERMIT_DETAIL_NUMBER ,
                    GBMS_INVOICE_NUMBER ,
                    INVOICE_TOTAL ,
                    CLIENT_NUMBER ,
                    CLIENT_LOCN_CODE ,
                    EXEMPTION_OVERRIDE_RATE,
                    PERMIT_OVERRIDE_AMOUNT ,
                    ORIGIN_ORG_NO ,
                    ADMIN_ORG_NO ,
                    ACK_MASK_ACODE ,
                    SUBMIT_TIMESTAMP ,
                    CANCEL_TIMESTAMP ,
                    SUBMIT_USERID ,
                    CANCEL_USERID ,
                    ENTRY_USERID ,
                    ENTRY_TIMESTAMP,
                    UPDATE_USERID ,
                    UPDATE_TIMESTAMP
                )
      SELECT V_PERMIT_AUDIT_ID,
            EPI.PERMIT_INVOICE_NUMBER,
            EPI.EXPORT_PERMIT_DETAIL_NUMBER,
            EPI.GBMS_INVOICE_NUMBER,
            EPI.INVOICE_TOTAL,
            EPI.CLIENT_NUMBER,
            EPI.CLIENT_LOCN_CODE,
            EPI.EXEMPTION_OVERRIDE_RATE,
            EPI.PERMIT_OVERRIDE_AMOUNT,
            EPI.ORIGIN_ORG_NO,
            EPI.ADMIN_ORG_NO,
            EPI.ACK_MASK_ACODE,
            EPI.SUBMIT_TIMESTAMP,
            EPI.CANCEL_TIMESTAMP,
            EPI.SUBMIT_USERID,
            EPI.CANCEL_USERID,
            EPI.ENTRY_USERID ,
            EPI.ENTRY_TIMESTAMP,
            EPI.UPDATE_USERID ,
            EPI.UPDATE_TIMESTAMP
       FROM EXPORT_PERMIT_INVOICE EPI
    WHERE PERMIT_INVOICE_NUMBER  =
             P_EXPORT_PERMIT_INVOICE_NUMBER;

    UPDATE EXPORT_PERMIT_INVOICE
    SET
        GBMS_INVOICE_NUMBER = P_GBMS_INVOICE_NUMBER,
        CANCEL_USERID = P_CANCEL_USERID,
        CANCEL_TIMESTAMP = CASE WHEN P_CANCEL_USERID IS NULL THEN NULL ELSE SYSDATE END,
        UPDATE_USERID = P_CANCEL_USERID,
        UPDATE_TIMESTAMP = SYSDATE
    WHERE  PERMIT_INVOICE_NUMBER = P_EXPORT_PERMIT_INVOICE_NUMBER;

  END UPDATE_EXPORT_PERMIT_INVOICE;

  /******************************************************************************
      Procedure:  FIND_EXPORT_PERMIT_INVOICE
      Purpose:
  ******************************************************************************/
  PROCEDURE FIND_EXPORT_PERMIT_INVOICE(P_EXPORT_PERMIT_INVOICE_NUMBER  IN EXPORT_PERMIT_INVOICE.PERMIT_INVOICE_NUMBER%TYPE,
                                       R_PERMIT_INVOICES              IN OUT ref_permit_invoice) IS
  BEGIN
    OPEN R_PERMIT_INVOICES FOR
    SELECT
       PERMIT_INVOICE_NUMBER,
       EXPORT_PERMIT_DETAIL_NUMBER,
       GBMS_INVOICE_NUMBER,
       INVOICE_TOTAL,
       CLIENT_NUMBER,
       CLIENT_LOCN_CODE,
       EXEMPTION_OVERRIDE_RATE,
       PERMIT_OVERRIDE_AMOUNT,
       ORIGIN_ORG_NO,
       ADMIN_ORG_NO,
       ACK_MASK_ACODE,
       SUBMIT_TIMESTAMP,
       CANCEL_TIMESTAMP,
       SUBMIT_USERID,
       CANCEL_USERID
    FROM EXPORT_PERMIT_INVOICE
    WHERE EXPORT_PERMIT_DETAIL_NUMBER = P_EXPORT_PERMIT_INVOICE_NUMBER
    ORDER BY CANCEL_TIMESTAMP DESC;
  END FIND_EXPORT_PERMIT_INVOICE;


