  /******************************************************************************
      Procedure:  GBMS_INSERT_INVOICE_DTL_TXN
      Purpose: Inserts a record in INVOICE_DTL_TXN.
  ******************************************************************************/
  PROCEDURE GBMS_INSERT_INVOICE_DTL_TXN(P_INVOICE_NUMBER     IN INVOICE_DTL_TXN.Invoice_Number%type,
                                   P_ORG_UNIT_NO IN FOREST_ACCOUNT_XREF.ORG_UNIT_NO%type,
                                   P_NUMBER_OF_UNITS    IN INVOICE_DTL_TXN.Number_Of_Units%type,
                                   P_UNIT_OF_MEASURE_CD IN INVOICE_DTL_TXN.Unit_Of_Measure_Cd%type,
                                   P_UNIT_RATE          IN INVOICE_DTL_TXN.Unit_Rate%type,
                                   P_EXTENDED_AMOUNT    IN INVOICE_DTL_TXN.Extended_Amount%type,
                                   P_OCG_SUPPLIER_NMBR  IN INVOICE_DTL_TXN.Ocg_Supplier_Nmbr%type,
                                   P_ACK_MASK_ACODE     IN INVOICE_DTL_TXN.ACK_MASK_ACODE%type,
                                   P_ENTRY_USER         IN INVOICE_DTL_TXN.ENTRY_USERID%type,
                                   P_LINE_ITEM_DESCR    IN INVOICE_DTL_TXN.LINE_ITEM_DESCR%type,
                                   P_PST_IND            IN INVOICE_DTL_TXN.PST_IND%type,
                                   P_GST_IND            IN INVOICE_DTL_TXN.GST_IND%type,
                                   P_HST_IND            IN INVOICE_DTL_TXN.HST_IND%type,
                                   P_RESULT             IN OUT GBMS_PERSISTENCE.ref_invoice_dtl_txn) IS

    V_RESPONSE_CENTRE_CD INVOICE_DTL_TXN.RESPONSE_CENTRE_CD%TYPE;
  BEGIN
    SELECT
      RESPONSE_CENTRE_CODE INTO V_RESPONSE_CENTRE_CD
    FROM FOREST_ACCOUNT_XREF
    WHERE ORG_UNIT_NO = P_ORG_UNIT_NO AND ACK_MASK_ACODE = P_ACK_MASK_ACODE;

    GBMS_PERSISTENCE.INSERT_INVOICE_DTL_TXN(P_INVOICE_NUMBER,
                                            V_RESPONSE_CENTRE_CD,
                                            P_NUMBER_OF_UNITS,
                                            P_UNIT_OF_MEASURE_CD,
                                            P_UNIT_RATE,
                                            P_EXTENDED_AMOUNT,
                                            P_OCG_SUPPLIER_NMBR,
                                            P_ACK_MASK_ACODE,
                                            P_ENTRY_USER,
                                            P_LINE_ITEM_DESCR,
                                            P_PST_IND,
                                            P_GST_IND,
                                            P_HST_IND,
                                            P_RESULT);
  END GBMS_INSERT_INVOICE_DTL_TXN;

