  PROCEDURE FIND_GBMS_INVOICE_HISTORY(P_GBMS_INVOICE_NUMBER IN GBMS_INVOICE_HISTORY_VW.INVOICE_NUMBER%TYPE,
                                      P_EXPORT_PERMIT_DETAIL_NUMBER IN GBMS_INVOICE_HISTORY_VW.LEXIS_PERMIT_NUMBER%TYPE,
                                      R_GBMS_INVOICE_HISTORYS IN OUT ref_gbms_invoice_history) IS
    V_COUNTER INT;
    V_PERMIT_NUMBER VARCHAR2(15) := P_EXPORT_PERMIT_DETAIL_NUMBER;

    BEGIN
       SELECT COUNT(*) INTO V_COUNTER
       FROM GBMS_INVOICE_HISTORY_VW
       WHERE LEXIS_PERMIT_NUMBER = V_PERMIT_NUMBER;

       IF V_COUNTER = 0 THEN
         BEGIN
         -- TRY TO USE THE GBMS INVOICE NUMBER TO GET OTHER PERMIT NUMBER
         SELECT LEXIS_PERMIT_NUMBER INTO V_PERMIT_NUMBER
         FROM GBMS_INVOICE_HISTORY_VW
         WHERE LOWER(INVOICE_NUMBER) = LOWER(P_GBMS_INVOICE_NUMBER);
         EXCEPTION WHEN NO_DATA_FOUND THEN
           V_PERMIT_NUMBER := P_EXPORT_PERMIT_DETAIL_NUMBER;
         END;
       END IF;

       OPEN R_GBMS_INVOICE_HISTORYS FOR
          SELECT
             INVOICE_NUMBER,
             CANCELLED_BY_INVOICE,
             REPLACED_BY_INVOICE,
             LEXIS_PERMIT_NUMBER,
             INVOICE_AMOUNT,
             PRINTED_IND,
             PRINTED_DATE,
             ENTRY_USERID,
             ENTRY_TIMESTAMP,
             UPDATE_USERID,
             UPDATE_TIMESTAMP
          FROM GBMS_INVOICE_HISTORY_VW
          WHERE LEXIS_PERMIT_NUMBER = V_PERMIT_NUMBER;
   END FIND_GBMS_INVOICE_HISTORY;

  /******************************************************************************
      Procedure:  FIND_END_USE_BY_PERMIT
      Purpose: Find an end use by permit.
  ******************************************************************************/
  PROCEDURE FIND_END_USE_BY_PERMIT(P_PERMIT_ID IN EXPORT_PERMIT_APPL_SPCS_ENDUSE.EXPORT_PERMIT_DETAIL_NUMBER%TYPE,
                                R_END_USES IN OUT ref_end_use_permit) IS
  BEGIN
    OPEN R_END_USES FOR
      SELECT EPASE.EXPORT_END_USE_CODE,
             EPASE.EXPORT_SPECIES_CODE,
             EPASE.EXPORT_PERMIT_DETAIL_NUMBER
        FROM EXPORT_PERMIT_APPL_SPCS_ENDUSE EPASE
       WHERE EPASE.EXPORT_PERMIT_DETAIL_NUMBER = P_PERMIT_ID;
  END FIND_END_USE_BY_PERMIT;

  /******************************************************************************
      Procedure:  INSERT_END_USE_PERMIT
      Purpose: Inserts a new permit species end use
  ******************************************************************************/
 PROCEDURE INSERT_END_USE_PERMIT(P_PERMIT_NUMBER  IN EXPORT_PERMIT_APPL_SPCS_ENDUSE.EXPORT_PERMIT_DETAIL_NUMBER%TYPE,
                           P_EXPORT_SPECIES_CODE IN EXPORT_PERMIT_APPL_SPCS_ENDUSE.EXPORT_SPECIES_CODE%TYPE,
                           P_EXPORT_END_USE_CODE IN EXPORT_PERMIT_APPL_SPCS_ENDUSE.EXPORT_END_USE_CODE%TYPE) IS
  BEGIN
    INSERT INTO EXPORT_PERMIT_APPL_SPCS_ENDUSE EPASE
      (EXPORT_PERMIT_DETAIL_NUMBER, EXPORT_SPECIES_CODE, EXPORT_END_USE_CODE)
    VALUES
      (P_PERMIT_NUMBER, P_EXPORT_SPECIES_CODE, P_EXPORT_END_USE_CODE);
  END INSERT_END_USE_PERMIT;
  /******************************************************************************
      Procedure:  DELETE_END_USE
      Purpose: Deletes an application species end use
  ******************************************************************************/
  PROCEDURE DELETE_END_USE_PERMIT(P_PERMIT_NUMBER IN EXPORT_PERMIT_APPL_SPCS_ENDUSE.EXPORT_PERMIT_DETAIL_NUMBER%TYPE) IS
  BEGIN
    DELETE FROM EXPORT_PERMIT_APPL_SPCS_ENDUSE EPASE
     WHERE EPASE.EXPORT_PERMIT_DETAIL_NUMBER = P_PERMIT_NUMBER;
  END DELETE_END_USE_PERMIT;

  /******************************************************************************
      Procedure:  SET_FIL_CALULATED_VALUES
      Purpose: Set FIL calcuated values at the Scale, Package and Permit level
      Fear the query.
  ******************************************************************************/
PROCEDURE SET_FIL_CALULATED_VALUES(P_PERMIT_NUMBER IN EXPORT_PERMIT_DETAIL.EXPORT_PERMIT_DETAIL_NUMBER%TYPE) IS
v_current_package VARCHAR2(40);
v_package_total NUMBER(11,2);
v_permit_total NUMBER(11,2);
v_scale_total NUMBER(11,2);
v_loop_counter NUMBER(5);
v_product_type VARCHAR2(2);
v_growth_type  VARCHAR2(3);
v_permit_override_fee_ind VARCHAR2(1);
v_fil_admin_value FEE_IN_LIEU_PERCENT.FEE_IN_LIEU_PERCENT%TYPE;
v_permit_issue_date DATE;
v_species_grade_volume EXPORT_SCALE_DETAIL.SPECIES_GRADE_VOLUME%TYPE;
V_ORG_UNIT_NO EXPORT_PERMIT_DETAIL.ORG_UNIT_NO%TYPE;
V_APPLICATION_DATE EXPORT_PERMIT_DETAIL.APPLICATION_DATE%TYPE;
V_EXEMPTION_NUMBER  EXPORT_PERMIT_DETAIL.EXEMPTION_NUMBER%TYPE;
v_exemption_type_code    export_exemption.export_exemption_type_code%type;
V_COUNTRY_CODE      EXPORT_PERMIT_DETAIL.EXPORT_COUNTRY_CODE%type;
V_OVERRIDE_FEE    EXPORT_PERMIT_DETAIL.Override_Fee%TYPE;
V_ROW_COUNT number;
v_exemption_rate export_exemption_rate.fixed_exemption_rate%TYPE;
v_scale_exempt_ovrd_rate  EXPORT_SCALE_DETAIL.EXEMPTION_OVERRIDE_RATE%TYPE;
P_UPDATE_USERID  EXPORT_PERMIT_DETAIL.update_userid%TYPE;
P_UPDATE_TIMESTAMP    EXPORT_PERMIT_DETAIL.update_timestamp%TYPE;
BEGIN
  v_loop_counter := 1;
  v_package_total := 0;
  v_permit_total := 0;
  v_permit_override_fee_ind := 'N';

  SELECT epd.export_permit_issue_date INTO v_permit_issue_date FROM EXPORT_PERMIT_DETAIL epd WHERE epd.export_permit_detail_number = P_PERMIT_NUMBER;

  SELECT fee_in_lieu_percent INTO v_fil_admin_value
  FROM   (
    SELECT filp.fee_in_lieu_percent FROM FEE_IN_LIEU_PERCENT filp WHERE NVL(v_permit_issue_date, sysdate) > filp.effective_date ORDER BY filp.effective_date DESC
  )
  WHERE  ROWNUM = 1;

FOR curs IN (
WITH all_tables AS (
  SELECT

    /*+ materialize */
    DISTINCT epd.export_permit_detail_number,
    epd.application_date,
    ep.application_number,
    epd.export_growth_type_code,
    ep.package_number,
    esd.export_scale_detail_id,
    esd.export_species_code,
    esd.export_grade_code,
    esd.species_grade_volume,
    epd.org_unit_no,
    ela.effective_date,
    ela.average_market_price,
    ha.timber_mark,
    brm.timber_mark as rp_timber_mark,
    ha.forest_file_id,
    pfu.file_type_code,
    tm.mark_issue_date,
    hva.issue_date,
    astm.ecas_id,
    ads.cutting_permit_id,
    ads.appraisal_status_code,
    ads.appraisal_category_code,
    adsc.appraisal_method_code,
    naw.worksheet_reference_type_code,
    aw.appraised_worksheet_id,
    asr.appraised_stumpage_rate_id,
    asr.stumpage_rate_effective_date,
    srs.subtotal_value,
    srs.stumpage_rte_subtotal_typ_code,
    hs.tender_opening_dt,
    hva.expiry_date,
    hva.extend_date,
    aso.SPECIFIED_OPERATING_RATE as frz
  FROM
    export_permit_detail epd
    INNER JOIN export_scale_detail esd ON esd.export_permit_detail_number = epd.export_permit_detail_number
    INNER JOIN export_package ep ON esd.package_number = ep.package_number
    LEFT OUTER JOIN export_log_amv ela ON ela.export_species_code = esd.export_species_code
    AND ela.export_grade_code = esd.export_grade_code
    AND ela.export_growth_type_code = epd.export_growth_type_code
    --AND trunc(epd.APPLICATION_DATE, 'MONTH') = ELA.EFFECTIVE_DATE
    and  (SELECT MAX(ELA.EFFECTIVE_DATE)
    FROM EXPORT_LOG_AMV ELA
    WHERE ELA.EFFECTIVE_DATE <= epd.APPLICATION_DATE
    AND ELA.EXPORT_SPECIES_CODE = esd.export_species_code
    AND ELA.EXPORT_GRADE_CODE = esd.export_grade_code
    AND ELA.EXPORT_GROWTH_TYPE_CODE = epd.export_growth_type_code ) = ELA.EFFECTIVE_DATE
    AND not ELA.EFFECTIVE_DATE > trunc(epd.APPLICATION_DATE, 'MONTH')
    INNER JOIN hauling_authority ha ON ha.timber_mark = esd.timber_mark
    LEFT OUTER JOIN harvesting_hauling_xref hhx ON hhx.timber_mark = ha.timber_mark
    LEFT OUTER JOIN harvesting_authority hva ON hva.forest_file_id = ha.forest_file_id
    AND hva.hva_skey = hhx.hva_skey
    LEFT OUTER JOIN prov_forest_use pfu ON pfu.forest_file_id = ha.forest_file_id
    LEFT OUTER JOIN timber_mark tm ON tm.timber_mark = ha.timber_mark
    AND tm.forest_file_id = ha.forest_file_id
    LEFT OUTER JOIN blanket_road_mark brm ON brm.timber_mark = ha.timber_mark
    AND brm.forest_file_id = ha.forest_file_id
    LEFT OUTER JOIN ads_submitted_timber_mark astm ON astm.timber_mark = ha.timber_mark
    LEFT OUTER JOIN harvest_sale hs ON hs.forest_file_id = pfu.forest_file_id
    LEFT OUTER JOIN appraisal_data_submission ads ON ads.ecas_id = astm.ecas_id
    LEFT OUTER JOIN appraisal_data_submission_ctrl adsc ON adsc.ecas_id = ads.ecas_id
    LEFT OUTER JOIN appraised_worksheet aw ON aw.ecas_id = adsc.ecas_id
    LEFT OUTER JOIN appraised_stumpage_rate asr ON asr.appraised_worksheet_id = aw.appraised_worksheet_id
    LEFT OUTER JOIN stumpage_rate_subtotal srs ON srs.appraised_stumpage_rate_id = asr.appraised_stumpage_rate_id
    LEFT OUTER JOIN non_appraised_worksheet naw ON naw.timber_mark = ha.timber_mark
    LEFT OUTER JOIN ADS_SPECIFIED_OPERATION aso on ads.ecas_id = aso.ecas_id
    AND aso.SPECIFIED_OPERATIONS_PHS_CODE = 'ADM'
    AND aso.SPECIFIED_OPERATIONS_CODE = 'FRZ' -- NEEDED FOR DATA CONSISTENCY, BUT MAY REMOVE RESULTS
    -- AND narc.scale_grade_code = s.export_grade_code
  WHERE
    epd.export_permit_detail_number LIKE P_PERMIT_NUMBER
),
filc1 AS (
  SELECT
    a.export_scale_detail_id,
    a.pctg,
    a.subtotal_value,
    a.stumpage_rate_effective_date
  FROM
    (
      SELECT
        esd.export_scale_detail_id,
        esd.timber_mark,
        esd.export_species_code,
        esd.export_grade_code,
        srs.subtotal_value,
        (
          -- FIL %
          CASE WHEN esd.export_grade_code = 'Z' THEN 'N/A' WHEN REGEXP_LIKE(
            esd.export_species_code, '^(FI|CE|CY)$'
          ) THEN '15' WHEN REGEXP_LIKE(
            esd.export_species_code, '^(HE|BA|SP|WH|LO|YE|UU|WB)$'
          ) THEN CASE WHEN srs.subtotal_value BETWEEN 0
          AND 30.49 THEN '10' WHEN srs.subtotal_value BETWEEN 30.50
          AND 31.49 THEN '11' WHEN srs.subtotal_value BETWEEN 31.50
          AND 32.49 THEN '12' WHEN srs.subtotal_value BETWEEN 32.50
          AND 33.49 THEN '13' WHEN srs.subtotal_value BETWEEN 33.50
          AND 34.49 THEN '14' WHEN srs.subtotal_value BETWEEN 34.50
          AND 35.49 THEN '15' WHEN srs.subtotal_value BETWEEN 35.50
          AND 36.49 THEN '16' WHEN srs.subtotal_value BETWEEN 36.50
          AND 37.49 THEN '17' WHEN srs.subtotal_value BETWEEN 37.50
          AND 38.49 THEN '18' WHEN srs.subtotal_value BETWEEN 38.50
          AND 39.49 THEN '19' WHEN srs.subtotal_value BETWEEN 39.50
          AND 40.49 THEN '20' WHEN srs.subtotal_value BETWEEN 40.50
          AND 41.49 THEN '21' WHEN srs.subtotal_value BETWEEN 41.50
          AND 42.49 THEN '22' WHEN srs.subtotal_value BETWEEN 42.50
          AND 43.49 THEN '23' WHEN srs.subtotal_value BETWEEN 43.50
          AND 44.49 THEN '24' WHEN srs.subtotal_value BETWEEN 44.50
          AND 45.49 THEN '25' WHEN srs.subtotal_value BETWEEN 45.50
          AND 46.49 THEN '26' WHEN srs.subtotal_value BETWEEN 46.50
          AND 47.49 THEN '27' WHEN srs.subtotal_value BETWEEN 47.50
          AND 48.49 THEN '28' WHEN srs.subtotal_value BETWEEN 48.50
          AND 49.49 THEN '29' WHEN srs.subtotal_value BETWEEN 49.50
          AND 50.49 THEN '30' WHEN srs.subtotal_value BETWEEN 50.50
          AND 51.49 THEN '31' WHEN srs.subtotal_value BETWEEN 51.50
          AND 52.49 THEN '32' WHEN srs.subtotal_value BETWEEN 52.50
          AND 53.49 THEN '33' WHEN srs.subtotal_value BETWEEN 53.50
          AND 54.49 THEN '34' WHEN srs.subtotal_value BETWEEN 54.50
          AND 55.49 THEN '35' WHEN srs.subtotal_value BETWEEN 55.50
          AND 56.49 THEN '36' WHEN srs.subtotal_value BETWEEN 56.50
          AND 57.49 THEN '37' WHEN srs.subtotal_value BETWEEN 57.50
          AND 58.49 THEN '38' WHEN srs.subtotal_value BETWEEN 58.50
          AND 59.49 THEN '39' WHEN srs.subtotal_value BETWEEN 59.50
          AND 60.49 THEN '40' WHEN srs.subtotal_value BETWEEN 60.50
          AND 61.49 THEN '41' WHEN srs.subtotal_value BETWEEN 61.50
          AND 62.49 THEN '42' WHEN srs.subtotal_value BETWEEN 62.50
          AND 63.49 THEN '43' WHEN srs.subtotal_value BETWEEN 63.50
          AND 64.49 THEN '44' WHEN srs.subtotal_value BETWEEN 64.50
          AND 65.49 THEN '45' WHEN srs.subtotal_value BETWEEN 65.50
          AND 66.49 THEN '46' WHEN srs.subtotal_value BETWEEN 66.50
          AND 67.49 THEN '47' WHEN srs.subtotal_value BETWEEN 67.50
          AND 68.49 THEN '48' WHEN srs.subtotal_value BETWEEN 68.50
          AND 69.49 THEN '49' WHEN srs.subtotal_value BETWEEN 69.50
          AND 1000 THEN '50' ELSE 'ERR' END WHEN REGEXP_LIKE(
            esd.export_species_code, '^(AL|AR|AS|BI|CO|MA)$'
          ) THEN 'N/A' ELSE 'ERR' END
        ) AS pctg,
        asr.stumpage_rate_effective_date,
        ROW_NUMBER() OVER(
          PARTITION BY esd.export_scale_detail_id,
          esd.timber_mark,
          esd.export_species_code,
          esd.export_grade_code
          ORDER BY
            asr.stumpage_rate_effective_date
        ) row_num
      FROM
        export_scale_detail esd
        LEFT OUTER JOIN ads_submitted_timber_mark astm ON astm.timber_mark = esd.timber_mark
        LEFT OUTER JOIN appraisal_data_submission ads ON ads.ecas_id = astm.ecas_id
        LEFT OUTER JOIN appraisal_data_submission_ctrl adsc ON adsc.ecas_id = ads.ecas_id
        LEFT OUTER JOIN appraised_worksheet aw ON aw.ecas_id = adsc.ecas_id
        LEFT OUTER JOIN appraised_stumpage_rate asr ON asr.appraised_worksheet_id = aw.appraised_worksheet_id
        LEFT OUTER JOIN stumpage_rate_subtotal srs ON srs.appraised_stumpage_rate_id = asr.appraised_stumpage_rate_id
        LEFT OUTER JOIN ADS_SPECIFIED_OPERATION aso on ads.ecas_id = aso.ecas_id
        AND aso.SPECIFIED_OPERATIONS_PHS_CODE = 'ADM'
        AND aso.SPECIFIED_OPERATIONS_CODE = 'FRZ'
      WHERE
        esd.EXPORT_PERMIT_DETAIL_NUMBER LIKE P_PERMIT_NUMBER
        and srs.STUMPAGE_RTE_SUBTOTAL_TYP_CODE = 'EWB'
    ) a
  WHERE
    nvl(row_num, 1) = 1
),
filc2 AS (
  SELECT
    a.export_scale_detail_id,
    a.pctg,
    a.subtotal_value,
    a.stumpage_rate_effective_date
  FROM
    (
      SELECT
        esd.export_scale_detail_id,
        esd.timber_mark,
        esd.export_species_code,
        esd.export_grade_code,
        srs.subtotal_value,
        (
          -- FIL %
          CASE WHEN esd.export_grade_code = 'Z' THEN 'N/A' WHEN REGEXP_LIKE(
            esd.export_species_code, '^(FI|CE|CY)$'
          ) THEN '15' WHEN REGEXP_LIKE(
            esd.export_species_code, '^(HE|BA|SP|WH|LO|YE|UU|WB)$'
          ) THEN CASE WHEN srs.subtotal_value BETWEEN 0
          AND 30.49 THEN '10' WHEN srs.subtotal_value BETWEEN 30.50
          AND 31.49 THEN '11' WHEN srs.subtotal_value BETWEEN 31.50
          AND 32.49 THEN '12' WHEN srs.subtotal_value BETWEEN 32.50
          AND 33.49 THEN '13' WHEN srs.subtotal_value BETWEEN 33.50
          AND 34.49 THEN '14' WHEN srs.subtotal_value BETWEEN 34.50
          AND 35.49 THEN '15' WHEN srs.subtotal_value BETWEEN 35.50
          AND 36.49 THEN '16' WHEN srs.subtotal_value BETWEEN 36.50
          AND 37.49 THEN '17' WHEN srs.subtotal_value BETWEEN 37.50
          AND 38.49 THEN '18' WHEN srs.subtotal_value BETWEEN 38.50
          AND 39.49 THEN '19' WHEN srs.subtotal_value BETWEEN 39.50
          AND 40.49 THEN '20' WHEN srs.subtotal_value BETWEEN 40.50
          AND 41.49 THEN '21' WHEN srs.subtotal_value BETWEEN 41.50
          AND 42.49 THEN '22' WHEN srs.subtotal_value BETWEEN 42.50
          AND 43.49 THEN '23' WHEN srs.subtotal_value BETWEEN 43.50
          AND 44.49 THEN '24' WHEN srs.subtotal_value BETWEEN 44.50
          AND 45.49 THEN '25' WHEN srs.subtotal_value BETWEEN 45.50
          AND 46.49 THEN '26' WHEN srs.subtotal_value BETWEEN 46.50
          AND 47.49 THEN '27' WHEN srs.subtotal_value BETWEEN 47.50
          AND 48.49 THEN '28' WHEN srs.subtotal_value BETWEEN 48.50
          AND 49.49 THEN '29' WHEN srs.subtotal_value BETWEEN 49.50
          AND 50.49 THEN '30' WHEN srs.subtotal_value BETWEEN 50.50
          AND 51.49 THEN '31' WHEN srs.subtotal_value BETWEEN 51.50
          AND 52.49 THEN '32' WHEN srs.subtotal_value BETWEEN 52.50
          AND 53.49 THEN '33' WHEN srs.subtotal_value BETWEEN 53.50
          AND 54.49 THEN '34' WHEN srs.subtotal_value BETWEEN 54.50
          AND 1000 THEN '35' ELSE 'ERR' END WHEN REGEXP_LIKE(
            esd.export_species_code, '^(AL|AR|AS|BI|CO|MA)$'
          ) THEN 'N/A' ELSE 'ERR' END
        ) AS pctg,
        asr.stumpage_rate_effective_date,
        ROW_NUMBER() OVER(
          PARTITION BY esd.export_scale_detail_id,
          esd.timber_mark,
          esd.export_species_code,
          esd.export_grade_code
          ORDER BY
            asr.stumpage_rate_effective_date
        ) row_num
      FROM
        export_scale_detail esd
        LEFT OUTER JOIN ads_submitted_timber_mark astm ON astm.timber_mark = esd.timber_mark
        LEFT OUTER JOIN appraisal_data_submission ads ON ads.ecas_id = astm.ecas_id
        LEFT OUTER JOIN appraisal_data_submission_ctrl adsc ON adsc.ecas_id = ads.ecas_id
        LEFT OUTER JOIN appraised_worksheet aw ON aw.ecas_id = adsc.ecas_id
        LEFT OUTER JOIN appraised_stumpage_rate asr ON asr.appraised_worksheet_id = aw.appraised_worksheet_id
        LEFT OUTER JOIN stumpage_rate_subtotal srs ON srs.appraised_stumpage_rate_id = asr.appraised_stumpage_rate_id
        LEFT OUTER JOIN ADS_SPECIFIED_OPERATION aso on ads.ecas_id = aso.ecas_id
        AND aso.SPECIFIED_OPERATIONS_PHS_CODE = 'ADM'
        AND aso.SPECIFIED_OPERATIONS_CODE = 'FRZ'
      WHERE
        esd.EXPORT_PERMIT_DETAIL_NUMBER LIKE P_PERMIT_NUMBER
        and srs.STUMPAGE_RTE_SUBTOTAL_TYP_CODE = 'EWB'
    ) a
  WHERE
    nvl(row_num, 1) = 1
