-- S1
--
select
  PERMIT,
  export_scale_detail_id,
  application_number,
  org_unit_no,
  PERMIT_APPLICATION_DATE,
  AMV_DATE,
  query_section,
  timber_mark_issue_date,
  tender_opening_dt,
  worksheet_reference_type_code,
  BLANKET_ROAD_MARK,
  FILE_TYPE,
  TIMBER_MARK,
  SPECIES,
  GRADE,
  to_number(VOLUME) volume,
  AMV,
  fil,
  ewb,
  FRZ,
  "PACKAGE",
  stumpage_rate_effective_date,
  APPRAISAL_CATEGORY_CODE,
  APPRAISAL_STATUS,
  APPRAISAL_METHOD,
  CASE
    WHEN MULTIPLICATION_FACTOR = 'ERR' THEN
      'ERR'
    ELSE
      TO_CHAR((MULTIPLICATION_FACTOR - 1) * 100)
  END
  MULTIPLICATION_FACTOR
FROM
  (
    select
      PERMIT_APPLICATION_DATE,
      export_scale_detail_id,
      application_number,
      org_unit_no,
      "PACKAGE",
      TIMBER_MARK,
      SPECIES,
      GRADE,
      to_number(VOLUME) volume,
      PERMIT,
      AMV_DATE,
      AMV,
      FILE_TYPE,
      APPRAISAL_STATUS,
      APPRAISAL_METHOD,
      min(stumpage_rate_effective_Date) stumpage_rate_effective_date,
      fil,
      ewb,
      MULTIPLICATION_FACTOR,
      timber_mark_issue_date,
      tender_opening_dt,
      worksheet_reference_type_code,
      BLANKET_ROAD_MARK,
      APPRAISAL_CATEGORY_CODE,
      FRZ,
      query_section,
      ROW_NUMBER() OVER(
        PARTITION BY TIMBER_MARK,
        SPECIES,
        GRADE,
        "PACKAGE"
        ORDER BY
          query_section
      ) row_num
    from
      (
        (
          SELECT
            DISTINCT NVL(
              TO_CHAR(APPLICATION_DATE, 'YYYY-MM-DD'),
              'ERR'
            ) PERMIT_APPLICATION_DATE,
            a.export_scale_detail_id,
            a.application_number,
            a.org_unit_no,
            NVL(
              TO_CHAR(PACKAGE_NUMBER),
              'ERR'
            ) "PACKAGE",
            NVL(TIMBER_MARK, 'ERR') TIMBER_MARK,
            NVL(EXPORT_SPECIES_CODE, 'ERR') SPECIES,
            NVL(EXPORT_GRADE_CODE, 'ERR') GRADE,
            NVL(
              TO_CHAR(
                SUM(SPECIES_GRADE_VOLUME)
              ),
              'ERR'
            ) VOLUME,
            NVL(
              TO_CHAR(EXPORT_PERMIT_DETAIL_NUMBER),
              'ERR'
            ) PERMIT,
            (
              CASE WHEN EXPORT_SPECIES_CODE in ('AL', 'AR', 'AS', 'BI', 'CO', 'MA') THEN '' ELSE NVL(
                TO_CHAR(EFFECTIVE_DATE, 'YYYY-MM-DD'),
                'ERR'
              ) END
            ) AMV_DATE,
            (
              CASE WHEN EXPORT_SPECIES_CODE in ('AL', 'AR', 'AS', 'BI', 'CO', 'MA') THEN '1' ELSE NVL(
                TO_CHAR(
                  AVERAGE_MARKET_PRICE, '999999.99'
                ),
                'ERR'
              ) END
            ) AMV,
            NVL(FILE_TYPE_CODE, 'ERR') FILE_TYPE,
            NVL(APPRAISAL_STATUS_CODE, 'ERR') APPRAISAL_STATUS,
            NVL(APPRAISAL_METHOD_CODE, 'ERR') APPRAISAL_METHOD,
            NVL(
              TO_CHAR(
                a.STUMPAGE_RATE_EFFECTIVE_DATE,
                'YYYY-MM-DD'
              ),
              'ERR'
            ) STUMPAGE_RATE_EFFECTIVE_DATE,
            CASE WHEN TIMBER_MARK = 'A95353' THEN '14' WHEN TIMBER_MARK = 'TA0275' THEN '10' WHEN TENDER_OPENING_DT >= TO_DATE('2019-08-29', 'YYYY-MM-DD')
            AND TENDER_OPENING_DT < TO_DATE('2020-01-09', 'YYYY-MM-DD') THEN NVL(f.pctg, 'ERR') WHEN TENDER_OPENING_DT >= TO_DATE('2020-01-09', 'YYYY-MM-DD')
            AND TENDER_OPENING_DT < TO_DATE('2021-01-07', 'YYYY-MM-DD') THEN NVL(f2.pctg, 'ERR') WHEN TENDER_OPENING_DT >= TO_DATE('2021-01-07', 'YYYY-MM-DD') THEN NVL(f3.pctg, 'ERR') ELSE 'ERR' END FIL,
            CASE WHEN TENDER_OPENING_DT >= TO_DATE('2019-08-29', 'YYYY-MM-DD')
            AND TENDER_OPENING_DT < TO_DATE('2020-01-09', 'YYYY-MM-DD') THEN NVL(
              TO_CHAR(f.subtotal_value, '99999.99'),
              ''
            ) WHEN TENDER_OPENING_DT >= TO_DATE('2020-01-09', 'YYYY-MM-DD')
            AND TENDER_OPENING_DT < TO_DATE('2021-01-07', 'YYYY-MM-DD') THEN NVL(
              TO_CHAR(f2.subtotal_value, '99999.99'),
              ''
            ) WHEN TENDER_OPENING_DT >= TO_DATE('2021-01-07', 'YYYY-MM-DD') THEN NVL(
              TO_CHAR(f3.subtotal_value, '99999.99'),
              ''
            ) ELSE '' END EWB,
            NVL(
              TO_CHAR(
                LEXIS_POLICY.GET_POLICY_PCT_INCREASE(
                  a.application_date, a.org_unit_no
                )/ 100 + 1
              ),
              'ERR'
            ) MULTIPLICATION_FACTOR,
            NVL(
              TO_CHAR(ISSUE_DATE, 'YYYY-MM-DD'),
              'ERR'
            ) TIMBER_MARK_ISSUE_DATE,
            NVL(
              TO_CHAR(TENDER_OPENING_DT),
              'ERR'
            ) TENDER_OPENING_DT,
            NVL(
              a.worksheet_reference_type_code,
              ''
            ) worksheet_reference_type_code,
            '' BLANKET_ROAD_MARK,
            APPRAISAL_CATEGORY_CODE,
            NVL(
              TO_CHAR(
                SUM(a.frz)
              ),
              ''
            ) FRZ,
            'Section 1: Fully Appraised BCTS TMs effective July 1 2019' QUERY_SECTION
          FROM
            all_tables a
            LEFT OUTER JOIN filc1 f ON a.export_scale_detail_id = f.export_scale_detail_id
            LEFT OUTER JOIN filc2 f2 ON a.export_scale_detail_id = f2.export_scale_detail_id
            LEFT OUTER JOIN filc3 f3 ON a.export_scale_detail_id = f3.export_scale_detail_id -- Section1_2
          WHERE
            a.stumpage_rte_subtotal_typ_code = 'EWB' -- Section1_3: file_type_code BETWEEN A20-27 OR B20-B23
            AND (
              REGEXP_LIKE(
                FILE_TYPE_CODE, '^A2(0|1|2|3|4|5|6|7)$'
              )
              OR REGEXP_LIKE(FILE_TYPE_CODE, '^B2(0|1|2|3)$')
            ) -- Seciton1_4: HARVEST_SALE.TENDER_OPENING_DT is on or after July 8 2019
            AND TENDER_OPENING_DT >= TO_DATE('2019-08-29', 'YYYY-MM-DD') -- Section1_1
            AND a.export_permit_detail_number LIKE P_PERMIT_NUMBER
            AND a.STUMPAGE_RATE_EFFECTIVE_DATE = (
              CASE WHEN TENDER_OPENING_DT >= TO_DATE('2019-08-29', 'YYYY-MM-DD')
              AND TENDER_OPENING_DT < TO_DATE('2020-01-09', 'YYYY-MM-DD') THEN f.STUMPAGE_RATE_EFFECTIVE_DATE WHEN TENDER_OPENING_DT >= TO_DATE('2021-01-09', 'YYYY-MM-DD')
              AND TENDER_OPENING_DT < TO_DATE('2021-01-07', 'YYYY-MM-DD') THEN f2.STUMPAGE_RATE_EFFECTIVE_DATE ELSE f3.STUMPAGE_RATE_EFFECTIVE_DATE END
            )
          GROUP BY
            APPLICATION_DATE,
            a.export_scale_detail_id,
            a.application_number,
            a.org_unit_no,
            PACKAGE_NUMBER,
            TIMBER_MARK,
            EXPORT_SPECIES_CODE,
            EXPORT_GRADE_CODE,
            EXPORT_PERMIT_DETAIL_NUMBER,
            EFFECTIVE_DATE,
            AVERAGE_MARKET_PRICE,
            FILE_TYPE_CODE,
            APPRAISAL_STATUS_CODE,
            APPRAISAL_METHOD_CODE,
            a.STUMPAGE_RATE_EFFECTIVE_DATE,
            f.pctg,
            f2.pctg,
            f3.pctg,
            a.application_date,
            a.org_unit_no,
            f.subtotal_value,
            f2.subtotal_value,
            f3.subtotal_value,
            ISSUE_DATE,
            TENDER_OPENING_DT,
            a.worksheet_reference_type_code,
            APPRAISAL_CATEGORY_CODE
          UNION ALL
            --
            -- S2
            --
          SELECT
            DISTINCT NVL(
              TO_CHAR(APPLICATION_DATE, 'YYYY-MM-DD'),
              'ERR'
            ) PERMIT_APPLICATION_DATE,
            a.export_scale_detail_id,
            a.application_number,
            a.org_unit_no,
            NVL(
              TO_CHAR(PACKAGE_NUMBER),
              'ERR'
            ) "PACKAGE",
            NVL(TIMBER_MARK, 'ERR') TIMBER_MARK,
            NVL(EXPORT_SPECIES_CODE, 'ERR') SPECIES,
            NVL(EXPORT_GRADE_CODE, 'ERR') GRADE,
            NVL(
              TO_CHAR(
                SUM(SPECIES_GRADE_VOLUME)
              ),
              'ERR'
            ) VOLUME,
            NVL(
              TO_CHAR(EXPORT_PERMIT_DETAIL_NUMBER),
              'ERR'
            ) PERMIT,
            (
              CASE WHEN EXPORT_SPECIES_CODE in ('AL', 'AR', 'AS', 'BI', 'CO', 'MA') THEN '' ELSE NVL(
                TO_CHAR(EFFECTIVE_DATE, 'YYYY-MM-DD'),
                'ERR'
              ) END
            ) AMV_DATE,
            (
              CASE WHEN EXPORT_SPECIES_CODE in ('AL', 'AR', 'AS', 'BI', 'CO', 'MA') THEN '1' ELSE NVL(
                TO_CHAR(
                  AVERAGE_MARKET_PRICE, '999999.99'
                ),
                'ERR'
              ) END
            ) AMV,
            NVL(FILE_TYPE_CODE, 'ERR') FILE_TYPE,
            NVL(APPRAISAL_STATUS_CODE, 'ERR') APPRAISAL_STATUS,
            NVL(APPRAISAL_METHOD_CODE, 'ERR') APPRAISAL_METHOD,
            NVL(
              TO_CHAR(
                a.STUMPAGE_RATE_EFFECTIVE_DATE,
                'YYYY-MM-DD'
              ),
              'ERR'
            ) STUMPAGE_RATE_EFFECTIVE_DATE,
            (
              CASE WHEN a.APPLICATION_DATE >= TO_DATE('2021-04-01', 'YYYY-MM-DD') THEN --table 2
              (
                CASE WHEN NVL(EXTEND_DATE, EXPIRY_DATE) <= TO_DATE('2020-12-15', 'YYYY-MM-DD') THEN f3.pctg WHEN a.APPRAISAL_CATEGORY_CODE = 'P' THEN f.pctg WHEN a.STUMPAGE_RATE_EFFECTIVE_DATE >= TO_DATE('2020-12-15', 'YYYY-MM-DD')
                AND a.STUMPAGE_RATE_EFFECTIVE_DATE < TO_DATE('2021-03-31', 'YYYY-MM-DD') THEN f7.pctg ELSE f5.pctg END
              ) ELSE --table 1
              (
                CASE WHEN NVL(EXTEND_DATE, EXPIRY_DATE) <= TO_DATE('2020-12-15', 'YYYY-MM-DD') THEN f4.pctg WHEN a.APPRAISAL_CATEGORY_CODE = 'P' THEN f2.pctg WHEN a.ISSUE_DATE <= TO_DATE('2020-12-15', 'YYYY-MM-DD') THEN f8.pctg ELSE f6.pctg END
              ) END
            ) FIL,
            (
              CASE WHEN a.APPLICATION_DATE >= TO_DATE('2021-04-01', 'YYYY-MM-DD') THEN --table 2
              (
                CASE WHEN NVL(EXTEND_DATE, EXPIRY_DATE) <= TO_DATE('2020-12-15', 'YYYY-MM-DD') THEN NVL(
                  TO_CHAR(f3.subtotal_value, '99999.99'),
                  ''
                ) WHEN a.APPRAISAL_CATEGORY_CODE = 'P' THEN NVL(
                  TO_CHAR(f.subtotal_value, '99999.99'),
                  ''
                ) WHEN a.ISSUE_DATE >= TO_DATE('2020-12-15', 'YYYY-MM-DD') THEN NVL(
                  TO_CHAR(f7.subtotal_value, '99999.99'),
                  ''
                ) ELSE NVL(
                  TO_CHAR(f5.subtotal_value, '99999.99'),
                  ''
                ) END
              ) ELSE --table 1
              (
                CASE WHEN NVL(EXTEND_DATE, EXPIRY_DATE) <= TO_DATE('2020-12-15', 'YYYY-MM-DD') THEN NVL(
                  TO_CHAR(f4.subtotal_value, '99999.99'),
                  ''
                ) WHEN a.APPRAISAL_CATEGORY_CODE = 'P' THEN NVL(
                  TO_CHAR(f2.subtotal_value, '99999.99'),
                  ''
                ) WHEN a.ISSUE_DATE <= TO_DATE('2020-12-15', 'YYYY-MM-DD') THEN NVL(
                  TO_CHAR(f8.subtotal_value, '99999.99'),
                  ''
                ) ELSE NVL(
                  TO_CHAR(f6.subtotal_value, '99999.99'),
                  ''
                ) END
              ) END
            ) EWB,
            NVL(
              TO_CHAR(
                LEXIS_POLICY.GET_POLICY_PCT_INCREASE(
                  a.application_date, a.org_unit_no
                )/ 100 + 1
              ),
              'ERR'
            ) MULTIPLICATION_FACTOR,
            NVL(
              TO_CHAR(ISSUE_DATE, 'YYYY-MM-DD'),
              'ERR'
            ) TIMBER_MARK_ISSUE_DATE,
            NVL(
              TO_CHAR(TENDER_OPENING_DT),
              ''
            ) TENDER_OPENING_DT,
            NVL(
              a.worksheet_reference_type_code,
              ''
            ) worksheet_reference_type_code,
            '' BLANKET_ROAD_MARK,
            APPRAISAL_CATEGORY_CODE,
            NVL(
              TO_CHAR(
                SUM(a.frz)
              ),
              ''
            ) FRZ,
            'Section 2: All other Fully Appraised TMs (i.e. non-BCTS TM) that are issued on or after Dec 15 2019' QUERY_SECTION
          FROM
            all_tables a
            LEFT OUTER JOIN filc9 f ON a.export_scale_detail_id = f.export_scale_detail_id
            LEFT OUTER JOIN filc10 f2 ON a.export_scale_detail_id = f2.export_scale_detail_id
            LEFT OUTER JOIN filc5 f3 ON a.export_scale_detail_id = f3.export_scale_detail_id
            LEFT OUTER JOIN filc6 f4 ON a.export_scale_detail_id = f4.export_scale_detail_id
            LEFT OUTER JOIN filc7 f5 ON a.export_scale_detail_id = f5.export_scale_detail_id
            LEFT OUTER JOIN filc8 f6 ON a.export_scale_detail_id = f6.export_scale_detail_id
            LEFT OUTER JOIN filc4 f7 ON a.export_scale_detail_id = f7.export_scale_detail_id
            LEFT OUTER JOIN filc12 f8 ON a.export_scale_detail_id = f8.export_scale_detail_id -- Section2_1
          WHERE
            a.export_permit_detail_number LIKE P_PERMIT_NUMBER -- Section2_2
            AND UPPER(
              a.stumpage_rte_subtotal_typ_code
            ) = 'EWB' -- Section2_3
            AND UPPER(FILE_TYPE_CODE) NOT IN ('B08', 'B09', 'B13', 'B14')
            AND NOT REGEXP_LIKE(
              FILE_TYPE_CODE, '^A2(0|1|2|3|4|5|6|7)$'
            )
            AND NOT REGEXP_LIKE(FILE_TYPE_CODE, '^B2(0|1|2|3)$')
            AND a.STUMPAGE_RATE_EFFECTIVE_DATE =(
              CASE WHEN a.APPLICATION_DATE >= TO_DATE('2021-04-01', 'YYYY-MM-DD') THEN --table 2
              (
                CASE WHEN NVL(EXTEND_DATE, EXPIRY_DATE) <= TO_DATE('2020-12-15', 'YYYY-MM-DD') THEN f3.STUMPAGE_RATE_EFFECTIVE_DATE WHEN a.APPRAISAL_CATEGORY_CODE = 'P' THEN f.STUMPAGE_RATE_EFFECTIVE_DATE WHEN a.ISSUE_DATE >= TO_DATE('2020-12-15', 'YYYY-MM-DD') THEN f7.STUMPAGE_RATE_EFFECTIVE_DATE ELSE f5.STUMPAGE_RATE_EFFECTIVE_DATE END
              ) ELSE (
                CASE WHEN NVL(EXTEND_DATE, EXPIRY_DATE) <= TO_DATE('2020-12-15', 'YYYY-MM-DD') THEN f4.STUMPAGE_RATE_EFFECTIVE_DATE WHEN a.APPRAISAL_CATEGORY_CODE = 'P' THEN f2.STUMPAGE_RATE_EFFECTIVE_DATE WHEN a.ISSUE_DATE <= TO_DATE('2020-12-15', 'YYYY-MM-DD') THEN f8.STUMPAGE_RATE_EFFECTIVE_DATE ELSE f6.STUMPAGE_RATE_EFFECTIVE_DATE END
              ) END
            )
          GROUP BY
            APPLICATION_DATE,
            a.export_scale_detail_id,
            a.application_number,
            a.org_unit_no,
            PACKAGE_NUMBER,
            TIMBER_MARK,
            EXPORT_SPECIES_CODE,
            EXPORT_GRADE_CODE,
            EXPORT_PERMIT_DETAIL_NUMBER,
            EFFECTIVE_DATE,
            AVERAGE_MARKET_PRICE,
            FILE_TYPE_CODE,
            APPRAISAL_STATUS_CODE,
            APPRAISAL_METHOD_CODE,
            a.application_date,
            a.org_unit_no,
            f.subtotal_value,
            f2.subtotal_value,
            f3.subtotal_value,
            f4.subtotal_value,
            f5.subtotal_value,
            f6.subtotal_value,
            f7.subtotal_value,
            f8.subtotal_value,
            a.STUMPAGE_RATE_EFFECTIVE_DATE,
            f.pctg,
            f2.pctg,
            f3.pctg,
            f4.pctg,
            f5.pctg,
            f6.pctg,
            f7.pctg,
            f8.pctg,
            STUMPAGE_RTE_SUBTOTAL_TYP_CODE,
            ISSUE_DATE,
            EXPIRY_DATE,
            EXTEND_DATE,
            worksheet_reference_type_code,
            TENDER_OPENING_DT,
            APPRAISAL_CATEGORY_CODE
          UNION ALL
            --
            -- S3
            --
          SELECT
            DISTINCT NVL(
              TO_CHAR(APPLICATION_DATE, 'YYYY-MM-DD'),
              'ERR'
            ) PERMIT_APPLICATION_DATE,
            a.export_scale_detail_id,
            a.application_number,
            a.org_unit_no,
            NVL(
              TO_CHAR(PACKAGE_NUMBER),
              'ERR'
            ) "PACKAGE",
            NVL(TIMBER_MARK, 'ERR') TIMBER_MARK,
            NVL(EXPORT_SPECIES_CODE, 'ERR') SPECIES,
            NVL(EXPORT_GRADE_CODE, 'ERR') GRADE,
            NVL(
              TO_CHAR(
                SUM(SPECIES_GRADE_VOLUME)
              ),
              'ERR'
            ) VOLUME,
            NVL(
              TO_CHAR(EXPORT_PERMIT_DETAIL_NUMBER),
              'ERR'
            ) PERMIT,
            (
              CASE WHEN EXPORT_SPECIES_CODE in ('AL', 'AR', 'AS', 'BI', 'CO', 'MA') THEN '' ELSE NVL(
                TO_CHAR(EFFECTIVE_DATE, 'YYYY-MM-DD'),
                'ERR'
              ) END
            ) AMV_DATE,
            (
              CASE WHEN EXPORT_SPECIES_CODE in ('AL', 'AR', 'AS', 'BI', 'CO', 'MA') THEN '1' ELSE NVL(
                TO_CHAR(
                  AVERAGE_MARKET_PRICE, '999999.99'
                ),
                'ERR'
              ) END
            ) AMV,
            NVL(FILE_TYPE_CODE, 'ERR') FILE_TYPE,
            '' APPRAISAL_STATUS,
            '' APPRAISAL_METHOD_CODE,
            '' STUMPAGE_RATE_EFFECTIVE_DATE,
            NVL(f.pctg, 'ERR') FIL,
            '' EWB,
            NVL(
              TO_CHAR(
                LEXIS_POLICY.GET_POLICY_PCT_INCREASE(
                  a.application_date, a.org_unit_no
                )/ 100 + 1
              ),
              'ERR'
            ) MULTIPLICATION_FACTOR,
            (
              CASE WHEN a.worksheet_reference_type_code = 'RP'
              OR a.FILE_TYPE_CODE = 'B09'
              OR a.rp_timber_mark IS NOT NULL THEN NVL(
                TO_CHAR(ISSUE_DATE, 'YYYY-MM-DD'),
                ''
              ) ELSE NVL(
                TO_CHAR(ISSUE_DATE, 'YYYY-MM-DD'),
                'ERR'
              ) END
            ) TIMBER_MARK_ISSUE_DATE,
            (
              CASE WHEN a.worksheet_reference_type_code IN ('DK', 'DKC')
              AND (
                REGEXP_LIKE(
                  FILE_TYPE_CODE, '^A2(0|1|2|3|4|5|6|7)$'
                )
                OR REGEXP_LIKE(FILE_TYPE_CODE, '^B2(0|1|2|3)$')
              ) THEN NVL(
                TO_CHAR(TENDER_OPENING_DT),
                'ERR'
              ) ELSE NVL(
                TO_CHAR(TENDER_OPENING_DT),
                ''
              ) END
            ) TENDER_OPENING_DT,
            (
              CASE WHEN a.FILE_TYPE_CODE = 'B09'
              OR a.rp_timber_mark IS NOT NULL THEN NVL(
                worksheet_reference_type_code, ''
              ) ELSE NVL(
                worksheet_reference_type_code, 'ERR'
              ) END
            ) worksheet_reference_type_code,
            (
              CASE WHEN a.worksheet_reference_type_code = 'RP' THEN (
                CASE WHEN a.rp_timber_mark IS NOT NULL THEN 'RP' ELSE 'ERR' END
              ) ELSE (
                CASE WHEN a.rp_timber_mark IS NOT NULL THEN 'RP' ELSE '' END
              ) END
            ) BLANKET_ROAD_MARK,
            APPRAISAL_CATEGORY_CODE,
            NVL(
              TO_CHAR(
                SUM(a.frz)
              ),
              ''
            ) FRZ,
            'Section 3: All Non-Appraised TMs (Miscellaneous Timber Pricing Policy - Chapter 7, Coast Appraisal Manual)' QUERY_SECTION
          FROM
            all_tables a
            LEFT OUTER JOIN filc11 f ON a.export_scale_detail_id = f.export_scale_detail_id -- SECTION 3_1
          WHERE
            a.export_permit_detail_number LIKE P_PERMIT_NUMBER
            AND (
              --SECTION3_2
              (
                a.worksheet_reference_type_code in (
                  'CF', 'CRA', 'DT', 'DR', 'GBR', 'GBN',
                  'GRP', 'LT', 'MD', 'PH', 'SRD', 'SFP',
                  'WL'
                )
              ) --SECTION3_3
              OR (
                a.worksheet_reference_type_code in ('DK', 'DKC', 'DPD', 'DPC')
              ) --SECTION3_4
              OR FILE_TYPE_CODE = 'B09' --SECTION3_5
              OR a.rp_timber_mark IS NOT NULL
              OR a.timber_mark = 'BCOMB6'
            )
            AND a.timber_mark NOT IN (
              'TA0912', 'TA0978', 'TA1110', 'A0912',
              'A0978', 'A1110'
            )
          GROUP BY
            APPLICATION_DATE,
            a.export_scale_detail_id,
            a.application_number,
            a.org_unit_no,
            PACKAGE_NUMBER,
            TIMBER_MARK,
            EXPORT_SPECIES_CODE,
            EXPORT_GRADE_CODE,
            EXPORT_PERMIT_DETAIL_NUMBER,
            EFFECTIVE_DATE,
            AVERAGE_MARKET_PRICE,
            FILE_TYPE_CODE,
            APPRAISAL_STATUS_CODE,
            APPRAISAL_METHOD_CODE,
            STUMPAGE_RATE_EFFECTIVE_DATE,
            f.pctg,
            STUMPAGE_RTE_SUBTOTAL_TYP_CODE,
            a.application_date,
            a.org_unit_no,
            ISSUE_DATE,
            TENDER_OPENING_DT,
            worksheet_reference_type_code,
            a.rp_timber_mark,
            APPRAISAL_CATEGORY_CODE -- Section 4
            )
        union
          (
            select
              permit_application_date,
              export_scale_detail_id,
              application_number,
              org_unit_no,
              package,
              timber_mark,
              species,
              grade,
              volume,
              permit,
              amv_date,
              amv,
              file_type,
              appraisal_status,
              appraisal_method,
              STUMPAGE_RATE_EFFECTIVE_DATE,
              case when grade = 'Z' then 'N/A' when species in ('FI', 'CE', 'CY') then '15' when species in (
                'HE', 'BA', 'SP', 'WH', 'LO', 'YE', 'UU',
                'WB'
              )
              and grade not in ('U', 'X', 'Y', 'Z') then '10' when species in (
                'HE', 'BA', 'SP', 'WH', 'LO', 'YE', 'UU',
                'WB'
              )
              and grade in ('U', 'X', 'Y', 'Z') then '5' when species in ('AL', 'AR', 'AS', 'BI', 'CO', 'MA') THEN 'N/A' else '0' END FIL,
              EWB,
              MULTIPLICATION_FACTOR,
              TIMBER_MARK_ISSUE_DATE,
              TENDER_OPENING_DT,
              worksheet_reference_type_code,
              BLANKET_ROAD_MARK,
              APPRAISAL_CATEGORY_CODE,
              FRZ,
              QUERY_SECTION
            from
              (
                SELECT
                  DISTINCT NVL(
                    TO_CHAR(APPLICATION_DATE, 'YYYY-MM-DD'),
                    'ERR'
                  ) PERMIT_APPLICATION_DATE,
                  ESD.export_scale_detail_id,
                  ep.application_number,
                  EPD.ORG_UNIT_NO,
                  NVL(
                    TO_CHAR(ESD.PACKAGE_NUMBER),
                    'ERR'
                  ) "PACKAGE",
                  NVL(ESD.TIMBER_MARK, 'ERR') TIMBER_MARK,
                  NVL(ESD.EXPORT_SPECIES_CODE, 'ERR') SPECIES,
                  NVL(ESD.EXPORT_GRADE_CODE, 'ERR') GRADE,
                  NVL(
                    TO_CHAR(SPECIES_GRADE_VOLUME),
                    'ERR'
                  ) VOLUME,
                  NVL(
                    TO_CHAR(
                      ESD.EXPORT_PERMIT_DETAIL_NUMBER
                    ),
                    'ERR'
                  ) PERMIT,
                  (
                    CASE WHEN ESD.EXPORT_SPECIES_CODE in ('AL', 'AR', 'AS', 'BI', 'CO', 'MA') THEN '' ELSE NVL(
                      TO_CHAR(
                        ELA.EFFECTIVE_DATE, 'YYYY-MM-DD'
                      ),
                      'ERR'
                    ) END
                  ) AMV_DATE,
                  (
                    CASE WHEN ESD.EXPORT_SPECIES_CODE in ('AL', 'AR', 'AS', 'BI', 'CO', 'MA') THEN '1' ELSE NVL(
                      TO_CHAR(
                        ELA.AVERAGE_MARKET_PRICE, '999999.99'
                      ),
                      'ERR'
                    ) END
                  ) AMV,
                  NVL(FILE_TYPE_CODE, 'ERR') FILE_TYPE,
                  NVL(APPRAISAL_STATUS_CODE, 'ERR') APPRAISAL_STATUS,
                  NVL(
                    adsc.APPRAISAL_METHOD_CODE, 'ERR'
                  ) APPRAISAL_METHOD,
                  NVL(
                    TO_CHAR(
                      STUMPAGE_RATE_EFFECTIVE_DATE, 'YYYY-MM-DD'
                    ),
                    'ERR'
                  ) STUMPAGE_RATE_EFFECTIVE_DATE,
                  '' EWB,
                  NVL(
                    TO_CHAR(
                      LEXIS_POLICY.GET_POLICY_PCT_INCREASE(application_date, org_unit_no)/ 100 + 1
                    ),
                    'ERR'
                  ) MULTIPLICATION_FACTOR,
                  NVL(
                    TO_CHAR(ISSUE_DATE, 'YYYY-MM-DD'),
                    'ERR'
                  ) TIMBER_MARK_ISSUE_DATE,
                  NVL(
                    TO_CHAR(TENDER_OPENING_DT),
                    ''
                  ) TENDER_OPENING_DT,
                  NVL(
                    naw.worksheet_reference_type_code,
                    ''
                  ) worksheet_reference_type_code,
                  '' BLANKET_ROAD_MARK,
                  APPRAISAL_CATEGORY_CODE,
                  NVL(
                    TO_CHAR(
                      SUM(aso.SPECIFIED_OPERATING_RATE)
                    ),
                    ''
                  ) as frz,
                  'Section 4: All other line items' QUERY_SECTION,
                  ROW_NUMBER() OVER(
                    PARTITION BY esd.timber_mark,
                    esd.export_species_code,
                    esd.export_grade_code,
                    esd.PACKAGE_NUMBER
                    ORDER BY
                      asr.stumpage_rate_effective_date
                  ) row_num
                FROM
                  export_permit_detail epd
                  INNER JOIN export_scale_detail esd ON esd.export_permit_detail_number = epd.export_permit_detail_number
                  INNER JOIN export_package ep ON esd.package_number = ep.package_number
                  LEFT OUTER JOIN export_log_amv ela ON ela.export_species_code = esd.export_species_code
                  AND ela.export_grade_code = esd.export_grade_code
                  AND ela.export_growth_type_code = epd.export_growth_type_code
                  --AND trunc(epd.APPLICATION_DATE, 'MONTH') = ELA.EFFECTIVE_DATE
                  and  (SELECT MAX(ELA.EFFECTIVE_DATE)
                  FROM EXPORT_LOG_AMV ELA
                  WHERE ELA.EFFECTIVE_DATE <= epd.APPLICATION_DATE
                  AND ELA.EXPORT_SPECIES_CODE = esd.export_species_code
                  AND ELA.EXPORT_GRADE_CODE = esd.export_grade_code
                  AND ELA.EXPORT_GROWTH_TYPE_CODE = epd.export_growth_type_code ) = ELA.EFFECTIVE_DATE
                  AND not ELA.EFFECTIVE_DATE > trunc(epd.APPLICATION_DATE, 'MONTH')
                  INNER JOIN hauling_authority ha ON ha.timber_mark = esd.timber_mark
                  LEFT OUTER JOIN harvesting_hauling_xref hhx ON hhx.timber_mark = ha.timber_mark
                  LEFT OUTER JOIN harvesting_authority hva ON hva.forest_file_id = ha.forest_file_id
                  AND hva.hva_skey = hhx.hva_skey
                  LEFT OUTER JOIN prov_forest_use pfu ON pfu.forest_file_id = ha.forest_file_id
                  LEFT OUTER JOIN timber_mark tm ON tm.timber_mark = ha.timber_mark
                  AND tm.forest_file_id = ha.forest_file_id
                  LEFT OUTER JOIN ads_submitted_timber_mark astm ON astm.timber_mark = ha.timber_mark
                  LEFT OUTER JOIN harvest_sale hs ON hs.forest_file_id = pfu.forest_file_id
                  LEFT OUTER JOIN appraisal_data_submission ads ON ads.ecas_id = astm.ecas_id
                  LEFT OUTER JOIN appraisal_data_submission_ctrl adsc ON adsc.ecas_id = ads.ecas_id
                  LEFT OUTER JOIN appraised_worksheet aw ON aw.ecas_id = adsc.ecas_id
                  LEFT OUTER JOIN appraised_stumpage_rate asr ON asr.appraised_worksheet_id = aw.appraised_worksheet_id
                  LEFT OUTER JOIN stumpage_rate_subtotal srs ON srs.appraised_stumpage_rate_id = asr.appraised_stumpage_rate_id
                  LEFT OUTER JOIN non_appraised_worksheet naw ON naw.timber_mark = ha.timber_mark
                  LEFT OUTER JOIN ADS_SPECIFIED_OPERATION aso on ads.ecas_id = aso.ecas_id
                  AND aso.SPECIFIED_OPERATIONS_PHS_CODE = 'ADM'
                  AND aso.SPECIFIED_OPERATIONS_CODE = 'FRZ' -- Section1_2
                WHERE
                  epd.export_permit_detail_number LIKE P_PERMIT_NUMBER
                GROUP BY
                  EPD.APPLICATION_DATE,
                  ESD.export_scale_detail_id,
                  ep.application_number,
                  EPD.org_unit_no,
                  ESD.PACKAGE_NUMBER,
                  ESD.TIMBER_MARK,
                  ESD.EXPORT_SPECIES_CODE,
                  ESD.EXPORT_GRADE_CODE,
                  ESD.EXPORT_PERMIT_DETAIL_NUMBER,
                  ELA.EFFECTIVE_DATE,
                  ELA.AVERAGE_MARKET_PRICE,
                  FILE_TYPE_CODE,
                  APPRAISAL_STATUS_CODE,
                  adsc.APPRAISAL_METHOD_CODE,
                  STUMPAGE_RATE_EFFECTIVE_DATE,
                  epd.application_date,
                  epd.org_unit_no,
                  subtotal_value,
                  ISSUE_DATE,
                  SPECIES_GRADE_VOLUME,
                  TENDER_OPENING_DT,
                  naw.worksheet_reference_type_code,
                  APPRAISAL_CATEGORY_CODE
              )
            where
              row_num = 1
          )
      )
    group by
      PERMIT_APPLICATION_DATE,
      export_scale_detail_id,
      application_number,
      org_unit_no,
      "PACKAGE",
      TIMBER_MARK,
      SPECIES,
      GRADE,
      VOLUME,
      PERMIT,
      AMV,
      AMV_DATE,
      FILE_TYPE,
      APPRAISAL_STATUS,
      APPRAISAL_METHOD,
      MULTIPLICATION_FACTOR,
      FIL,
      EWB,
      timber_mark_issue_date,
      tender_opening_dt,
      worksheet_reference_type_code,
      BLANKET_ROAD_MARK,
      APPRAISAL_CATEGORY_CODE,
      FRZ,
      QUERY_SECTION
    ORDER BY
      "PACKAGE",
      TIMBER_MARK,
      SPECIES,
      GRADE,
      PERMIT_APPLICATION_DATE,
      PERMIT,
      AMV_DATE,
      FILE_TYPE,
      APPRAISAL_STATUS,
      APPRAISAL_METHOD,
      FIL,
      EWB,
      TIMBER_MARK_ISSUE_DATE,
      worksheet_reference_type_code
  )
WHERE
  row_num = 1)
 LOOP
        IF v_loop_counter = 1 THEN
          v_current_package := curs.PACKAGE;
        END IF;

        select eea.export_product_type_code, eea.export_growth_type_code into v_product_type, v_growth_type
          from export_exemption_application eea
          where eea.application_number = curs.application_number;

        SELECT epd.permit_override_fee_ind, epd.org_unit_no, epd.application_date, epd.exemption_number, epd.export_country_code, epd.override_fee, epd.update_userid,epd.update_timestamp
        INTO v_permit_override_fee_ind,V_ORG_UNIT_NO, V_APPLICATION_DATE,V_EXEMPTION_NUMBER, V_COUNTRY_CODE, V_OVERRIDE_FEE, P_UPDATE_USERID, P_UPDATE_TIMESTAMP
        FROM EXPORT_PERMIT_DETAIL epd WHERE epd.export_permit_detail_number = P_PERMIT_NUMBER;

        select ee.export_exemption_type_code into v_exemption_type_code from export_exemption ee where ee.exemption_number=V_EXEMPTION_NUMBER;

IF (V_ORG_UNIT_NO IN (1835,1909,1910) or (V_ORG_UNIT_NO in(1908) and curs.grade not in ('1','2','3','4','5','6'))) then

	if(v_exemption_type_code ='M') and (TO_DATE(curs.permit_application_date, 'YYYY-MM-DD') >= TO_DATE('2024-06-27', 'YYYY-MM-DD')) then
		v_scale_total := LEXIS_POLICY.GET_TWO_ELEVEN_FEE(TO_DATE(curs.permit_application_date, 'YYYY-MM-DD'), v_product_type, curs.volume, curs.org_unit_no, curs.species, curs.grade, v_growth_type, curs.fil, curs.multiplication_factor);
	Else
		v_scale_total := LEXIS_POLICY.GET_2004_FEE(TO_DATE(curs.permit_application_date, 'YYYY-MM-DD'), v_product_type, curs.volume, curs.org_unit_no, curs.species, curs.grade, v_growth_type);
        end if;
    if(v_exemption_type_code ='B') then
        select count(*) into V_ROW_COUNT from export_exemption_rate where exemption_number=V_EXEMPTION_NUMBER;
        IF V_ROW_COUNT > 0 THEN
         select fixed_exemption_rate into v_exemption_rate from export_exemption_rate where exemption_number=V_EXEMPTION_NUMBER;
        v_scale_total := v_exemption_rate * curs.volume;
        select exemption_override_rate into v_scale_exempt_ovrd_rate from export_scale_detail where export_scale_detail_id=curs.export_scale_detail_id;
        if v_scale_exempt_ovrd_rate != v_exemption_rate then
            update EXPORT_SCALE_DETAIL esd set esd.exemption_override_rate = v_exemption_rate  WHERE esd.export_scale_detail_id = curs.export_scale_detail_id;
        end if;
            UPDATE EXPORT_SCALE_DETAIL esd SET
                   esd.average_market_price =  v_exemption_rate,
                   esd.estimated_winning_bid = NULL,
                   esd.fee_in_lieu =  NULL ,
                   esd.multiplication_factor = CASE WHEN V_COUNTRY_CODE = 'CA' THEN NULL ELSE curs.multiplication_factor END,
                   esd.scale_detail_fee = CASE WHEN v_permit_override_fee_ind = 'Y' THEN NULL WHEN V_COUNTRY_CODE = 'CA' THEN NULL WHEN (TO_DATE(curs.permit_application_date, 'YYYY-MM-DD') < TO_DATE('2024-06-27', 'YYYY-MM-DD')) 	THEN NULL ELSE v_scale_total END,
                   esd.update_userid  = P_UPDATE_USERID,
                   esd.update_timestamp = P_UPDATE_TIMESTAMP
            WHERE esd.export_scale_detail_id = curs.export_scale_detail_id;
            ELSE
            UPDATE EXPORT_SCALE_DETAIL esd SET
                   esd.average_market_price = CASE WHEN curs.amv = 'ERR' THEN NULL ELSE  TO_NUMBER(trim(curs.amv), '999999.99') END,
                   esd.estimated_winning_bid = NULL,
                   esd.fee_in_lieu =  NULL ,
                   esd.multiplication_factor = CASE WHEN V_COUNTRY_CODE = 'CA' THEN NULL ELSE curs.multiplication_factor END,
                   esd.scale_detail_fee = CASE WHEN v_permit_override_fee_ind = 'Y' THEN NULL WHEN V_COUNTRY_CODE = 'CA' THEN NULL WHEN (TO_DATE(curs.permit_application_date, 'YYYY-MM-DD') < TO_DATE('2024-06-27', 'YYYY-MM-DD')) 	THEN NULL ELSE v_scale_total END,
                   esd.update_userid  = P_UPDATE_USERID,
                   esd.update_timestamp = P_UPDATE_TIMESTAMP
            WHERE esd.export_scale_detail_id = curs.export_scale_detail_id;
        END IF;

        else
            UPDATE EXPORT_SCALE_DETAIL esd SET
                   esd.average_market_price = CASE WHEN curs.amv = 'ERR' THEN NULL ELSE TO_NUMBER(trim(curs.amv), '999999.99') END,
                   esd.estimated_winning_bid = case when curs.grade ='Z' then null WHEN V_COUNTRY_CODE = 'CA' THEN NULL else TO_NUMBER(trim(curs.ewb),'99999.99') end ,
                   esd.fee_in_lieu = CASE WHEN curs.fil = 'N/A' THEN NULL WHEN V_COUNTRY_CODE = 'CA' THEN NULL ELSE curs.fil END,
                   esd.multiplication_factor = CASE WHEN V_COUNTRY_CODE = 'CA' THEN NULL ELSE curs.multiplication_factor END,
                   esd.scale_detail_fee = CASE WHEN v_permit_override_fee_ind = 'Y' THEN NULL WHEN V_COUNTRY_CODE = 'CA' THEN NULL WHEN (TO_DATE(curs.permit_application_date, 'YYYY-MM-DD') < TO_DATE('2024-06-27', 'YYYY-MM-DD')) 	THEN NULL ELSE v_scale_total END,
                   esd.update_userid  = P_UPDATE_USERID,
                   esd.update_timestamp = P_UPDATE_TIMESTAMP
            WHERE esd.export_scale_detail_id = curs.export_scale_detail_id;
          --  end if;
        end if;

    IF v_current_package != curs.PACKAGE THEN--new package data,
              --update package fee
              --UPDATE EXPORT_PACKAGE ep SET ep.package_fee = CASE WHEN v_permit_override_fee_ind = 'Y' THEN NULL ELSE v_package_total END WHERE ep.package_number = v_current_package;
               UPDATE EXPORT_PACKAGE ep SET ep.package_fee = CASE when (V_APPLICATION_DATE < TO_DATE('2024-06-27', 'YYYY-MM-DD')) then null
    WHEN v_permit_override_fee_ind = 'Y' THEN NULL WHEN V_COUNTRY_CODE = 'CA' THEN NULL ELSE v_package_total END, ep.update_userid  = P_UPDATE_USERID,
                   ep.update_timestamp = P_UPDATE_TIMESTAMP WHERE ep.package_number = v_current_package;
              v_current_package := curs.PACKAGE;
              v_package_total := 0;
            END IF;
            v_package_total := v_package_total + v_scale_total;
            v_permit_total := v_permit_total + v_scale_total;
            v_loop_counter := v_loop_counter + 1;
Else
     v_scale_total := LEXIS_POLICY.GET_2004_FEE(TO_DATE(curs.permit_application_date, 'YYYY-MM-DD'), v_product_type, curs.volume, curs.org_unit_no, curs.species, curs.grade, v_growth_type);
    select count(*) into V_ROW_COUNT from export_exemption_rate where exemption_number=V_EXEMPTION_NUMBER;

            IF V_ROW_COUNT > 0  and v_exemption_type_code ='B' THEN
            select fixed_exemption_rate into v_exemption_rate from export_exemption_rate where exemption_number=V_EXEMPTION_NUMBER;
            v_scale_total := v_exemption_rate * curs.volume;
             select exemption_override_rate into v_scale_exempt_ovrd_rate from export_scale_detail where export_scale_detail_id=curs.export_scale_detail_id;
        if v_scale_exempt_ovrd_rate != v_exemption_rate then
            update EXPORT_SCALE_DETAIL esd set esd.exemption_override_rate = v_exemption_rate  WHERE esd.export_scale_detail_id = curs.export_scale_detail_id;
        end if;
                UPDATE EXPORT_SCALE_DETAIL esd SET
                       esd.average_market_price = v_exemption_rate,
                       esd.estimated_winning_bid = NULL,
                       esd.fee_in_lieu =  NULL,
                       esd.multiplication_factor = Null,
                       esd.scale_detail_fee = CASE WHEN v_permit_override_fee_ind = 'Y' THEN NULL WHEN V_COUNTRY_CODE = 'CA' THEN NULL WHEN (TO_DATE(curs.permit_application_date, 'YYYY-MM-DD') < TO_DATE('2024-06-27', 'YYYY-MM-DD')) THEN NULL ELSE v_scale_total END,
                       esd.update_userid  = P_UPDATE_USERID,
                       esd.update_timestamp = P_UPDATE_TIMESTAMP
                WHERE esd.export_scale_detail_id = curs.export_scale_detail_id;
            else

             UPDATE EXPORT_SCALE_DETAIL esd SET
                           esd.average_market_price = CASE WHEN curs.amv = 'ERR' THEN NULL ELSE TO_NUMBER(trim(curs.amv), '999999.99') END,
                           esd.estimated_winning_bid = NULL,
                           esd.fee_in_lieu =  NULL,
                           esd.multiplication_factor = Null,
                           esd.scale_detail_fee = CASE WHEN v_permit_override_fee_ind = 'Y' THEN NULL WHEN V_COUNTRY_CODE = 'CA' THEN NULL WHEN (TO_DATE(curs.permit_application_date, 'YYYY-MM-DD') < TO_DATE('2024-06-27', 'YYYY-MM-DD')) THEN NULL ELSE v_scale_total END,
                           esd.update_userid  = P_UPDATE_USERID,
                           esd.update_timestamp = P_UPDATE_TIMESTAMP
                    WHERE esd.export_scale_detail_id = curs.export_scale_detail_id;
          end if;
     IF v_current_package != curs.PACKAGE THEN--new package data,
              --update package fee
              --UPDATE EXPORT_PACKAGE ep SET ep.package_fee = CASE WHEN v_permit_override_fee_ind = 'Y' THEN NULL ELSE v_package_total END WHERE ep.package_number = v_current_package;
               UPDATE EXPORT_PACKAGE ep SET ep.package_fee = CASE when (V_APPLICATION_DATE < TO_DATE('2024-06-27', 'YYYY-MM-DD')) then null
    WHEN v_permit_override_fee_ind = 'Y' THEN NULL WHEN V_COUNTRY_CODE = 'CA' THEN NULL ELSE v_package_total END, ep.update_userid  = P_UPDATE_USERID,
                   ep.update_timestamp = P_UPDATE_TIMESTAMP WHERE ep.package_number = v_current_package;
              v_current_package := curs.PACKAGE;
              v_package_total := 0;
            END IF;
            v_package_total := v_package_total + v_scale_total;
            v_permit_total := v_permit_total + v_scale_total;
            v_loop_counter := v_loop_counter + 1;
End if;
    END LOOP;
    UPDATE EXPORT_PACKAGE ep SET ep.package_fee = CASE when (V_APPLICATION_DATE < TO_DATE('2024-06-27', 'YYYY-MM-DD')) then null
    WHEN v_permit_override_fee_ind = 'Y' THEN NULL WHEN V_COUNTRY_CODE = 'CA' THEN NULL ELSE v_package_total END, ep.update_userid  = P_UPDATE_USERID,
                   ep.update_timestamp = P_UPDATE_TIMESTAMP WHERE ep.package_number = v_current_package;

    UPDATE EXPORT_PERMIT_DETAIL esd SET esd.permit_total_fee = CASE WHEN (esd.application_date < TO_DATE('2024-06-27', 'YYYY-MM-DD')) THEN NULL WHEN V_COUNTRY_CODE = 'CA' THEN NULL WHEN v_permit_override_fee_ind = 'Y' THEN V_OVERRIDE_FEE
     ELSE v_permit_total END WHERE esd.export_permit_detail_number = P_PERMIT_NUMBER;

END SET_FIL_CALULATED_VALUES;

end LEXIS;
/

  CREATE OR REPLACE EDITIONABLE PACKAGE "THE"."LEXIS_POLICY" IS

  TYPE REF_CUR_GENERAL IS REF CURSOR;

  TYPE REC_FEE_CALCS is RECORD(
                            EXPORT_PRODUCT_TYPE_CODE  EXPORT_EXEMPTION_APPLICATION.EXPORT_PRODUCT_TYPE_CODE%TYPE,
                            SPECIES_GRADE_VOLUME      NUMBER(12,2),
                            ORG_UNIT_NO               ORG_UNIT.ORG_UNIT_NO%TYPE,
                            EXPORT_SPECIES_CODE       EXPORT_SCALE_DETAIL.EXPORT_SPECIES_CODE%TYPE,
                            EXPORT_GRADE_CODE         EXPORT_SCALE_DETAIL.EXPORT_GRADE_CODE%TYPE,
                            EXPORT_GROWTH_TYPE_CODE   EXPORT_EXEMPTION_APPLICATION.EXPORT_GROWTH_TYPE_CODE%TYPE);

  REC_FEE_CALC              REC_FEE_CALCS;

  TYPE REF_FEE_CALCS IS REF CURSOR RETURN REC_FEE_CALC%TYPE;


  -- ABSTRACT FUNCTIONS (Used by reporting code)
  FUNCTION GET_DOMESTIC_VALUE(P_DATE                    IN DATE,
                              P_EXPORT_SPECIES_CODE     IN VARCHAR,
                              P_EXPORT_GRADE_CODE       IN VARCHAR,
                              P_EXPORT_GROWTH_TYPE_CODE IN VARCHAR,
                              P_VOLUME                  IN NUMBER)
    RETURN NUMBER;
  FUNCTION GET_FEE(P_DATE                    IN DATE,
                   P_PRODUCT_TYPE            IN VARCHAR,
                   P_VOLUME                  IN NUMBER,
                   P_ORG_UNIT_NO             IN NUMBER,
                   P_SPECIES_CODE            IN VARCHAR,
                   P_GRADE_CODE              IN VARCHAR,
                   P_EXPORT_GROWTH_TYPE_CODE IN VARCHAR) RETURN NUMBER;
  FUNCTION GET_PERMIT_FEE(P_PERMIT_NUMBER IN NUMBER, P_PERMIT_DATE IN DATE)
    RETURN NUMBER;
  FUNCTION GET_PERMIT_DV(P_PERMIT_NUMBER IN NUMBER, P_PERMIT_DATE IN DATE)
    RETURN NUMBER;
  FUNCTION GET_FEE_PERCENTAGE(P_SPECIES IN VARCHAR, P_GRADE IN VARCHAR)
    RETURN NUMBER;

  -- POLICY IMPLEMENTATIONS
  FUNCTION GET_2004_DOMESTIC_VALUE(P_DATE                    IN DATE,
                                   P_EXPORT_SPECIES_CODE     IN VARCHAR,
                                   P_EXPORT_GRADE_CODE       IN VARCHAR,
                                   P_EXPORT_GROWTH_TYPE_CODE IN VARCHAR,
                                   P_VOLUME                  IN NUMBER)
    RETURN NUMBER;
  FUNCTION GET_2004_FEE(P_DATE                    IN DATE,
                        P_PRODUCT_TYPE            IN VARCHAR,
                        P_VOLUME                  IN NUMBER,
                        P_ORG_UNIT_NO             IN NUMBER,
                        P_SPECIES_CODE            IN VARCHAR,
                        P_GRADE_CODE              IN VARCHAR,
                        P_EXPORT_GROWTH_TYPE_CODE IN VARCHAR) RETURN NUMBER;
  FUNCTION GET_2004_PERMIT_FEE(P_PERMIT_NUMBER IN NUMBER,
                               P_PERMIT_DATE   IN DATE) RETURN NUMBER;
  FUNCTION GET_2004_PERMIT_DV(P_PERMIT_NUMBER IN NUMBER,
                              P_PERMIT_DATE   IN DATE) RETURN NUMBER;
  FUNCTION GET_2004_FEE_PERCENTAGE(P_SPECIES IN VARCHAR,
                                   P_GRADE   IN VARCHAR) RETURN NUMBER;

  function GET_POLICY_PCT_INCREASE(P_DATE in date,
                              P_ORG_UNIT in lexis_fee_policy.org_unit_no%type) return number;

 FUNCTION GET_TWO_ELEVEN_FEE(P_DATE                    IN DATE,
                        P_PRODUCT_TYPE            IN VARCHAR,
                        P_VOLUME                  IN NUMBER,
                        P_ORG_UNIT_NO             IN NUMBER,
                        P_SPECIES_CODE            IN VARCHAR,
                        P_GRADE_CODE              IN VARCHAR,
                        P_EXPORT_GROWTH_TYPE_CODE IN VARCHAR,
                        P_FIL                     IN VARCHAR,
                        P_MF                      IN VARCHAR) RETURN NUMBER;

END LEXIS_POLICY;
/
CREATE OR REPLACE EDITIONABLE PACKAGE BODY "THE"."LEXIS_POLICY" IS

  FUNCTION GET_DOMESTIC_VALUE(P_DATE                    IN DATE,
                              P_EXPORT_SPECIES_CODE     IN VARCHAR,
                              P_EXPORT_GRADE_CODE       IN VARCHAR,
                              P_EXPORT_GROWTH_TYPE_CODE IN VARCHAR,
                              P_VOLUME                  IN NUMBER)
    RETURN NUMBER IS
  BEGIN
    RETURN GET_2004_DOMESTIC_VALUE(P_DATE,
                                   P_EXPORT_SPECIES_CODE,
                                   P_EXPORT_GRADE_CODE,
                                   P_EXPORT_GROWTH_TYPE_CODE,
                                   P_VOLUME);
  END GET_DOMESTIC_VALUE;

  FUNCTION GET_FEE(P_DATE                    IN DATE,
                   P_PRODUCT_TYPE            IN VARCHAR,
                   P_VOLUME                  IN NUMBER,
                   P_ORG_UNIT_NO             IN NUMBER,
                   P_SPECIES_CODE            IN VARCHAR,
                   P_GRADE_CODE              IN VARCHAR,
                   P_EXPORT_GROWTH_TYPE_CODE IN VARCHAR) RETURN NUMBER IS
  BEGIN
    RETURN GET_2004_FEE(P_DATE,
                        P_PRODUCT_TYPE,
                        P_VOLUME,
                        P_ORG_UNIT_NO,
                        P_SPECIES_CODE,
                        P_GRADE_CODE,
                        P_EXPORT_GROWTH_TYPE_CODE);
  END GET_FEE;

  FUNCTION GET_PERMIT_FEE(P_PERMIT_NUMBER IN NUMBER, P_PERMIT_DATE IN DATE)
    RETURN NUMBER IS
  BEGIN
    RETURN GET_2004_PERMIT_FEE(P_PERMIT_NUMBER, P_PERMIT_DATE);
  END GET_PERMIT_FEE;

  FUNCTION GET_PERMIT_DV(P_PERMIT_NUMBER IN NUMBER, P_PERMIT_DATE IN DATE)
    RETURN NUMBER IS
  BEGIN
    RETURN GET_2004_PERMIT_DV(P_PERMIT_NUMBER, P_PERMIT_DATE);
  END GET_PERMIT_DV;

  FUNCTION GET_FEE_PERCENTAGE(P_SPECIES IN VARCHAR, P_GRADE IN VARCHAR)
    RETURN NUMBER IS
  BEGIN
    RETURN GET_2004_FEE_PERCENTAGE(P_SPECIES, P_GRADE);
  END GET_FEE_PERCENTAGE;

  /******************************************************************************
      PROCEDURE:  GET_2004_DOMESTIC_VALUE
      PURPOSE: CALCULATES THE DOMESTIC VALUE OF AN EXPORT PERMIT.

    IMPORTANT NOTE: This code has been duplicated in the following JAVA class:
		ca.bc.gov.mof.lexis.service.policy.August2004ExportPolicy.getDomesticValueForScale()
    Any code changes here MUST be reflected in the above method!
  ******************************************************************************/
  FUNCTION GET_2004_DOMESTIC_VALUE(P_DATE                    IN DATE,
                                   P_EXPORT_SPECIES_CODE     IN VARCHAR,
                                   P_EXPORT_GRADE_CODE       IN VARCHAR,
                                   P_EXPORT_GROWTH_TYPE_CODE IN VARCHAR,
                                   P_VOLUME                  IN NUMBER)
    RETURN NUMBER IS
    AMV_CURSOR LEXIS.ref_log_amv;
    AMV_REC    LEXIS.rec_log_amvs;
    AMV        NUMBER := 1;
    DV         NUMBER := 0;
  BEGIN

    -- Deciduous species always have an AMV of $1 / m3
    IF P_EXPORT_SPECIES_CODE IN ('AL', 'AR', 'AS', 'BI', 'CO', 'MA') THEN
      DV := P_VOLUME;
    ELSE
      LEXIS.FIND_LOG_AMV(P_DATE,
                         P_EXPORT_SPECIES_CODE,
                         P_EXPORT_GRADE_CODE,
                         P_EXPORT_GROWTH_TYPE_CODE,
                         AMV_CURSOR);

      LOOP
        FETCH AMV_CURSOR
          INTO AMV_REC;
        EXIT WHEN AMV_CURSOR%NOTFOUND;
        AMV := AMV_REC.AVERAGE_MARKET_PRICE;
      END LOOP;

      DV := AMV * P_VOLUME;
    END IF;

    RETURN DV;
  END GET_2004_DOMESTIC_VALUE;

  /******************************************************************************
      PROCEDURE:  GET_2004_FEE
      PURPOSE: CALCULATES THE EXPECTED FEE.

    IMPORTANT NOTE: This code has been duplicated in the following JAVA class:
		ca.bc.gov.mof.lexis.service.policy.August2004ExportPolicy.getFeeForScale()
    Any code changes here MUST be reflected in the above method!
  ******************************************************************************/
  FUNCTION GET_2004_FEE(P_DATE                    IN DATE,
                        P_PRODUCT_TYPE            IN VARCHAR,
                        P_VOLUME                  IN NUMBER,
                        P_ORG_UNIT_NO             IN NUMBER,
                        P_SPECIES_CODE            IN VARCHAR,
                        P_GRADE_CODE              IN VARCHAR,
                        P_EXPORT_GROWTH_TYPE_CODE IN VARCHAR) RETURN NUMBER IS

    AMV_CURSOR     LEXIS.ref_log_amv;
    AMV_REC        LEXIS.rec_log_amvs;
    AMV            NUMBER(9, 2) := 1;
    TOTAL_FEE      NUMBER(9, 2) := 0;
    FEE_PERCENTAGE NUMBER(9, 2) := 0;
    V_POLICY_PCT   number;

  BEGIN

    IF P_PRODUCT_TYPE = 'T' THEN
      -- product type T fee is $1/m3 across the board
      TOTAL_FEE := P_VOLUME;
    ELSIF P_ORG_UNIT_NO IN (1835,1908,1909,1910) THEN
      IF P_SPECIES_CODE IN ('AL', 'AR', 'AS', 'BI', 'CO', 'MA') THEN
        -- fee is $1/m3 for all deciduous species
        TOTAL_FEE := P_VOLUME;
      ELSE
        -- RCO Calculations
        FEE_PERCENTAGE := GET_2004_FEE_PERCENTAGE(P_SPECIES_CODE,
                                                  P_GRADE_CODE);
        LEXIS.FIND_LOG_AMV(P_DATE,
                           P_SPECIES_CODE,
                           P_GRADE_CODE,
                           P_EXPORT_GROWTH_TYPE_CODE,
                           AMV_CURSOR);

        LOOP
          FETCH AMV_CURSOR
            INTO AMV_REC;
          EXIT WHEN AMV_CURSOR%NOTFOUND;
          AMV := AMV_REC.AVERAGE_MARKET_PRICE;
        END LOOP;

        IF (AMV * FEE_PERCENTAGE) < 1 THEN
          -- if the calculated fee falls below $1, make it $1
          TOTAL_FEE := P_VOLUME;
        ELSE
          TOTAL_FEE := AMV * FEE_PERCENTAGE * P_VOLUME;
        END IF;

      END IF;

    ELSE
      -- fee is $1/m3 for interior regions
      TOTAL_FEE := P_VOLUME;
    END IF;



    V_POLICY_PCT := GET_POLICY_PCT_INCREASE(P_DATE, P_ORG_UNIT_NO);

    TOTAL_FEE := (TOTAL_FEE+(TOTAL_FEE*(V_POLICY_PCT/100)));

    RETURN TOTAL_FEE;
  END GET_2004_FEE;

    /******************************************************************************
      function:  GET_POLICY_PCT_INCREASE
      Purpose: Finds a specific fee policy factor
  ******************************************************************************/
  function GET_POLICY_PCT_INCREASE(P_DATE in date,
                              P_ORG_UNIT in lexis_fee_policy.org_unit_no%type) return number is
    v_percent_increase lexis_fee_policy.percent_increase%type;
    v_id lexis_fee_policy.lexis_fee_policy_id%type;
    BEGIN
    select lfp.lexis_fee_policy_id
    into v_id
    from lexis_fee_policy lfp,
    (
     select max(ilfp.effective_date) as effective_date
               from lexis_fee_policy ilfp
              where ilfp.org_unit_no = P_ORG_UNIT
                and ilfp.effective_date <= P_DATE

     ) mp
    where mp.effective_date = lfp.effective_date
    and lfp.org_unit_no = P_ORG_UNIT;


    select lfp.percent_increase
    into v_percent_increase
    from lexis_fee_policy lfp
    where lexis_fee_policy_id = v_id;

    return v_percent_increase;
    EXCEPTION WHEN NO_DATA_FOUND THEN RETURN 0;

    end GET_POLICY_PCT_INCREASE;



  /******************************************************************************
      PROCEDURE:  GET_2004_FEE_PERCENTAGE
      PURPOSE: CALCULATES THE EXPECTED FEE PERCENTAGE APPLIED.
  ******************************************************************************/
  FUNCTION GET_2004_FEE_PERCENTAGE(P_SPECIES IN VARCHAR,
                                   P_GRADE   IN VARCHAR) RETURN NUMBER IS
    FEE_PCNT NUMBER(4, 2) := 0;
  BEGIN

    IF P_SPECIES = 'FI' THEN
      FEE_PCNT := 0.15;
    ELSIF P_GRADE IN ('U', 'X', 'Y', 'Z') THEN
      FEE_PCNT := 0.05;
    ELSE
      FEE_PCNT := 0.10;
    END IF;

    RETURN FEE_PCNT;
  END GET_2004_FEE_PERCENTAGE;

  /******************************************************************************
      PROCEDURE:  GET_2004_PERMIT_FEE
      PURPOSE: CALCULATES THE EXPECTED FEE FOR ALL SCALES ASSOCIATED WITH A PERMIT.
  ******************************************************************************/
  FUNCTION GET_2004_PERMIT_FEE(P_PERMIT_NUMBER IN NUMBER,
                               P_PERMIT_DATE   IN DATE) RETURN NUMBER IS

--    SCALE_CUR LEXIS.ref_scale_detail;
 --   SCALE_REC LEXIS.rec_scale_details;

    FEE_CUR REF_FEE_CALCS;

    TOTAL_FEE NUMBER := 0;
  BEGIN


    OPEN FEE_CUR FOR
SELECT EEA.EXPORT_PRODUCT_TYPE_CODE,
       sum(ESD.SPECIES_GRADE_VOLUME),
       EEA.ORG_UNIT_NO,
       ESD.EXPORT_SPECIES_CODE,
       ESD.EXPORT_GRADE_CODE,
       EEA.EXPORT_GROWTH_TYPE_CODE
  FROM EXPORT_SCALE_DETAIL ESD
 INNER JOIN EXPORT_PACKAGE EP
    ON EP.Package_Number = ESD.Package_Number
 INNER JOIN EXPORT_EXEMPTION_APPLICATION EEA
    ON EP.APPLICATION_NUMBER = EEA.APPLICATION_NUMBER
 WHERE ESD.EXPORT_PERMIT_DETAIL_NUMBER = P_PERMIT_NUMBER
 group by EEA.EXPORT_PRODUCT_TYPE_CODE,
          EEA.ORG_UNIT_NO,
          ESD.EXPORT_SPECIES_CODE,
          ESD.EXPORT_GRADE_CODE,
          EEA.EXPORT_GROWTH_TYPE_CODE;



      LOOP
        FETCH FEE_CUR
          INTO REC_FEE_CALC;
        EXIT WHEN FEE_CUR%NOTFOUND;

        TOTAL_FEE := TOTAL_FEE +
                     GET_2004_FEE(P_PERMIT_DATE,
                                  REC_FEE_CALC.EXPORT_PRODUCT_TYPE_CODE,
                                  REC_FEE_CALC.SPECIES_GRADE_VOLUME,
                                  REC_FEE_CALC.ORG_UNIT_NO,
                                  REC_FEE_CALC.EXPORT_SPECIES_CODE,
                                  REC_FEE_CALC.EXPORT_GRADE_CODE,
                                  REC_FEE_CALC.EXPORT_GROWTH_TYPE_CODE);
      END LOOP;

    RETURN TOTAL_FEE;
  END GET_2004_PERMIT_FEE;

  /******************************************************************************
      PROCEDURE:  GET_2004_PERMIT_DV
      PURPOSE: CALCULATES THE EXPECTED FEE FOR ALL SCALES ASSOCIATED WITH A PERMIT.
  ******************************************************************************/
  FUNCTION GET_2004_PERMIT_DV(P_PERMIT_NUMBER IN NUMBER,
                              P_PERMIT_DATE   IN DATE) RETURN NUMBER IS


    SCALE_CUR LEXIS.ref_scale_detail;
    SCALE_REC LEXIS.rec_scale_details;

    APP_CUR LEXIS.ref_application;
    APP_REC LEXIS.rec_applications;

    TOTAL_DV NUMBER := 0;
  BEGIN
/*
    -- find all of the packages for this permit
    LEXIS.FIND_PACKAGES_BY_PERMIT(P_PERMIT_NUMBER, PACKAGE_CUR);

    LOOP
      FETCH PACKAGE_CUR
        INTO PACKAGE_REC;
      EXIT WHEN PACKAGE_CUR%NOTFOUND;
*/
      -- find all of the scales for this permit
      LEXIS.FIND_SCALE_DETAIL_BY_PRM(P_PERMIT_NUMBER, SCALE_CUR);

      LOOP
        FETCH SCALE_CUR
          INTO SCALE_REC;
        EXIT WHEN SCALE_CUR%NOTFOUND;

        -- get the application associated with this scale
        LEXIS.FIND_APPLICATION_BY_NUMBER(SCALE_REC.APPLICATION_NUMBER, APP_CUR);
        FETCH APP_CUR
          INTO APP_REC;

        TOTAL_DV := TOTAL_DV +
                    GET_2004_DOMESTIC_VALUE(P_PERMIT_DATE,
                                            SCALE_REC.EXPORT_SPECIES_CODE,
                                            SCALE_REC.EXPORT_GRADE_CODE,
                                            APP_REC.EXPORT_GROWTH_TYPE_CODE,
                                            SCALE_REC.SPECIES_GRADE_VOLUME);
      END LOOP;

--    END LOOP;

    RETURN TOTAL_DV;
  END GET_2004_PERMIT_DV;

  FUNCTION GET_TWO_ELEVEN_FEE(P_DATE                    IN DATE,
                        P_PRODUCT_TYPE            IN VARCHAR,
                        P_VOLUME                  IN NUMBER,
                        P_ORG_UNIT_NO             IN NUMBER,
                        P_SPECIES_CODE            IN VARCHAR,
                        P_GRADE_CODE              IN VARCHAR,
                        P_EXPORT_GROWTH_TYPE_CODE IN VARCHAR,
                        P_FIL                     IN VARCHAR,
                        P_MF                      IN VARCHAR) RETURN NUMBER IS

    AMV_CURSOR     LEXIS.ref_log_amv;
    AMV_REC        LEXIS.rec_log_amvs;
    AMV            NUMBER(9, 2) := 1;
    TOTAL_FEE      NUMBER(9, 2) := 0;
    FIL            NUMBER:=0;
    MF             NUMBER:=0;
  BEGIN

    IF (P_ORG_UNIT_NO IN (1835,1909,1910) or (P_ORG_UNIT_NO in(1908) and P_GRADE_CODE not in ('1','2','3','4','5','6'))) THEN

     IF P_SPECIES_CODE IN ('AL', 'AR', 'AS', 'BI', 'CO', 'MA') THEN
        AMV := 1;
     else
        LEXIS.FIND_LOG_AMV(P_DATE,
                           P_SPECIES_CODE,
                           P_GRADE_CODE,
                           P_EXPORT_GROWTH_TYPE_CODE,
                           AMV_CURSOR);


        LOOP
          FETCH AMV_CURSOR
            INTO AMV_REC;
          EXIT WHEN AMV_CURSOR%NOTFOUND;
          AMV := AMV_REC.AVERAGE_MARKET_PRICE;
        END LOOP;
     end if;
FIL := CASE WHEN P_FIL = 'N/A' THEN NULL ELSE to_number(P_FIL) END;
MF  := CASE WHEN (P_MF IS NOT NULL AND P_MF = 0) THEN NULL ELSE P_MF END;
       IF FIL is not null  and P_MF is not null THEN
            IF P_MF = 0 THEN
              TOTAL_FEE := AMV * (FIL/100) * P_VOLUME;
              ELSE
              TOTAL_FEE := AMV * (FIL/100) * (1 + P_MF/100) * P_VOLUME;
              END IF;
        elsif FIL is not null and P_mf is  null then
            TOTAL_FEE := AMV * (FIL/100) * P_VOLUME;
        elsif FIL is  null  and P_MF is not null then
            IF P_MF = 0 THEN
             TOTAL_FEE := AMV  * P_VOLUME;
             ELSE
             TOTAL_FEE := AMV *  (1+ P_MF/100) * P_VOLUME;
             END IF;
        else
            TOTAL_FEE := AMV *  P_VOLUME;
       END IF;

      END IF;



    RETURN TOTAL_FEE;
  END GET_TWO_ELEVEN_FEE;

END LEXIS_POLICY;
/

