CREATE OR REPLACE EDITIONABLE PACKAGE BODY "THE"."LEXIS_CODES" is

  /******************************************************************************
      Procedure:  FIND_ALL_APP_STATUS_CODES
      Purpose: Find all available Export Application Status codes.
  ******************************************************************************/
  PROCEDURE FIND_ALL_APP_STATUS_CODES(P_CODES IN OUT ref_code) IS
  BEGIN
    OPEN P_CODES FOR
      SELECT C.EXPORT_APPLICATION_STATUS_CODE AS CODE,
             C.DESCRIPTION,
             C.EFFECTIVE_DATE,
             C.EXPIRY_DATE,
             C.UPDATE_TIMESTAMP,
             O.ORDER_BY,
             O.GROUP_BY
        FROM EXPORT_APPLICATION_STATUS_CODE C
       INNER JOIN export_appln_sts_code_order O ON C.EXPORT_APPLICATION_STATUS_CODE =
                                                   O.EXPORT_APPLICATION_STATUS_CODE
       WHERE SYSDATE BETWEEN EFFECTIVE_DATE AND EXPIRY_DATE
       ORDER BY O.GROUP_BY, O.ORDER_BY;
  END FIND_ALL_APP_STATUS_CODES;

  /******************************************************************************
      Procedure:  FIND_APPLICATION_STATUS_CODE
      Purpose: Find an application status code.
  ******************************************************************************/
  PROCEDURE FIND_APPLICATION_STATUS_CODE(P_CODE   IN VARCHAR,
                                         P_RESULT IN OUT ref_code) IS
  BEGIN
    OPEN P_RESULT FOR
      SELECT C.EXPORT_APPLICATION_STATUS_CODE AS CODE,
             C.DESCRIPTION,
             C.EFFECTIVE_DATE,
             C.EXPIRY_DATE,
             C.UPDATE_TIMESTAMP,
             O.ORDER_BY,
             O.GROUP_BY
        FROM EXPORT_APPLICATION_STATUS_CODE C
       INNER JOIN export_appln_sts_code_order O ON C.EXPORT_APPLICATION_STATUS_CODE =
                                                   O.EXPORT_APPLICATION_STATUS_CODE
       WHERE C.EXPORT_APPLICATION_STATUS_CODE = P_CODE
         AND SYSDATE BETWEEN EFFECTIVE_DATE AND EXPIRY_DATE;
  END FIND_APPLICATION_STATUS_CODE;

  /******************************************************************************
      Procedure:  FIND_APPLICATION_STATUS_GROUP
      Purpose: Find the group of application status codes.
  ******************************************************************************/
  PROCEDURE FIND_APPLICATION_STATUS_GROUP(P_CODE   IN export_appln_sts_code_order.group_by%type,
                                          P_RESULT IN OUT ref_code) IS
  BEGIN
    OPEN P_RESULT FOR
      SELECT C.EXPORT_APPLICATION_STATUS_CODE AS CODE,
             C.DESCRIPTION,
             C.EFFECTIVE_DATE,
             C.EXPIRY_DATE,
             C.UPDATE_TIMESTAMP,
             O.ORDER_BY,
             O.GROUP_BY
        FROM EXPORT_APPLICATION_STATUS_CODE C
       INNER JOIN export_appln_sts_code_order O ON C.EXPORT_APPLICATION_STATUS_CODE =
                                                   O.EXPORT_APPLICATION_STATUS_CODE
       WHERE O.GROUP_BY = P_CODE
         AND SYSDATE BETWEEN EFFECTIVE_DATE AND EXPIRY_DATE
       ORDER BY O.ORDER_BY;
  END FIND_APPLICATION_STATUS_GROUP;

  /******************************************************************************
      Procedure:  FIND_ALL_PRODUCT_TYPE_CODES
      Purpose: Find available Product Type codes.
  ******************************************************************************/
  PROCEDURE FIND_ALL_PRODUCT_TYPE_CODES(P_CODES IN OUT ref_code) IS
  BEGIN
    OPEN P_CODES FOR
      SELECT C.EXPORT_PRODUCT_TYPE_CODE AS CODE,
             C.DESCRIPTION,
             C.EFFECTIVE_DATE,
             C.EXPIRY_DATE,
             C.UPDATE_TIMESTAMP,
             O.ORDER_BY,
             O.GROUP_BY
        FROM EXPORT_PRODUCT_TYPE_CODE C
       INNER JOIN EXPORT_PRODUCT_TYPE_CODE_ORDER O ON C.EXPORT_PRODUCT_TYPE_CODE =
                                                      O.EXPORT_PRODUCT_TYPE_CODE
       WHERE SYSDATE BETWEEN EFFECTIVE_DATE AND EXPIRY_DATE
       ORDER BY O.GROUP_BY, O.ORDER_BY;
  END FIND_ALL_PRODUCT_TYPE_CODES;

  /******************************************************************************
      Procedure:  FIND_PRODUCT_TYPE_CODE
      Purpose: Find a product type code.
  ******************************************************************************/
  PROCEDURE FIND_PRODUCT_TYPE_CODE(P_CODE   IN VARCHAR,
                                   P_RESULT IN OUT ref_code) IS
  BEGIN
    OPEN P_RESULT FOR
      SELECT C.EXPORT_PRODUCT_TYPE_CODE AS CODE,
             C.DESCRIPTION,
             C.EFFECTIVE_DATE,
             C.EXPIRY_DATE,
             C.UPDATE_TIMESTAMP,
             O.ORDER_BY,
             O.GROUP_BY
        FROM EXPORT_PRODUCT_TYPE_CODE C
       INNER JOIN EXPORT_PRODUCT_TYPE_CODE_ORDER O ON C.EXPORT_PRODUCT_TYPE_CODE =
                                                      O.EXPORT_PRODUCT_TYPE_CODE
       WHERE C.EXPORT_PRODUCT_TYPE_CODE = P_CODE
         AND SYSDATE BETWEEN EFFECTIVE_DATE AND EXPIRY_DATE;
  END FIND_PRODUCT_TYPE_CODE;

  /******************************************************************************
      Procedure:  FIND_PRODUCT_TYPE_GROUP
      Purpose: Find the group of product types.
  ******************************************************************************/
  PROCEDURE FIND_PRODUCT_TYPE_GROUP(P_CODE   IN EXPORT_PRODUCT_TYPE_CODE_ORDER.GROUP_BY%type,
                                    P_RESULT IN OUT ref_code) IS
  BEGIN
    OPEN P_RESULT FOR
      SELECT C.EXPORT_PRODUCT_TYPE_CODE AS CODE,
             C.DESCRIPTION,
             C.EFFECTIVE_DATE,
             C.EXPIRY_DATE,
             C.UPDATE_TIMESTAMP,
             O.ORDER_BY,
             O.GROUP_BY
        FROM EXPORT_PRODUCT_TYPE_CODE C
       INNER JOIN EXPORT_PRODUCT_TYPE_CODE_ORDER O ON C.EXPORT_PRODUCT_TYPE_CODE =
                                                      O.EXPORT_PRODUCT_TYPE_CODE
       WHERE O.GROUP_BY = P_CODE
